	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.highlightSpellbookSpells)
		{
			return null;
		}

		ActiveSearch search = plugin.getActiveSearch();
		if (search == null)
		{
			return null;
		}

		List<PathStep> path = search.getPath();
		if (path == null || path.isEmpty())
		{
			return null;
		}

		Widget spellLayer = client.getWidget(InterfaceID.MagicSpellbook.SPELLLAYER);
		if (spellLayer == null || spellLayer.isHidden())
		{
			return null;
		}

		int pathIndex = getPlayerPathIndex(path);
		if (pathIndex < 0 || pathIndex + 1 >= path.size())
		{
			return null;
		}

		Set<Transport> transports = plugin.transportsForEdge(path.get(pathIndex), path.get(pathIndex + 1));
		Color highlight = plugin.colourBankPickupHighlight;

		for (Transport transport : transports)
		{
			if (!TransportType.TELEPORTATION_SPELL.equals(transport.getType()))
			{
				continue;
			}
			String displayInfo = transport.getDisplayInfo();
			if (displayInfo == null)
			{
				continue;
			}
			Integer widgetId = SPELL_WIDGET_IDS.get(displayInfo);
			if (widgetId == null)
			{
				continue;
			}
			Widget spellWidget = client.getWidget(widgetId);
			if (spellWidget == null || spellWidget.isHidden())
			{
				continue;
			}
			Rectangle bounds = spellWidget.getBounds();
			Stroke oldStroke = graphics.getStroke();
			graphics.setStroke(new BasicStroke(2));
			graphics.setColor(highlight);
			graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
			graphics.setStroke(oldStroke);
		}

		return null;
	}
}

package shortestpath.pathfinder;

public enum AbstractNodeKind
{
	// These four abstract teleport states mirror the wilderness buckets that change
	// which teleports are legal.
	GLOBAL_TELEPORTS_OVER_30,
	GLOBAL_TELEPORTS_OVER_20,
	GLOBAL_TELEPORTS_OVER_0,
	GLOBAL_TELEPORTS_NORMAL;

	public static AbstractNodeKind fromWildernessLevel(int wildernessLevel)
	{
		if (wildernessLevel > 30)
		{
			return GLOBAL_TELEPORTS_OVER_30;
		}
		if (wildernessLevel > 20)
		{
			return GLOBAL_TELEPORTS_OVER_20;
		}
		if (wildernessLevel > 0)
		{
			return GLOBAL_TELEPORTS_OVER_0;
		}
		return GLOBAL_TELEPORTS_NORMAL;
	}

	public int maxWildernessLevel()
	{
		switch (this)
		{
			case GLOBAL_TELEPORTS_OVER_30:
				return 31;
			case GLOBAL_TELEPORTS_OVER_20:
				return 30;
			case GLOBAL_TELEPORTS_OVER_0:
				return 20;
			case GLOBAL_TELEPORTS_NORMAL:
			default:
				return 0;
		}
	}
}

