package shortestpath.pathfinder;

import shortestpath.PrimitiveIntList;
import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;

public class CollisionMap
{
	// Enum.values() makes copies every time which hurts performance in the hotpath
	private static final OrdinalDirection[] ORDINAL_VALUES = OrdinalDirection.values();

	private final SplitFlagMap collisionData;
	// This is only safe if pathfinding is single-threaded. Holds the ids of the neighbour nodes
	// appended to the NodeGraph during the most recent getNeighbors call.
	private final PrimitiveIntList neighbors = new PrimitiveIntList(16);
	private final boolean[] traversable = new boolean[8];

	public CollisionMap(SplitFlagMap collisionData)
	{
		this.collisionData = collisionData;
	}

	/**
	 * The region grid bounds to scan when enumerating every collision tile (e.g.
	 * {@link shortestpath.pathfinder.exact.RoutingStaticBuilder}). Delegates to
	 * {@link SplitFlagMap#getRegionExtents()} by default; overridable so tests can substitute a
	 * small synthetic extent without touching that shared static state.
	 */
	public SplitFlagMap.RegionExtent regionExtent()
	{
		return SplitFlagMap.getRegionExtents();
	}

	private static int packedPointFromOrdinal(int startPacked, OrdinalDirection direction)
	{
		final int x = WorldPointUtil.unpackWorldX(startPacked);
		final int y = WorldPointUtil.unpackWorldY(startPacked);
		final int plane = WorldPointUtil.unpackWorldPlane(startPacked);
		return WorldPointUtil.packWorldPoint(x + direction.x, y + direction.y, plane);
	}

	public byte getRegionPlaneCounts(int regionIndex)
	{
		return collisionData.getRegionPlaneCounts(regionIndex);
	}

	private boolean get(int x, int y, int z, int flag)
	{
		return collisionData.get(x, y, z, flag);
	}

	public boolean n(int x, int y, int z)
	{
		return get(x, y, z, SplitFlagMap.FLAG_NORTH);
	}

	public boolean s(int x, int y, int z)
	{
		return n(x, y - 1, z);
	}

	public boolean e(int x, int y, int z)
	{
		return get(x, y, z, SplitFlagMap.FLAG_EAST);
	}

	public boolean w(int x, int y, int z)
	{
		return e(x - 1, y, z);
	}

	// The wall flags record whether a structural boundary (a wall or door
	// edge) sits on the edge, regardless of whether the edge is currently
	// passable. They stay unset on edges that are blocked only by an
	// object's footprint or a tile-level floor/seal block.
	public boolean wallN(int x, int y, int z)
	{
		return get(x, y, z, SplitFlagMap.FLAG_WALL_NORTH);
	}

	public boolean wallS(int x, int y, int z)
	{
		return wallN(x, y - 1, z);
	}

	public boolean wallE(int x, int y, int z)
	{
		return get(x, y, z, SplitFlagMap.FLAG_WALL_EAST);
	}

	public boolean wallW(int x, int y, int z)
	{
		return wallE(x - 1, y, z);
	}

	private boolean ne(int x, int y, int z)
	{
		return n(x, y, z) && e(x, y + 1, z) && e(x, y, z) && n(x + 1, y, z);
	}

	private boolean nw(int x, int y, int z)
	{
		return n(x, y, z) && w(x, y + 1, z) && w(x, y, z) && n(x - 1, y, z);
	}

	private boolean se(int x, int y, int z)
	{
		return s(x, y, z) && e(x, y - 1, z) && e(x, y, z) && s(x + 1, y, z);
	}

	private boolean sw(int x, int y, int z)
	{
		return s(x, y, z) && w(x, y - 1, z) && w(x, y, z) && s(x - 1, y, z);
	}

	public boolean isBlocked(int x, int y, int z)
	{
		return !n(x, y, z) && !s(x, y, z) && !e(x, y, z) && !w(x, y, z);
	}

	/**
	 * Returns the ordinary 8-direction walking mask (bits N, NE, E, SE, S, SW, W, NW); a diagonal
	 * is open only when both flanking cardinal moves are.
	 */
	public byte ordinaryWalkingMask(int packedPoint)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int z = WorldPointUtil.unpackWorldPlane(packedPoint);
		if (isBlocked(x, y, z))
		{
			return 0;
		}

		int mask = 0;
		if (n(x, y, z)) mask |= 1;
		if (ne(x, y, z)) mask |= 1 << 1;
		if (e(x, y, z)) mask |= 1 << 2;
		if (se(x, y, z)) mask |= 1 << 3;
		if (s(x, y, z)) mask |= 1 << 4;
		if (sw(x, y, z)) mask |= 1 << 5;
		if (w(x, y, z)) mask |= 1 << 6;
		if (nw(x, y, z)) mask |= 1 << 7;
		return (byte) mask;
	}

	/** Returns authoritative walking neighbours without transport-specific edges. */
	public int[] ordinaryWalkingNeighbors(int packedPoint)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int z = WorldPointUtil.unpackWorldPlane(packedPoint);
		if (!isBlocked(x, y, z))
		{
			final int mask = Byte.toUnsignedInt(ordinaryWalkingMask(packedPoint));
			final int[] result = new int[Integer.bitCount(mask)];
			int index = 0;
			for (int bit = 0; bit < 8; bit++)
			{
				if ((mask & (1 << bit)) != 0)
				{
					result[index++] = WorldPointUtil.packWorldPoint(
						x + new int[]{0, 1, 1, 1, 0, -1, -1, -1}[bit],
						y + new int[]{1, 1, 0, -1, -1, -1, 0, 1}[bit], z);
				}
			}
			return result;
		}

		int[] result = new int[8];
		int count = 0;
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx == 0 && dy == 0 || !isWalkable(x + dx, y + dy, z))
				{
					continue;
				}
				if (dx == 0 || dy == 0 || (isWalkable(x + dx, y, z) && isWalkable(x, y + dy, z)))
				{
					result[count++] = WorldPointUtil.packWorldPoint(x + dx, y + dy, z);
				}
			}
		}
		return java.util.Arrays.copyOf(result, count);
	}

	private boolean isWalkable(int x, int y, int z)
	{
		return n(x, y, z) || s(x, y, z) || e(x, y, z) || w(x, y, z);
	}

	public PrimitiveIntList getNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, boolean targetInWilderness, NodeGraph graph)
	{
		if (graph.isTile(node))
		{
			return getTileNeighbors(node, visited, config, wildernessLevel, graph);
		}
		else
		{
			return getAbstractNodeNeighbors(node, visited, config, targetInWilderness, graph);
		}
	}

	// Get neighbours for a walkable tile:
	//      * Neighbouring tiles we can walk to
	//      * A transition into banked state, if the current tile is a bank.
	//      * Transition into abstract global teleport nodes, if we haven't tried that yet.
	private PrimitiveIntList getTileNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, NodeGraph graph)
	{
		final int packedPosition = graph.packedPosition(node);
		final int x = WorldPointUtil.unpackWorldX(packedPosition);
		final int y = WorldPointUtil.unpackWorldY(packedPosition);
		final int z = WorldPointUtil.unpackWorldPlane(packedPosition);

		neighbors.clear();

		// The banked state is only entered through an explicit, costed transition: standing on a
		// bank-accessible tile emits a bank-visit edge carrying the configured penalty, so the
		// charge sits on the decision to bank rather than on the edges leaving the bank tile.
		// The edge is flagged as a transport so Pathfinder queues it on the cost-ordered pending
		// heap — the FIFO tile boundary queue is only ordered for unit-cost walking edges.
		boolean pathBankVisited = graph.bankVisited(node);
		if (!pathBankVisited && config.isBankPathEnabled() && config.bankAccessible(packedPosition)
			&& !visited.get(packedPosition, true))
		{
			neighbors.add(graph.createBankVisit(packedPosition, node, config.getBankVisitCost()));
		}

		// Firstly check if there are any transports or teleports which are applicable from the current tile.
		Transport[] transports = config.getTransportsPacked(pathBankVisited).getOrDefault(packedPosition, TransportAvailability.EMPTY_TRANSPORTS);
		// If this tile was itself reached via a delayed-visit teleport (e.g. QUETZAL_WHISTLE), propagate its
		// differential cost to any competing delayed-visit transports emitted from here. This prevents the
		// pathfinder from choosing a chain (e.g. whistle → landing site A → fly to B) over a direct teleport
		// to B, because the chain inherits the teleport's penalty and is therefore always more expensive.
		int inheritedDifferential = (graph.isTransport(node) && graph.isDelayedVisit(node))
			? graph.differentialCost(node)
			: 0;
		for (Transport transport : transports)
		{
			boolean delayedVisit = transport.getType().sharesDestinationsWith() != null;
			// Do not consider a transport if its target tile is already settled —
			// dequeued from pending via a cheaper-or-equal route.
			// For transports that share destinations with a teleport, skip this check
			// so both can compete in the priority queue (delayed visit).
			if (!delayedVisit && visited.get(transport.getDestination(), pathBankVisited))
			{
				continue;
			}
			// Inherit the parent teleport's differential as a real cost on chained shared-destination transports,
			// so that chaining (e.g. fly to landing site A then use station to B) is always more expensive than
			// a direct teleport to B.
			int chainPenalty = (delayedVisit && inheritedDifferential > 0) ? inheritedDifferential : 0;
			// NB: Do not need to check for wilderness level for transports, since transports have specific origin tile.
			neighbors.add(graph.createTransport(
				transport.getDestination(),
				node,
				transport.getDuration(),
				config.getAdditionalTransportCost(transport) + chainPenalty,
				pathBankVisited,
				delayedVisit,
				delayedVisit ? config.getDifferentialCost(transport) : 0,
				transport));
		}

		// Global teleports are only considered from an abstract node, so each
		// wilderness/bank state expands them once.
		AbstractNodeKind abstractKind = AbstractNodeKind.fromWildernessLevel(wildernessLevel);
		if (!visited.getAbstract(abstractKind, pathBankVisited))
		{
			neighbors.add(graph.createAbstract(abstractKind, node, pathBankVisited));
		}

		// Then add tiles which we can walk to, which go into the FIFO boundary queue.
		if (isBlocked(x, y, z))
		{
			boolean westBlocked = isBlocked(x - 1, y, z);
			boolean eastBlocked = isBlocked(x + 1, y, z);
			boolean southBlocked = isBlocked(x, y - 1, z);
			boolean northBlocked = isBlocked(x, y + 1, z);
			boolean southWestBlocked = isBlocked(x - 1, y - 1, z);
			boolean southEastBlocked = isBlocked(x + 1, y - 1, z);
			boolean northWestBlocked = isBlocked(x - 1, y + 1, z);
			boolean northEastBlocked = isBlocked(x + 1, y + 1, z);
			traversable[0] = !westBlocked;
			traversable[1] = !eastBlocked;
			traversable[2] = !southBlocked;
			traversable[3] = !northBlocked;
			traversable[4] = !southWestBlocked && !westBlocked && !southBlocked;
			traversable[5] = !southEastBlocked && !eastBlocked && !southBlocked;
			traversable[6] = !northWestBlocked && !westBlocked && !northBlocked;
			traversable[7] = !northEastBlocked && !eastBlocked && !northBlocked;
		}
		else
		{
			traversable[0] = w(x, y, z);
			traversable[1] = e(x, y, z);
			traversable[2] = s(x, y, z);
			traversable[3] = n(x, y, z);
			traversable[4] = sw(x, y, z);
			traversable[5] = se(x, y, z);
			traversable[6] = nw(x, y, z);
			traversable[7] = ne(x, y, z);
		}

		for (int i = 0; i < traversable.length; i++)
		{
			OrdinalDirection d = ORDINAL_VALUES[i];
			int neighborPacked = packedPointFromOrdinal(packedPosition, d);
			if (visited.get(neighborPacked, pathBankVisited))
			{
				continue;
			}

			if (traversable[i])
			{
				neighbors.add(graph.createTile(neighborPacked, node, pathBankVisited));
			}
			else if (Math.abs(d.x + d.y) == 1 && isBlocked(x + d.x, y + d.y, z))
			{
				// The transport starts from a blocked adjacent tile, e.g. fairy ring
				// Only checks non-teleport transports (includes portals and levers, but not
				// items and spells)
				Transport[] neighborTransports = config.getTransportsPacked(pathBankVisited).getOrDefault(neighborPacked,
					TransportAvailability.EMPTY_TRANSPORTS);
				for (Transport transport : neighborTransports)
				{
					if (transport.getOrigin() == Transport.UNDEFINED_ORIGIN
						|| !(transport.isUsableAtWildernessLevel(wildernessLevel))
						|| visited.get(transport.getOrigin(), pathBankVisited))
					{
						continue;
					}
					neighbors.add(graph.createTile(transport.getOrigin(), node, pathBankVisited));
				}
			}
		}

		return neighbors;
	}

	// The only abstract nodes are currently for global teleports
	private PrimitiveIntList getAbstractNodeNeighbors(int node, VisitedTiles visited, PathfinderConfig config,
		boolean targetInWilderness, NodeGraph graph)
	{
		neighbors.clear();
		int sourceTile = graph.getClosestTilePosition(node);
		boolean bankVisited = graph.bankVisited(node);
		int maxWildernessLevel = graph.abstractKind(node).maxWildernessLevel();
		for (Transport transport : config.getUsableTeleports(bankVisited))
		{
			boolean delayedVisit = transport.getType().sharesDestinationsWith() != null;
			if (!delayedVisit && visited.get(transport.getDestination(), bankVisited))
			{
				continue;
			}
			if (!transport.isUsableAtWildernessLevel(maxWildernessLevel))
			{
				continue;
			}
			if (config.avoidWilderness(sourceTile, transport.getDestination(), targetInWilderness))
			{
				continue;
			}
			// The differential cost is only used for priority-queue ordering (compareCost), not
			// propagated as real cost, so applying it unconditionally is safe: a nearby partner
			// station can still win the dequeue race, and a far-away whistle still resolves as the
			// cheapest path because no competitor has a lower real cost to the same destination.
			int differentialCost = delayedVisit ? config.getDifferentialCost(transport) : 0;
			neighbors.add(graph.createTransport(
				transport.getDestination(),
				node,
				transport.getDuration(),
				config.getAdditionalTransportCost(transport),
				bankVisited,
				delayedVisit,
				differentialCost,
				transport));
		}
		return neighbors;
	}
}

package shortestpath.pathfinder;

import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.IntPredicate;
import java.util.function.Supplier;
import shortestpath.leagues.LeagueModeState;
import shortestpath.pathfinder.exact.ExactForwardSearch;
import shortestpath.pathfinder.exact.ExactRoute;
import shortestpath.pathfinder.exact.ExactRoutingSession;
import shortestpath.pathfinder.exact.ExactWalkCanonicalizer;
import shortestpath.pathfinder.exact.InGameWalkRewriter;
import shortestpath.pathfinder.exact.PreparedRoutingAccount;
import shortestpath.pathfinder.exact.PreparedTarget;
import shortestpath.pathfinder.exact.RoutingStatic;
import shortestpath.pathfinder.exact.SearchRestrictions;
import shortestpath.pathfinder.exact.SiteGraph;

/** ActiveSearch adapter for the exact core. */
public final class ExactPathfinder implements ActiveSearch
{
	private final PathfinderStats stats = new PathfinderStats();
	private final int start;
	private final Set<Integer> targets;
	// The tiles the prepared target actually terminates on: the requested
	// targets plus each blocked target's fallback tiles, resolved the same way
	// the legacy backend resolves them (issue #640). {@link #targets} stays the
	// requested set for reporting and restart equality.
	private final Set<Integer> goals;
	private final boolean hasViableGoal;
	private final Runnable completionCallback;
	private final CollisionMap collision;
	private final Supplier<RoutingStatic> routingStatic;
	private final ExactRoutingSession session;
	private final PreparedRoutingAccount account;
	private final SearchRestrictions restrictions;
	private final long cutoffMillis;
	private final double heuristicWeight;
	private final long accountPrepareNanos;
	private volatile long routingStaticNanos;
	private volatile long graphPrepareNanos;
	private final String failure;
	private volatile boolean cancelled;
	private volatile boolean done;
	private volatile List<PathStep> path;
	private volatile List<PathStep> provisionalPath;
	private volatile PathfinderResult result;
	private volatile ExactForwardSearch.Counters exactStats;
	private volatile long reverseSearchNanos;
	private volatile long heuristicPrepareNanos;
	private volatile long forwardSearchNanos;
	private volatile long walkCanonicalizeNanos;
	private volatile List<ExactWalkCanonicalizer.Diagnostic> walkDiagnostics = List.of();
	private volatile long walkRewriteNanos;
	private volatile List<Integer> clickPoints = List.of();
	private volatile List<Integer> keptStepIndices = List.of();
	private volatile boolean graphReused;
	private volatile boolean targetReused;

	public ExactPathfinder(PathfinderConfig config, RoutingStatic routingStatic, int start, Set<Integer> targets,
		Runnable completionCallback)
	{
		this(config, constant(routingStatic), start, targets, completionCallback);
	}

	public ExactPathfinder(PathfinderConfig config, RoutingStatic routingStatic, int start, Set<Integer> targets,
		Runnable completionCallback, double heuristicWeight)
	{
		this(config, constant(routingStatic), start, targets, completionCallback, heuristicWeight);
	}

	/**
	 * Creates a search whose static routing data is obtained from {@code routingStatic} when the
	 * search runs, so a first-use build happens on the pathfinding thread rather than here.
	 */
	public ExactPathfinder(PathfinderConfig config, Supplier<RoutingStatic> routingStatic, int start,
		Set<Integer> targets, Runnable completionCallback)
	{
		this(config, routingStatic, start, targets, completionCallback,
			config == null ? 1 : config.getExactHeuristicWeight());
	}

	public ExactPathfinder(PathfinderConfig config, Supplier<RoutingStatic> routingStatic, int start,
		Set<Integer> targets, Runnable completionCallback, double heuristicWeight)
	{
		this(config, routingStatic, null, start, targets, completionCallback, heuristicWeight);
	}

	/**
	 * Creates a search that reuses the account graph and prepared targets held by {@code session}
	 * across queries; {@code null} prepares everything for this search alone.
	 */
	public ExactPathfinder(PathfinderConfig config, Supplier<RoutingStatic> routingStatic,
		ExactRoutingSession session, int start, Set<Integer> targets, Runnable completionCallback)
	{
		this(config, routingStatic, session, start, targets, completionCallback,
			config == null ? 1 : config.getExactHeuristicWeight());
	}

	public ExactPathfinder(PathfinderConfig config, RoutingStatic routingStatic, ExactRoutingSession session,
		int start, Set<Integer> targets, Runnable completionCallback, double heuristicWeight)
	{
		this(config, constant(routingStatic), session, start, targets, completionCallback, heuristicWeight);
	}

	public ExactPathfinder(PathfinderConfig config, Supplier<RoutingStatic> routingStatic,
		ExactRoutingSession session, int start, Set<Integer> targets, Runnable completionCallback,
		double heuristicWeight)
	{
		if (config == null || routingStatic == null || targets == null) throw new NullPointerException();
		if (!(heuristicWeight > 0) || !Double.isFinite(heuristicWeight))
			throw new IllegalArgumentException("heuristic weight must be positive and finite");
		this.start = start;
		this.targets = Set.copyOf(targets);
		this.completionCallback = completionCallback;
		this.collision = config.getMap();
		this.routingStatic = routingStatic;
		this.session = session == null ? new ExactRoutingSession() : session;
		long phaseStarted = System.nanoTime();
		this.account = config.prepareExactRoutingAccount(true);
		this.accountPrepareNanos = System.nanoTime() - phaseStarted;
		this.restrictions = restrictions(config, this.targets);
		TargetGoals resolved = TargetGoals.resolve(config, start, this.targets);
		this.goals = resolved.goals();
		this.hasViableGoal = resolved.hasViableGoal();
		this.cutoffMillis = config.getCalculationCutoffMillis();
		this.heuristicWeight = heuristicWeight;
		this.failure = null;
		this.path = List.of(new PathStep(start, false));
	}

	private static Supplier<RoutingStatic> constant(RoutingStatic routingStatic)
	{
		if (routingStatic == null) throw new NullPointerException();
		return () -> routingStatic;
	}

	/**
	 * The same positional gates legacy checks per edge: {@code avoidWilderness} and the league's
	 * always-blocked region, each lifted when a target lies inside the gated area (the user asked
	 * for that tile, so the route must be allowed to reach it).
	 */
	private static SearchRestrictions restrictions(PathfinderConfig config, Set<Integer> targets)
	{
		boolean avoidWilderness = config.isAvoidWilderness() && !WildernessChecker.isInWilderness(targets);
		LeagueModeState league = config.getLeagueModeState();
		IntPredicate blockedRegion = null;
		if (league != null && league.isSeasonal())
		{
			boolean targetInBlockedRegion = false;
			for (int target : targets)
			{
				targetInBlockedRegion |= league.isInBlockedRegion(target);
			}
			if (!targetInBlockedRegion)
			{
				blockedRegion = league::isInBlockedRegion;
			}
		}
		return SearchRestrictions.of(avoidWilderness, blockedRegion);
	}

	private ExactPathfinder(int start, Set<Integer> targets, Runnable completionCallback, String failure)
	{
		this.start = start;
		this.targets = Set.copyOf(targets);
		this.completionCallback = completionCallback;
		this.collision = null;
		this.routingStatic = null;
		this.session = null;
		this.account = null;
		this.restrictions = SearchRestrictions.none();
		this.goals = this.targets;
		this.hasViableGoal = false;
		this.cutoffMillis = 0;
		this.heuristicWeight = 1;
		this.accountPrepareNanos = 0;
		this.failure = failure;
		this.path = List.of(new PathStep(start, false));
	}

	public static ExactPathfinder failed(int start, Set<Integer> targets, Runnable completionCallback, Throwable error)
	{
		String detail = error.getMessage();
		return new ExactPathfinder(start, targets, completionCallback,
			"Exact backend unavailable: " + (detail == null ? error.getClass().getSimpleName() : detail));
	}

	@Override
	public void cancel()
	{
		cancelled = true;
	}

	@Override
	public int getStart()
	{ return start;
	}

	@Override
	public Set<Integer> getTargets()
	{ return targets;
	}

	@Override
	public List<PathStep> getPath()
	{
		List<PathStep> shown = provisionalPath;
		return shown != null ? shown : path;
	}

	/**
	 * Shows {@code previous} as this search's path until the search completes, so recalculating a
	 * route keeps the old one on screen instead of collapsing it to the start tile. Call before
	 * running the search; a cancelled search keeps showing it.
	 */
	public void showUntilDone(List<PathStep> previous)
	{
		provisionalPath = previous == null || previous.size() < 2 ? null : List.copyOf(previous);
	}

	/** Whether {@link #getPath()} is still the previous route passed to {@link #showUntilDone}. */
	public boolean isShowingProvisionalPath()
	{
		return provisionalPath != null;
	}

	@Override
	public boolean isDone()
	{ return done;
	}

	@Override
	public PathfinderResult getResult()
	{
		return stats.started && stats.ended ? result : null;
	}

	@Override
	public PathfinderStats getStats()
	{
		return stats.started && stats.ended ? stats : null;
	}

	/** Completed exact-search counters, or {@code null} while the search is running. */
	public ExactForwardSearch.Counters getExactStats()
	{
		return stats.started && stats.ended ? exactStats : null;
	}

	public long getAccountPrepareNanos()
	{ return accountPrepareNanos;
	}

	public long getRoutingStaticNanos()
	{ return routingStaticNanos;
	}

	public long getGraphPrepareNanos()
	{ return graphPrepareNanos;
	}

	public long getReverseSearchNanos()
	{ return reverseSearchNanos;
	}

	public long getHeuristicPrepareNanos()
	{ return heuristicPrepareNanos;
	}

	public long getForwardSearchNanos()
	{ return forwardSearchNanos;
	}

	/** Time spent choosing each walking leg's canonical walk. */
	public long getWalkCanonicalizeNanos()
	{ return walkCanonicalizeNanos;
	}

	/**
	 * Walking legs that kept the search's own walk because the canonicaliser disagreed with the
	 * route about them; empty when every leg was canonicalised.
	 */
	public List<ExactWalkCanonicalizer.Diagnostic> getWalkDiagnostics()
	{ return walkDiagnostics;
	}

	/** Time spent rewriting the canonical walking legs into the game's own walking paths. */
	public long getWalkRewriteNanos()
	{ return walkRewriteNanos;
	}

	/**
	 * Ascending indices into the route's steps of the tiles the player clicks to walk it in game;
	 * empty until a route is found.
	 */
	public List<Integer> getClickPoints()
	{ return clickPoints;
	}

	/**
	 * Ascending indices into the route's steps of the walking steps that kept the canonical step
	 * because no in-game click realises them; empty until a route is found.
	 */
	public List<Integer> getKeptStepIndices()
	{ return keptStepIndices;
	}

	/** Whether the account graph came from the session rather than being built for this search. */
	public boolean isGraphReused()
	{ return graphReused;
	}

	/** Whether this search's target set was already prepared in the session. */
	public boolean isTargetReused()
	{ return targetReused;
	}

	@Override
	public void run()
	{
		stats.start();
		long started = System.nanoTime();
		try
		{
			if (failure != null)
			{
				exactStats = ExactForwardSearch.Counters.empty();
				result = new PathfinderResult(start, firstTarget(), false, path, start, PathfinderResult.NO_PATH_COST,
					0, 0, System.nanoTime() - started, PathTerminationReason.BACKEND_FAILURE, failure);
				return;
			}
			long phaseStarted = System.nanoTime();
			RoutingStatic staticData = routingStatic.get();
			routingStaticNanos = System.nanoTime() - phaseStarted;
			phaseStarted = System.nanoTime();
			ExactRoutingSession.Lookup<SiteGraph> graph = session.graph(staticData, account);
			graphPrepareNanos = System.nanoTime() - phaseStarted;
			graphReused = graph.reused();
			AtomicBoolean timedOut = new AtomicBoolean();
			// A zero cutoff means no cutoff for the exact backend.
			SearchDeadline deadline = cutoffMillis > 0 ? new SearchDeadline(cutoffMillis) : null;
			int[] packedTargets = goals.stream().mapToInt(Integer::intValue).toArray();
			ExactForwardSearch.Result best = null;
			int bestTarget = firstTarget();
			int partialCost = PathfinderResult.NO_PATH_COST;
			exactStats = ExactForwardSearch.Counters.empty();
			// When every target is a blocked tile that no transport lands on and
			// no walkable tile exists within the unreachable distance, no state can
			// satisfy the goal set — skip the search like the legacy backend does.
			if (!cancelled && hasViableGoal && packedTargets.length != 0)
			{
				// One search towards every target at once; it ends at the cheapest one to reach.
				phaseStarted = System.nanoTime();
				ExactRoutingSession.Lookup<PreparedTarget> prepared = session.target(graph.value(), collision,
					packedTargets);
				targetReused = prepared.reused();
				if (targetReused)
				{
					heuristicPrepareNanos = System.nanoTime() - phaseStarted;
				}
				else
				{
					reverseSearchNanos = prepared.value().reverseSearchNanos();
					heuristicPrepareNanos = prepared.value().heuristicPrepareNanos();
				}
				phaseStarted = System.nanoTime();
				ExactForwardSearch.Result current = prepared.value().search(start,
					() ->
					{
						if (cancelled) return true;
						if (deadline != null && deadline.expired())
						{
							timedOut.set(true);
							return true;
						}
						return false;
					}, heuristicWeight, restrictions, deadline == null ? ExactForwardSearch.NO_PROGRESS : deadline::progressed);
				forwardSearchNanos = System.nanoTime() - phaseStarted;
				stats.nodesChecked += current.counters().statesPopped();
				stats.transportsChecked += current.counters().transportCandidates();
				exactStats = current.counters();
				ExactRoute found = null;
				if (current.reached())
				{
					best = current;
					found = current.route();
				}
				else if (timedOut.get() && !cancelled)
				{
					// Like legacy: a cut-off search still routes to the tile it got closest to.
					found = current.closestRoute();
					partialCost = current.closestCost();
				}
				if (found != null)
				{
					// Publish only the final path, so the render thread never shows the raw one. First
					// pick each walking leg's canonical walk among the equally cheap ones, then turn it
					// into the clicks along it and the paths the game's own walking takes between them.
					phaseStarted = System.nanoTime();
					ExactWalkCanonicalizer.Result canonical = new ExactWalkCanonicalizer(collision, account,
						restrictions).canonicalize(found);
					walkCanonicalizeNanos = System.nanoTime() - phaseStarted;
					walkDiagnostics = canonical.diagnostics();
					phaseStarted = System.nanoTime();
					InGameWalkRewriter.Result walked = new InGameWalkRewriter(collision, restrictions).rewrite(canonical);
					walkRewriteNanos = System.nanoTime() - phaseStarted;
					clickPoints = walked.clickPoints();
					keptStepIndices = walked.keptStepIndices();
					path = walked.path();
					if (best != null) bestTarget = last(path);
				}
			}

			if (cancelled)
				result = new PathfinderResult(start, firstTarget(), false, List.of(new PathStep(start, false)), start,
					PathfinderResult.NO_PATH_COST, stats.nodesChecked, stats.transportsChecked, System.nanoTime() - started,
					PathTerminationReason.CANCELLED);
			else if (timedOut.get())
				result = new PathfinderResult(start, bestTarget, best != null, path,
					last(path), best == null ? partialCost : best.cost(), stats.nodesChecked,
					stats.transportsChecked, System.nanoTime() - started, PathTerminationReason.CUTOFF_REACHED);
			else if (best != null)
				result = new PathfinderResult(start, bestTarget, true, path, last(path), best.cost(), stats.nodesChecked,
					stats.transportsChecked, System.nanoTime() - started, PathTerminationReason.TARGET_REACHED);
			else
				result = new PathfinderResult(start, firstTarget(), false, path, last(path), PathfinderResult.NO_PATH_COST,
					stats.nodesChecked, stats.transportsChecked, System.nanoTime() - started,
					PathTerminationReason.SEARCH_EXHAUSTED);
		}
		// Errors too: the static build allocates the large search arrays, where OOM is the most
		// plausible fatal failure; an uncaught Error would leave result null and display as
		// "unreachable" rather than a backend failure. Matches runQuery's catch.
		catch (RuntimeException | Error error)
		{
			exactStats = exactStats == null ? ExactForwardSearch.Counters.empty() : exactStats;
			result = new PathfinderResult(start, firstTarget(), false, path, last(path), PathfinderResult.NO_PATH_COST,
				stats.nodesChecked, stats.transportsChecked, System.nanoTime() - started,
				PathTerminationReason.BACKEND_FAILURE,
				"Exact backend failed: " + (error.getMessage() == null ? error.getClass().getSimpleName() : error.getMessage()));
		}
		finally
		{
			if (!cancelled) provisionalPath = null;
			done = !cancelled;
			stats.end();
			if (completionCallback != null) completionCallback.run();
		}
	}

	private int firstTarget()
	{
		return targets.stream().min(Integer::compareUnsigned).orElse(Integer.MIN_VALUE);
	}

	private static int last(List<PathStep> steps)
	{
		return steps.isEmpty() ? Integer.MIN_VALUE : steps.get(steps.size() - 1).getPackedPosition();
	}
}

package shortestpath.pathfinder;

import java.io.IOException;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import shortestpath.Destination;
import shortestpath.pathfinder.exact.RoutingCuts;
import shortestpath.pathfinder.exact.RoutingStatic;
import shortestpath.pathfinder.exact.RoutingStaticBuilder;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportLoader;

/**
 * Builds the exact backend's static routing data once per plugin session, on first use.
 *
 * <p>The build runs on whichever thread first calls {@link #get()} (the pathfinding executor in
 * the plugin), never on the client thread. A failed build is remembered and rethrown so a broken
 * resource does not trigger a rebuild on every query.
 */
@Slf4j
public final class ExactRoutingStaticProvider implements Supplier<RoutingStatic>
{
	private final Supplier<CollisionMap> collision;
	private RoutingStatic routingStatic;
	private RuntimeException failure;
	private RoutingStaticBuilder.Diagnostics diagnostics;

	public ExactRoutingStaticProvider(Supplier<CollisionMap> collision)
	{
		this.collision = Objects.requireNonNull(collision, "collision");
	}

	@Override
	public synchronized RoutingStatic get()
	{
		if (routingStatic != null) return routingStatic;
		if (failure != null) throw failure;
		try
		{
			Map<Integer, Set<Transport>> transports = TransportLoader.loadAllFromResources();
			Set<Integer> banks = Destination.loadAllFromResources().get("bank");
			RoutingCuts cuts = RoutingCuts.loadFromResources();
			if (cuts.cutCount() == 0)
			{
				log.warn("{} is missing or empty; building exact routing data without cuts",
					RoutingCuts.RESOURCE);
			}
			RoutingStaticBuilder.Result result = RoutingStaticBuilder.build(collision.get(), transports,
				banks == null ? Set.of() : banks, cuts.pairs());
			diagnostics = result.diagnostics;
			routingStatic = result.routingStatic;
			log.debug("Built exact routing data with cuts for collision map {}: {}",
				Long.toHexString(cuts.collisionFingerprint()), diagnostics);
			return routingStatic;
		}
		catch (IOException error)
		{
			failure = new IllegalStateException("cannot build exact routing data", error);
			throw failure;
		}
		catch (RuntimeException error)
		{
			failure = error;
			throw error;
		}
	}

	/** Diagnostics from the completed build, or {@code null} before the first successful build. */
	public synchronized RoutingStaticBuilder.Diagnostics getDiagnostics()
	{
		return diagnostics;
	}
}

package shortestpath.pathfinder;

/**
 * A minimal growable FIFO of primitive {@code int} node ids backed by a ring buffer.
 * <p>
 * Replaces the {@code ArrayDeque<Node>} boundary queue in {@link Pathfinder} so the search frontier
 * no longer boxes node references. Only the operations the pathfinder needs are implemented; it is
 * single-threaded (worker only) like the queue it replaces.
 */
class IntDeque
{
	private int[] elements;
	private int head;
	private int tail;
	private int size;

	IntDeque(int initialCapacity)
	{
		elements = new int[Math.max(1, initialCapacity)];
	}

	int size()
	{
		return size;
	}

	boolean isEmpty()
	{
		return size == 0;
	}

	void addLast(int value)
	{
		if (size == elements.length)
		{
			grow();
		}
		elements[tail] = value;
		tail = increment(tail);
		size++;
	}

	void addFirst(int value)
	{
		if (size == elements.length)
		{
			grow();
		}
		head = decrement(head);
		elements[head] = value;
		size++;
	}

	/**
	 * @return the first element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int peekFirst()
	{
		return size == 0 ? NodeGraph.NO_NODE : elements[head];
	}

	/**
	 * @return the removed first element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int pollFirst()
	{
		if (size == 0)
		{
			return NodeGraph.NO_NODE;
		}
		final int value = elements[head];
		head = increment(head);
		size--;
		return value;
	}

	void clear()
	{
		head = 0;
		tail = 0;
		size = 0;
	}

	private int increment(int index)
	{
		return index + 1 == elements.length ? 0 : index + 1;
	}

	private int decrement(int index)
	{
		return index == 0 ? elements.length - 1 : index - 1;
	}

	private void grow()
	{
		final int oldCapacity = elements.length;
		final int[] grown = new int[oldCapacity << 1];
		for (int i = 0; i < size; i++)
		{
			grown[i] = elements[(head + i) % oldCapacity];
		}
		elements = grown;
		head = 0;
		tail = size;
	}
}

package shortestpath.pathfinder;

import java.util.Arrays;

/**
 * A binary min-heap of primitive {@code int} node ids ordered by {@link NodeGraph#compareCost}.
 * <p>
 * Replaces the {@code PriorityQueue<TransportNode>} pending queue in {@link Pathfinder} so transport
 * candidates are stored as int ids rather than boxed node objects. The ordering key is fixed when a
 * node is created (its differential cost never changes), so no decrease-key support is needed; the
 * pathfinder discards stale cheaper duplicates with its dequeue-time visited re-check. Single-threaded
 * (worker only), matching the queue it replaces.
 */
class IntMinHeap
{
	private final NodeGraph graph;
	private int[] heap;
	private int size;

	IntMinHeap(NodeGraph graph, int initialCapacity)
	{
		this.graph = graph;
		this.heap = new int[Math.max(1, initialCapacity)];
	}

	int size()
	{
		return size;
	}

	boolean isEmpty()
	{
		return size == 0;
	}

	/**
	 * @return the minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int peek()
	{
		return size == 0 ? NodeGraph.NO_NODE : heap[0];
	}

	void add(int id)
	{
		if (size == heap.length)
		{
			heap = Arrays.copyOf(heap, heap.length << 1);
		}
		heap[size] = id;
		siftUp(size);
		size++;
	}

	/**
	 * @return the removed minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int poll()
	{
		if (size == 0)
		{
			return NodeGraph.NO_NODE;
		}
		final int top = heap[0];
		size--;
		if (size > 0)
		{
			heap[0] = heap[size];
			siftDown(0);
		}
		return top;
	}

	void clear()
	{
		size = 0;
	}

	private void siftUp(int index)
	{
		final int id = heap[index];
		final int key = graph.compareCost(id);
		while (index > 0)
		{
			final int parent = (index - 1) >> 1;
			if (key >= graph.compareCost(heap[parent]))
			{
				break;
			}
			heap[index] = heap[parent];
			index = parent;
		}
		heap[index] = id;
	}

	private void siftDown(int index)
	{
		final int id = heap[index];
		final int key = graph.compareCost(id);
		final int half = size >> 1;
		while (index < half)
		{
			int child = (index << 1) + 1;
			int childKey = graph.compareCost(heap[child]);
			final int right = child + 1;
			if (right < size)
			{
				final int rightKey = graph.compareCost(heap[right]);
				if (rightKey < childKey)
				{
					child = right;
					childKey = rightKey;
				}
			}
			if (key <= childKey)
			{
				break;
			}
			heap[index] = heap[child];
			index = child;
		}
		heap[index] = id;
	}
}

package shortestpath.pathfinder;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;

/**
 * Structure-of-Arrays store for pathfinding nodes.
 * <p>
 * The previous design allocated one {@link Object} per explored tile (a {@code Node} or
 * {@code TransportNode}). Heavy searches explore hundreds of thousands of tiles, so this produced
 * hundreds of thousands of live objects, each carrying a ~16-byte header plus several object
 * references (issue #491). Here every node is instead an {@code int} index into parallel primitive
 * arrays, so a whole search holds only a handful of arrays regardless of how many nodes it visits.
 * <p>
 * The fields packed per node are exactly those of the old {@code Node}/{@code TransportNode}:
 * packed world position, the index of the previous node ({@link #NO_NODE} for the start),
 * accumulated cost, the transport differential cost (queue-ordering only), a set of boolean flags,
 * and the {@link AbstractNodeKind} ordinal for abstract nodes — plus the {@link Transport}
 * that produced a transport edge, so consumers can identify which transport the path actually
 * used instead of reconstructing it from origin/destination (ambiguous on shared-destination
 * transports).
 * <p>
 * <strong>Threading.</strong> The search runs on a single worker thread, but the render thread
 * reads the partial path while the search is still running (progressive rendering via
 * {@code Pathfinder.getPath()}). Node data is write-once and is published to the render thread by
 * the single volatile {@code Pathfinder.bestLastNode} handoff rather than by marking these arrays
 * {@code volatile} (which would cripple the hot loop, see the field comment). The chain walks
 * ({@link #getPathSteps} / {@link #getClosestTilePosition}) snapshot the arrays into locals and
 * tolerate an index that is out of bounds or released. This means a walk concurrent with a
 * grow/release can never throw; at worst it yields a one-frame-stale path.
 */
public class NodeGraph
{
	public static final int NO_NODE = -1;

	private static final byte FLAG_BANK_VISITED = 1;       // bit0
	private static final byte FLAG_ABSTRACT = 1 << 1;      // bit1
	private static final byte FLAG_DELAYED_VISIT = 1 << 2; // bit2
	private static final byte FLAG_TRANSPORT = 1 << 3;     // bit3
	private static final byte FLAG_BANK_VISIT = 1 << 4;    // bit4

	// Enum.values() copies on every call, so cache it for the abstractKind lookup.
	private static final AbstractNodeKind[] ABSTRACT_KINDS = AbstractNodeKind.values();

	// The node arrays are NOT volatile: making them volatile forces every accessor (packedPosition,
	// cost, isTile, compareCost, the append() writes, ...) to re-read the array reference on each
	// call and blocks the JIT from caching the base in a register or eliminating bounds checks. The
	// hot loop touches these hundreds of times per node, so volatile reads roughly halved field
	// throughput (~1.6x slower searches). Safe publication to the render thread is provided instead
	// by the single volatile Pathfinder.bestLastNode handoff: the worker writes the node data, then
	// volatile-writes bestLastNode; the render thread volatile-reads bestLastNode before walking,
	// which establishes happens-before for all the plain writes above it. The walk methods snapshot
	// the references into locals and tolerate a null (post-release) or stale-but-valid (mid-grow,
	// Arrays.copyOf preserves every index) array, so a concurrent grow/release never throws.
	private int[] packedPosition;
	private int[] previous;
	private int[] cost;
	private int[] differentialCost;
	private byte[] flags;
	private byte[] abstractKind;
	private Transport[] transports;
	private int size;

	public NodeGraph(int initialCapacity)
	{
		final int capacity = Math.max(1, initialCapacity);
		packedPosition = new int[capacity];
		previous = new int[capacity];
		cost = new int[capacity];
		differentialCost = new int[capacity];
		flags = new byte[capacity];
		abstractKind = new byte[capacity];
		transports = new Transport[capacity];
	}

	public int size()
	{
		return size;
	}

	private void ensureCapacity()
	{
		if (size < packedPosition.length)
		{
			return;
		}
		// Grow by 50% like ArrayList. Arrays.copyOf preserves every existing index, and node data
		// is write-once, so a render thread reading a pre-grow array still sees correct values for
		// the indices it walks.
		final int newCapacity = packedPosition.length + (packedPosition.length >> 1);
		packedPosition = Arrays.copyOf(packedPosition, newCapacity);
		previous = Arrays.copyOf(previous, newCapacity);
		cost = Arrays.copyOf(cost, newCapacity);
		differentialCost = Arrays.copyOf(differentialCost, newCapacity);
		flags = Arrays.copyOf(flags, newCapacity);
		abstractKind = Arrays.copyOf(abstractKind, newCapacity);
		transports = Arrays.copyOf(transports, newCapacity);
	}

	private int append(int packed, int prev, int nodeCost, int diffCost, byte flagBits, byte kind)
	{
		ensureCapacity();
		final int id = size;
		packedPosition[id] = packed;
		previous[id] = prev;
		cost[id] = nodeCost;
		differentialCost[id] = diffCost;
		abstractKind[id] = kind;
		flags[id] = flagBits;
		size = id + 1;
		return id;
	}

	private int costOf(int id)
	{
		return id == NO_NODE ? 0 : cost[id];
	}

	/**
	 * The search root. Carries no previous node and zero cost.
	 */
	public int createStart(int packedPosition)
	{
		return append(packedPosition, NO_NODE, 0, 0, (byte) 0, (byte) 0);
	}

	/**
	 * A concrete walkable tile. Travel cost is the walking distance from the previous node, but
	 * only when the previous node is itself a tile (mirrors the old {@code Node.cost}); reaching a
	 * tile from an abstract node adds no travel cost.
	 */
	public int createTile(int packedPosition, int previous, boolean bankVisited)
	{
		final int travelTime = (previous != NO_NODE && isTile(previous))
			? WorldPointUtil.distanceBetween(this.packedPosition[previous], packedPosition)
			: 0;
		final byte flagBits = bankVisited ? FLAG_BANK_VISITED : 0;
		return append(packedPosition, previous, costOf(previous) + travelTime, 0, flagBits, (byte) 0);
	}

	/**
	 * A transport destination tile. Cost is the previous cost plus the transport's travel time and
	 * any additional cost; there is no walking-distance term (mirrors the old {@code TransportNode}).
	 * The chosen {@link Transport} is stored on the node so the reconstructed path can report
	 * which transport produced the edge.
	 */
	public int createTransport(int packedPosition, int previous, int travelTime, int additionalCost,
		boolean bankVisited, boolean delayedVisit, int differentialCost, Transport transport)
	{
		byte flagBits = FLAG_TRANSPORT;
		if (bankVisited)
		{
			flagBits |= FLAG_BANK_VISITED;
		}
		if (delayedVisit)
		{
			flagBits |= FLAG_DELAYED_VISIT;
		}
		final int id = append(packedPosition, previous, costOf(previous) + travelTime + additionalCost,
			differentialCost, flagBits, (byte) 0);
		transports[id] = transport;
		return id;
	}

	/**
	 * The paid transition into the banked state. Emitted from a bank-accessible tile when the
	 * path has not banked yet: the node stays on the same position and carries the configured
	 * bank visit cost, so the penalty is charged once on the decision to bank rather than on
	 * the edges leaving the bank tile.
	 * <p>
	 * The node is flagged as a transport even though no real transport exists: {@link
	 * Pathfinder#addNeighbors} routes transport-flagged nodes to the cost-ordered pending
	 * heap instead of the FIFO tile boundary queue, which is only correct for unit-cost
	 * walking edges. A costed transition must go through the heap or nodes would no longer
	 * be expanded in increasing cost order.
	 */
	public int createBankVisit(int packedPosition, int previous, int bankVisitCost)
	{
		return append(packedPosition, previous, costOf(previous) + bankVisitCost, 0,
			(byte) (FLAG_TRANSPORT | FLAG_BANK_VISITED | FLAG_BANK_VISIT), (byte) 0);
	}

	/**
	 * An abstract search-state node (global teleports). Has no world position and inherits the
	 * previous node's cost (mirrors the old {@code Node.abstractNode}).
	 */
	public int createAbstract(AbstractNodeKind abstractKind, int previous, boolean bankVisited)
	{
		byte flagBits = FLAG_ABSTRACT;
		if (bankVisited)
		{
			flagBits |= FLAG_BANK_VISITED;
		}
		return append(WorldPointUtil.UNDEFINED, previous, costOf(previous), 0, flagBits,
			(byte) abstractKind.ordinal());
	}

	public int packedPosition(int id)
	{
		return packedPosition[id];
	}

	public int previous(int id)
	{
		return previous[id];
	}

	public int cost(int id)
	{
		return cost[id];
	}

	public int differentialCost(int id)
	{
		return differentialCost[id];
	}

	/**
	 * The cost used for priority-queue ordering, includes the transport differential.
	 */
	public int compareCost(int id)
	{
		return cost[id] + differentialCost[id];
	}

	public boolean bankVisited(int id)
	{
		return (flags[id] & FLAG_BANK_VISITED) != 0;
	}

	public boolean isTile(int id)
	{
		return (flags[id] & FLAG_ABSTRACT) == 0;
	}

	public boolean isAbstract(int id)
	{
		return (flags[id] & FLAG_ABSTRACT) != 0;
	}

	public boolean isTransport(int id)
	{
		return (flags[id] & FLAG_TRANSPORT) != 0;
	}

	public boolean isDelayedVisit(int id)
	{
		return (flags[id] & FLAG_DELAYED_VISIT) != 0;
	}

	/**
	 * The transport that produced the edge into {@code id}, or null for walking edges,
	 * bank-visit transitions and the start node.
	 */
	public Transport transport(int id)
	{
		return transports[id];
	}

	public AbstractNodeKind abstractKind(int id)
	{
		return ABSTRACT_KINDS[abstractKind[id]];
	}

	/**
	 * Walks the previous chain from {@code id} to the start, collecting the tile nodes into an
	 * ordered list of path steps. Abstract nodes are skipped, and so are bank-visit
	 * transitions: a bank visit is a state change, not a movement step — the tile the player
	 * banked at is already in the path as the preceding step.
	 * <p>
	 * Safe to call from the render thread during the search: the arrays are snapshotted into locals
	 * and the walk is bounds-tolerant, so a concurrent grow or {@link #release()} yields an empty
	 * or one-frame-stale result rather than throwing.
	 */
	public List<PathStep> getPathSteps(int id)
	{
		final int[] prev = previous;
		final int[] packed = packedPosition;
		final byte[] flg = flags;
		final Transport[] trans = transports;
		if (prev == null || packed == null || flg == null || trans == null || id == NO_NODE)
		{
			return new ArrayList<>();
		}
		final int len = prev.length;

		int node = id;
		int n = 0;
		while (node != NO_NODE && node < len)
		{
			if ((flg[node] & (FLAG_ABSTRACT | FLAG_BANK_VISIT)) == 0)
			{
				n++;
			}
			node = prev[node];
		}

		final List<PathStep> pathSteps = new ArrayList<>(n);
		for (int i = 0; i < n; i++)
		{
			pathSteps.add(null);
		}

		node = id;
		int i = n;
		while (node != NO_NODE && node < len && i > 0)
		{
			if ((flg[node] & (FLAG_ABSTRACT | FLAG_BANK_VISIT)) == 0)
			{
				pathSteps.set(--i, new PathStep(packed[node], (flg[node] & FLAG_BANK_VISITED) != 0,
					trans[node]));
			}
			node = prev[node];
		}

		return pathSteps;
	}

	/**
	 * Walks the previous chain from {@code id} until the first tile node and returns its packed
	 * position, or {@link WorldPointUtil#UNDEFINED} if none. Same threading guarantees as
	 * {@link #getPathSteps}.
	 */
	public int getClosestTilePosition(int id)
	{
		final int[] prev = previous;
		final int[] packed = packedPosition;
		final byte[] flg = flags;
		if (prev == null || packed == null || flg == null)
		{
			return WorldPointUtil.UNDEFINED;
		}
		final int len = prev.length;
		int node = id;
		while (node != NO_NODE && node < len && (flg[node] & FLAG_ABSTRACT) != 0)
		{
			node = prev[node];
		}
		return (node != NO_NODE && node < len) ? packed[node] : WorldPointUtil.UNDEFINED;
	}

	/**
	 * Releases the backing arrays once the search is finished and the final path has been
	 * materialised, so the large per-search working set becomes eligible for garbage collection
	 * (the old design dropped the explored {@code Node} objects the same way by clearing the
	 * frontier collections). A render-thread walk in flight keeps its own local references and
	 * finishes safely.
	 */
	public void release()
	{
		packedPosition = null;
		previous = null;
		cost = null;
		differentialCost = null;
		flags = null;
		abstractKind = null;
		transports = null;
		size = 0;
	}
}

package shortestpath.pathfinder;

public enum OrdinalDirection
{
	WEST(-1, 0),
	EAST(1, 0),
	SOUTH(0, -1),
	NORTH(0, 1),
	SOUTH_WEST(-1, -1),
	SOUTH_EAST(1, -1),
	NORTH_WEST(-1, 1),
	NORTH_EAST(1, 1);

	final int x;
	final int y;

	OrdinalDirection(int x, int y)
	{
		this.x = x;
		this.y = y;
	}
}

