		restrictedHeuristicZeroes, heuristicCacheHits, initialCapability, normalHeuristicEnabledAtStart);
	}
	}

	private static final class SearchSpace
	{
		private static final int STATUS_CLEAR = 1;
		private static final int STATUS_WILDERNESS = 2;
		private static final int STATUS_BLOCKED_REGION = 4;

		final RoutingStatic stat; final int[] extraTiles, extraSites; final int[][] extraComponents;
		final int baseCount, tileCount; private final PreparedRoutingAccount account;
		private SearchRestrictions restrictions = SearchRestrictions.none();
		/**
		 * Per-node gate status bits, computed on first ask: entering the wilderness or the blocked
		 * league region is asked about on every walking edge, so the lookups are memoised. Only
		 * allocated while a gate is active.
		 */
		private byte[] gateBits;
		static final int HEURISTIC_PAGE_BITS = 10;
		static final int HEURISTIC_PAGE_MASK = (1 << HEURISTIC_PAGE_BITS) - 1;
		/** Cache encoding of an infinite heuristic; other values are stored plus one, so 0 means absent. */
		static final int CACHED_INF = -1;
		/**
		 * Each tile state's heuristic, filled on first lookup. The heuristic depends only on the
		 * state, but the search asks for it at every improving relaxation, again when the state
		 * pops and for the banked twin of a bank-dominated state. Pages are allocated on first
		 * touch, so a search pays only for the regions it reaches.
		 */
		private int[][] heuristicPages;
		private SearchSpace(RoutingStatic stat, PreparedRoutingAccount account, int[] extraTiles,
			int[][] extraComponents, int[] extraSites)
	{ this.stat = stat; this.account = account; this.extraTiles = extraTiles; this.extraComponents = extraComponents;
		this.extraSites = extraSites; baseCount = stat.searchTileCount(); tileCount = baseCount + extraTiles.length;
	}
		static SearchSpace create(TargetOverlay target, int start, SearchRestrictions restrictions)
		{
			RoutingStatic stat = target.routingStatic(); int[] values = new int[stat.siteCount() + target.targetCount() + 1]; int count = 0;
			for (int site = 0; site < stat.siteCount(); site++) count = add(values, count, stat.siteTile(site), stat);
			for (int i = 0; i < target.targetCount(); i++) count = add(values, count, target.packedTarget(i), stat);
			count = add(values, count, start, stat);
			for (int i = 1; i < count; i++)
	{ int value = values[i], j = i - 1; while (j >= 0 && Integer.compareUnsigned(values[j], value) > 0) values[j + 1] = values[j--]; values[j + 1] = value;
	}
			int extraCount = 0; for (int i = 0; i < count; i++) if (stat.searchIndex(values[i]) < 0) values[extraCount++] = values[i];
			int[] extras = Arrays.copyOf(values, extraCount); int[][] components = new int[extraCount][];
			int[] sites = new int[extraCount];
			for (int i = 0; i < extraCount; i++)
	{ int tile = extras[i], site = stat.siteIndex(tile), targetIndex = target.targetIndex(tile); sites[i] = site;
		components[i] = targetIndex >= 0 ? target.componentsView(targetIndex) : site >= 0 ? stat.siteComponents(site) : stat.attachments(tile, target.collision());
	}
			SearchSpace space = new SearchSpace(stat, target.account(), extras, components, sites);
			space.restrictions = restrictions;
			if (restrictions.anyGate())
			{
				space.gateBits = new byte[space.tileCount];
			}
			return space;
		}
		private static int add(int[] values, int count, int value, RoutingStatic stat)
	{ if (stat.searchIndex(value) >= 0) return count; for (int i = 0; i < count; i++) if (values[i] == value) return count; values[count] = value; return count + 1;
	}
		int node(int tile)
	{ int base = stat.searchIndex(tile); if (base >= 0) return base; int extra = binarySearch(extraTiles, tile); return extra < 0 ? -1 : baseCount + extra;
	}
		int state(int tile, boolean banked)
	{ return stateForNode(node(tile), banked);
	}
		int tile(int node)
	{ return node < baseCount ? stat.searchTile(node) : extraTiles[node - baseCount];
	}
		int[] components(int node)
	{ return extraComponents[node - baseCount];
	}
		int[] heuristicPage(int state)
		{
			if (heuristicPages == null) heuristicPages = new int[((tileCount * 2) >> HEURISTIC_PAGE_BITS) + 1][];
			int index = state >> HEURISTIC_PAGE_BITS;
			int[] page = heuristicPages[index];
			if (page == null)
			{
				page = new int[1 << HEURISTIC_PAGE_BITS];
				heuristicPages[index] = page;
			}
			return page;
		}
		boolean isBase(int node)
	{ return node < baseCount;
	}
		/** A bank in the world (static topology) that this account may use (prepared account). */
		boolean isUsableBankNode(int node)
	{ return isBankNode(node) && account.bankAccessible(tile(node));
	}
		boolean isBankNode(int node)
	{ return node < baseCount ? stat.isBankNode(node) : stat.isBankSite(extraSites[node - baseCount]);
	}
		boolean bankGlobalRelevant()
		{ return account.allowTransports() && account.bankPathEnabled();
		}
		boolean hasLocalOrigin(int tile, boolean banked)
	{ PreparedRoutingAccount.View view = account.localView(banked); int index = lowerBound(view.origins, tile); return index < view.count && view.origins[index] == tile;
	}
		/** The node's wilderness/blocked-region status bits, computed on first ask. */
		private int gateStatus(int node)
		{
			int value = gateBits[node];
			if (value == 0)
			{
				int tile = tile(node);
				value = STATUS_CLEAR
					| (WildernessChecker.isInWilderness(tile) ? STATUS_WILDERNESS : 0)
					| (restrictions.inBlockedRegion(tile) ? STATUS_BLOCKED_REGION : 0);
				gateBits[node] = (byte) value;
			}
			return value;
		}
		/** Legacy's tile-to-tile gate: a step may not enter the wilderness or the blocked region. */
		boolean stepAllowed(int fromNode, int toNode)
		{
			if (gateBits == null) return true;
			int from = gateStatus(fromNode), to = gateStatus(toNode);
			return restrictions.stepAllowed((from & STATUS_WILDERNESS) != 0, (to & STATUS_WILDERNESS) != 0,
				(from & STATUS_BLOCKED_REGION) != 0, (to & STATUS_BLOCKED_REGION) != 0);
		}
		/** Whether a global cast with {@code capability} (the source band) may land on the tile. */
		boolean globalAllowed(TeleportCapability capability, int destination)
		{
			return restrictions.globalAllowed(capability, destination);
		}
		private static int binarySearch(int[] values, int target)
	{ int low = 0, high = values.length - 1; while (low <= high)
	{ int middle = low + (high - low) / 2, compare = Integer.compareUnsigned(values[middle], target); if (compare == 0) return middle; if (compare < 0) low = middle + 1; else high = middle - 1;
	} return -1;
	}
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;

/** Primitive duplicate-entry min-heap ordered by (priority, cost, state). */
public final class ExactMinHeap
{
	private int[] priorities, costs, states;
	private int size;
	private int poppedPriority, poppedCost, poppedState;

	public ExactMinHeap(int initialCapacity)
	{
		int capacity = Math.max(1, initialCapacity);
		priorities = new int[capacity];
		costs = new int[capacity];
		states = new int[capacity];
	}

	public int size()
	{
		return size;
	}
	public boolean isEmpty()
	{
		return size == 0;
	}
	public int priority()
	{
		return poppedPriority;
	}
	public int cost()
	{
		return poppedCost;
	}
	public int state()
	{
		return poppedState;
	}

	public void push(int priority, int cost, int state)
	{
		ExactCosts.validate(priority);
		ExactCosts.validate(cost);
		if (priority == ExactCosts.INF || cost == ExactCosts.INF)
			throw new IllegalArgumentException("infinite heap entries are not searchable");
		if (size == states.length)
		{
			int capacity = states.length < 1_073_741_824 ? states.length * 2 : Integer.MAX_VALUE;
			priorities = Arrays.copyOf(priorities, capacity);
			costs = Arrays.copyOf(costs, capacity);
			states = Arrays.copyOf(states, capacity);
		}
		priorities[size] = priority;
		costs[size] = cost;
		states[size] = state;
		siftUp(size++);
	}

	public boolean poll()
	{
		if (size == 0)
			return false;
		poppedPriority = priorities[0];
		poppedCost = costs[0];
		poppedState = states[0];
		--size;
		if (size != 0)
		{
			priorities[0] = priorities[size];
			costs[0] = costs[size];
			states[0] = states[size];
			siftDown(0);
		}
		return true;
	}

	private boolean before(int left, int right)
	{
		int result = Integer.compare(priorities[left], priorities[right]);
		if (result != 0)
			return result < 0;
		result = Integer.compare(costs[left], costs[right]);
		return result != 0 ? result < 0 : Integer.compare(states[left], states[right]) < 0;
	}

	private void siftUp(int index)
	{
		int priority = priorities[index], cost = costs[index], state = states[index];
		while (index > 0)
		{
			int parent = (index - 1) >>> 1;
			if (compare(priority, cost, state, priorities[parent], costs[parent], states[parent]) >= 0)
				break;
			priorities[index] = priorities[parent];
			costs[index] = costs[parent];
			states[index] = states[parent];
			index = parent;
		}
		priorities[index] = priority;
		costs[index] = cost;
		states[index] = state;
	}

	private void siftDown(int index)
	{
		int priority = priorities[index], cost = costs[index], state = states[index];
		int half = size >>> 1;
		while (index < half)
		{
			int child = (index << 1) + 1;
			int right = child + 1;
			if (right < size && before(right, child))
				child = right;
			if (compare(priority, cost, state, priorities[child], costs[child], states[child]) <= 0)
				break;
			priorities[index] = priorities[child];
			costs[index] = costs[child];
			states[index] = states[child];
			index = child;
		}
		priorities[index] = priority;
		costs[index] = cost;
		states[index] = state;
	}

	private static int compare(int p1, int c1, int s1, int p2, int c2, int s2)
	{
		int result = Integer.compare(p1, p2);
		if (result != 0)
			return result;
		result = Integer.compare(c1, c2);
		return result != 0 ? result : Integer.compare(s1, s2);
	}
}

package shortestpath.pathfinder.exact;

import java.util.List;
import shortestpath.pathfinder.PathStep;

/**
 * A reconstructed exact route: its steps, plus what the search knew about each of them that the
 * steps alone do not say. A step reached through a global-teleport hub records which hub, since
 * the hub is not a tile and does not appear among the steps; every step records the cost the
 * search reached it at.
 */
public final class ExactRoute
{
	/** The step was reached from the previous step directly: a walk, a bank visit or a transport. */
	public static final byte FROM_STEP = 0;
	/** The first hub arrival; the step is the destination of a teleport cast with capability {@code arrival - 1}. */
	private static final byte FROM_HUB = 1;

	private final List<PathStep> steps;
	private final byte[] arrivals;
	private final int[] costs;

	ExactRoute(List<PathStep> steps, byte[] arrivals, int[] costs)
	{
		if (arrivals.length != steps.size() || costs.length != steps.size())
			throw new IllegalArgumentException("route metadata does not match its steps");
		this.steps = List.copyOf(steps);
		this.arrivals = arrivals;
		this.costs = costs;
	}

	/** A route of plain steps with no search metadata: every step is reached from the previous one. */
	public static ExactRoute of(List<PathStep> steps, int[] costs)
	{
		return new ExactRoute(steps, new byte[steps.size()], costs.clone());
	}

	public List<PathStep> steps()
	{
		return steps;
	}

	public int size()
	{
		return steps.size();
	}

	/** The arrival of a step reached through the hub casting the globals {@code capability} allows. */
	public static byte fromHub(TeleportCapability capability)
	{
		return (byte) (FROM_HUB + capability.ordinal());
	}

	/** The capability of the hub an arrival came through; {@code arrival} must not be {@link #FROM_STEP}. */
	public static TeleportCapability hubCapability(byte arrival)
	{
		return TeleportCapability.values()[arrival - FROM_HUB];
	}

	/** How step {@code index} was reached: {@link #FROM_STEP} or {@link #fromHub one of the hubs}. */
	public byte arrival(int index)
	{
		return arrivals[index];
	}

	/** The cost at which the search reached step {@code index}. */
	public int cost(int index)
	{
		return costs[index];
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import shortestpath.pathfinder.CollisionMap;

/**
 * Keeps exact-routing preparation alive between queries, following the model's lifetimes:
 *
 * <pre>
 * static   RoutingStatic                 owned by the caller
 * account  SiteGraph                     reused while the routing fingerprint is unchanged
 * target   PreparedTarget                reused for the same target set while its SiteGraph and
 *                                        collision map are
 * search   ExactForwardSearch            per query
 * </pre>
 *
 * <p>The account key is the {@link PreparedRoutingAccount#fingerprint() routing fingerprint}
 * rather than object identity, because the plugin recompiles the account before every query even
 * when nothing routing-relevant changed. Changing the graph drops every prepared target.
 *
 * <p>Prepared targets keep the collision map they were built with and the forward search reads
 * it, so they are only reused with that same collision map instance.
 */
public final class ExactRoutingSession
{
	public static final int DEFAULT_TARGET_CAPACITY = 16;

	private final int targetCapacity;
	private final LinkedHashMap<TargetKey, PreparedTarget> targets;
	private SiteGraph graph;
	private CollisionMap targetCollision;

	public ExactRoutingSession()
	{
		this(DEFAULT_TARGET_CAPACITY);
	}

	public ExactRoutingSession(int targetCapacity)
	{
		if (targetCapacity < 1) throw new IllegalArgumentException("target capacity must be positive");
		this.targetCapacity = targetCapacity;
		this.targets = new LinkedHashMap<>(targetCapacity * 2, 0.75f, true);
	}

	/** The account-lifetime graph for {@code account}, rebuilt only when its fingerprint changes. */
	public synchronized Lookup<SiteGraph> graph(RoutingStatic stat, PreparedRoutingAccount account)
	{
		if (stat == null || account == null) throw new NullPointerException();
		if (graph != null && graph.routingStatic() == stat
			&& graph.preparedAccount().fingerprint() == account.fingerprint())
		{
			return new Lookup<>(graph, true);
		}
		graph = new SiteGraph(stat, account);
		targets.clear();
		targetCollision = null;
		return new Lookup<>(graph, false);
	}

	/** The prepared target for {@code packed}, reused while {@code graph} is the session's graph. */
	public Lookup<PreparedTarget> target(SiteGraph graph, CollisionMap collision, int packed)
	{
		return target(graph, collision, new int[] {packed});
	}

	/**
	 * The prepared target for the set {@code packedTargets} (order and duplicates do not matter),
	 * reused while {@code graph} is the session's graph.
	 */
	public synchronized Lookup<PreparedTarget> target(SiteGraph graph, CollisionMap collision, int[] packedTargets)
	{
		if (graph == null || collision == null || packedTargets == null) throw new NullPointerException();
		if (graph != this.graph)
			return new Lookup<>(PreparedTarget.prepare(graph, collision, packedTargets), false);
		if (collision != targetCollision)
		{
			targets.clear();
			targetCollision = collision;
		}
		TargetKey key = new TargetKey(packedTargets);
		PreparedTarget cached = targets.get(key);
		if (cached != null) return new Lookup<>(cached, true);
		PreparedTarget prepared = PreparedTarget.prepare(graph, collision, packedTargets);
		targets.put(key, prepared);
		for (Iterator<Map.Entry<TargetKey, PreparedTarget>> eldest = targets.entrySet().iterator();
			targets.size() > targetCapacity; )
		{
			eldest.next();
			eldest.remove();
		}
		return new Lookup<>(prepared, false);
	}

	/** Drops the prepared targets but keeps the account graph. */
	public synchronized void clearTargets()
	{
		targets.clear();
	}

	/** Drops every cached stage, e.g. when the static routing data is replaced. */
	public synchronized void clear()
	{
		graph = null;
		targets.clear();
		targetCollision = null;
	}

	public synchronized int cachedTargetCount()
	{
		return targets.size();
	}

	/** A target set in canonical (sorted, duplicate-free) form. */
	private static final class TargetKey
	{
		private final int[] tiles;
		private final int hash;

		TargetKey(int[] packedTargets)
		{
			int[] sorted = packedTargets.clone();
			Arrays.sort(sorted);
			int count = 0;
			for (int i = 0; i < sorted.length; i++)
				if (count == 0 || sorted[count - 1] != sorted[i])
					sorted[count++] = sorted[i];
			tiles = Arrays.copyOf(sorted, count);
			hash = Arrays.hashCode(tiles);
		}

		@Override
		public boolean equals(Object other)
		{
			return other instanceof TargetKey && Arrays.equals(tiles, ((TargetKey) other).tiles);
		}

		@Override
		public int hashCode()
		{
			return hash;
		}
	}

	/** A cached stage together with whether it was reused rather than built by this call. */
	public static final class Lookup<T>
	{
		private final T value;
		private final boolean reused;

		Lookup(T value, boolean reused)
		{
			this.value = value;
			this.reused = reused;
		}

		public T value()
		{
			return value;
		}
		public boolean reused()
		{
			return reused;
		}
	}
}

package shortestpath.pathfinder.exact;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.PathStep;

/**
 * Picks a natural-looking walk for each walking leg of an exact route, without changing what the
 * route costs or does.
 * <p>
 * The exact search minimises route cost only (the primary objective). Walking costs one tick in
 * each of the eight directions, so a walking leg usually has many equally cheap realisations, and
 * the search returns whichever its queue order found: diagonals that zig-zag, sideways drift, or an
 * arbitrary tile along the edge of the area a teleport may be cast from. This pass runs after the
 * search and replaces each leg by the best leg under a secondary, presentation-only objective,
 * compared lexicographically:
 * <ol>
 * <li>walking ticks, which must equal the leg's ticks in the route: the primary cost is fixed;</li>
 * <li>axis travel, the sum of |dx| + |dy| over the moves (a cardinal move counts 1, a diagonal 2).
 * Once the ticks are fixed, the least axis travel removes needless coordinate backtracking: a leg
 * travels at least the Manhattan distance between its ends, and every move west that a later move
 * east cancels adds 2. Diagonals are not penalised as such; (0,0) to (40,40) remains 40 diagonal
 * moves, while (0,0) to (1,40) becomes one diagonal and 39 straight moves rather than alternating
 * diagonals;</li>
 * <li>heading changes, the number of moves whose direction differs from the previous move's. They
 * come last because they only describe how a path that is already short and direct reads, and
 * fewer turns must never buy extra distance;</li>
 * <li>a deterministic tie-break: among legs equal on all three, the search keeps the first one it
 * finds, expanding moves in the game's own order (W, E, S, N, SW, SE, NW, NE).</li>
 * </ol>
 * <p>
 * A leg need not end on the tile the search chose. It ends anywhere its next action can be taken
 * with the same consequences (a {@link WalkGoal}): the leg before a global teleport ends anywhere
 * the teleport can be cast, and the leg before a transport at any origin of the same action
 * ({@link PreparedRoutingAccount#localActionClass}). Every other leg keeps its end tile: the final
 * destination, a bank visit, or a transport taken straight after banking.
 * <p>
 * Each leg is searched with A* over (tile, incoming direction) under the lexicographic objective,
 * bounded by the leg's ticks. Since the exact search is optimal, no goal is fewer ticks away; a
 * leg whose goal is closer, or that cannot reach its goal in its ticks, means the route and this
 * pass disagree about walking, and the leg is kept unchanged with a {@link Diagnostic}.
 */
public final class ExactWalkCanonicalizer
{
	/** Legs longer than this keep the search's walk; their window would not fit the state keys. */
	static final int MAX_LEG_TICKS = 4096;
	/** States a leg's search may expand before the leg keeps the search's walk. */
	static final int MAX_EXPANSIONS = 250_000;

	private static final int NONE = 8;
	// Directions index GameWalkOrder's tables: the game's expansion order W, E, S, N, SW, SE,
	// NW, NE, of which the first four are cardinal.

	private final CollisionMap map;
	private final PreparedRoutingAccount account;
	private final SearchRestrictions restrictions;
	private final StateTable states = new StateTable();
	private final LexHeap heap = new LexHeap();

	public ExactWalkCanonicalizer(CollisionMap map, PreparedRoutingAccount account)
	{
		this(map, account, SearchRestrictions.none());
	}

	/**
	 * @param restrictions the search's positional gates: a canonical walk must obey them too, or
	 * it could reroute a leg through tiles the forward search was not allowed to enter
	 */
	public ExactWalkCanonicalizer(CollisionMap map, PreparedRoutingAccount account, SearchRestrictions restrictions)
	{
		if (map == null || account == null || restrictions == null) throw new NullPointerException();
		this.map = map;
		this.account = account;
		this.restrictions = restrictions;
	}

	/** Why a leg kept the search's own walk. */
	public enum Outcome
	{
		/** The leg was replaced by its canonical walk, which may be the same walk. */
		CANONICAL,
		/** A goal tile is fewer ticks away than the leg took: the route or the goal is wrong. */
		SHORTER_ROUTE,
		/** No goal tile is reachable in the leg's ticks: the walking models disagree. */
		NO_ROUTE,
		/** The search expanded {@link #MAX_EXPANSIONS} states without finishing. */
		SEARCH_LIMIT,
		/** The leg is longer than {@link #MAX_LEG_TICKS}. */
		TOO_LONG
	}

	/** A leg that kept the search's walk, and why. */
	public static final class Diagnostic
	{
		private final int startIndex, ticks, foundTicks;
		private final Outcome outcome;
		private final String goal;

		Diagnostic(int startIndex, int ticks, Outcome outcome, int foundTicks, String goal)
		{
			this.startIndex = startIndex;
			this.ticks = ticks;
			this.outcome = outcome;
			this.foundTicks = foundTicks;
			this.goal = goal;
		}

		public int startIndex()
		{
			return startIndex;
		}

		public int ticks()
		{
			return ticks;
		}

		public Outcome outcome()
		{
			return outcome;
		}

		@Override
		public String toString()
		{
			return "walking leg at step " + startIndex + " (" + ticks + " ticks, " + goal + "): " + outcome
				+ (outcome == Outcome.SHORTER_ROUTE ? " in " + foundTicks + " ticks" : "");
		}
	}

	/** A route with canonical walking legs. */
	public static final class Result
	{
		private final List<PathStep> path;
		// Each leg's first and last step index in path, two entries per leg.
		private final int[] legBounds;
		private final List<Diagnostic> diagnostics;

		Result(List<PathStep> path, int[] legBounds, List<Diagnostic> diagnostics)
		{
			this.path = path;
			this.legBounds = legBounds;
			this.diagnostics = diagnostics;
		}

		public List<PathStep> path()
		{
			return path;
		}

		/** Walking legs of at least one tick in the route. */
		public int legs()
		{
			return legBounds.length / 2;
		}

		/** The index in {@link #path()} of the first step of walking leg {@code leg}. */
		public int legStart(int leg)
		{
			return legBounds[2 * leg];
		}

		/** The index in {@link #path()} of the last step of walking leg {@code leg}. */
		public int legEnd(int leg)
		{
			return legBounds[2 * leg + 1];
		}

		/** Legs that kept the search's walk; empty when every leg was canonicalised. */
		public List<Diagnostic> diagnostics()
		{
			return diagnostics;
		}
	}

	/** A walk found by {@link #walk}: the tiles after the start, or why there is none. */
	static final class Walk
	{
		final Outcome outcome;
		final int[] tiles;
		final int foundTicks, expansions;

		Walk(Outcome outcome, int[] tiles, int foundTicks, int expansions)
		{
			this.outcome = outcome;
			this.tiles = tiles;
			this.foundTicks = foundTicks;
			this.expansions = expansions;
		}
	}

	public Result canonicalize(ExactRoute route)
	{
		List<PathStep> steps = route.steps();
		List<PathStep> path = new ArrayList<>(steps);
		List<Diagnostic> diagnostics = new ArrayList<>();
		int[] legBounds = new int[8];
		int legs = 0;
		int legStart = 0;
		for (int i = 1; i <= steps.size(); i++)
		{
			if (i < steps.size() && isWalk(route, i)) continue;
			int legEnd = i - 1, ticks = legEnd - legStart;
			if (ticks > 0)
			{
				if (2 * legs == legBounds.length) legBounds = Arrays.copyOf(legBounds, 2 * legBounds.length);
				legBounds[2 * legs] = legStart;
				legBounds[2 * legs + 1] = legEnd;
				legs++;
				PathStep start = steps.get(legStart);
				WalkGoal goal = goal(route, legEnd);
				Walk walk = walk(start.getPackedPosition(), ticks, goal);
				if (walk.outcome == Outcome.CANONICAL)
				{
					for (int t = 0; t < ticks; t++)
						path.set(legStart + 1 + t, new PathStep(walk.tiles[t], start.isBankVisited()));
				}
				else
				{
					diagnostics.add(new Diagnostic(legStart, ticks, walk.outcome, walk.foundTicks, goal.toString()));
				}
			}
			legStart = i;
		}
		return new Result(List.copyOf(path), Arrays.copyOf(legBounds, 2 * legs), List.copyOf(diagnostics));
	}

	/** Whether step {@code index} is a walking move from the previous step, as the exact search walks. */
	private boolean isWalk(ExactRoute route, int index)
	{
		if (route.arrival(index) != ExactRoute.FROM_STEP) return false;
		PathStep from = route.steps().get(index - 1), to = route.steps().get(index);
		// A transport can land one tile away; its edge paid the transport's duration, not a walk
		// tick, so it must not be folded into a walking leg.
		if (to.getTransport() != null) return false;
		if (from.isBankVisited() != to.isBankVisited()) return false;
		int a = from.getPackedPosition(), b = to.getPackedPosition();
		int plane = WorldPointUtil.unpackWorldPlane(a);
		if (plane != WorldPointUtil.unpackWorldPlane(b)) return false;
		int ax = WorldPointUtil.unpackWorldX(a), ay = WorldPointUtil.unpackWorldY(a);
		int bx = WorldPointUtil.unpackWorldX(b), by = WorldPointUtil.unpackWorldY(b);
		int dx = bx - ax, dy = by - ay;
		if (Math.max(Math.abs(dx), Math.abs(dy)) != 1) return false;
		if (map.isBlocked(ax, ay, plane))
		{
			for (int next : map.ordinaryWalkingNeighbors(a))
				if (next == b) return true;
			return false;
		}
		int direction = direction(dx, dy);
		if ((map.ordinaryWalkingMask(a) & 1 << GameWalkOrder.ORDER_BITS[direction]) != 0) return true;
		// The exact search also steps onto a blocked transport origin next to it, to take the transport.
		return direction < 4 && map.isBlocked(bx, by, plane) && hasLocalOrigin(b, from.isBankVisited());
	}

	/** Where the leg ending at step {@code end} may end instead, given the route's next action. */
	private WalkGoal goal(ExactRoute route, int end)
	{
		List<PathStep> steps = route.steps();
		PathStep last = steps.get(end);
		int tile = last.getPackedPosition();
		if (end + 1 == steps.size()) return WalkGoal.tile(tile);
		byte arrival = route.arrival(end + 1);
		if (arrival != ExactRoute.FROM_STEP)
		{
			// A global teleport: castable anywhere its hub's capability is.
			WalkGoal area = WalkGoal.teleportArea(ExactRoute.hubCapability(arrival));
			return area.contains(WorldPointUtil.unpackWorldX(tile), WorldPointUtil.unpackWorldY(tile))
				? area : WalkGoal.tile(tile);
		}
		PathStep next = steps.get(end + 1);
		// A bank visit, or a transport taken with banked items straight after it, stays where it is.
		if (next.isBankVisited() != last.isBankVisited()) return WalkGoal.tile(tile);
		int[] origins = actionOrigins(tile, next.getPackedPosition(), route.cost(end + 1) - route.cost(end),
			last.isBankVisited());
		return origins == null ? WalkGoal.tile(tile) : WalkGoal.tiles(origins, WorldPointUtil.unpackWorldPlane(tile));
	}

	/**
	 * The origins of the local transport action from {@code origin} to {@code destination} that cost
	 * {@code cost}, or {@code null} unless exactly one action class matches.
	 */
	private int[] actionOrigins(int origin, int destination, int cost, boolean banked)
	{
		PreparedRoutingAccount.View view = account.localView(banked);
		int actionClass = Integer.MIN_VALUE;
		for (int i = lowerBound(view.origins, origin); i < view.count && view.origins[i] == origin; i++)
		{
			if (view.destinations[i] != destination || view.costs[i] != cost) continue;
			if (actionClass != Integer.MIN_VALUE && actionClass != view.actionClasses[i]) return null;
			actionClass = view.actionClasses[i];
		}
		if (actionClass == Integer.MIN_VALUE) return null;
		int[] origins = new int[4];
		int count = 0;
		for (int i = 0; i < view.count; i++)
		{
			if (view.actionClasses[i] != actionClass) continue;
			if (count == origins.length) origins = Arrays.copyOf(origins, count * 2);
			origins[count++] = view.origins[i];
		}
		return Arrays.copyOf(origins, count);
	}

	private boolean hasLocalOrigin(int tile, boolean banked)
	{
		PreparedRoutingAccount.View view = account.localView(banked);
		int index = lowerBound(view.origins, tile);
		return index < view.count && view.origins[index] == tile;
	}

	/**
	 * The lexicographically best walk of exactly {@code ticks} moves from {@code start} to a tile of
	 * {@code goal} on the same plane.
	 */
	Walk walk(int start, int ticks, WalkGoal goal)
	{
		if (ticks > MAX_LEG_TICKS) return new Walk(Outcome.TOO_LONG, null, 0, 0);
		int sx = WorldPointUtil.unpackWorldX(start), sy = WorldPointUtil.unpackWorldY(start);
		int plane = WorldPointUtil.unpackWorldPlane(start);
		// Tiles are numbered within the (2 ticks + 1)-wide square the leg cannot leave.
		int width = 2 * ticks + 1;
		// Lexicographic keys (f ticks, f axis travel, g turns) packed into one long.
		long axisRange = 2L * ticks + 1, turnRange = ticks + 1;
		states.reset();
		heap.clear();

		long startBound = goal.lowerBound(sx, sy);
		if (WalkGoal.ticks(startBound) > ticks) return new Walk(Outcome.NO_ROUTE, null, 0, 0);
		int startState = states.tile(ticks * width + ticks) * 9 + NONE;
		states.set(startState, 0, 0, 0, -1);
		heap.push((WalkGoal.ticks(startBound) * axisRange + WalkGoal.axisTravel(startBound)) * turnRange, startState);

		int expansions = 0;
		while (!heap.isEmpty())
		{
			int state = heap.pop();
			if (states.closed[state]) continue;
			states.closed[state] = true;
			int tile = state / 9, incoming = state % 9, local = states.locals[tile];
			int x = sx - ticks + local % width, y = sy - ticks + local / width;
			int gTicks = states.ticks[state], gAxis = states.axis[state], gTurns = states.turns[state];
			if (dominated(gTicks, gAxis, gTurns, tile)) continue;
			if (goal.contains(x, y))
			{
				if (gTicks < ticks) return new Walk(Outcome.SHORTER_ROUTE, null, gTicks, expansions);
				return new Walk(Outcome.CANONICAL, trace(state, sx, sy, ticks, width, plane), gTicks, expansions);
			}
			if (++expansions > MAX_EXPANSIONS) return new Walk(Outcome.SEARCH_LIMIT, null, 0, expansions);
			if (gTicks == ticks) continue;

			int packed = WorldPointUtil.packWorldPoint(x, y, plane);
			int mask;
			boolean blocked = map.isBlocked(x, y, plane);
			if (blocked)
			{
				// Only the start can be blocked (a transport may land on one); leave it as the search does.
				mask = 0;
				for (int next : map.ordinaryWalkingNeighbors(packed))
					mask |= 1 << GameWalkOrder.ORDER_BITS[direction(WorldPointUtil.unpackWorldX(next) - x,
						WorldPointUtil.unpackWorldY(next) - y)];
			}
			else
			{
				mask = map.ordinaryWalkingMask(packed);
			}
			for (int direction = 0; direction < 8; direction++)
			{
				int nx = x + GameWalkOrder.ORDER_DX[direction], ny = y + GameWalkOrder.ORDER_DY[direction];
				if ((mask & 1 << GameWalkOrder.ORDER_BITS[direction]) == 0)
				{
					// A blocked goal tile may still be stepped onto cardinally, as the exact search does.
					if (direction >= 4 || blocked || !goal.entersBlockedTiles() || !map.isBlocked(nx, ny, plane)
						|| !goal.contains(nx, ny)) continue;
				}
				if (!restrictions.stepAllowed(packed, WorldPointUtil.packWorldPoint(nx, ny, plane)))
				{
					continue;
				}
				long bound = goal.lowerBound(nx, ny);
				int nextTicks = gTicks + 1;
				if (nextTicks + WalkGoal.ticks(bound) > ticks) continue;
				int nextAxis = gAxis + (direction < 4 ? 1 : 2);
				int nextTurns = gTurns + (incoming == NONE || incoming == direction ? 0 : 1);
				int nextTile = states.tile((ny - sy + ticks) * width + nx - sx + ticks);
				if (dominated(nextTicks, nextAxis, nextTurns, nextTile)) continue;
				int next = nextTile * 9 + direction;
				if (states.closed[next] || !better(nextTicks, nextAxis, nextTurns, next)) continue;
				states.set(next, nextTicks, nextAxis, nextTurns, state);
				long fTicks = nextTicks + WalkGoal.ticks(bound), fAxis = nextAxis + WalkGoal.axisTravel(bound);
				heap.push((fTicks * axisRange + fAxis) * turnRange + nextTurns, next);
			}
		}
		return new Walk(Outcome.NO_ROUTE, null, 0, expansions);
	}

	/**
	 * Whether a state of {@code tile} reached with (ticks, axis, turns) cannot beat the tile's best
	 * state so far. Any walk on from the state can continue from the best one with the same moves,
	 * at the cost of at most one more turn for the first move, so only a state with less ticks or
	 * axis travel, or the same and no more turns, can still do better. Best states only improve, so
	 * a state this rejects stays rejected.
	 */
	private boolean dominated(int ticks, int axis, int turns, int tile)
	{
		if (ticks != states.bestTicks[tile]) return ticks > states.bestTicks[tile];
		if (axis != states.bestAxis[tile]) return axis > states.bestAxis[tile];
		return turns > states.bestTurns[tile];
	}

	/** Whether the state's recorded walk is lexicographically worse than (ticks, axis, turns); unset ones are. */
	private boolean better(int ticks, int axis, int turns, int state)
	{
		if (ticks != states.ticks[state]) return ticks < states.ticks[state];
		if (axis != states.axis[state]) return axis < states.axis[state];
		return turns < states.turns[state];
	}

	private int[] trace(int state, int sx, int sy, int ticks, int width, int plane)
	{
		int[] tiles = new int[states.ticks[state]];
		for (int i = tiles.length - 1; i >= 0; i--, state = states.parent[state])
		{
			int local = states.locals[state / 9];
			tiles[i] = WorldPointUtil.packWorldPoint(sx - ticks + local % width, sy - ticks + local / width, plane);
		}
		return tiles;
	}

	private static int direction(int dx, int dy)
	{
		for (int i = 0; i < 8; i++)
			if (GameWalkOrder.ORDER_DX[i] == dx && GameWalkOrder.ORDER_DY[i] == dy) return i;
		throw new IllegalArgumentException("not a walking move: " + dx + "," + dy);
	}

	private static int lowerBound(int[] values, int target)
	{
		int low = 0, high = values.length;
		while (low < high)
		{
			int middle = low + (high - low) / 2;
			if (Integer.compareUnsigned(values[middle], target) < 0) low = middle + 1;
			else high = middle;
		}
		return low;
	}

	/**
	 * The tiles a leg's search has reached, by their number in the leg's square, reused across legs.
	 * Tile {@code t} owns states {@code 9t} to {@code 9t + 8}, one per incoming direction (8 for the
	 * start's none), and the best* arrays hold the lexicographically least of them.
	 */
	private static final class StateTable
	{
		private static final int UNSET = Integer.MAX_VALUE;

		int size;
		int[] locals = new int[256], bestTicks = new int[256], bestAxis = new int[256], bestTurns = new int[256];
		int[] ticks = new int[256 * 9], axis = new int[256 * 9], turns = new int[256 * 9], parent = new int[256 * 9];
		boolean[] closed = new boolean[256 * 9];
		// Open addressing from tile number to tile; a slot is live only if stamped with this leg's generation.
		private int[] slots = new int[1024], stamps = new int[1024];
		private int generation;

		void reset()
		{
			size = 0;
			if (++generation == 0)
			{
				Arrays.fill(stamps, 0);
				generation = 1;
			}
		}

		/** The tile numbered {@code local}, added with no states if it is new. */
		int tile(int local)
		{
			int mask = slots.length - 1, slot = hash(local) & mask;
			for (; stamps[slot] == generation; slot = slot + 1 & mask)
				if (locals[slots[slot]] == local) return slots[slot];
			if (size == locals.length) grow();
			if (2 * (size + 1) > slots.length)
			{
				rehash();
				mask = slots.length - 1;
				for (slot = hash(local) & mask; stamps[slot] == generation; ) slot = slot + 1 & mask;
			}
			int tile = size++;
			locals[tile] = local;
			bestTicks[tile] = UNSET;
			Arrays.fill(ticks, tile * 9, tile * 9 + 9, UNSET);
			Arrays.fill(closed, tile * 9, tile * 9 + 9, false);
			stamps[slot] = generation;
			slots[slot] = tile;
			return tile;
		}

		void set(int state, int tick, int axisTravel, int turnCount, int from)
		{
			ticks[state] = tick;
			axis[state] = axisTravel;
			turns[state] = turnCount;
			parent[state] = from;
			int tile = state / 9;
			if (tick < bestTicks[tile] || tick == bestTicks[tile] && (axisTravel < bestAxis[tile]
				|| axisTravel == bestAxis[tile] && turnCount < bestTurns[tile]))
			{
				bestTicks[tile] = tick;
				bestAxis[tile] = axisTravel;
				bestTurns[tile] = turnCount;
			}
		}

		private void grow()
		{
			int capacity = locals.length * 2;
			locals = Arrays.copyOf(locals, capacity);
			bestTicks = Arrays.copyOf(bestTicks, capacity);
			bestAxis = Arrays.copyOf(bestAxis, capacity);
			bestTurns = Arrays.copyOf(bestTurns, capacity);
			ticks = Arrays.copyOf(ticks, capacity * 9);
			axis = Arrays.copyOf(axis, capacity * 9);
			turns = Arrays.copyOf(turns, capacity * 9);
			parent = Arrays.copyOf(parent, capacity * 9);
			closed = Arrays.copyOf(closed, capacity * 9);
		}

		private void rehash()
		{
			slots = new int[slots.length * 2];
			stamps = new int[slots.length];
			generation = 1;
			int mask = slots.length - 1;
			for (int tile = 0; tile < size; tile++)
			{
				int slot = hash(locals[tile]) & mask;
				while (stamps[slot] == generation) slot = slot + 1 & mask;
				stamps[slot] = generation;
				slots[slot] = tile;
			}
		}

		private static int hash(int key)
		{
			int h = key * 0x9E3779B9;
			return h ^ h >>> 16;
		}
	}

	/** A binary min-heap of states by key, first in first out among equal keys. */
	private static final class LexHeap
	{
		private long[] keys = new long[1024];
		private int[] sequence = new int[1024], states = new int[1024];
		private int size, pushed;

		void clear()
		{
			size = 0;
			pushed = 0;
		}

		boolean isEmpty()
		{
			return size == 0;
		}

		void push(long key, int state)
		{
			if (size == keys.length)
			{
				keys = Arrays.copyOf(keys, size * 2);
				sequence = Arrays.copyOf(sequence, size * 2);
				states = Arrays.copyOf(states, size * 2);
			}
			int at = size++, order = pushed++;
			while (at > 0)
			{
				int up = (at - 1) / 2;
				if (!less(key, order, keys[up], sequence[up])) break;
				move(up, at);
				at = up;
			}
			keys[at] = key;
			sequence[at] = order;
			states[at] = state;
		}

		int pop()
		{
			int result = states[0];
			size--;
			long key = keys[size];
			int order = sequence[size], state = states[size], at = 0;
			while (true)
			{
				int child = 2 * at + 1;
				if (child >= size) break;
				if (child + 1 < size && less(keys[child + 1], sequence[child + 1], keys[child], sequence[child])) child++;
				if (!less(keys[child], sequence[child], key, order)) break;
				move(child, at);
				at = child;
			}
			keys[at] = key;
			sequence[at] = order;
			states[at] = state;
			return result;
		}

		private void move(int from, int to)
		{
			keys[to] = keys[from];
			sequence[to] = sequence[from];
			states[to] = states[from];
		}

		private static boolean less(long key, int order, long otherKey, int otherOrder)
		{
			return key < otherKey || key == otherKey && order < otherOrder;
		}
	}
}

package shortestpath.pathfinder.exact;

import shortestpath.pathfinder.CollisionMap;

/**
 * The order the game's own walking expands a tile's neighbours — W, E, S, N, SW, SE, NW, NE —
 * as the {@link CollisionMap#ordinaryWalkingMask} bit and step delta of each direction. Shared
 * by the walk passes that model that order — the leg canonicaliser and the in-game walk
 * rewriter — which would silently disagree with the game if the tables ever drifted apart.
 * Package-private:
 * the arrays are mutable, so they are not exposed to callers.
 */
final class GameWalkOrder
{
	// CollisionMap.ordinaryWalkingMask bits (0-N, 1-NE, 2-E, 3-SE, 4-S, 5-SW, 6-W, 7-NW) in the
	// game's expansion order W, E, S, N, SW, SE, NW, NE; the first four are cardinal.
	static final int[] ORDER_BITS = {6, 2, 4, 0, 5, 3, 7, 1};
	static final int[] ORDER_DX = {-1, 1, 0, 0, -1, 1, -1, 1};
	static final int[] ORDER_DY = {0, 0, -1, 1, -1, -1, 1, 1};

	private GameWalkOrder()
	{
	}
}

package shortestpath.pathfinder.exact;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.PathStep;

/**
 * Rewrites the canonical walking legs of an exact route into the tiles the game's own walking
 * takes when the player clicks along them, without changing what the route costs or does.
 * <p>
 * {@link ExactWalkCanonicalizer} picks the intended walk of each leg: the cleanest of its equally
 * cheap walks. The player does not walk tiles, though; they click a tile, and the game runs a
 * breadth-first search over a 128x128 window centred on them, expanding neighbours in the order
 * W, E, S, N, SW, SE, NW, NE, and walks the path traced back from the clicked tile along each
 * tile's first discoverer. That path need not be the intended one even when it is as short.
 * <p>
 * Each leg is split into clicks on its intended walk. From the leg's current tile, the click is
 * the furthest later tile of the leg within {@link #DEFAULT_CLICK_RADIUS a minimap click's reach}
 * whose in-game path is exactly as long as the intended walk to it, and the intended walk up to it
 * is replaced by that in-game path. The in-game path may leave the intended walk between clicks;
 * every click is on it. A shorter in-game path is refused too, as it would change the route's
 * cost. So is one whose traced path steps through a tile the search's {@link SearchRestrictions}
 * gate off — the game does not know those gates, so keeping the canonical step preserves both
 * the cost and the restriction — and one needing more than {@link #MAX_CHECKPOINTS} checkpoint
 * tiles, which the game would walk only up to the 25th corner. A step no click realises (one the
 * game does not walk, such as onto a blocked transport origin) keeps the intended step; the
 * client's fallback search for an approximate target when a click is unreachable is deliberately
 * not emulated. Legs keep their tiles at both ends and their length, so every other step of the
 * route, and the route's cost, are unchanged.
 */
public final class InGameWalkRewriter
{
	/** Roughly the reach of a minimap click, in tiles. */
	public static final int DEFAULT_CLICK_RADIUS = 15;

	/**
	 * Checkpoint tiles the client keeps for one click's walk: the direction-change corners of
	 * the traced path plus the destination. A click needing more is walked only up to the 25th
	 * checkpoint and the player stops short, so such a candidate is refused rather than drawn.
	 */
	private static final int MAX_CHECKPOINTS = 25;

	private static final int WINDOW = 128;
	private static final int HALF_WINDOW = WINDOW / 2;
	private static final int UNVISITED = -1;
	// The game's expansion order lives in GameWalkOrder, shared with the canonicaliser.

	private final CollisionMap map;
	private final int clickRadius;
	private final SearchRestrictions restrictions;
	private final int[] distance = new int[WINDOW * WINDOW];
	private final int[] parent = new int[WINDOW * WINDOW];
	private final int[] queue = new int[WINDOW * WINDOW];

	public InGameWalkRewriter(CollisionMap map)
	{
		this(map, DEFAULT_CLICK_RADIUS, SearchRestrictions.none());
	}

	public InGameWalkRewriter(CollisionMap map, int clickRadius)
	{
		this(map, clickRadius, SearchRestrictions.none());
	}

	/**
	 * @param restrictions the search's positional gates: the spliced in-game paths must obey them
	 * too, or a leg could be drawn through tiles the forward search was not allowed to enter
	 */
	public InGameWalkRewriter(CollisionMap map, SearchRestrictions restrictions)
	{
		this(map, DEFAULT_CLICK_RADIUS, restrictions);
	}

	public InGameWalkRewriter(CollisionMap map, int clickRadius, SearchRestrictions restrictions)
	{
		if (map == null || restrictions == null) throw new NullPointerException();
		if (clickRadius < 2) throw new IllegalArgumentException("click radius must reach a diagonal neighbour");
		this.map = map;
		this.clickRadius = clickRadius;
		this.restrictions = restrictions;
	}

	/** A rewritten route and the indices of its steps the player clicks to walk it. */
	public static final class Result
	{
		private final List<PathStep> path;
		private final List<Integer> clickPoints;
		private final List<Integer> keptStepIndices;

		Result(List<PathStep> path, List<Integer> clickPoints, List<Integer> keptStepIndices)
		{
			this.path = path;
			this.clickPoints = clickPoints;
			this.keptStepIndices = keptStepIndices;
		}

		/** The route, as long as the canonical one and with the same steps outside its walking legs. */
		public List<PathStep> path()
		{
			return path;
		}

		/**
		 * Ascending indices into {@link #path()} of the tiles to click, one per click. Every
		 * index is a real click: the game's own walking path lands on that tile.
		 */
		public List<Integer> clickPoints()
		{
			return clickPoints;
		}

		/**
		 * Ascending indices into {@link #path()} of the steps that kept the canonical step
		 * because no in-game click realises them; they are not clicks.
		 */
		public List<Integer> keptStepIndices()
		{
			return keptStepIndices;
		}

		/** Walking steps that kept the canonical step because no in-game click realises them. */
		public int keptSteps()
		{
			return keptStepIndices.size();
		}
	}

	/** Rewrites the walking legs of a canonicalised route; every other step is kept. */
	public Result rewrite(ExactWalkCanonicalizer.Result canonical)
	{
		int[] legBounds = new int[2 * canonical.legs()];
		for (int leg = 0; leg < canonical.legs(); leg++)
		{
			legBounds[2 * leg] = canonical.legStart(leg);
			legBounds[2 * leg + 1] = canonical.legEnd(leg);
		}
		return rewrite(canonical.path(), legBounds);
	}

	/**
	 * Rewrites the walking legs of {@code path}: leg {@code k} runs from step {@code legBounds[2k]}
	 * to step {@code legBounds[2k + 1]}, and its steps are single-tile walking moves.
	 */
	Result rewrite(List<PathStep> path, int[] legBounds)
	{
		List<PathStep> rewritten = new ArrayList<>(path);
		List<Integer> clicks = new ArrayList<>();
		List<Integer> kept = new ArrayList<>();
		for (int leg = 0; leg < legBounds.length; leg += 2)
			rewriteLeg(path, legBounds[leg], legBounds[leg + 1], rewritten, clicks, kept);
		return new Result(List.copyOf(rewritten), List.copyOf(clicks), List.copyOf(kept));
	}

	/**
	 * Replaces {@code rewritten[from + 1..to]} by the in-game walk along the clicks on
	 * {@code path[from..to]}, appending each click's index to {@code clicks} and the index of
	 * each step the game cannot be made to walk to {@code kept}.
	 */
	private void rewriteLeg(List<PathStep> path, int from, int to, List<PathStep> rewritten,
		List<Integer> clicks, List<Integer> kept)
	{
		boolean banked = path.get(from).isBankVisited();
		int current = from;
		while (current < to)
		{
			int source = path.get(current).getPackedPosition();
			int sx = WorldPointUtil.unpackWorldX(source), sy = WorldPointUtil.unpackWorldY(source);
			int plane = WorldPointUtil.unpackWorldPlane(source);
			int originX = sx - HALF_WINDOW, originY = sy - HALF_WINDOW;

			// Leg tiles within reach; the BFS need only run as deep as the furthest of them.
			int deepest = 1;
			for (int i = current + 1; i <= to; i++)
				if (withinReach(sx, sy, path.get(i).getPackedPosition())) deepest = i - current;
			search(originX, originY, plane, sx, sy, deepest);

			int click = -1;
			for (int i = current + deepest; i > current && click < 0; i--)
			{
				int tile = path.get(i).getPackedPosition();
				if (!withinReach(sx, sy, tile)) continue;
				// withinReach bounds the tile to (64±15) locally, inside the window: never -1.
				int local = localIndex(originX, originY, tile);
				// Exactly as long as the canonical walk: no shorter, which would change the cost.
				if (distance[local] != i - current) continue;
				// The traced game path must also walk only steps the search's restrictions allow;
				// a candidate that violates them is refused, and a nearer one is tried instead.
				if (traceAllowed(originX, originY, plane, local, i - current)) click = i;
			}

			if (click < 0)
			{
				// Not a step the game walks; keep the canonical one. Record it as a kept step,
				// not a click: no click's in-game path lands on it, so showing it as a click
				// point would mark a tile the game cannot be made to walk to.
				kept.add(current + 1);
				current++;
			}
			else
			{
				int at = localIndex(originX, originY, path.get(click).getPackedPosition());
				for (int i = click; i > current; i--, at = parent[at])
					rewritten.set(i, new PathStep(WorldPointUtil.packWorldPoint(originX + at % WINDOW,
						originY + at / WINDOW, plane), banked));
				clicks.add(click);
				current = click;
			}
		}
	}

	/**
	 * Whether the in-game path traced back {@code hops} steps from local index {@code at} may be
	 * spliced into the leg: every hop must be a step the search's restrictions allow, directed
	 * from the tile nearer the click's source to the tile it lands on, and the path must fit the
	 * client's per-click budget of {@link #MAX_CHECKPOINTS} checkpoint tiles — its
	 * direction-change corners plus the destination — or the game would stop short of the click.
	 */
	private boolean traceAllowed(int originX, int originY, int plane, int at, int hops)
	{
		int previousDx = 0, previousDy = 0, turns = 0;
		for (int i = 0; i < hops; i++, at = parent[at])
		{
			int from = parent[at];
			if (!restrictions.stepAllowed(
				WorldPointUtil.packWorldPoint(originX + from % WINDOW, originY + from / WINDOW, plane),
				WorldPointUtil.packWorldPoint(originX + at % WINDOW, originY + at / WINDOW, plane)))
			{
				return false;
			}
			int dx = at % WINDOW - from % WINDOW, dy = at / WINDOW - from / WINDOW;
			if (i > 0 && (dx != previousDx || dy != previousDy)) turns++;
			previousDx = dx;
			previousDy = dy;
		}
		return turns + 1 <= MAX_CHECKPOINTS;
	}

	private boolean withinReach(int sx, int sy, int tile)
	{
		int dx = WorldPointUtil.unpackWorldX(tile) - sx, dy = WorldPointUtil.unpackWorldY(tile) - sy;
		return dx * dx + dy * dy <= clickRadius * clickRadius;
	}

	private static int localIndex(int originX, int originY, int tile)
	{
		int x = WorldPointUtil.unpackWorldX(tile) - originX, y = WorldPointUtil.unpackWorldY(tile) - originY;
		return x < 0 || y < 0 || x >= WINDOW || y >= WINDOW ? -1 : y * WINDOW + x;
	}

	/** The game's walking BFS from {@code (sx, sy)}, stopped once every tile within {@code depth} is found. */
	private void search(int originX, int originY, int plane, int sx, int sy, int depth)
	{
		Arrays.fill(distance, UNVISITED);
		int start = (sy - originY) * WINDOW + (sx - originX);
		distance[start] = 0;
		parent[start] = start;
		int head = 0, tail = 0;
		queue[tail++] = start;
		while (head < tail)
		{
			int at = queue[head++];
			if (distance[at] >= depth) break;
			int x = at % WINDOW, y = at / WINDOW;
			int mask = map.ordinaryWalkingMask(WorldPointUtil.packWorldPoint(originX + x, originY + y, plane));
			for (int i = 0; i < GameWalkOrder.ORDER_BITS.length; i++)
			{
				if ((mask & (1 << GameWalkOrder.ORDER_BITS[i])) == 0) continue;
				int nx = x + GameWalkOrder.ORDER_DX[i], ny = y + GameWalkOrder.ORDER_DY[i];
				if (nx < 0 || ny < 0 || nx >= WINDOW || ny >= WINDOW) continue;
				int next = ny * WINDOW + nx;
				if (distance[next] != UNVISITED) continue;
				distance[next] = distance[at] + 1;
				parent[next] = at;
				queue[tail++] = next;
			}
		}
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;

/** Query-lifetime raw seeds and provenance-reduced exact seed scans. */
public final class PreparedHeuristic
{
	private final TargetOverlay overlay;
	private final ReverseLabels reverse;
	private final int[][] seedTiles;
	private final int[][] seedLabels;
	private final int[][] generatorTiles;
	private final int[][] generatorLabels;
	private final long preparationNanos;

	private PreparedHeuristic(TargetOverlay overlay, ReverseLabels reverse, int[][] seedTiles, int[][] seedLabels,
		int[][] generatorTiles, int[][] generatorLabels, long preparationNanos)
	{
		this.overlay = overlay;
		this.reverse = reverse;
		this.seedTiles = seedTiles;
		this.seedLabels = seedLabels;
		this.generatorTiles = generatorTiles;
		this.generatorLabels = generatorLabels;
		this.preparationNanos = preparationNanos;
	}

	public static PreparedHeuristic prepare(TargetOverlay overlay, ReverseLabels reverse)
	{
		if (reverse == null || reverse.overlay() != overlay)
			throw new IllegalArgumentException("reverse labels belong to another target overlay");
		long started = System.nanoTime();
		int bucketCount = overlay.routingStatic().routingComponentCount() * 2;
		IntList[] raw = new IntList[bucketCount];
		GeneratorList[] reduced = new GeneratorList[bucketCount];
		RoutingStatic stat = overlay.routingStatic();
		SiteGraph graph = overlay.graph();
		for (int site = 0; site < graph.spatialNodeCount(); site++)
		{
			addSite(raw, reduced, reverse, overlay, site, stat.siteTile(site), stat.siteComponents(site), false);
			addSite(raw, reduced, reverse, overlay, site, stat.siteTile(site), stat.siteComponents(site), true);
		}
		for (int target = 0; target < overlay.targetCount(); target++)
		{
			if (!overlay.synthetic(target))
				continue;
			addSite(raw, reduced, reverse, overlay, overlay.targetNode(target), overlay.packedTarget(target),
				overlay.componentsView(target), false);
			addSite(raw, reduced, reverse, overlay, overlay.targetNode(target), overlay.packedTarget(target),
				overlay.componentsView(target), true);
		}
		int[][] tiles = new int[bucketCount][], labels = new int[bucketCount][];
		int[][] generatorTiles = new int[bucketCount][], generatorLabels = new int[bucketCount][];
		for (int i = 0; i < bucketCount; i++)
		{
			tiles[i] = raw[i] == null ? new int[0] : raw[i].tiles();
			labels[i] = raw[i] == null ? new int[0] : raw[i].labels();
			generatorTiles[i] = reduced[i] == null ? new int[0] : reduced[i].tiles();
			generatorLabels[i] = reduced[i] == null ? new int[0] : reduced[i].labels();
		}
		return new PreparedHeuristic(overlay, reverse, tiles, labels, generatorTiles, generatorLabels,
			System.nanoTime() - started);
	}

	public TargetOverlay overlay()
	{
		return overlay;
	}
	public ReverseLabels reverseLabels()
	{
		return reverse;
	}
	public int seedCount(int component, boolean banked)
	{
		return seedTiles[key(component, banked)].length;
	}
	public int seedTile(int component, boolean banked, int index)
	{
		return seedTiles[key(component, banked)][index];
	}
	public int seedLabel(int component, boolean banked, int index)
	{
		return seedLabels[key(component, banked)][index];
	}
	public int generatorCount(int component, boolean banked)
	{
		return generatorTiles[key(component, banked)].length;
	}
	public int generatorTile(int component, boolean banked, int index)
	{
		return generatorTiles[key(component, banked)][index];
	}
	public int generatorLabel(int component, boolean banked, int index)
	{
		return generatorLabels[key(component, banked)][index];
	}
	public int rawSeedCount()
	{
		return total(seedTiles);
	}
	public int generatorCount()
	{
		return total(generatorTiles);
	}
	public double generatorRatio()
	{
		int raw = rawSeedCount();
		return raw == 0 ? 0 : (double) generatorCount() / raw;
	}
	public long preparationNanos()
	{
		return preparationNanos;
	}

	public int estimate(int packed, boolean banked)
	{
		return estimate(packed, banked, overlay.routingStatic().attachments(packed, overlay.collision()));
	}

	public int estimate(TargetOverlay candidate, int packed, boolean banked)
	{
		candidate.requireCompatible(overlay.graph());
		if (candidate != overlay)
			throw new IllegalArgumentException("heuristic belongs to another target query");
		return estimate(packed, banked);
	}

	/** Evaluate against the collision snapshot used to create the target overlay. */
	public int estimate(CollisionMap collision, int packed, boolean banked)
	{
		if (collision == null)
			throw new NullPointerException("collision");
		return estimate(packed, banked, overlay.routingStatic().attachments(packed, collision));
	}

	public int estimate(int packed, boolean banked, int[] components)
	{
		return estimateTable(packed, banked, components, generatorTiles, generatorLabels, true);
	}

	public int estimateBaseNode(int packed, boolean banked, int component)
	{
		int best = targetLabel(packed, banked);
		int site = overlay.routingStatic().siteIndex(packed);
		if (site >= 0) best = Math.min(best, reverse.label(site, banked));
		return Math.min(best,
			estimateComponent(packed, banked, component, generatorTiles, generatorLabels, true));
	}

	/** Raw seed-scan oracle retained for reduced-generator differential checks. */
	int estimateRaw(int packed, boolean banked, int[] components)
	{
		return estimateTable(packed, banked, components, seedTiles, seedLabels, false);
	}

	int estimateGenerators(int packed, boolean banked, int[] components)
	{
		return estimateTable(packed, banked, components, generatorTiles, generatorLabels, false);
	}

	private int estimateTable(int packed, boolean banked, int[] components, int[][] tiles, int[][] labels,
		boolean fallbackToRaw)
	{
		RoutingStatic stat = overlay.routingStatic();
		int best = targetLabel(packed, banked);
		int site = stat.siteIndex(packed);
		if (site >= 0)
			best = Math.min(best, reverse.label(site, banked));
		for (int component : components)
			best = Math.min(best, estimateComponent(packed, banked, component, tiles, labels, fallbackToRaw));
		return best;
	}

	private int estimateComponent(int packed, boolean banked, int component, int[][] tiles, int[][] labels,
		boolean fallbackToRaw)
	{
		int key = key(component, banked);
		int[] bucketTiles = tiles[key];
		int[] bucketLabels = labels[key];
		if (fallbackToRaw && bucketTiles.length == 0)
		{
			bucketTiles = seedTiles[key];
			bucketLabels = seedLabels[key];
		}
		int best = ExactCosts.INF;
		for (int i = 0; i < bucketTiles.length; i++)
			best = Math.min(best, ExactCosts.add(bucketLabels[i],
				WorldPointUtil.distanceBetween(packed, bucketTiles[i])));
		return best;
	}

	private static void addSite(IntList[] raw, GeneratorList[] reduced, ReverseLabels reverse,
		TargetOverlay overlay, int node, int packed, int[] components, boolean banked)
	{
		int state = SiteGraph.stateId(node, banked);
		int distance = reverse.label(node, banked);
		if (distance == ExactCosts.INF)
			return;
		for (int component : components)
		{
			int key = key(component, banked);
			add(raw, key, packed, distance);
			if (!reverse.hasProvenance())
				continue;
			int origin = reverse.generatorOrigin(state);
			int generatorState = validOrigin(reverse, overlay, node, packed, components, component, state, origin)
				? origin : state;
			int generatorNode = generatorState / 2;
			int generatorTile = overlay.nodeTile(generatorNode);
			int generatorLabel = reverse.label(generatorNode, (generatorState & 1) != 0);
			if (reduced[key] == null)
				reduced[key] = new GeneratorList();
			reduced[key].add(generatorState, generatorTile, generatorLabel);
		}
	}

	private static boolean validOrigin(ReverseLabels reverse, TargetOverlay overlay, int node, int packed,
		int[] components, int component, int state, int origin)
	{
		if (origin < 0 || (origin & 1) != (state & 1))
			return false;
		int originNode = origin / 2;
		if (originNode >= overlay.graph().spatialNodeCount() && overlay.syntheticTarget(originNode) < 0)
			return false;
		int originTile = overlay.nodeTile(originNode);
		int direct = WorldPointUtil.distanceBetween(originTile, packed);
		if (direct == ExactCosts.INF)
			return false;
		if (reverse.generatorWeightDoubled(state) == ExactCosts.INF
			|| reverse.doubledLabel(state) != ExactCosts.add(reverse.generatorWeightDoubled(state), ExactCosts.twice(direct)))
			return false;
		int[] originComponents = overlay.nodeComponents(originNode);
		return contains(originComponents, component);
	}

	private int targetLabel(int packed, boolean banked)
	{
		int target = overlay.targetIndex(packed);
		return target < 0 ? ExactCosts.INF : reverse.targetLabel(target, banked);
	}

	private static int key(int component, boolean banked)
	{
		return component * 2 + (banked ? 1 : 0);
	}

	private static void add(IntList[] raw, int key, int packed, int label)
	{
		if (raw[key] == null)
			raw[key] = new IntList();
		raw[key].add(packed, label);
	}

	private static boolean contains(int[] values, int target)
	{
		for (int value : values)
			if (value == target)
				return true;
		return false;
	}

	private static int total(int[][] values)
	{
		int total = 0;
		for (int[] value : values)
			total += value.length;
		return total;
	}

	private static final class IntList
	{
		private int[] tiles = new int[8], labels = new int[8];
		private int size;

		void add(int tile, int label)
		{
			if (size == tiles.length)
			{
				tiles = Arrays.copyOf(tiles, size * 2);
				labels = Arrays.copyOf(labels, size * 2);
			}
			tiles[size] = tile;
			labels[size++] = label;
		}
		int[] tiles()
		{
			return Arrays.copyOf(tiles, size);
		}
		int[] labels()
		{
			return Arrays.copyOf(labels, size);
		}
	}

	private static final class GeneratorList
	{
		private int[] ids = new int[8], tiles = new int[8], labels = new int[8];
		private int size;

		void add(int id, int tile, int label)
		{
			for (int i = 0; i < size; i++)
				if (ids[i] == id)
					return;
			if (size == ids.length)
			{
				ids = Arrays.copyOf(ids, size * 2);
				tiles = Arrays.copyOf(tiles, size * 2);
				labels = Arrays.copyOf(labels, size * 2);
			}
			ids[size] = id;
			tiles[size] = tile;
			labels[size++] = label;
		}
		int[] tiles()
		{
			sort();
			return Arrays.copyOf(tiles, size);
		}
		int[] labels()
		{
			sort();
			return Arrays.copyOf(labels, size);
		}
		private void sort()
		{
			for (int i = 1; i < size; i++)
			{
				int j = i;
				while (j > 0 && ids[j] < ids[j - 1])
				{
					int id = ids[j];
					ids[j] = ids[j - 1];
					ids[j - 1] = id;
					int tile = tiles[j];
					tiles[j] = tiles[j - 1];
					tiles[j - 1] = tile;
					int label = labels[j];
					labels[j] = labels[j - 1];
					labels[j - 1] = label;
					j--;
				}
			}
		}
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;
import java.util.Collection;
import java.util.function.ToIntFunction;
import shortestpath.PrimitiveIntHashMap;
import shortestpath.pathfinder.TransportAvailability;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/** Immutable account/config snapshot used by the exact graph. */
public final class PreparedRoutingAccount
{
	private static final long FNV_OFFSET = 0xcbf29ce484222325L;
	private static final long FNV_PRIME = 0x100000001b3L;
	private static final TeleportCapability[] CAPABILITIES = TeleportCapability.values();

	private final boolean allowTransports;
	private final boolean bankPathEnabled;
	/** Bank tiles this account may use, in unsigned order: a subset of the static bank tiles. */
	private final int[] accessibleBankTiles;
	private final int bankVisitCost;
	private final View[] local = new View[2];
	/** The global teleports castable with each {@link TeleportCapability}, by ordinal, in each bank layer. */
	private final View[][] global;
	private final long fingerprint;

	private PreparedRoutingAccount(boolean allowTransports, boolean bankPathEnabled, int[] accessibleBankTiles,
		int bankVisitCost, View[] local, View[][] global)
	{
		this.allowTransports = allowTransports;
		this.bankPathEnabled = bankPathEnabled;
		this.accessibleBankTiles = accessibleBankTiles;
		this.bankVisitCost = bankVisitCost;
		this.local[0] = local[0];
		this.local[1] = local[1];
		this.global = global;
		this.fingerprint = computeFingerprint();
	}

	/**
	 * @param accessibleBankTiles the bank tiles whose requirements this account meets, as resolved by
	 * {@code PathfinderConfig.bankAccessible}; the static data knows every bank, so this decides
	 * which of them may switch a route into the banked layer
	 * @param bankVisitCost what switching into the banked layer costs, as legacy's bank-visit edge
	 * ({@code PathfinderConfig.getBankVisitCost})
	 */
	public static PreparedRoutingAccount compile(TransportAvailability carried, TransportAvailability banked,
		boolean bankPathEnabled, Collection<Integer> accessibleBankTiles, int bankVisitCost,
		boolean allowTransports, ToIntFunction<Transport> additionalCost)
	{
		int[] banks = sortedUnsigned(accessibleBankTiles);
		ExactCosts.validate(bankVisitCost);
		View[] local = new View[2];
		View[][] global = new View[CAPABILITIES.length][2];
		for (int bankedState = 0; bankedState < 2; bankedState++)
		{
			TransportAvailability availability = bankedState != 0 ? banked : carried;
			local[bankedState] = allowTransports
				? View.local(availability.getTransportsPacked(), additionalCost) : View.empty(true);
			for (TeleportCapability capability : CAPABILITIES)
				global[capability.ordinal()][bankedState] = allowTransports
					? View.global(availability.getUsableTeleports(), additionalCost, capability) : View.empty(false);
		}
		return new PreparedRoutingAccount(allowTransports, bankPathEnabled, banks, bankVisitCost, local, global);
	}

	private static int[] sortedUnsigned(Collection<Integer> tiles)
	{
		int[] result = new int[tiles.size()];
		int size = 0;
		for (int tile : tiles)
			result[size++] = tile ^ Integer.MIN_VALUE;
		Arrays.sort(result);
		int unique = 0;
		for (int i = 0; i < size; i++)
			if (unique == 0 || result[unique - 1] != result[i])
				result[unique++] = result[i];
		for (int i = 0; i < unique; i++)
			result[i] ^= Integer.MIN_VALUE;
		return Arrays.copyOf(result, unique);
	}

	public boolean allowTransports()
	{
		return allowTransports;
	}
	public boolean bankPathEnabled()
	{
		return bankPathEnabled;
	}
	/**
	 * Whether this account may bank at {@code packedTile}. Only meaningful for a tile the static
	 * data marks as a bank; the forward search asks only there, so the binary search stays rare.
	 */
	public boolean bankAccessible(int packedTile)
	{
		int low = 0, high = accessibleBankTiles.length - 1;
		while (low <= high)
		{
			int middle = (low + high) >>> 1;
			int compare = Integer.compareUnsigned(accessibleBankTiles[middle], packedTile);
			if (compare == 0) return true;
			if (compare < 0) low = middle + 1;
			else high = middle - 1;
		}
		return false;
	}
	/** The cost of switching into the banked layer at an accessible bank. */
	public int bankVisitCost()
	{
		return bankVisitCost;
	}
	public int accessibleBankCount()
	{
		return accessibleBankTiles.length;
	}
	public int accessibleBankTile(int index)
	{
		return accessibleBankTiles[index];
	}
	public long fingerprint()
	{
		return fingerprint;
	}
	public String fingerprintHex()
	{
		return String.format("%016x", fingerprint);
	}

	public int localCount(boolean banked)
	{
		return view(local, banked).count;
	}
	public int localOrigin(boolean banked, int index)
	{
		return view(local, banked).origins[index];
	}
	public int localDestination(boolean banked, int index)
	{
		return view(local, banked).destinations[index];
	}
	public int localCost(boolean banked, int index)
	{
		return view(local, banked).costs[index];
	}
	public int localType(boolean banked, int index)
	{
		return view(local, banked).types[index];
	}
	public int localMaxWilderness(boolean banked, int index)
	{
		return view(local, banked).maxWilderness[index];
	}
	/**
	 * The local transport's action class: entries in one layer share a class exactly when they are
	 * the same game action (type, object and menu option, display text, consumption and item
	 * requirements) to the same destination at the same cost, differing at most in origin. Taking
	 * any of them leads to the same state, so a route may take the action from whichever origin.
	 */
	public int localActionClass(boolean banked, int index)
	{
		return view(local, banked).actionClasses[index];
	}
	/** The global teleports castable outside the wilderness: every global this account has. */
	public int globalCount(boolean banked)
	{
		return globalCount(TeleportCapability.ALL, banked);
	}
	public int globalDestination(boolean banked, int index)
	{
		return globalDestination(TeleportCapability.ALL, banked, index);
	}
	public int globalCost(boolean banked, int index)
	{
		return globalCost(TeleportCapability.ALL, banked, index);
	}
	public int globalType(boolean banked, int index)
	{
		return globalView(TeleportCapability.ALL, banked).types[index];
	}
	public int globalMaxWilderness(boolean banked, int index)
	{
		return globalMaxWilderness(TeleportCapability.ALL, banked, index);
	}
	/** The global teleports castable with {@code capability}. */
	public int globalCount(TeleportCapability capability, boolean banked)
	{
		return globalView(capability, banked).count;
	}
	public int globalDestination(TeleportCapability capability, boolean banked, int index)
	{
		return globalView(capability, banked).destinations[index];
	}
	public int globalCost(TeleportCapability capability, boolean banked, int index)
	{
		return globalView(capability, banked).costs[index];
	}
	public int globalMaxWilderness(TeleportCapability capability, boolean banked, int index)
	{
		return globalView(capability, banked).maxWilderness[index];
	}
	public Transport globalTransport(TeleportCapability capability, boolean banked, int index)
	{
		return globalView(capability, banked).transports[index];
	}

	View localView(boolean banked)
	{
		return view(local, banked);
	}
	View globalView(boolean banked)
	{
		return globalView(TeleportCapability.ALL, banked);
	}
	View globalView(TeleportCapability capability, boolean banked)
	{
		return view(global[capability.ordinal()], banked);
	}

	private static View view(View[] views, boolean banked)
	{
		return views[banked ? 1 : 0];
	}

	private long computeFingerprint()
	{
		long hash = FNV_OFFSET;
		hash = mix(hash, allowTransports ? 1 : 0);
		hash = mix(hash, bankPathEnabled ? 1 : 0);
		hash = u32(hash, bankVisitCost);
		hash = u32(hash, accessibleBankTiles.length);
		for (int tile : accessibleBankTiles)
			hash = u32(hash, tile);
		for (int kind = 0; kind <= CAPABILITIES.length; kind++)
		{
			for (int banked = 0; banked < 2; banked++)
			{
				View view = kind == 0 ? local[banked] : global[kind - 1][banked];
				hash = mix(hash, kind);
				hash = mix(hash, banked);
				for (int i = 0; i < view.count; i++)
				{
					if (kind == 0)
						hash = u32(hash, view.origins[i]);
					hash = u32(hash, view.destinations[i]);
					hash = u32(hash, view.costs[i]);
					hash = u32(hash, view.types[i]);
					hash = u32(hash, view.maxWilderness[i]);
				}
			}
		}
		return hash;
	}

	private static long u32(long hash, int value)
	{
		for (int shift = 0; shift < 32; shift += 8)
			hash = mix(hash, value >>> shift);
		return hash;
	}

	private static long mix(long hash, int value)
	{
		return (hash ^ (value & 0xffL)) * FNV_PRIME;
	}

	static String transportTypeName(int ordinal)
	{
		return TransportType.values()[ordinal].name();
	}

	static final class View
	{
		final boolean local;
		final int count;
		final int[] origins;
		final int[] destinations;
		final int[] costs;
		final int[] types;
		final int[] maxWilderness;
		final int[] actionClasses;
		/** The transport each row represents; parallel to the other arrays so a search can
		 *  report which transport produced an edge, not just its effect. */
		final Transport[] transports;

		private View(boolean local, int[] origins, int[] destinations, int[] costs, int[] types, int[] maxWilderness,
			int[] actionClasses, Transport[] transports)
		{
			this.local = local;
			this.count = destinations.length;
			this.origins = origins;
			this.destinations = destinations;
			this.costs = costs;
			this.types = types;
			this.maxWilderness = maxWilderness;
			this.actionClasses = actionClasses;
			this.transports = transports;
		}

		static View empty(boolean local)
		{
			return new View(local, new int[0], new int[0], new int[0], new int[0], new int[0], new int[0],
				new Transport[0]);
		}

		static View local(PrimitiveIntHashMap<Transport[]> map, ToIntFunction<Transport> additionalCost)
		{
			Builder builder = new Builder(true);
			int[] origins = map.keys();
			Arrays.sort(origins);
			for (int origin : origins)
			{
				Transport[] transports = map.getOrDefault(origin, TransportAvailability.EMPTY_TRANSPORTS);
				for (Transport transport : transports)
					builder.add(origin, transport, additionalCost);
			}
			return builder.build();
		}

		static View global(Transport[] transports, ToIntFunction<Transport> additionalCost,
			TeleportCapability capability)
		{
			Builder builder = new Builder(false);
			for (Transport transport : transports)
			{
				if (capability.canCast(transport))
				{
					builder.add(0, transport, additionalCost);
				}
			}
			return builder.build();
		}
	}

	private static final class Builder
	{
		private final boolean local;
		private int size;
		private int[] origins = new int[16];
		private int[] destinations = new int[16];
		private int[] costs = new int[16];
		private int[] types = new int[16];
		private int[] maxWilderness = new int[16];
		private int[] actionClasses = new int[16];
		private Transport[] transports = new Transport[16];
		private final java.util.Map<java.util.List<Object>, Integer> actionClassIds = new java.util.HashMap<>();

		Builder(boolean local)
		{
			this.local = local;
		}

		void add(int origin, Transport transport, ToIntFunction<Transport> additionalCost)
		{
			if (size == destinations.length)
			{
				int capacity = size * 2;
				origins = Arrays.copyOf(origins, capacity);
				destinations = Arrays.copyOf(destinations, capacity);
				costs = Arrays.copyOf(costs, capacity);
				types = Arrays.copyOf(types, capacity);
				maxWilderness = Arrays.copyOf(maxWilderness, capacity);
				actionClasses = Arrays.copyOf(actionClasses, capacity);
				transports = Arrays.copyOf(transports, capacity);
			}
			origins[size] = origin;
			destinations[size] = transport.getDestination();
			costs[size] = ExactCosts.add(transport.getDuration(), additionalCost.applyAsInt(transport));
			types[size] = transport.getType().ordinal();
			maxWilderness[size] = transport.getMaxWildernessLevel();
			actionClasses[size] = actionClass(transport, costs[size]);
			transports[size] = transport;
			size++;
		}

		private int actionClass(Transport transport, int cost)
		{
			// An action without an object description is never grouped: a class of its own, below zero.
			if (!local || transport.getObjectInfo() == null) return -1 - size;
			java.util.List<Object> key = java.util.Arrays.asList(transport.getType(), transport.getDestination(), cost,
				transport.getMaxWildernessLevel(), transport.getObjectInfo(), transport.getDisplayInfo(),
				transport.isConsumable(), transport.getItemRequirements());
			return actionClassIds.computeIfAbsent(key, k -> actionClassIds.size());
		}

		View build()
		{
			// Origins arrive in signed order but lookups need unsigned order, so plane 2/3 tiles
			// are out of place; an insertion sort was quadratic here.
			Integer[] order = new Integer[size];
			for (int i = 0; i < size; i++)
				order[i] = i;
			Arrays.sort(order, this::compare);
			int[] sortedOrigins = new int[size];
			int[] sortedDestinations = new int[size];
			int[] sortedCosts = new int[size];
			int[] sortedTypes = new int[size];
			int[] sortedMaxWilderness = new int[size];
			int[] sortedActionClasses = new int[size];
			Transport[] sortedTransports = new Transport[size];
			for (int i = 0; i < size; i++)
			{
				int from = order[i];
				sortedOrigins[i] = origins[from];
				sortedDestinations[i] = destinations[from];
				sortedCosts[i] = costs[from];
				sortedTypes[i] = types[from];
				sortedMaxWilderness[i] = maxWilderness[from];
				sortedActionClasses[i] = actionClasses[from];
				sortedTransports[i] = transports[from];
			}
			return new View(local, sortedOrigins, sortedDestinations, sortedCosts, sortedTypes, sortedMaxWilderness,
				sortedActionClasses, sortedTransports);
		}

		private int compare(int left, int right)
		{
			int result = Integer.compareUnsigned(origins[left], origins[right]);
			if (result != 0)
				return result;
			result = Integer.compareUnsigned(destinations[left], destinations[right]);
			if (result != 0)
				return result;
			result = Integer.compare(costs[left], costs[right]);
			if (result != 0)
				return result;
			result = Integer.compare(types[left], types[right]);
			return result != 0 ? result : Integer.compare(maxWilderness[left], maxWilderness[right]);
		}
	}
}

package shortestpath.pathfinder.exact;

import java.util.function.BooleanSupplier;
import shortestpath.pathfinder.CollisionMap;

/**
 * Target-lifetime preparation: the target overlay, its reverse labels and the heuristic built
 * from them. None of it depends on the start, so one prepared target serves any number of
 * forward searches for the same account snapshot. With several target tiles, a search ends at
 * whichever target is cheapest to reach.
 */
public final class PreparedTarget
{
	private final TargetOverlay overlay;
	private final PreparedHeuristic heuristic;
	private final long reverseSearchNanos;
	private final long heuristicPrepareNanos;

	private PreparedTarget(TargetOverlay overlay, PreparedHeuristic heuristic, long reverseSearchNanos,
		long heuristicPrepareNanos)
	{
		this.overlay = overlay;
		this.heuristic = heuristic;
		this.reverseSearchNanos = reverseSearchNanos;
		this.heuristicPrepareNanos = heuristicPrepareNanos;
	}

	public static PreparedTarget prepare(SiteGraph graph, CollisionMap collision, int packed)
	{
		return prepare(graph, collision, new int[] {packed});
	}

	public static PreparedTarget prepare(SiteGraph graph, CollisionMap collision, int[] packedTargets)
	{
		TargetOverlay overlay = new TargetOverlay(graph, collision, packedTargets);
		long phaseStarted = System.nanoTime();
		ReverseLabels reverse = ReverseLabels.compute(overlay);
		long reverseSearchNanos = System.nanoTime() - phaseStarted;
		phaseStarted = System.nanoTime();
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(overlay, reverse);
		long heuristicPrepareNanos = System.nanoTime() - phaseStarted;
		return new PreparedTarget(overlay, heuristic, reverseSearchNanos, heuristicPrepareNanos);
	}

	public ExactForwardSearch.Result search(int start, BooleanSupplier cancelled, double heuristicWeight)
	{
		return search(start, cancelled, heuristicWeight, SearchRestrictions.none(), ExactForwardSearch.NO_PROGRESS);
	}

	/**
	 * {@code restrictions} mirrors the positional gates legacy applies per edge; they only remove
	 * edges, so the prepared heuristic stays admissible and this target may be reused.
	 * {@code progressed} runs each time the closest-reached-tile record improves.
	 */
	public ExactForwardSearch.Result search(int start, BooleanSupplier cancelled, double heuristicWeight,
		SearchRestrictions restrictions, Runnable progressed)
	{
		return ExactForwardSearch.search(overlay, heuristic, start, cancelled, true, heuristicWeight,
			restrictions, progressed);
	}

	public TargetOverlay overlay()
	{
		return overlay;
	}
	public PreparedHeuristic heuristic()
	{
		return heuristic;
	}
	/** The target tiles, in unsigned order. */
	public int[] packedTargets()
	{
		return overlay.packedTargets();
	}
	/** Time the reverse relaxed search took when this target was prepared. */
	public long reverseSearchNanos()
	{
		return reverseSearchNanos;
	}
	/** Time the heuristic seed/generator tables took when this target was prepared. */
	public long heuristicPrepareNanos()
	{
		return heuristicPrepareNanos;
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;

/** Exact relaxed reverse labels with a clique oracle and sparse production path. */
public final class ReverseLabels
{
	private final TargetOverlay overlay;
	private final int[] labels;
	private final int[] generatorOrigins;
	private final int[] generatorWeights;
	private final int settled;
	private final int stale;
	private final int pushes;
	private final int sparseRelaxations;
	private final int explicitRelaxations;
	private final int attachmentRelaxations;
	private final long elapsedNanos;
	private final boolean sparse;

	private ReverseLabels(TargetOverlay overlay, int[] labels, int[] generatorOrigins, int[] generatorWeights,
		int settled, int stale, int pushes, int sparseRelaxations, int explicitRelaxations,
		int attachmentRelaxations, long elapsedNanos, boolean sparse)
	{
		this.overlay = overlay;
		this.labels = labels;
		this.generatorOrigins = generatorOrigins;
		this.generatorWeights = generatorWeights;
		this.settled = settled;
		this.stale = stale;
		this.pushes = pushes;
		this.sparseRelaxations = sparseRelaxations;
		this.explicitRelaxations = explicitRelaxations;
		this.attachmentRelaxations = attachmentRelaxations;
		this.elapsedNanos = elapsedNanos;
		this.sparse = sparse;
	}

	/** Production path; test fixtures without a sparse network fall back to the clique reference. */
	public static ReverseLabels compute(TargetOverlay overlay)
	{
		return usableSparse(overlay) ? computeSparse(overlay) : computeClique(overlay);
	}

	/** Transparent component-clique correctness oracle. */
	static ReverseLabels computeClique(TargetOverlay overlay)
	{
		long started = System.nanoTime();
		SiteGraph graph = overlay.graph();
		RoutingStatic stat = overlay.routingStatic();
		int spatialCount = graph.spatialNodeCount();
		int[] labels = new int[overlay.queryNodeCount() * 2];
		Arrays.fill(labels, ExactCosts.INF);
		ExactMinHeap queue = new ExactMinHeap(Math.max(16, labels.length));
		int pushes = 0;
		for (int target = 0; target < overlay.targetCount(); target++)
		{
			for (boolean banked : new boolean[] {false, true})
			{
				int seed = overlay.targetState(target, banked);
				labels[seed] = 0;
				queue.push(0, 0, seed);
				pushes++;
			}
		}
		int settled = 0, stale = 0;
		while (queue.poll())
		{
			int state = queue.state(), cost = queue.cost();
			if (cost != labels[state])
			{
				stale++;
				continue;
			}
			settled++;
			int node = state / 2;
			boolean banked = (state & 1) != 0;
			if (node < graph.nodeCount())
			{
				for (int edge = graph.reverseEdgeStart(state); edge < graph.reverseEdgeEnd(state); edge++)
				{
					if (relax(labels, queue, graph.reverseFromState(edge),
						ExactCosts.add(cost, graph.reverseCost(edge))))
						pushes++;
				}
			}
			if (node < spatialCount)
			{
				for (int component : stat.siteComponents(node))
				{
					for (int other : stat.componentSites(component))
					{
						if (other != node && relax(labels, queue, SiteGraph.stateId(other, banked),
							ExactCosts.add(cost, distance(stat.siteTile(node), stat.siteTile(other)))))
							pushes++;
					}
				}
				// Targets are seeded at zero, so walking from a site into a target never improves it.
			}
			else
			{
				int target = overlay.syntheticTarget(node);
				for (int i = 0; target >= 0 && i < overlay.attachmentCount(target); i++)
				{
					if (relax(labels, queue, SiteGraph.stateId(overlay.attachmentSite(target, i), banked),
						ExactCosts.add(cost, overlay.attachmentCost(target, i))))
						pushes++;
				}
			}
		}
		return new ReverseLabels(overlay, labels, null, null, settled, stale, pushes, 0, 0, 0,
			System.nanoTime() - started, false);
	}

	/** Sparse CSR reverse Dijkstra, including internal Steiner states. */
	static ReverseLabels computeSparse(TargetOverlay overlay)
	{
		long started = System.nanoTime();
		SiteGraph graph = overlay.graph();
		RoutingStatic stat = overlay.routingStatic();
		int routingNodes = overlay.queryNodeCount();
		int originalCount = stat.sparseOriginalCount();
		int stateCount = (routingNodes + stat.sparseSteinerCount()) * 2;
		int[] doubled = new int[stateCount];
		int[] origins = new int[stateCount];
		int[] weights = new int[stateCount];
		Arrays.fill(doubled, ExactCosts.INF);
		Arrays.fill(origins, -1);
		Arrays.fill(weights, ExactCosts.INF);
		ExactMinHeap queue = new ExactMinHeap(Math.max(16, stateCount));
		int pushes = 0;
		for (int target = 0; target < overlay.targetCount(); target++)
		{
			for (boolean banked : new boolean[] {false, true})
			{
				int seed = overlay.targetState(target, banked);
				doubled[seed] = 0;
				origins[seed] = seed;
				weights[seed] = 0;
				queue.push(0, 0, seed);
				pushes++;
			}
		}
		int settled = 0, stale = 0;
		int sparseEdges = 0, explicitEdges = 0, attachmentEdges = 0;
		while (queue.poll())
		{
			int state = queue.state(), cost = queue.cost();
			if (cost != doubled[state])
			{
				stale++;
				continue;
			}
			settled++;
			int vertex = state / 2;
			boolean banked = (state & 1) != 0;
			if (vertex < graph.nodeCount())
			{
				for (int edge = graph.reverseEdgeStart(state); edge < graph.reverseEdgeEnd(state); edge++)
				{
					explicitEdges++;
					int edgeCost = ExactCosts.twice(graph.reverseCost(edge));
					if (relax(doubled, origins, weights, queue, state,
						graph.reverseFromState(edge), edgeCost, graph.reverseStartsGenerator(edge)))
						pushes++;
				}
			}
			if (vertex < originalCount || vertex >= routingNodes)
			{
				int sparseVertex = vertex < originalCount ? vertex : originalCount + vertex - routingNodes;
				for (int edge = stat.sparseOffset(sparseVertex); edge < stat.sparseOffset(sparseVertex + 1); edge++)
				{
					sparseEdges++;
					int destination = sparseNode(routingNodes, originalCount, stat.sparseDestination(edge));
					if (relax(doubled, origins, weights, queue, state, SiteGraph.stateId(destination, banked),
						stat.sparseWeight(edge), false))
						pushes++;
				}
			}
			// Targets are seeded at zero, so walking from a site into a target never improves it;
			// only a synthetic target's own attachment edges need relaxing.
			int target = vertex < routingNodes ? overlay.syntheticTarget(vertex) : -1;
			for (int i = 0; target >= 0 && i < overlay.attachmentCount(target); i++)
			{
				attachmentEdges++;
				if (relax(doubled, origins, weights, queue, state,
					SiteGraph.stateId(overlay.attachmentSite(target, i), banked),
					ExactCosts.twice(overlay.attachmentCost(target, i)), false))
					pushes++;
			}
		}
		int[] labels = new int[routingNodes * 2];
		int[] routingOrigins = new int[routingNodes * 2];
		int[] routingWeights = new int[routingNodes * 2];
		for (int state = 0; state < labels.length; state++)
		{
			labels[state] = ExactCosts.halve(doubled[state]);
			routingOrigins[state] = origins[state];
			routingWeights[state] = weights[state];
		}
		return new ReverseLabels(overlay, labels, routingOrigins, routingWeights, settled, stale, pushes,
			sparseEdges, explicitEdges, attachmentEdges, System.nanoTime() - started, true);
	}

	public TargetOverlay overlay()
	{
		return overlay;
	}
	public int label(int node, boolean banked)
	{
		return labels[SiteGraph.stateId(node, banked)];
	}
	public int targetLabel(boolean banked)
	{
		return labels[overlay.targetState(banked)];
	}
	public int targetLabel(int target, boolean banked)
	{
		return labels[overlay.targetState(target, banked)];
	}
	public int stateCount()
	{
		return labels.length;
	}
	public int[] labels()
	{
		return labels.clone();
	}
	public int settledCount()
	{
		return settled;
	}
	public int staleCount()
	{
		return stale;
	}
	public int pushCount()
	{
		return pushes;
	}
	public boolean sparse()
	{
		return sparse;
	}
	public int sparseRelaxationCount()
	{
		return sparseRelaxations;
	}
	public int explicitRelaxationCount()
	{
		return explicitRelaxations;
	}
	public int attachmentRelaxationCount()
	{
		return attachmentRelaxations;
	}
	public long elapsedNanos()
	{
		return elapsedNanos;
	}
	boolean hasProvenance()
	{
		return generatorOrigins != null;
	}
	int generatorOrigin(int state)
	{
		return generatorOrigins[state];
	}
	int generatorWeightDoubled(int state)
	{
		return generatorWeights[state];
	}
	int doubledLabel(int state)
	{
		return ExactCosts.twice(labels[state]);
	}

	private static boolean usableSparse(TargetOverlay overlay)
	{
		RoutingStatic stat = overlay.routingStatic();
		return stat.sparseAdjacencyCount() != 0 || stat.siteCount() <= 1;
	}

	private static int sparseNode(int routingNodes, int originalCount, int sparseVertex)
	{
		return sparseVertex < originalCount ? sparseVertex : routingNodes + sparseVertex - originalCount;
	}

	private static boolean relax(int[] labels, ExactMinHeap queue, int state, int candidate)
	{
		if (candidate == ExactCosts.INF || candidate >= labels[state])
			return false;
		labels[state] = candidate;
		queue.push(candidate, candidate, state);
		return true;
	}

	private static boolean relax(int[] distances, int[] origins, int[] weights, ExactMinHeap queue, int from,
		int next, int edgeCost, boolean startsGenerator)
	{
		int candidate = ExactCosts.add(distances[from], edgeCost);
		if (candidate == ExactCosts.INF || candidate >= distances[next])
			return false;
		distances[next] = candidate;
		if (startsGenerator)
		{
			origins[next] = next;
			weights[next] = candidate;
		}
		else
		{
			origins[next] = origins[from];
			weights[next] = weights[from];
		}
		queue.push(candidate, candidate, next);
		return true;
	}

	private static int distance(int left, int right)
	{
		return shortestpath.WorldPointUtil.distanceBetween(left, right);
	}
}

package shortestpath.pathfinder.exact;

import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Objects;

/**
 * Separator cut edges for the exact backend, stored as {@code routing-cuts.bin}.
 *
 * <p>The cuts are generated offline with KaHIP by the tooling repository and committed next to
 * {@code collision-map.zip}. They only affect performance: {@link RoutingStaticBuilder} ignores
 * cuts that are no longer walking edges or no longer separate anything, so stale cuts never make
 * routes wrong.
 *
 * <p>Format, all little-endian:
 * <pre>
 * 8 bytes  ASCII "RSPCUTS\0"
 * u32      format version, exactly 1
 * u64      FNV-1a 64 of the collision-map.zip bytes the cuts were generated from (informational)
 * i32 x 5  maximum component size, minimum child size, maximum separator size, imbalance, seed
 * u8 + n   KaHIP preconfiguration name, ASCII
 * u32      cut count
 * u32 x 2n cut pairs (from, to): from &lt; to (unsigned), pairs strictly ascending
 * </pre>
 * The reader rejects a wrong header, truncation, unsorted or duplicate pairs, and trailing bytes.
 */
public final class RoutingCuts
{
	public static final String RESOURCE = "/routing-cuts.bin";
	private static final byte[] MAGIC = "RSPCUTS\0".getBytes(StandardCharsets.US_ASCII);
	private static final int FORMAT_VERSION = 1;
	private static final long FNV_OFFSET = 0xcbf29ce484222325L;
	private static final long FNV_PRIME = 0x100000001b3L;

	private final long collisionFingerprint;
	private final Parameters parameters;
	private final int[] pairs;

	/** The KaHIP partitioning parameters the cuts were generated with. */
	public static final class Parameters
	{
		public final int maximumComponentSize;
		public final int minimumChildSize;
		public final int maximumSeparatorSize;
		public final int imbalance;
		public final int seed;
		public final String preconfiguration;

		public Parameters(int maximumComponentSize, int minimumChildSize, int maximumSeparatorSize, int imbalance,
			int seed, String preconfiguration)
		{
			this.maximumComponentSize = maximumComponentSize;
			this.minimumChildSize = minimumChildSize;
			this.maximumSeparatorSize = maximumSeparatorSize;
			this.imbalance = imbalance;
			this.seed = seed;
			this.preconfiguration = Objects.requireNonNull(preconfiguration, "preconfiguration");
			if (preconfiguration.length() > 255 || !StandardCharsets.US_ASCII.newEncoder().canEncode(preconfiguration))
				throw new IllegalArgumentException("preconfiguration must be ASCII and at most 255 characters");
		}

		@Override
		public boolean equals(Object other)
		{
			if (!(other instanceof Parameters)) return false;
			Parameters that = (Parameters) other;
			return maximumComponentSize == that.maximumComponentSize && minimumChildSize == that.minimumChildSize
				&& maximumSeparatorSize == that.maximumSeparatorSize && imbalance == that.imbalance
				&& seed == that.seed && preconfiguration.equals(that.preconfiguration);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(maximumComponentSize, minimumChildSize, maximumSeparatorSize, imbalance, seed,
				preconfiguration);
		}

		@Override
		public String toString()
		{
			return maximumComponentSize + " " + minimumChildSize + " " + maximumSeparatorSize + " " + imbalance
				+ " " + seed + " " + preconfiguration;
		}
	}

	/**
	 * @param pairs cut edges as packed {@code (from, to)} tile pairs; they are canonicalised
	 *              ({@code from < to}), sorted and de-duplicated
	 */
	public RoutingCuts(long collisionFingerprint, Parameters parameters, int[] pairs)
	{
		if (pairs.length % 2 != 0) throw new IllegalArgumentException("cut pairs must have even length");
		this.collisionFingerprint = collisionFingerprint;
		this.parameters = Objects.requireNonNull(parameters, "parameters");
		this.pairs = canonicalise(pairs);
	}

	private RoutingCuts(long collisionFingerprint, Parameters parameters, int[] pairs, boolean trusted)
	{
		this.collisionFingerprint = collisionFingerprint;
		this.parameters = parameters;
		this.pairs = pairs;
	}

	public long collisionFingerprint()
	{
		return collisionFingerprint;
	}

	public Parameters parameters()
	{
		return parameters;
	}

	public int cutCount()
	{
		return pairs.length / 2;
	}

	/** Cut edges as a flat array: {@code [2*i]} is the lower tile, {@code [2*i+1]} the higher. */
	public int[] pairs()
	{
		return pairs.clone();
	}

	/** No cuts at all: builds without separators, so it only costs performance. */
	public static RoutingCuts empty()
	{
		return new RoutingCuts(0, new Parameters(0, 0, 0, 0, 0, ""), new int[0]);
	}

	/**
	 * Loads the packaged {@code routing-cuts.bin}, or an empty index when the jar does not
	 * contain it: missing cuts only affect build performance, never the routes. A corrupt
	 * resource still fails loudly, since that indicates a broken build rather than an
	 * optional one.
	 */
	public static RoutingCuts loadFromResources()
	{
		try (InputStream stream = RoutingCuts.class.getResourceAsStream(RESOURCE))
		{
			if (stream == null) return empty();
			return read(stream.readAllBytes());
		}
		catch (IOException error)
		{
			throw new IllegalStateException("cannot load " + RESOURCE + ": " + error.getMessage(), error);
		}
	}

	public static RoutingCuts read(byte[] bytes) throws IOException
	{
		ByteBuffer input = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
		byte[] magic = new byte[MAGIC.length];
		require(input, magic.length, "magic");
		input.get(magic);
		if (!Arrays.equals(magic, MAGIC)) throw new IOException("routing-cuts wrong magic");
		require(input, 4 + 8 + 5 * 4 + 1, "header");
		int version = input.getInt();
		if (version != FORMAT_VERSION) throw new IOException("unsupported routing-cuts version " + version);
		long fingerprint = input.getLong();
		int maximumComponentSize = input.getInt();
		int minimumChildSize = input.getInt();
		int maximumSeparatorSize = input.getInt();
		int imbalance = input.getInt();
		int seed = input.getInt();
		int nameLength = Byte.toUnsignedInt(input.get());
		require(input, nameLength, "preconfiguration");
		byte[] name = new byte[nameLength];
		input.get(name);
		for (byte value : name)
			if (value < 0x20 || value > 0x7e) throw new IOException("routing-cuts preconfiguration is not ASCII");
		require(input, 4, "cut count");
		long count = Integer.toUnsignedLong(input.getInt());
		if (count * 8 != input.remaining())
			throw new IOException(count * 8 > input.remaining() ? "truncated routing-cuts pairs"
				: "routing-cuts has trailing bytes");
		int[] pairs = new int[(int) count * 2];
		for (int i = 0; i < pairs.length; i += 2)
		{
			pairs[i] = input.getInt();
			pairs[i + 1] = input.getInt();
			if (Integer.compareUnsigned(pairs[i], pairs[i + 1]) >= 0)
				throw new IOException("routing-cuts pair " + i / 2 + " is not canonical");
			if (i > 0 && comparePairs(pairs, i - 2, i) >= 0)
				throw new IOException("routing-cuts pairs are not strictly ascending at " + i / 2);
		}
		return new RoutingCuts(fingerprint, new Parameters(maximumComponentSize, minimumChildSize,
			maximumSeparatorSize, imbalance, seed, new String(name, StandardCharsets.US_ASCII)), pairs, true);
	}

	public byte[] write()
	{
		byte[] name = parameters.preconfiguration.getBytes(StandardCharsets.US_ASCII);
		ByteBuffer output = ByteBuffer.allocate(MAGIC.length + 4 + 8 + 5 * 4 + 1 + name.length + 4 + pairs.length * 4)
			.order(ByteOrder.LITTLE_ENDIAN);
		output.put(MAGIC);
		output.putInt(FORMAT_VERSION);
		output.putLong(collisionFingerprint);
		output.putInt(parameters.maximumComponentSize);
		output.putInt(parameters.minimumChildSize);
		output.putInt(parameters.maximumSeparatorSize);
		output.putInt(parameters.imbalance);
		output.putInt(parameters.seed);
		output.put((byte) name.length);
		output.put(name);
		output.putInt(pairs.length / 2);
		for (int value : pairs)
			output.putInt(value);
		return output.array();
	}

	/** FNV-1a 64 over raw bytes; used to identify the collision map a cut file was generated from. */
	public static long fingerprint(byte[] bytes)
	{
		long hash = FNV_OFFSET;
		for (byte value : bytes)
			hash = (hash ^ (value & 0xffL)) * FNV_PRIME;
		return hash;
	}

	private static void require(ByteBuffer input, int bytes, String label) throws IOException
	{
		if (input.remaining() < bytes) throw new IOException("truncated routing-cuts " + label);
	}

	private static int[] canonicalise(int[] raw)
	{
		long[] keys = new long[raw.length / 2];
		for (int i = 0; i < keys.length; i++)
		{
			int a = raw[2 * i], b = raw[2 * i + 1];
			if (a == b) throw new IllegalArgumentException("cut is a self edge");
			int low = Integer.compareUnsigned(a, b) < 0 ? a : b;
			int high = low == a ? b : a;
			keys[i] = (Integer.toUnsignedLong(low) << 32) | Integer.toUnsignedLong(high);
		}
		long[] unique = Arrays.stream(keys).sorted().distinct().toArray();
		int[] result = new int[unique.length * 2];
		for (int i = 0; i < unique.length; i++)
		{
			result[2 * i] = (int) (unique[i] >>> 32);
			result[2 * i + 1] = (int) unique[i];
		}
		return result;
	}

	private static int comparePairs(int[] pairs, int left, int right)
	{
		int compare = Integer.compareUnsigned(pairs[left], pairs[right]);
		return compare != 0 ? compare : Integer.compareUnsigned(pairs[left + 1], pairs[right + 1]);
	}
}

package shortestpath.pathfinder.exact;

import java.io.IOException;
import java.util.Arrays;
import shortestpath.pathfinder.CollisionMap;

/** Immutable primitive-array representation of the exact backend's static routing data. */
public final class RoutingStatic
{
	private final int[] searchTiles, searchComponents, northNodes, southNodes;
	private final byte[] walkingMasks;
	private final int[] siteTiles, siteComponentOffsets, siteComponentIds;
	private final int routingComponentCount;
	private final int[] componentSiteOffsets, componentSiteIds, reachableBankTiles;
	private final byte[] reachableBankNodes, reachableBankSites;
	private final int[] crossingFromSite, crossingToSite, crossingCosts;
	private final int sparseOriginalCount, sparseVertexCount, sparseSteinerCount;
	private final int sparseUndirectedEdgeCount, sparseAdjacencyCount;
	private final int[] sparseOffsets, sparseDestinations, sparseWeights;

	private RoutingStatic(int[] searchTiles, int[] searchComponents, byte[] walkingMasks, int[] northNodes,
		int[] southNodes, int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds,
		int routingComponentCount, int[] componentSiteOffsets, int[] componentSiteIds, int[] reachableBankTiles,
		int[] crossingFromSite, int[] crossingToSite, int[] crossingCosts, int sparseOriginalCount,
		int sparseVertexCount, int sparseSteinerCount, int sparseUndirectedEdgeCount, int sparseAdjacencyCount,
		int[] sparseOffsets, int[] sparseDestinations, int[] sparseWeights)
	{
		this.searchTiles = searchTiles;
		this.searchComponents = searchComponents;
		this.walkingMasks = walkingMasks;
		this.northNodes = northNodes;
		this.southNodes = southNodes;
		this.siteTiles = siteTiles;
		this.siteComponentOffsets = siteComponentOffsets;
		this.siteComponentIds = siteComponentIds;
		this.routingComponentCount = routingComponentCount;
		this.componentSiteOffsets = componentSiteOffsets;
		this.componentSiteIds = componentSiteIds;
		this.reachableBankTiles = reachableBankTiles;
		this.reachableBankNodes = new byte[searchTiles.length];
		this.reachableBankSites = new byte[siteTiles.length];
		for (int tile : reachableBankTiles)
		{
			int node = binarySearch(searchTiles, tile);
			if (node >= 0) reachableBankNodes[node] = 1;
			int site = binarySearch(siteTiles, tile);
			if (site >= 0) reachableBankSites[site] = 1;
		}
		this.crossingFromSite = crossingFromSite;
		this.crossingToSite = crossingToSite;
		this.crossingCosts = crossingCosts;
		this.sparseOriginalCount = sparseOriginalCount;
		this.sparseVertexCount = sparseVertexCount;
		this.sparseSteinerCount = sparseSteinerCount;
		this.sparseUndirectedEdgeCount = sparseUndirectedEdgeCount;
		this.sparseAdjacencyCount = sparseAdjacencyCount;
		this.sparseOffsets = sparseOffsets;
		this.sparseDestinations = sparseDestinations;
		this.sparseWeights = sparseWeights;
	}

	static RoutingStatic create(int[] searchTiles, int[] searchComponents, byte[] walkingMasks, int[] northNodes,
		int[] southNodes, int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds,
		int routingComponentCount, int[] componentSiteOffsets, int[] componentSiteIds, int[] reachableBankTiles,
		int[] crossingFromSite, int[] crossingToSite, int[] crossingCosts, int sparseOriginalCount,
		int sparseVertexCount, int sparseSteinerCount, int sparseUndirectedEdgeCount, int sparseAdjacencyCount,
		int[] sparseOffsets, int[] sparseDestinations, int[] sparseWeights) throws IOException
	{
		RoutingStatic result = new RoutingStatic(searchTiles.clone(), searchComponents.clone(), walkingMasks.clone(),
			northNodes.clone(), southNodes.clone(), siteTiles.clone(), siteComponentOffsets.clone(),
			siteComponentIds.clone(), routingComponentCount, componentSiteOffsets.clone(), componentSiteIds.clone(),
			reachableBankTiles.clone(), crossingFromSite.clone(), crossingToSite.clone(), crossingCosts.clone(),
			sparseOriginalCount, sparseVertexCount, sparseSteinerCount, sparseUndirectedEdgeCount, sparseAdjacencyCount,
			sparseOffsets.clone(), sparseDestinations.clone(), sparseWeights.clone());
		result.validate();
		return result;
	}

	private void validate() throws IOException
	{
		aligned(searchComponents, searchTiles.length, "search components");
		aligned(walkingMasks, searchTiles.length, "walking masks");
		aligned(northNodes, searchTiles.length, "north nodes");
		aligned(southNodes, searchTiles.length, "south nodes");
		ascending(searchTiles, "search tiles");
		ascending(siteTiles, "site tiles");
		ascending(reachableBankTiles, "reachable bank tiles");
		refs(searchComponents, routingComponentCount, "search component");
		nodeRefs(northNodes, searchTiles.length, "north node");
		nodeRefs(southNodes, searchTiles.length, "south node");
		csr(siteComponentOffsets, siteComponentIds, siteTiles.length, routingComponentCount, "site components");
		csr(componentSiteOffsets, componentSiteIds, routingComponentCount, siteTiles.length, "component sites");
		for (int tile : reachableBankTiles)
			if (siteIndex(tile) < 0)
				throw new IOException("reachable bank tile is not a static site: " + Integer.toUnsignedString(tile));
		aligned(crossingToSite, crossingFromSite.length, "crossing destinations");
		aligned(crossingCosts, crossingFromSite.length, "crossing costs");
		for (int i = 0; i < crossingFromSite.length; i++)
		{
			if (crossingFromSite[i] < 0 || crossingFromSite[i] >= siteTiles.length || crossingToSite[i] < 0
				|| crossingToSite[i] >= siteTiles.length)
				throw new IOException("crossing site out of range at index " + i);
			if (crossingFromSite[i] == crossingToSite[i] || crossingCosts[i] < 0)
				throw new IOException("invalid crossing at index " + i);
		}
		if (sparseOriginalCount != siteTiles.length || sparseSteinerCount != sparseVertexCount - sparseOriginalCount
			|| sparseAdjacencyCount != 2L * sparseUndirectedEdgeCount)
			throw new IOException("inconsistent sparse counts");
		csr(sparseOffsets, sparseDestinations, sparseVertexCount, sparseVertexCount, "sparse");
		for (int weight : sparseWeights)
			if (weight < 0)
				throw new IOException("negative sparse weight");
		if (sparseWeights.length != sparseDestinations.length)
			throw new IOException("sparse weight length mismatch");
		validateRelations();
	}

	private static void aligned(Object array, int length, String label) throws IOException
	{
		if (java.lang.reflect.Array.getLength(array) != length)
			throw new IOException(label + " length mismatch");
	}

	private static void ascending(int[] values, String label) throws IOException
	{
		for (int i = 1; i < values.length; i++)
			if (Integer.compareUnsigned(values[i - 1], values[i]) >= 0)
				throw new IOException(label + " is not strictly ascending at index " + i);
	}

	private static void refs(int[] values, int limit, String label) throws IOException
	{
		for (int value : values)
			if (value < 0 || value >= limit)
				throw new IOException(label + " out of range");
	}

	private static void nodeRefs(int[] values, int limit, String label) throws IOException
	{
		for (int value : values)
			if (value != -1 && (value < 0 || value >= limit))
				throw new IOException(label + " out of range");
	}

	private static void csr(int[] offsets, int[] values, int groups, int limit, String label) throws IOException
	{
		if (offsets.length != groups + 1 || offsets.length == 0 || offsets[0] != 0
			|| offsets[offsets.length - 1] != values.length)
			throw new IOException(label + " offsets are invalid");
		for (int i = 1; i < offsets.length; i++)
			if (offsets[i] < offsets[i - 1])
				throw new IOException(label + " offsets are not monotonic at index " + i);
		for (int value : values)
			if (value < 0 || value >= limit)
				throw new IOException(label + " reference out of range");
	}

	private void validateRelations() throws IOException
	{
		for (int site = 0; site < siteTiles.length; site++)
			for (int p = siteComponentOffsets[site]; p < siteComponentOffsets[site + 1]; p++)
				if (!contains(componentSiteIds, componentSiteOffsets[siteComponentIds[p]],
						componentSiteOffsets[siteComponentIds[p] + 1], site))
					throw new IOException("site/component relation is not reciprocal");
		for (int component = 0; component < routingComponentCount; component++)
			for (int p = componentSiteOffsets[component]; p < componentSiteOffsets[component + 1]; p++)
				if (!contains(siteComponentIds, siteComponentOffsets[componentSiteIds[p]],
						siteComponentOffsets[componentSiteIds[p] + 1], component))
					throw new IOException("component/site relation is not reciprocal");
	}

	private static boolean contains(int[] values, int start, int end, int target)
	{
		for (int i = start; i < end; i++)
			if (values[i] == target)
				return true;
		return false;
	}

	public int searchTileCount()
	{
		return searchTiles.length;
	}
	public int siteCount()
	{
		return siteTiles.length;
	}
	public int routingComponentCount()
	{
		return routingComponentCount;
	}
	public int reachableBankCount()
	{
		return reachableBankTiles.length;
	}
	public int reachableBankTile(int index)
	{
		return reachableBankTiles[index];
	}
	/**
	 * Whether the search tile is a bank in the world. This is account-independent: whether an
	 * account may bank there is {@link PreparedRoutingAccount#bankAccessible(int)}.
	 */
	public boolean isBankNode(int node)
	{
		return reachableBankNodes[node] != 0;
	}
	/** Whether the site is a bank in the world; see {@link #isBankNode(int)}. */
	public boolean isBankSite(int site)
	{
		return site >= 0 && reachableBankSites[site] != 0;
	}
	public int crossingCount()
	{
		return crossingFromSite.length;
	}
	public int sparseVertexCount()
	{
		return sparseVertexCount;
	}
	public int sparseOriginalCount()
	{
		return sparseOriginalCount;
	}
	public int sparseSteinerCount()
	{
		return sparseSteinerCount;
	}
	public int sparseAdjacencyCount()
	{
		return sparseAdjacencyCount;
	}
	public int searchTile(int index)
	{
		return searchTiles[index];
	}
	public int walkingMask(int index)
	{
		return Byte.toUnsignedInt(walkingMasks[index]);
	}
	public int northNode(int index)
	{
		return northNodes[index];
	}
	public int southNode(int index)
	{
		return southNodes[index];
	}
	public int routingComponent(int index)
	{
		return searchComponents[index];
	}
	public int siteTile(int index)
	{
		return siteTiles[index];
	}
	public int searchIndex(int packed)
	{
		return binarySearch(searchTiles, packed);
	}
	public int siteIndex(int packed)
	{
		return binarySearch(siteTiles, packed);
	}
	public int[] siteComponents(int site)
	{
		return Arrays.copyOfRange(siteComponentIds, siteComponentOffsets[site], siteComponentOffsets[site + 1]);
	}
	public int[] componentSites(int component)
	{
		return Arrays.copyOfRange(
			componentSiteIds, componentSiteOffsets[component], componentSiteOffsets[component + 1]);
	}
	public int crossingFromSite(int index)
	{
		return crossingFromSite[index];
	}
	public int crossingToSite(int index)
	{
		return crossingToSite[index];
	}
	public int crossingCost(int index)
	{
		return crossingCosts[index];
	}
	public int sparseOffset(int index)
	{
		return sparseOffsets[index];
	}
	public int sparseDestination(int index)
	{
		return sparseDestinations[index];
	}
	public int sparseWeight(int index)
	{
		return sparseWeights[index];
	}

	public int[] attachments(int packedPoint, CollisionMap collision)
	{
		int index = searchIndex(packedPoint);
		if (index >= 0)
			return new int[] {searchComponents[index]};
		int[] result = new int[8];
		int count = 0;
		for (int neighbor : collision.ordinaryWalkingNeighbors(packedPoint))
		{
			int neighborIndex = searchIndex(neighbor);
			if (neighborIndex >= 0 && !contains(result, 0, count, searchComponents[neighborIndex]))
				result[count++] = searchComponents[neighborIndex];
		}
		Arrays.sort(result, 0, count);
		return Arrays.copyOf(result, count);
	}

	private static int binarySearch(int[] values, int target)
	{
		int low = 0, high = values.length - 1;
		while (low <= high)
		{
			int middle = low + (high - low) / 2;
			int compare = Integer.compareUnsigned(values[middle], target);
			if (compare == 0)
				return middle;
			if (compare < 0)
				low = middle + 1;
			else
				high = middle - 1;
		}
		return -1;
	}
}

package shortestpath.pathfinder.exact;

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.SplitFlagMap;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/**
 * Derives the exact backend's {@link RoutingStatic} from the {@link CollisionMap}, the raw
 * (account-independent) transports and global teleports, the bank list, and separator cut edges.
 *
 * <ol>
 *   <li>Natural components: flood fill over ordinary walking edges.</li>
 *   <li>Routing components: the same flood fill, not crossing cut edges. Cuts that are no longer
 *       walking edges are ignored; cuts that no longer separate two routing components are
 *       dropped. Cuts therefore only affect performance, never routes.</li>
 *   <li>Structural reachability: natural components reachable from Lumbridge through any
 *       transport or global teleport of any type, seasonal included, regardless of requirements.</li>
 *   <li>Search tiles: every tile of a reachable natural component, with its walking mask,
 *       routing component and north/south neighbour indexes.</li>
 *   <li>Sites (transport endpoints, crossing endpoints and reachable banks), their component
 *       attachments in both directions, and separator crossings.</li>
 *   <li>The sparse walking network over the sites ({@link SparseWalkingNetworkBuilder}).</li>
 * </ol>
 */
public final class RoutingStaticBuilder
{
	/** Structural-reachability seed tile (Lumbridge). */
	private static final int SEED_TILE = WorldPointUtil.packWorldPoint(3221, 3218, 0);
	/** One full {@code y} unit in the packed encoding (bit 15). */
	private static final int Y_UNIT = 1 << 15;

	private RoutingStaticBuilder()
	{
	}

	/** Per-step timings and derivation counts, for the plugin's build diagnostics. */
	public static final class Diagnostics
	{
		public final long enumerateWalkableNanos;
		public final long naturalComponentsNanos;
		public final long cutValidationNanos;
		public final long routingComponentsNanos;
		public final long reachabilityNanos;
		public final long searchTilesNanos;
		public final long sitesAndAttachmentsNanos;
		public final long sparseNetworkNanos;
		public final long validateNanos;
		public final long totalNanos;

		public final int walkableTileCount;
		public final int naturalComponentCount;
		public final int routingComponentCount;
		public final int largestRoutingComponentSize;
		public final int reachableNaturalComponentCount;

		public final int inputCutCount;
		public final int duplicateCutCount;
		public final int invalidCutCount;
		public final int nonSeparatingCutCount;
		public final int crossingCount;

		public final int searchTileCount;
		public final int siteCount;
		public final int reachableBankCount;

		Diagnostics(long enumerateWalkableNanos, long naturalComponentsNanos, long cutValidationNanos,
			long routingComponentsNanos, long reachabilityNanos, long searchTilesNanos,
			long sitesAndAttachmentsNanos, long sparseNetworkNanos, long validateNanos, long totalNanos,
			int walkableTileCount, int naturalComponentCount, int routingComponentCount,
			int largestRoutingComponentSize, int reachableNaturalComponentCount, int inputCutCount,
			int duplicateCutCount, int invalidCutCount, int nonSeparatingCutCount, int crossingCount,
			int searchTileCount, int siteCount, int reachableBankCount)
		{
			this.enumerateWalkableNanos = enumerateWalkableNanos;
			this.naturalComponentsNanos = naturalComponentsNanos;
			this.cutValidationNanos = cutValidationNanos;
			this.routingComponentsNanos = routingComponentsNanos;
			this.reachabilityNanos = reachabilityNanos;
			this.searchTilesNanos = searchTilesNanos;
			this.sitesAndAttachmentsNanos = sitesAndAttachmentsNanos;
			this.sparseNetworkNanos = sparseNetworkNanos;
			this.validateNanos = validateNanos;
			this.totalNanos = totalNanos;
			this.walkableTileCount = walkableTileCount;
			this.naturalComponentCount = naturalComponentCount;
			this.routingComponentCount = routingComponentCount;
			this.largestRoutingComponentSize = largestRoutingComponentSize;
			this.reachableNaturalComponentCount = reachableNaturalComponentCount;
			this.inputCutCount = inputCutCount;
			this.duplicateCutCount = duplicateCutCount;
			this.invalidCutCount = invalidCutCount;
			this.nonSeparatingCutCount = nonSeparatingCutCount;
			this.crossingCount = crossingCount;
			this.searchTileCount = searchTileCount;
			this.siteCount = siteCount;
			this.reachableBankCount = reachableBankCount;
		}

		@Override
		public String toString()
		{
			return "RoutingStaticBuilder.Diagnostics{"
				+ "totalMs=" + (totalNanos / 1_000_000) + ", enumerateWalkableMs=" + (enumerateWalkableNanos / 1_000_000)
				+ ", naturalComponentsMs=" + (naturalComponentsNanos / 1_000_000)
				+ ", cutValidationMs=" + (cutValidationNanos / 1_000_000)
				+ ", routingComponentsMs=" + (routingComponentsNanos / 1_000_000)
				+ ", reachabilityMs=" + (reachabilityNanos / 1_000_000)
				+ ", searchTilesMs=" + (searchTilesNanos / 1_000_000)
				+ ", sitesAndAttachmentsMs=" + (sitesAndAttachmentsNanos / 1_000_000)
				+ ", sparseNetworkMs=" + (sparseNetworkNanos / 1_000_000)
				+ ", validateMs=" + (validateNanos / 1_000_000)
				+ ", walkableTileCount=" + walkableTileCount + ", naturalComponentCount=" + naturalComponentCount
				+ ", routingComponentCount=" + routingComponentCount
				+ ", largestRoutingComponentSize=" + largestRoutingComponentSize
				+ ", reachableNaturalComponentCount=" + reachableNaturalComponentCount
				+ ", inputCutCount=" + inputCutCount + ", duplicateCutCount=" + duplicateCutCount
				+ ", invalidCutCount=" + invalidCutCount + ", nonSeparatingCutCount=" + nonSeparatingCutCount
				+ ", crossingCount=" + crossingCount + ", searchTileCount=" + searchTileCount
				+ ", siteCount=" + siteCount + ", reachableBankCount=" + reachableBankCount + "}";
		}
	}

	/** The derived static world plus the diagnostics collected while building it. */
	public static final class Result
	{
		public final RoutingStatic routingStatic;
		public final Diagnostics diagnostics;

		Result(RoutingStatic routingStatic, Diagnostics diagnostics)
		{
			this.routingStatic = routingStatic;
			this.diagnostics = diagnostics;
		}
	}

	/**
	 * Builds the derived {@link RoutingStatic}.
	 *
	 * @param collision      authoritative walking-neighbour source.
	 * @param rawTransports  the plugin's raw, unfiltered, account-independent transports, keyed by
	 *                       packed origin tile or {@link shortestpath.WorldPointUtil#UNDEFINED} for
	 *                       origin-less (global) transports/teleports &mdash;
	 *                       {@code TransportLoader.loadAllFromResources()}'s direct result. Must
	 *                       include every {@link TransportType}, seasonal included.
	 * @param bankTiles      the whole bank destination set ({@code Destination.tsv}'s "bank" column),
	 *                       with no account filtering.
	 * @param cuts           candidate separator cut edges as packed {@code (from, to)} pairs:
	 *                       {@code cuts[2*i]}/{@code cuts[2*i+1]}.
	 */
	public static Result build(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports,
		Set<Integer> bankTiles, int[] cuts) throws IOException
	{
		return build(collision, rawTransports, bankTiles, cuts, SEED_TILE);
	}

	/**
	 * Same as {@link #build(CollisionMap, Map, Set, int[])}, but with an overridable structural
	 * reachability seed tile. Production callers must use the four-argument overload (the
	 * production seed policy is not configurable); this overload exists so synthetic-world unit
	 * tests can exercise structural reachability without embedding the real seed tile
	 * {@code (3221, 3218, 0)} in every tiny test world.
	 */
	public static Result build(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports,
		Set<Integer> bankTiles, int[] cuts, int seedTile) throws IOException
	{
		long totalStarted = System.nanoTime();

		long stepStarted = System.nanoTime();
		WalkableTiles walkable = enumerateWalkableTiles(collision);
		long enumerateWalkableNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		int[] naturalId = new int[walkable.tiles.length];
		int naturalComponentCount = floodFillComponents(walkable, null, naturalId);
		long naturalComponentsNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		CutSet cutSet = validateCuts(cuts, walkable);
		long cutValidationNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		int[] routingId = new int[walkable.tiles.length];
		int maxRoutingComponentId = floodFillComponents(walkable, cutSet.blocked, routingId);
		// Component arrays are indexed by id, so capacity is maxComponentId + 1 with empty groups retained.
		int routingComponentCount = maxRoutingComponentId + 1;
		int largestRoutingComponentSize = largestGroup(routingId, maxRoutingComponentId);
		long routingComponentsNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		boolean[] reachableNatural = structuralReachability(collision, walkable, naturalId, naturalComponentCount,
			rawTransports, seedTile);
		int reachableNaturalCount = count(reachableNatural);
		long reachabilityNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		SearchTiles search = buildSearchTiles(walkable, naturalId, routingId, reachableNatural);
		long searchTilesNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		List<Crossing> crossings = buildCrossings(cutSet.valid, routingId, walkable);
		int nonSeparating = cutSet.valid.size() - crossings.size();
		SitesAndAttachments sites = buildSites(rawTransports, bankTiles, crossings, search, collision,
			routingComponentCount);
		long sitesAndAttachmentsNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		SparseWalkingNetworkBuilder.Result sparse = SparseWalkingNetworkBuilder.build(sites.siteTiles,
			sites.siteComponentOffsets, sites.siteComponentIds);
		long sparseNetworkNanos = System.nanoTime() - stepStarted;

		int[] crossingFrom = new int[crossings.size()];
		int[] crossingTo = new int[crossings.size()];
		int[] crossingCost = new int[crossings.size()];
		for (int i = 0; i < crossings.size(); i++)
		{
			Crossing crossing = crossings.get(i);
			crossingFrom[i] = binarySearchUnsigned(sites.siteTiles, crossing.fromTile);
			crossingTo[i] = binarySearchUnsigned(sites.siteTiles, crossing.toTile);
			crossingCost[i] = 1;
		}

		stepStarted = System.nanoTime();
		RoutingStatic result = RoutingStatic.create(search.tiles, search.components, search.masks, search.north,
			search.south, sites.siteTiles, sites.siteComponentOffsets, sites.siteComponentIds, routingComponentCount,
			sites.componentSiteOffsets, sites.componentSiteIds, sites.reachableBankTiles, crossingFrom, crossingTo,
			crossingCost, sparse.originalCount, sparse.vertexCount, sparse.steinerCount, sparse.undirectedEdgeCount,
			sparse.adjacencyCount(), sparse.offsets, sparse.destinations, sparse.weights);
		long validateNanos = System.nanoTime() - stepStarted;

		long totalNanos = System.nanoTime() - totalStarted;
		Diagnostics diagnostics = new Diagnostics(enumerateWalkableNanos, naturalComponentsNanos, cutValidationNanos,
			routingComponentsNanos, reachabilityNanos, searchTilesNanos, sitesAndAttachmentsNanos, sparseNetworkNanos,
			validateNanos, totalNanos, walkable.tiles.length, naturalComponentCount, maxRoutingComponentId,
			largestRoutingComponentSize, reachableNaturalCount, cuts.length / 2, cutSet.duplicateCount,
			cutSet.invalidCount, nonSeparating, crossings.size(), search.tiles.length, sites.siteTiles.length,
			sites.reachableBankTiles.length);
		return new Result(result, diagnostics);
	}

	/**
	 * The ordinary walking graph over every walkable tile, with natural components and structural
	 * reachability computed exactly as {@link #build} does. The tooling cut generator partitions
	 * this graph, so generated cuts and the runtime agree on what a walking edge is.
	 */
	public static final class WalkingGraph
	{
		private final WalkableTiles walkable;
		private final int[] naturalId;
		private final int naturalComponentCount;
		private final boolean[] reachableNatural;

		private WalkingGraph(WalkableTiles walkable, int[] naturalId, int naturalComponentCount,
			boolean[] reachableNatural)
		{
			this.walkable = walkable;
			this.naturalId = naturalId;
			this.naturalComponentCount = naturalComponentCount;
			this.reachableNatural = reachableNatural;
		}

		/** Number of walkable tiles; tile indexes follow ascending unsigned packed order. */
		public int tileCount()
		{
			return walkable.tiles.length;
		}

		public int tile(int index)
		{
			return walkable.tiles[index];
		}

		/** Index of a walkable tile, or -1 when the tile is not walkable. */
		public int indexOf(int tile)
		{
			return walkable.index.get(tile);
		}

		/** Natural component id of a tile index, in {@code 1..naturalComponentCount()}. */
		public int naturalComponent(int index)
		{
			return naturalId[index];
		}

		public int naturalComponentCount()
		{
			return naturalComponentCount;
		}

		public boolean isStructurallyReachable(int naturalComponent)
		{
			return reachableNatural[naturalComponent];
		}

		/** Indexes of the walkable tiles reachable in one ordinary walking step. */
		public int[] neighbours(int index)
		{
			int[] tiles = ordinaryNeighborsFromMask(walkable.tiles[index], walkable.masks[index]);
			int[] result = new int[tiles.length];
			int count = 0;
			for (int tile : tiles)
			{
				int neighbour = walkable.index.get(tile);
				if (neighbour >= 0) result[count++] = neighbour;
			}
			return count == result.length ? result : Arrays.copyOf(result, count);
		}
	}

	/** Builds the walking graph used for cut generation; see {@link WalkingGraph}. */
	public static WalkingGraph walkingGraph(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports)
	{
		return walkingGraph(collision, rawTransports, SEED_TILE);
	}

	static WalkingGraph walkingGraph(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports, int seedTile)
	{
		WalkableTiles walkable = enumerateWalkableTiles(collision);
		int[] naturalId = new int[walkable.tiles.length];
		int naturalComponentCount = floodFillComponents(walkable, null, naturalId);
		boolean[] reachable = structuralReachability(collision, walkable, naturalId, naturalComponentCount,
			rawTransports, seedTile);
		return new WalkingGraph(walkable, naturalId, naturalComponentCount, reachable);
	}

	// ---- Step 0: enumerate every collision-walkable tile, ascending unsigned packed order ----

	private static final class WalkableTiles
	{
		final int[] tiles;
		final byte[] masks;
		final TileIndex index;

		WalkableTiles(int[] tiles, byte[] masks, TileIndex index)
		{
			this.tiles = tiles;
			this.masks = masks;
			this.index = index;
		}
	}

	private static WalkableTiles enumerateWalkableTiles(CollisionMap collision)
	{
		final int regionSize = 64;
		SplitFlagMap.RegionExtent extent = collision.regionExtent();
		int widthInclusive = extent.getWidth() + 1;
		IntArrayList tiles = new IntArrayList();
		ByteArrayList masks = new ByteArrayList();
		for (int ry = 0; ry <= extent.getHeight(); ry++)
		{
			int regionY = extent.getMinY() + ry;
			for (int rx = 0; rx <= extent.getWidth(); rx++)
			{
				int regionX = extent.getMinX() + rx;
				int index = rx + ry * widthInclusive;
				int planeCount = collision.getRegionPlaneCounts(index);
				if (planeCount <= 0)
				{
					continue;
				}
				int baseX = regionX * regionSize;
				int baseY = regionY * regionSize;
				for (int plane = 0; plane < planeCount; plane++)
				{
					for (int ly = 0; ly < regionSize; ly++)
					{
						int y = baseY + ly;
						for (int lx = 0; lx < regionSize; lx++)
						{
							int x = baseX + lx;
							if (!collision.isBlocked(x, y, plane))
							{
								int packed = WorldPointUtil.packWorldPoint(x, y, plane);
								tiles.add(packed);
								masks.add(collision.ordinaryWalkingMask(packed));
							}
						}
					}
				}
			}
		}
		int[] tileArray = tiles.toArray();
		byte[] maskArray = masks.toArray();
		sortUnsignedWithPayload(tileArray, maskArray);
		return new WalkableTiles(tileArray, maskArray, new TileIndex(tileArray));
	}

	// ---- Step 1/3: flood fill (natural when blocked==null, routing when blocked is a valid-cut set) ----

	/** Returns the number of components assigned (ids {@code 1..count}), 0 if there were no walkable tiles. */
	private static int floodFillComponents(WalkableTiles walkable, LongOpenHashSet blocked, int[] componentOut)
	{
		int n = walkable.tiles.length;
		int[] queue = new int[n == 0 ? 1 : n];
		int nextId = 1;
		for (int seed = 0; seed < n; seed++)
		{
			if (componentOut[seed] != 0)
			{
				continue;
			}
			int head = 0, tail = 0;
			queue[tail++] = seed;
			componentOut[seed] = nextId;
			while (head < tail)
			{
				int position = queue[head++];
				int tile = walkable.tiles[position];
				for (int neighbor : ordinaryNeighborsFromMask(tile, walkable.masks[position]))
				{
					int neighborPosition = walkable.index.get(neighbor);
					if (neighborPosition < 0 || componentOut[neighborPosition] != 0)
					{
						continue;
					}
					if (blocked != null && blocked.contains(canonicalKey(tile, neighbor)))
					{
						continue;
					}
					componentOut[neighborPosition] = nextId;
					queue[tail++] = neighborPosition;
				}
			}
			nextId++;
		}
		return nextId - 1;
	}

	// Clockwise 0-N,1-NE,2-E,3-SE,4-S,5-SW,6-W,7-NW; the bit layout of CollisionMap.ordinaryWalkingMask.
	private static final int[] NEIGHBOR_DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] NEIGHBOR_DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private static int[] ordinaryNeighborsFromMask(int tile, byte maskByte)
	{
		int mask = Byte.toUnsignedInt(maskByte);
		int x = WorldPointUtil.unpackWorldX(tile);
		int y = WorldPointUtil.unpackWorldY(tile);
		int z = WorldPointUtil.unpackWorldPlane(tile);
		int[] result = new int[Integer.bitCount(mask)];
		int count = 0;
		for (int bit = 0; bit < 8; bit++)
		{
			if ((mask & (1 << bit)) != 0)
			{
				result[count++] = WorldPointUtil.packWorldPoint(x + NEIGHBOR_DX[bit], y + NEIGHBOR_DY[bit], z);
			}
		}
		return result;
	}

	private static int largestGroup(int[] componentOf, int componentCount)
	{
		if (componentCount <= 0)
		{
			return 0;
		}
		int[] sizes = new int[componentCount + 1];
		for (int component : componentOf)
		{
			sizes[component]++;
		}
		int largest = 0;
		for (int size : sizes)
		{
			largest = Math.max(largest, size);
		}
		return largest;
	}

	// ---- Cuts: validity ("ignore cuts that are not current walking edges") + canonical dedup ----

	private static final class CutSet
	{
		final List<long[]> valid; // each entry {a, b} as raw ints boxed in a long[2] for simplicity
		final LongOpenHashSet blocked;
		final int duplicateCount;
		final int invalidCount;

		CutSet(List<long[]> valid, LongOpenHashSet blocked, int duplicateCount, int invalidCount)
		{
			this.valid = valid;
			this.blocked = blocked;
			this.duplicateCount = duplicateCount;
			this.invalidCount = invalidCount;
		}
	}

	private static CutSet validateCuts(int[] cuts, WalkableTiles walkable)
	{
		HashSet<Long> seenCanonical = new HashSet<>();
		int duplicateCount = 0;
		List<long[]> candidates = new ArrayList<>();
		int pairCount = cuts.length / 2;
		for (int i = 0; i < pairCount; i++)
		{
			int rawA = cuts[2 * i];
			int rawB = cuts[2 * i + 1];
			int a = Integer.compareUnsigned(rawA, rawB) <= 0 ? rawA : rawB;
			int b = Integer.compareUnsigned(rawA, rawB) <= 0 ? rawB : rawA;
			long key = canonicalKey(a, b);
			if (!seenCanonical.add(key))
			{
				duplicateCount++;
				continue;
			}
			candidates.add(new long[] {Integer.toUnsignedLong(a), Integer.toUnsignedLong(b)});
		}
		List<long[]> valid = new ArrayList<>();
		LongOpenHashSet blocked = new LongOpenHashSet(Math.max(16, candidates.size() * 2));
		int invalidCount = 0;
		for (long[] candidate : candidates)
		{
			int a = (int) candidate[0];
			int b = (int) candidate[1];
			int posA = walkable.index.get(a);
			int[] neighborsOfA = posA < 0 ? new int[0] : ordinaryNeighborsFromMask(a, walkable.masks[posA]);
			if (posA < 0 || !contains(neighborsOfA, 0, neighborsOfA.length, b))
			{
				invalidCount++;
				continue;
			}
			valid.add(candidate);
			blocked.add(canonicalKey(a, b));
		}
		return new CutSet(valid, blocked, duplicateCount, invalidCount);
	}

	private static long canonicalKey(int a, int b)
	{
		int min = Integer.compareUnsigned(a, b) <= 0 ? a : b;
		int max = Integer.compareUnsigned(a, b) <= 0 ? b : a;
		return (Integer.toUnsignedLong(min) << 32) | Integer.toUnsignedLong(max);
	}

	// ---- Structural reachability: closure over NATURAL components ----
	// Reachability must use natural, not routing, components: a cut never makes a tile unreachable.
	// The closure is an account-independent overapproximation of the geography routes can use, so it
	// deliberately follows every known transport, seasonal ones included, whatever its requirements.
	// It only prunes components nothing can reach, such as the sea. Whether an account can take a
	// transport is decided later, by PreparedRoutingAccount and the forward search.

	private static boolean[] structuralReachability(CollisionMap collision, WalkableTiles walkable, int[] naturalId,
		int naturalComponentCount, Map<Integer, Set<Transport>> rawTransports, int seedTile)
	{
		Map<Integer, List<Integer>> edges = new HashMap<>();
		Set<Integer> globalDestinations = new HashSet<>();
		for (Set<Transport> set : rawTransports.values())
		{
			for (Transport transport : set)
			{
				int origin = transport.getOrigin();
				int destination = transport.getDestination();

				// attachmentEdges: every endpoint point of every transport, any type, any origin state.
				int[] originAttachments = origin == WorldPointUtil.UNDEFINED ? new int[0]
					: naturalAttachments(origin, walkable, naturalId, collision);
				int[] destinationAttachments = naturalAttachments(destination, walkable, naturalId, collision);
				addAttachmentClique(edges, originAttachments);
				addAttachmentClique(edges, destinationAttachments);

				if (origin == WorldPointUtil.UNDEFINED)
				{
					// globalDestinations: global-teleport destinations.
					for (int naturalComponent : destinationAttachments)
					{
						globalDestinations.add(naturalComponent);
					}
				}
				else
				{
					// transportEdges: local transports, directed origin -> destination.
					for (int fromComponent : originAttachments)
					{
						for (int toComponent : destinationAttachments)
						{
							edges.computeIfAbsent(fromComponent, k -> new ArrayList<>()).add(toComponent);
						}
					}
				}
			}
		}

		int[] seedComponents = naturalAttachments(seedTile, walkable, naturalId, collision);
		if (seedComponents.length == 0)
		{
			throw new IllegalStateException(
				"missing structural reachability seed: no natural component attaches to the production seed tile");
		}

		boolean[] reachable = new boolean[naturalComponentCount + 1];
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		for (int seed : seedComponents)
		{
			if (!reachable[seed])
			{
				reachable[seed] = true;
				queue.add(seed);
			}
		}
		while (!queue.isEmpty())
		{
			int component = queue.poll();
			for (int next : edges.getOrDefault(component, List.of()))
			{
				if (!reachable[next])
				{
					reachable[next] = true;
					queue.add(next);
				}
			}
			for (int global : globalDestinations)
			{
				if (!reachable[global])
				{
					reachable[global] = true;
					queue.add(global);
				}
			}
		}
		return reachable;
	}

	private static void addAttachmentClique(Map<Integer, List<Integer>> edges, int[] attachments)
	{
		if (attachments.length < 2)
		{
			return;
		}
		for (int a : attachments)
		{
			for (int b : attachments)
			{
				if (a != b)
				{
					edges.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
				}
			}
		}
	}

	/**
	 * Natural components a point attaches to: its own component if it is walkable, otherwise
	 * the union of its ordinary walking neighbours' components.
	 */
	private static int[] naturalAttachments(int point, WalkableTiles walkable, int[] naturalId, CollisionMap collision)
	{
		int position = walkable.index.get(point);
		if (position >= 0)
		{
			return new int[] {naturalId[position]};
		}
		int[] neighbors = collision.ordinaryWalkingNeighbors(point);
		int[] buffer = new int[8];
		int count = 0;
		for (int neighbor : neighbors)
		{
			int neighborPosition = walkable.index.get(neighbor);
			if (neighborPosition >= 0)
			{
				int component = naturalId[neighborPosition];
				if (!contains(buffer, 0, count, component))
				{
					buffer[count++] = component;
				}
			}
		}
		return Arrays.copyOf(buffer, count);
	}

	// ---- Section A: search tiles, routing components, walking masks, north/south ----

	private static final class SearchTiles
	{
		final int[] tiles, components, north, south;
		final byte[] masks;

		SearchTiles(int[] tiles, int[] components, byte[] masks, int[] north, int[] south)
		{
			this.tiles = tiles;
			this.components = components;
			this.masks = masks;
			this.north = north;
			this.south = south;
		}
	}

	private static SearchTiles buildSearchTiles(WalkableTiles walkable, int[] naturalId, int[] routingId,
		boolean[] reachableNatural)
	{
		int n = walkable.tiles.length;
		IntArrayList tiles = new IntArrayList();
		IntArrayList components = new IntArrayList();
		ByteArrayList masks = new ByteArrayList();
		for (int i = 0; i < n; i++)
		{
			if (reachableNatural[naturalId[i]])
			{
				tiles.add(walkable.tiles[i]);
				components.add(routingId[i]);
				masks.add(walkable.masks[i]);
			}
		}
		int[] tileArray = tiles.toArray();
		int[] componentArray = components.toArray();
		byte[] maskArray = masks.toArray();
		int[] north = new int[tileArray.length];
		int[] south = new int[tileArray.length];
		for (int i = 0; i < tileArray.length; i++)
		{
			north[i] = binarySearchUnsigned(tileArray, tileArray[i] + Y_UNIT);
			south[i] = binarySearchUnsigned(tileArray, tileArray[i] - Y_UNIT);
		}
		return new SearchTiles(tileArray, componentArray, maskArray, north, south);
	}

	// ---- Section: routing components / crossings ----

	private static final class Crossing
	{
		final int fromTile, toTile;

		Crossing(int fromTile, int toTile)
		{
			this.fromTile = fromTile;
			this.toTile = toTile;
		}
	}

	private static List<Crossing> buildCrossings(List<long[]> validCuts, int[] routingId, WalkableTiles walkable)
	{
		List<Crossing> crossings = new ArrayList<>();
		for (long[] cut : validCuts)
		{
			int a = (int) cut[0];
			int b = (int) cut[1];
			int posA = walkable.index.get(a);
			int posB = walkable.index.get(b);
			if (posA < 0 || posB < 0 || routingId[posA] == routingId[posB])
			{
				continue;
			}
			crossings.add(new Crossing(a, b));
		}
		crossings.sort((left, right) ->
		{
			int cmp = Integer.compareUnsigned(left.fromTile, right.fromTile);
			return cmp != 0 ? cmp : Integer.compareUnsigned(left.toTile, right.toTile);
		});
		return crossings;
	}

	// ---- Sections B/C/D/E: sites and attachments ----

	private static final class SitesAndAttachments
	{
		final int[] siteTiles, siteComponentOffsets, siteComponentIds, componentSiteOffsets, componentSiteIds;
		final int[] reachableBankTiles;

		SitesAndAttachments(int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds,
			int[] componentSiteOffsets, int[] componentSiteIds, int[] reachableBankTiles)
		{
			this.siteTiles = siteTiles;
			this.siteComponentOffsets = siteComponentOffsets;
			this.siteComponentIds = siteComponentIds;
			this.componentSiteOffsets = componentSiteOffsets;
			this.componentSiteIds = componentSiteIds;
			this.reachableBankTiles = reachableBankTiles;
		}
	}

	private static SitesAndAttachments buildSites(Map<Integer, Set<Transport>> rawTransports, Set<Integer> bankTiles,
		List<Crossing> crossings, SearchTiles search, CollisionMap collision, int routingComponentCount)
	{
		HashSet<Integer> siteSet = new HashSet<>();
		for (Set<Transport> set : rawTransports.values())
		{
			for (Transport transport : set)
			{
				if (transport.getOrigin() != WorldPointUtil.UNDEFINED)
				{
					siteSet.add(transport.getOrigin());
				}
				siteSet.add(transport.getDestination());
			}
		}
		for (Crossing crossing : crossings)
		{
			siteSet.add(crossing.fromTile);
			siteSet.add(crossing.toTile);
		}
		List<Integer> reachableBanks = new ArrayList<>();
		for (int bank : bankTiles)
		{
			if (routingAttachments(bank, search, collision).length > 0)
			{
				reachableBanks.add(bank);
				siteSet.add(bank);
			}
		}

		int[] siteTiles = toSortedUnsignedArray(siteSet);
		int[] reachableBankTiles = toSortedUnsignedArray(reachableBanks);

		int[] siteComponentOffsets = new int[siteTiles.length + 1];
		int[][] perSite = new int[siteTiles.length][];
		int totalSiteComponentValues = 0;
		for (int i = 0; i < siteTiles.length; i++)
		{
			perSite[i] = routingAttachments(siteTiles[i], search, collision);
			siteComponentOffsets[i + 1] = siteComponentOffsets[i] + perSite[i].length;
			totalSiteComponentValues += perSite[i].length;
		}
		int[] siteComponentIds = new int[totalSiteComponentValues];
		int cursor = 0;
		for (int[] components : perSite)
		{
			for (int component : components)
			{
				siteComponentIds[cursor++] = component;
			}
		}

		int[] groupCounts = new int[routingComponentCount];
		for (int component : siteComponentIds)
		{
			groupCounts[component]++;
		}
		int[] componentSiteOffsets = new int[routingComponentCount + 1];
		for (int i = 0; i < routingComponentCount; i++)
		{
			componentSiteOffsets[i + 1] = componentSiteOffsets[i] + groupCounts[i];
		}
		int[] componentSiteIds = new int[componentSiteOffsets[routingComponentCount]];
		int[] fillCursor = Arrays.copyOf(componentSiteOffsets, componentSiteOffsets.length);
		for (int site = 0; site < siteTiles.length; site++)
		{
			for (int p = siteComponentOffsets[site]; p < siteComponentOffsets[site + 1]; p++)
			{
				int component = siteComponentIds[p];
				componentSiteIds[fillCursor[component]++] = site;
			}
		}

		return new SitesAndAttachments(siteTiles, siteComponentOffsets, siteComponentIds, componentSiteOffsets,
			componentSiteIds, reachableBankTiles);
	}

	/**
	 * Routing components a point attaches to, using the final reachability-filtered search tiles:
	 * the tile's own component if it is a search tile, otherwise those of its walking neighbours.
	 * This matches {@link RoutingStatic#attachments} at runtime.
	 */
	private static int[] routingAttachments(int point, SearchTiles search, CollisionMap collision)
	{
		int index = binarySearchUnsigned(search.tiles, point);
		if (index >= 0)
		{
			return new int[] {search.components[index]};
		}
		int[] neighbors = collision.ordinaryWalkingNeighbors(point);
		int[] buffer = new int[8];
		int count = 0;
		for (int neighbor : neighbors)
		{
			int neighborIndex = binarySearchUnsigned(search.tiles, neighbor);
			if (neighborIndex >= 0)
			{
				int component = search.components[neighborIndex];
				if (!contains(buffer, 0, count, component))
				{
					buffer[count++] = component;
				}
			}
		}
		Arrays.sort(buffer, 0, count);
		return Arrays.copyOf(buffer, count);
	}

	// ---- Small shared utilities ----

	private static boolean contains(int[] values, int start, int end, int target)
	{
		for (int i = start; i < end; i++)
		{
			if (values[i] == target)
			{
				return true;
			}
		}
		return false;
	}

	private static int count(boolean[] values)
	{
		int count = 0;
		for (boolean value : values)
		{
			if (value)
			{
				count++;
			}
		}
		return count;
	}

	private static int[] toSortedUnsignedArray(java.util.Collection<Integer> values)
	{
		int[] result = new int[values.size()];
		int i = 0;
		for (int value : values)
		{
			result[i++] = value;
		}
		sortUnsigned(result);
		return result;
	}

	private static void sortUnsigned(int[] values)
	{
		for (int i = 0; i < values.length; i++)
		{
			values[i] ^= Integer.MIN_VALUE;
		}
		Arrays.sort(values);
		for (int i = 0; i < values.length; i++)
		{
			values[i] ^= Integer.MIN_VALUE;
		}
	}

	/**
	 * Sorts {@code keys} into ascending unsigned order, permuting {@code payload} (one byte per
	 * key) the same way. Packs each (flipped-signed key, payload byte) pair into a single
	 * {@code long} so the whole sort is a primitive {@code long[]} sort with no boxing, which
	 * matters at multi-million-tile scale.
	 */
	private static void sortUnsignedWithPayload(int[] keys, byte[] payload)
	{
		long[] packed = new long[keys.length];
		for (int i = 0; i < keys.length; i++)
		{
			long unsignedKey = Integer.toUnsignedLong(keys[i]);
			packed[i] = (unsignedKey << 8) | (payload[i] & 0xffL);
		}
		Arrays.sort(packed);
		for (int i = 0; i < keys.length; i++)
		{
			keys[i] = (int) (packed[i] >>> 8);
			payload[i] = (byte) packed[i];
		}
	}

	private static int nextPowerOfTwo(int value)
	{
		int highest = Integer.highestOneBit(value);
		return highest == value ? highest : highest * 2;
	}

	private static int binarySearchUnsigned(int[] values, int target)
	{
		int low = 0, high = values.length - 1;
		while (low <= high)
		{
			int middle = low + (high - low) / 2;
			int compare = Integer.compareUnsigned(values[middle], target);
			if (compare == 0)
			{
				return middle;
			}
			if (compare < 0)
			{
				low = middle + 1;
			}
			else
			{
				high = middle - 1;
			}
		}
		return -1;
	}

	// ---- Primitive-int growable list / hash structures (avoid boxing at multi-million-tile scale) ----

	private static final class IntArrayList
	{
		private int[] data = new int[1024];
		private int size;

		void add(int value)
		{
			if (size == data.length)
			{
				data = Arrays.copyOf(data, data.length * 2);
			}
			data[size++] = value;
		}

		int[] toArray()
		{
			return Arrays.copyOf(data, size);
		}
	}

	private static final class ByteArrayList
	{
		private byte[] data = new byte[1024];
		private int size;

		void add(byte value)
		{
			if (size == data.length)
			{
				data = Arrays.copyOf(data, data.length * 2);
			}
			data[size++] = value;
		}

		byte[] toArray()
		{
			return Arrays.copyOf(data, size);
		}
	}

	/** Open-addressing packed-tile (u32) to array-index map, sized for tens of millions of entries. */
	private static final class TileIndex
	{
		private final int[] keys;
		private final int[] slots; // slots[h] - 1 == index; 0 == empty
		private final int mask;

		TileIndex(int[] sortedTiles)
		{
			int capacity = nextPowerOfTwo(Math.max(16, sortedTiles.length) * 4);
			keys = new int[capacity];
			slots = new int[capacity];
			mask = capacity - 1;
			for (int i = 0; i < sortedTiles.length; i++)
			{
				int h = hash(sortedTiles[i]) & mask;
				while (slots[h] != 0)
				{
					h = (h + 1) & mask;
				}
				keys[h] = sortedTiles[i];
				slots[h] = i + 1;
			}
		}

		int get(int tile)
		{
			int h = hash(tile) & mask;
			while (slots[h] != 0)
			{
				if (keys[h] == tile)
				{
					return slots[h] - 1;
				}
				h = (h + 1) & mask;
			}
			return -1;
		}

		private static int hash(int value)
		{
			int h = value * 0x9E3779B1;
			return h ^ (h >>> 16);
		}
	}

	/** Open-addressing packed 64-bit canonical-cut-pair set. */
	private static final class LongOpenHashSet
	{
		private long[] keys;
		private int mask;
		private int size;

		LongOpenHashSet(int expectedSize)
		{
			int capacity = nextPowerOfTwo(Math.max(16, expectedSize) * 2);
			keys = new long[capacity];
			Arrays.fill(keys, Long.MIN_VALUE);
			mask = capacity - 1;
		}

		void add(long value)
		{
			int h = hash(value) & mask;
			while (keys[h] != Long.MIN_VALUE)
			{
				if (keys[h] == value)
				{
					return;
				}
				h = (h + 1) & mask;
			}
			keys[h] = value;
			size++;
		}

		boolean contains(long value)
		{
			int h = hash(value) & mask;
			while (keys[h] != Long.MIN_VALUE)
			{
				if (keys[h] == value)
				{
					return true;
				}
				h = (h + 1) & mask;
			}
			return false;
		}

		private static int hash(long value)
		{
			long h = value * 0x9E3779B97F4A7C15L;
			h ^= h >>> 32;
			return (int) h;
		}
	}
}

package shortestpath.pathfinder.exact;

import java.util.function.IntPredicate;
import shortestpath.pathfinder.WildernessChecker;

/**
 * Per-search positional restrictions applied on top of the prepared graph, mirroring the gates
 * the legacy pathfinder checks while relaxing edges ({@code avoidWilderness} and the league's
 * always-blocked region).
 *
 * <p>They are per-search rather than part of the account identity: the underlying setting can
 * change on every config refresh, and enforcing them removes edges instead of adding any, so
 * the prepared target's heuristic only ever under-estimates the restricted graph's distances and
 * stays admissible. Sessions may therefore reuse prepared accounts, targets and heuristics
 * across searches regardless of these settings.
 */
public final class SearchRestrictions
{
	private static final SearchRestrictions NONE = new SearchRestrictions(false, null);

	/** Avoid stepping or teleporting into the wilderness from outside it. */
	private final boolean avoidWilderness;
	/** Whether a tile lies in the league's always-blocked region, or {@code null} when the gate is off. */
	private final IntPredicate blockedRegion;

	private SearchRestrictions(boolean avoidWilderness, IntPredicate blockedRegion)
	{
		this.avoidWilderness = avoidWilderness;
		this.blockedRegion = blockedRegion;
	}

	/** No gates: every edge the graph offers may be relaxed. */
	public static SearchRestrictions none()
	{
		return NONE;
	}

	/**
	 * @param avoidWilderness bar steps and global teleports that enter the wilderness from
	 *                        outside it; the caller folds in legacy's exemption for a target in
	 *                        the wilderness
	 * @param blockedRegion   tests whether a tile lies in the league's always-blocked region, or
	 *                        {@code null} when the gate is off (a non-seasonal world, or a target
	 *                        inside the blocked region lifting the gate, as in legacy)
	 */
	public static SearchRestrictions of(boolean avoidWilderness, IntPredicate blockedRegion)
	{
		return avoidWilderness || blockedRegion != null ? new SearchRestrictions(avoidWilderness, blockedRegion)
			: NONE;
	}

	/** Whether any gate is active; when false, relaxing an edge never asks for a tile's status. */
	boolean anyGate()
	{
		return avoidWilderness || blockedRegion != null;
	}

	boolean avoidsWilderness()
	{
		return avoidWilderness;
	}

	/** Whether {@code tile} is inside the league's always-blocked region; false when the gate is off. */
	boolean inBlockedRegion(int tile)
	{
		return blockedRegion != null && blockedRegion.test(tile);
	}

	/**
	 * Whether a walking step between adjacent tiles may be relaxed, including the step onto a
	 * blocked transport origin. Like legacy, crossing into the wilderness or the blocked region
	 * is barred while moving inside either area, or out of it, is allowed.
	 */
	public boolean stepAllowed(int fromTile, int toTile)
	{
		if (!anyGate())
		{
			return true;
		}
		return stepAllowed(WildernessChecker.isInWilderness(fromTile), WildernessChecker.isInWilderness(toTile),
			inBlockedRegion(fromTile), inBlockedRegion(toTile));
	}

	boolean stepAllowed(boolean fromWilderness, boolean toWilderness, boolean fromBlocked, boolean toBlocked)
	{
		if (avoidWilderness && !fromWilderness && toWilderness)
		{
			return false;
		}
		return blockedRegion == null || fromBlocked || !toBlocked;
	}

	/**
	 * Whether a global teleport cast with {@code capability} may land on {@code destination}.
	 * {@link TeleportCapability#ALL} means the cast happens outside the wilderness, so a
	 * wilderness landing is barred while avoiding it; a cast from inside the wilderness
	 * (any {@code OVER_*} capability) may land inside it, as in legacy.
	 */
	boolean globalAllowed(TeleportCapability capability, int destination)
	{
		return !avoidWilderness || capability != TeleportCapability.ALL
			|| !WildernessChecker.isInWilderness(destination);
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;

/** Immutable two-layer account-specific site graph with reverse CSR edges. */
public final class SiteGraph
{
	public enum EdgeKind
	{
		LOCAL,
		BANK_TRANSITION,
		BANK_GLOBAL_ENTRY,
		BANK_GLOBAL_DESTINATION,
		SEPARATOR
	}

	private final RoutingStatic stat;
	private final PreparedRoutingAccount account;
	private final int nodeCount;
	private final boolean hasBankedGlobalHub;
	private final int[] reverseOffsets;
	private final int[] reverseFromStates;
	private final int[] reverseCosts;
	private final boolean[] reverseStartsGenerator;
	private final byte[] reverseKinds;

	public SiteGraph(RoutingStatic stat, PreparedRoutingAccount account)
	{
		this.stat = stat;
		this.account = account;
		int spatialCount = stat.siteCount();
		validateEndpoints(account, stat);
		int[] bankSites = bankSites(stat, account);
		int[] globalDestinations = globalDestinations(account, stat);
		hasBankedGlobalHub = account.allowTransports() && account.bankPathEnabled() && bankSites.length != 0
			&& globalDestinations.length != 0;
		nodeCount = spatialCount + (hasBankedGlobalHub ? 1 : 0);

		EdgeBuilder edges = new EdgeBuilder();
		addLocalEdges(edges, account.localView(false), false, stat);
		addLocalEdges(edges, account.localView(true), true, stat);
		if (account.bankPathEnabled())
		{
			for (int bankSite : bankSites)
			{
				edges.add(stateId(bankSite, false), stateId(bankSite, true), account.bankVisitCost(), true,
					EdgeKind.BANK_TRANSITION);
			}
		}
		if (hasBankedGlobalHub)
		{
			int hub = spatialCount;
			for (int bankSite : bankSites)
			{
				edges.add(stateId(bankSite, false), stateId(hub, true), account.bankVisitCost(), true,
					EdgeKind.BANK_GLOBAL_ENTRY);
			}
			for (int destination : globalDestinations)
			{
				int cost = minimumGlobalCost(account.globalView(true), destination);
				if (cost != ExactCosts.INF)
				{
					edges.add(stateId(hub, true), stateId(stat.siteIndex(destination), true), cost, false,
						EdgeKind.BANK_GLOBAL_DESTINATION);
				}
			}
		}
		for (int i = 0; i < stat.crossingCount(); i++)
		{
			int from = stat.crossingFromSite(i);
			int to = stat.crossingToSite(i);
			int cost = ExactCosts.validate(stat.crossingCost(i));
			for (boolean banked : new boolean[] {false, true})
			{
				edges.add(stateId(from, banked), stateId(to, banked), cost, true, EdgeKind.SEPARATOR);
				edges.add(stateId(to, banked), stateId(from, banked), cost, true, EdgeKind.SEPARATOR);
			}
		}
		Csr csr = edges.build(nodeCount * 2);
		reverseOffsets = csr.offsets;
		reverseFromStates = csr.fromStates;
		reverseCosts = csr.costs;
		reverseStartsGenerator = csr.startsGenerator;
		reverseKinds = csr.kinds;
	}

	public static SiteGraph compile(RoutingStatic stat, PreparedRoutingAccount account)
	{
		return new SiteGraph(stat, account);
	}

	public RoutingStatic routingStatic()
	{
		return stat;
	}
	public PreparedRoutingAccount preparedAccount()
	{
		return account;
	}
	public int spatialNodeCount()
	{
		return stat.siteCount();
	}
	public int nodeCount()
	{
		return nodeCount;
	}
	public int stateCount()
	{
		return nodeCount * 2;
	}
	public boolean hasBankedGlobalHub()
	{
		return hasBankedGlobalHub;
	}
	public int bankedGlobalHubNode()
	{
		return hasBankedGlobalHub ? stat.siteCount() : -1;
	}
	public int siteTile(int node)
	{
		return stat.siteTile(node);
	}
	public int nodeForTile(int tile)
	{
		return stat.siteIndex(tile);
	}

	public int reverseEdgeCount()
	{
		return reverseFromStates.length;
	}
	public int reverseEdgeStart(int state)
	{
		return reverseOffsets[state];
	}
	public int reverseEdgeEnd(int state)
	{
		return reverseOffsets[state + 1];
	}
	public int reverseFromState(int edge)
	{
		return reverseFromStates[edge];
	}
	public int reverseCost(int edge)
	{
		return reverseCosts[edge];
	}
	public boolean reverseStartsGenerator(int edge)
	{
		return reverseStartsGenerator[edge];
	}
	public EdgeKind reverseKind(int edge)
	{
		return EdgeKind.values()[reverseKinds[edge]];
	}

	public static int stateId(int node, boolean banked)
	{
		if (node < 0)
			throw new IllegalArgumentException("negative site node");
		return node * 2 + (banked ? 1 : 0);
	}

	private static void addLocalEdges(
		EdgeBuilder edges, PreparedRoutingAccount.View view, boolean banked, RoutingStatic stat)
	{
		for (int i = 0; i < view.count; i++)
		{
			int from = stat.siteIndex(view.origins[i]);
			int to = stat.siteIndex(view.destinations[i]);
			if (view.costs[i] != ExactCosts.INF)
			{
				edges.add(stateId(from, banked), stateId(to, banked), view.costs[i], true, EdgeKind.LOCAL);
			}
		}
	}

	private static void validateEndpoints(PreparedRoutingAccount account, RoutingStatic stat)
	{
		for (boolean banked : new boolean[] {false, true})
		{
			PreparedRoutingAccount.View local = account.localView(banked);
			for (int i = 0; i < local.count; i++)
			{
				requireSite(stat, local.origins[i], "local origin");
				requireSite(stat, local.destinations[i], "local destination");
			}
			PreparedRoutingAccount.View global = account.globalView(banked);
			for (int i = 0; i < global.count; i++)
				requireSite(stat, global.destinations[i], "global destination");
		}
	}

	private static void requireSite(RoutingStatic stat, int tile, String label)
	{
		if (stat.siteIndex(tile) < 0)
		{
			throw new IllegalStateException(label + " is not a static site: " + Integer.toUnsignedString(tile));
		}
	}

	/** The static bank sites this account may use. */
	private static int[] bankSites(RoutingStatic stat, PreparedRoutingAccount account)
	{
		int[] result = new int[stat.reachableBankCount()];
		int count = 0;
		for (int i = 0; i < result.length; i++)
		{
			int tile = stat.reachableBankTile(i);
			int site = stat.siteIndex(tile);
			if (site < 0)
				throw new IllegalStateException("reachable bank is not a static site");
			if (account.bankAccessible(tile))
				result[count++] = site;
		}
		return Arrays.copyOf(result, count);
	}

	private static int[] globalDestinations(PreparedRoutingAccount account, RoutingStatic stat)
	{
		PreparedRoutingAccount.View view = account.globalView(true);
		int[] result = new int[view.count];
		int count = 0;
		for (int i = 0; i < view.count; i++)
		{
			int destination = view.destinations[i];
			boolean present = false;
			for (int j = 0; j < count; j++)
				present |= result[j] == destination;
			if (!present)
				result[count++] = destination;
		}
		result = Arrays.copyOf(result, count);
		for (int i = 1; i < count; i++)
		{
			int value = result[i];
			int j = i - 1;
			while (j >= 0 && Integer.compareUnsigned(result[j], value) > 0)
			{
				result[j + 1] = result[j--];
			}
			result[j + 1] = value;
		}
		for (int destination : result)
			requireSite(stat, destination, "global destination");
		return result;
	}

	private static int minimumGlobalCost(PreparedRoutingAccount.View view, int destination)
	{
		int minimum = ExactCosts.INF;
		for (int i = 0; i < view.count; i++)
		{
			if (view.destinations[i] == destination && view.costs[i] < minimum)
				minimum = view.costs[i];
		}
		return minimum;
	}

	private static final class EdgeBuilder
	{
		private int size;
		private int[] from = new int[64], to = new int[64], costs = new int[64];
		private boolean[] starts = new boolean[64];
		private byte[] kinds = new byte[64];

		void add(int fromState, int toState, int cost, boolean startsGenerator, EdgeKind kind)
		{
			ExactCosts.validate(cost);
			if (cost == ExactCosts.INF)
				return;
			if (size == from.length)
			{
				int capacity = size * 2;
				from = Arrays.copyOf(from, capacity);
				to = Arrays.copyOf(to, capacity);
				costs = Arrays.copyOf(costs, capacity);
				starts = Arrays.copyOf(starts, capacity);
				kinds = Arrays.copyOf(kinds, capacity);
			}
			from[size] = fromState;
			to[size] = toState;
			costs[size] = cost;
			starts[size] = startsGenerator;
			kinds[size++] = (byte) kind.ordinal();
		}

		Csr build(int stateCount)
		{
			int[] offsets = new int[stateCount + 1];
			for (int i = 0; i < size; i++)
				offsets[to[i] + 1]++;
			for (int i = 1; i < offsets.length; i++)
				offsets[i] += offsets[i - 1];
			int[] positions = Arrays.copyOfRange(offsets, 1, offsets.length);
			int[] sortedFrom = new int[size], sortedCosts = new int[size];
			boolean[] sortedStarts = new boolean[size];
			byte[] sortedKinds = new byte[size];
			for (int i = 0; i < size; i++)
			{
				int position = --positions[to[i]];
				sortedFrom[position] = from[i];
				sortedCosts[position] = costs[i];
				sortedStarts[position] = starts[i];
				sortedKinds[position] = kinds[i];
			}
			return new Csr(offsets, sortedFrom, sortedCosts, sortedStarts, sortedKinds);
		}
	}

	private static final class Csr
	{
		final int[] offsets, fromStates, costs;
		final boolean[] startsGenerator;
		final byte[] kinds;

		Csr(int[] offsets, int[] fromStates, int[] costs, boolean[] startsGenerator, byte[] kinds)
		{
			this.offsets = offsets;
			this.fromStates = fromStates;
			this.costs = costs;
			this.startsGenerator = startsGenerator;
			this.kinds = kinds;
		}
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;
import java.util.Comparator;
import shortestpath.WorldPointUtil;

/**
 * Builds the sparse same-component walking network used by {@link ReverseLabels#computeSparse}.
 *
 * <p>Within each routing component, walking distance between two sites on the same plane is at
 * least their Chebyshev distance. Instead of connecting every pair of sites, the construction
 * works in rotated Manhattan coordinates {@code a = x + y}, {@code b = x - y}, where Manhattan
 * distance is exactly twice Chebyshev distance, and adds Steiner vertices along balanced
 * coordinate splits so that the shortest path between any two sites equals that distance.
 * Every edge weight is therefore doubled walking distance; {@link ReverseLabels#computeSparse}
 * halves it once at the end.
 */
public final class SparseWalkingNetworkBuilder
{
	private SparseWalkingNetworkBuilder()
	{
	}

	/** Section G in flat, undirected CSR form (adjacencyCount == 2 * undirectedEdgeCount). */
	public static final class Result
	{
		public final int originalCount;
		public final int vertexCount;
		public final int steinerCount;
		public final int undirectedEdgeCount;
		public final int[] offsets;
		public final int[] destinations;
		public final int[] weights;

		private Result(int originalCount, int vertexCount, int steinerCount, int undirectedEdgeCount, int[] offsets,
			int[] destinations, int[] weights)
		{
			this.originalCount = originalCount;
			this.vertexCount = vertexCount;
			this.steinerCount = steinerCount;
			this.undirectedEdgeCount = undirectedEdgeCount;
			this.offsets = offsets;
			this.destinations = destinations;
			this.weights = weights;
		}

		public int adjacencyCount()
		{
			return destinations.length;
		}
	}

	/**
	 * Builds the network from the static sites and their routing-component attachments:
	 *
	 * <ul>
	 *   <li>{@code siteTiles[s]}: packed tile of site {@code s}, ascending.</li>
	 *   <li>{@code siteComponentOffsets}, {@code siteComponentIds}: each site's ascending
	 *       routing-component attachments. A site attached to several components contributes
	 *       one point to each component, all sharing the same site vertex.</li>
	 * </ul>
	 *
	 * <p>Vertices {@code 0..siteTiles.length-1} are the sites, followed by Steiner vertices. A
	 * site with no component attachment is an isolated vertex.
	 *
	 * @param siteTiles              packed tiles, ascending unsigned packed order, one per site
	 * @param siteComponentOffsets   length {@code siteTiles.length + 1}, CSR offsets into {@code siteComponentIds}
	 * @param siteComponentIds       routing-component ids per site, ascending within each site's range
	 * @return the flattened CSR sparse walking network (section G)
	 */
	public static Result build(int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds)
	{
		int originalCount = siteTiles.length;
		int maxComponentId = -1;
		for (int cid : siteComponentIds)
		{
			if (cid > maxComponentId)
			{
				maxComponentId = cid;
			}
		}
		int componentCount = maxComponentId + 1;

		// Bucket sites by component id; only components that own at least one site are processed,
		// in ascending id order.
		int[] bucketCounts = new int[componentCount];
		for (int cid : siteComponentIds)
		{
			bucketCounts[cid]++;
		}
		int[] bucketOffsets = new int[componentCount + 1];
		for (int c = 0; c < componentCount; c++)
		{
			bucketOffsets[c + 1] = bucketOffsets[c] + bucketCounts[c];
		}
		int[] bucketSites = new int[siteComponentIds.length];
		int[] cursor = bucketOffsets.clone();
		for (int site = 0; site < originalCount; site++)
		{
			for (int p = siteComponentOffsets[site]; p < siteComponentOffsets[site + 1]; p++)
			{
				int cid = siteComponentIds[p];
				bucketSites[cursor[cid]++] = site;
			}
		}

		EdgeList edges = new EdgeList();
		int next = originalCount;
		for (int cid = 0; cid < componentCount; cid++)
		{
			int start = bucketOffsets[cid];
			int end = bucketOffsets[cid + 1];
			int size = end - start;
			if (size == 0)
			{
				continue;
			}
			Point[] points = new Point[size];
			for (int i = 0; i < size; i++)
			{
				int siteIndex = bucketSites[start + i];
				int tile = siteTiles[siteIndex];
				int x = WorldPointUtil.unpackWorldX(tile);
				int y = WorldPointUtil.unpackWorldY(tile);
				points[i] = new Point(siteIndex, x + y, x - y);
			}
			Arrays.sort(points, BY_A_B_ORIGINAL);
			next = buildComponent(next, points, edges);
		}

		int vertexCount = next;
		int steinerCount = vertexCount - originalCount;
		return undirectedAdjacency(originalCount, vertexCount, steinerCount, edges);
	}

	private enum Axis
	{
		A, B
	}

	private static final class Point
	{
		final int original;
		final int a;
		final int b;

		Point(int original, int a, int b)
		{
			this.original = original;
			this.a = a;
			this.b = b;
		}
	}

	private static final Comparator<Point> BY_A_B_ORIGINAL = (x, y) ->
	{
		if (x.a != y.a)
		{
			return Integer.compare(x.a, y.a);
		}
		if (x.b != y.b)
		{
			return Integer.compare(x.b, y.b);
		}
		return Integer.compare(x.original, y.original);
	};

	private static int coordOf(Axis axis, Point p)
	{
		return axis == Axis.A ? p.a : p.b;
	}

	private static int otherCoordOf(Axis axis, Point p)
	{
		return axis == Axis.A ? p.b : p.a;
	}

	private static Comparator<Point> axisComparator(Axis axis)
	{
		return (x, y) ->
		{
			int cx = coordOf(axis, x);
			int cy = coordOf(axis, y);
			if (cx != cy)
			{
				return Integer.compare(cx, cy);
			}
			return BY_A_B_ORIGINAL.compare(x, y);
		};
	}

	/**
	 * Recursively splits one component's points. {@code pts} arrives in inherited order (the
	 * global {@code a,b,original} sort at the top level, or a slice of the parent split's
	 * axis-sorted list below it); that order, not any re-sort here, decides which Steiner vertex
	 * id each point receives in {@link #addProjectionLevel}, keeping numbering deterministic.
	 */
	private static int buildComponent(int next, Point[] pts, EdgeList edges)
	{
		if (pts.length <= 1)
		{
			return next;
		}
		int a0 = pts[0].a;
		int b0 = pts[0].b;
		boolean allSameA = true;
		boolean allSameB = true;
		for (Point p : pts)
		{
			if (p.a != a0)
			{
				allSameA = false;
			}
			if (p.b != b0)
			{
				allSameB = false;
			}
		}
		if (allSameA && allSameB)
		{
			// Coincident points are chained with zero-weight edges; pts is already sorted by `original`
			// here, since a/b are constant and the inherited order derives from a sort
			// keyed on (axis-or-a-b, a, b, original).
			for (int i = 0; i + 1 < pts.length; i++)
			{
				edges.add(pts[i].original, pts[i + 1].original, 0);
			}
			return next;
		}
		Axis axis = allSameA ? Axis.B : Axis.A;
		return splitOn(axis, next, pts, edges);
	}

	/** Splits {@code pts} at the most balanced gap along {@code axis} and recurses on both halves. */
	private static int splitOn(Axis axis, int next, Point[] pts, EdgeList edges)
	{
		Point[] sorted = pts.clone();
		Arrays.sort(sorted, axisComparator(axis));
		int split = balancedGapSplit(axis, sorted);
		Point[] left = Arrays.copyOfRange(sorted, 0, split);
		Point[] right = Arrays.copyOfRange(sorted, split, sorted.length);
		int splitCoordinate = Math.floorDiv(
			coordOf(axis, sorted[split - 1]) + coordOf(axis, sorted[split]), 2);
		int afterProjection = addProjectionLevel(axis, splitCoordinate, next, pts, edges);
		int afterLeft = buildComponent(afterProjection, left, edges);
		return buildComponent(afterLeft, right, edges);
	}

	/**
	 * Returns the split index {@code i}: {@code sorted[0..i)} and {@code sorted[i..)} lie on
	 * either side of the chosen gap; the caller
	 * derives the Steiner splitter coordinate from the pair straddling that index.
	 */
	private static int balancedGapSplit(Axis axis, Point[] sorted)
	{
		int n = sorted.length;
		int preferred = n / 2;
		int bestIndex = -1;
		int bestDiff = Integer.MAX_VALUE;
		for (int i = 1; i < n; i++)
		{
			if (coordOf(axis, sorted[i - 1]) < coordOf(axis, sorted[i]))
			{
				int diff = Math.abs(i - preferred);
				if (diff < bestDiff)
				{
					bestDiff = diff;
					bestIndex = i;
				}
			}
		}
		if (bestIndex < 0)
		{
			throw new IllegalStateException("sparse walking split without a strict coordinate gap");
		}
		return bestIndex;
	}

	/**
	 * Allocates one fresh
	 * Steiner vertex per point in {@code pts} (in {@code pts}'s own order), a spoke edge
	 * from each point to its projection vertex, then chains the projections in ascending
	 * order of the other axis coordinate (ties by original site index).
	 */
	private static int addProjectionLevel(Axis axis, int splitCoordinate, int firstProjection, Point[] pts,
		EdgeList edges)
	{
		int count = pts.length;
		int[] steinerIds = new int[count];
		for (int i = 0; i < count; i++)
		{
			steinerIds[i] = firstProjection + i;
			edges.add(pts[i].original, steinerIds[i], Math.abs(coordOf(axis, pts[i]) - splitCoordinate));
		}
		Integer[] order = new Integer[count];
		for (int i = 0; i < count; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, (x, y) ->
		{
			int ox = otherCoordOf(axis, pts[x]);
			int oy = otherCoordOf(axis, pts[y]);
			if (ox != oy)
			{
				return Integer.compare(ox, oy);
			}
			return Integer.compare(pts[x].original, pts[y].original);
		});
		for (int i = 0; i + 1 < count; i++)
		{
			int leftIndex = order[i];
			int rightIndex = order[i + 1];
			int weight = Math.abs(otherCoordOf(axis, pts[leftIndex]) - otherCoordOf(axis, pts[rightIndex]));
			edges.add(steinerIds[leftIndex], steinerIds[rightIndex], weight);
		}
		return firstProjection + count;
	}

	/** Growable primitive (from, to, weight) triples; final counts are small primitive arrays. */
	private static final class EdgeList
	{
		private int[] from = new int[16];
		private int[] to = new int[16];
		private int[] weight = new int[16];
		private int size;

		void add(int a, int b, int w)
		{
			if (size == from.length)
			{
				int capacity = size * 2;
				from = Arrays.copyOf(from, capacity);
				to = Arrays.copyOf(to, capacity);
				weight = Arrays.copyOf(weight, capacity);
			}
			from[size] = a;
			to[size] = b;
			weight[size] = w;
			size++;
		}
	}

	/**
	 * Materialises both directions of every edge as CSR adjacency. The order of entries within
	 * one vertex's range does not affect any distance.
	 */
	private static Result undirectedAdjacency(int originalCount, int vertexCount, int steinerCount, EdgeList edges)
	{
		int[] counts = new int[vertexCount];
		for (int i = 0; i < edges.size; i++)
		{
			counts[edges.from[i]]++;
			counts[edges.to[i]]++;
		}
		int[] offsets = new int[vertexCount + 1];
		for (int v = 0; v < vertexCount; v++)
		{
			offsets[v + 1] = offsets[v] + counts[v];
		}
		int[] destinations = new int[offsets[vertexCount]];
		int[] weights = new int[offsets[vertexCount]];
		int[] cursor = offsets.clone();
		for (int i = 0; i < edges.size; i++)
		{
			int a = edges.from[i];
			int b = edges.to[i];
			int w = edges.weight[i];
			destinations[cursor[a]] = b;
			weights[cursor[a]] = w;
			cursor[a]++;
			destinations[cursor[b]] = a;
			weights[cursor[b]] = w;
			cursor[b]++;
		}
		return new Result(originalCount, vertexCount, steinerCount, edges.size, offsets, destinations, weights);
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;
import shortestpath.pathfinder.CollisionMap;

/**
 * Query-local target sites and their point-attachment walking edges.
 *
 * <p>An overlay holds one or more target tiles; a search towards it ends at whichever target is
 * cheapest to reach. Targets that are static sites reuse their site node; every other target gets
 * its own synthetic node appended after the account graph's nodes, in target order.
 */
public final class TargetOverlay
{
	private final SiteGraph graph;
	private final RoutingStatic stat;
	private final PreparedRoutingAccount account;
	private final long accountFingerprint;
	private final CollisionMap collision;
	private final int[] packed;
	private final int[] nodes;
	private final int[][] components;
	private final int[][] attachmentSites;
	private final int[][] attachmentCosts;
	private final int[] syntheticTargets;

	public TargetOverlay(SiteGraph graph, CollisionMap collision, int packed)
	{
		this(graph, collision, new int[] {packed});
	}

	public TargetOverlay(SiteGraph graph, CollisionMap collision, int[] packedTargets)
	{
		if (graph == null || collision == null || packedTargets == null)
			throw new NullPointerException();
		this.graph = graph;
		this.stat = graph.routingStatic();
		this.account = graph.preparedAccount();
		this.accountFingerprint = account.fingerprint();
		this.collision = collision;
		this.packed = sortedUnique(packedTargets);
		if (packed.length == 0)
			throw new IllegalArgumentException("target overlay needs at least one target");
		int count = packed.length;
		nodes = new int[count];
		components = new int[count][];
		attachmentSites = new int[count][];
		attachmentCosts = new int[count][];
		int[] synthetic = new int[count];
		int syntheticCount = 0;
		for (int target = 0; target < count; target++)
		{
			int existing = graph.nodeForTile(packed[target]);
			if (existing >= 0)
			{
				nodes[target] = existing;
				components[target] = stat.siteComponents(existing);
			}
			else
			{
				nodes[target] = graph.nodeCount() + syntheticCount;
				synthetic[syntheticCount++] = target;
				components[target] = stat.attachments(packed[target], collision);
			}
			attach(target);
		}
		syntheticTargets = Arrays.copyOf(synthetic, syntheticCount);
	}

	public SiteGraph graph()
	{
		return graph;
	}
	public RoutingStatic routingStatic()
	{
		return stat;
	}
	public PreparedRoutingAccount account()
	{
		return account;
	}
	CollisionMap collision()
	{
		return collision;
	}
	public long accountFingerprint()
	{
		return accountFingerprint;
	}
	public int queryNodeCount()
	{
		return graph.nodeCount() + syntheticTargets.length;
	}

	public int targetCount()
	{
		return packed.length;
	}
	/** The target tiles, in unsigned order. */
	public int[] packedTargets()
	{
		return packed.clone();
	}
	public int packedTarget(int target)
	{
		return packed[target];
	}
	/** Index of {@code tile} among the targets, or a negative value if it is not a target. */
	public int targetIndex(int tile)
	{
		if (packed.length == 1)
			return packed[0] == tile ? 0 : -1;
		int low = 0, high = packed.length - 1;
		while (low <= high)
		{
			int middle = (low + high) >>> 1, compare = Integer.compareUnsigned(packed[middle], tile);
			if (compare == 0) return middle;
			if (compare < 0) low = middle + 1; else high = middle - 1;
		}
		return -1;
	}
	public boolean isTarget(int tile)
	{
		return targetIndex(tile) >= 0;
	}
	public int targetNode(int target)
	{
		return nodes[target];
	}
	public boolean synthetic(int target)
	{
		return nodes[target] >= graph.nodeCount();
	}
	public int[] components(int target)
	{
		return components[target].clone();
	}
	int[] componentsView(int target)
	{
		return components[target];
	}
	public int attachmentCount(int target)
	{
		return attachmentSites[target].length;
	}
	public int attachmentSite(int target, int index)
	{
		return attachmentSites[target][index];
	}
	public int attachmentCost(int target, int index)
	{
		return attachmentCosts[target][index];
	}
	public int targetState(int target, boolean banked)
	{
		return SiteGraph.stateId(nodes[target], banked);
	}

	public int syntheticCount()
	{
		return syntheticTargets.length;
	}
	/** The target index owning synthetic node {@code node}, or a negative value for any other node. */
	int syntheticTarget(int node)
	{
		int index = node - graph.nodeCount();
		return index >= 0 && index < syntheticTargets.length ? syntheticTargets[index] : -1;
	}
	/** Tile of a spatial site node or a synthetic target node. */
	int nodeTile(int node)
	{
		int target = syntheticTarget(node);
		return target >= 0 ? packed[target] : stat.siteTile(node);
	}
	/** Routing components of a spatial site node or a synthetic target node. */
	int[] nodeComponents(int node)
	{
		int target = syntheticTarget(node);
		return target >= 0 ? components[target] : stat.siteComponents(node);
	}

	/** The only target's tile; single-target overlays only. */
	public int packedTarget()
	{
		return packed[single()];
	}
	/** The only target's node; single-target overlays only. */
	public int targetNode()
	{
		return nodes[single()];
	}
	/** Whether the only target is synthetic; single-target overlays only. */
	public boolean synthetic()
	{
		return synthetic(single());
	}
	/** The only target's routing components; single-target overlays only. */
	public int[] components()
	{
		return components(single());
	}
	/** The only target's attachment count; single-target overlays only. */
	public int attachmentCount()
	{
		return attachmentCount(single());
	}
	/** The only target's attachment site; single-target overlays only. */
	public int attachmentSite(int index)
	{
		return attachmentSite(single(), index);
	}
	/** The only target's attachment cost; single-target overlays only. */
	public int attachmentCost(int index)
	{
		return attachmentCost(single(), index);
	}
	/** The only target's state; single-target overlays only. */
	public int targetState(boolean banked)
	{
		return targetState(single(), banked);
	}

	void requireCompatible(SiteGraph candidate)
	{
		if (candidate.routingStatic() != stat || candidate.preparedAccount() != account
			|| candidate.preparedAccount().fingerprint() != accountFingerprint)
		{
			throw new IllegalArgumentException("target overlay belongs to another static/account snapshot");
		}
	}

	private int single()
	{
		if (packed.length != 1)
			throw new IllegalStateException("overlay has " + packed.length + " targets");
		return 0;
	}

	private void attach(int target)
	{
		int[] targetComponents = components[target];
		int capacity = 0;
		for (int component : targetComponents)
			capacity += stat.componentSites(component).length;
		int[] sites = new int[capacity];
		int count = 0;
		for (int component : targetComponents)
		{
			for (int site : stat.componentSites(component))
			{
				if (firstSharedComponent(targetComponents, site) == component)
					sites[count++] = site;
			}
		}
		attachmentSites[target] = Arrays.copyOf(sites, count);
		attachmentCosts[target] = new int[count];
		// Only a synthetic target's attachments enter the reverse search. Walking distances rather
		// than Chebyshev ones keep a target deep in a winding area from looking close to its
		// entrances, which would otherwise make the search flood everything within that slack.
		TargetWalkDistances walk = nodes[target] >= graph.nodeCount()
			? TargetWalkDistances.search(stat, packed[target], targetComponents) : null;
		for (int i = 0; i < count; i++)
		{
			int site = stat.siteTile(attachmentSites[target][i]);
			int chebyshev = distance(packed[target], site);
			attachmentCosts[target][i] = walk == null ? chebyshev : walk.bound(site, chebyshev);
		}
	}

	private int firstSharedComponent(int[] targetComponents, int site)
	{
		for (int component : targetComponents)
		{
			for (int siteComponent : stat.siteComponents(site))
				if (siteComponent == component)
					return component;
		}
		throw new IllegalStateException("target attachment missing shared routing component");
	}

	private static int[] sortedUnique(int[] values)
	{
		int[] sorted = values.clone();
		for (int i = 0; i < sorted.length; i++)
			sorted[i] ^= Integer.MIN_VALUE;
		Arrays.sort(sorted);
		int count = 0;
		for (int i = 0; i < sorted.length; i++)
			if (count == 0 || sorted[count - 1] != sorted[i])
				sorted[count++] = sorted[i];
		for (int i = 0; i < count; i++)
			sorted[i] ^= Integer.MIN_VALUE;
		return Arrays.copyOf(sorted, count);
	}

	private static int distance(int left, int right)
	{
		return shortestpath.WorldPointUtil.distanceBetween(left, right);
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;
import shortestpath.WorldPointUtil;

/**
 * Lower bounds on the walking cost from a target's attachment sites to the target, from a bounded
 * breadth-first search backwards over the static walking edges, within the target's routing
 * components.
 *
 * <p>Why a walk inside the components is enough: sites are every transport endpoint, crossing
 * endpoint and bank, and routing components are only left by crossing a cut, whose endpoints are
 * sites. A route's last stretch after its last site is therefore a pure walk inside the target's
 * components, and costs at least the distance found here. A site never reached gets the distance
 * of the search's frontier when it stopped (no closer tile was left unvisited), and every bound
 * is at least the Chebyshev distance the overlay used before.
 */
final class TargetWalkDistances
{
	/** Tiles the search may visit per target; larger components get frontier bounds beyond it. */
	static final int TILE_BUDGET = 1 << 16;

	// Bit b of a walking mask steps by (DX[b], DY[b]), as in ExactForwardSearch.walkBase.
	private static final int[] DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private final RoutingStatic stat;
	private final int[] components;
	private final NodeDistances distances;
	private final int frontier;

	private TargetWalkDistances(RoutingStatic stat, int[] components, NodeDistances distances, int frontier)
	{
		this.stat = stat;
		this.components = components;
		this.distances = distances;
		this.frontier = frontier;
	}

	/** Null when the target is not a static search tile (its attachments keep Chebyshev costs). */
	static TargetWalkDistances search(RoutingStatic stat, int target, int[] components)
	{
		int start = stat.searchIndex(target);
		if (start < 0) return null;
		NodeDistances distances = new NodeDistances(TILE_BUDGET);
		int[] queue = new int[TILE_BUDGET];
		int head = 0, tail = 0;
		distances.put(start, 0);
		queue[tail++] = start;
		int frontier = 0;
		boolean exhausted = true;
		while (head < tail)
		{
			int node = queue[head++];
			int distance = distances.get(node);
			for (int direction = 0; direction < 8; direction++)
			{
				// The neighbour in this direction is a predecessor if it walks back onto this tile,
				// by the same index arithmetic the forward search uses.
				int from = successor(stat, node, direction), bit = (direction + 4) & 7;
				if (from < 0 || from >= stat.searchTileCount()) continue;
				if ((stat.walkingMask(from) & (1 << bit)) == 0 || successor(stat, from, bit) != node) continue;
				if (distances.get(from) >= 0 || !inComponents(stat.routingComponent(from), components)) continue;
				if (tail == TILE_BUDGET)
				{
					exhausted = false;
					break;
				}
				distances.put(from, distance + 1);
				queue[tail++] = from;
			}
			if (!exhausted)
			{
				// Every unvisited tile is at least as far as the tile being expanded.
				frontier = distance;
				break;
			}
			frontier = distance + 1;
		}
		return new TargetWalkDistances(stat, components, distances, frontier);
	}

	/**
	 * A lower bound on walking from {@code site} to the target, never below {@code chebyshev}.
	 * A site off the search tiles (a blocked transport origin) first steps to a neighbour.
	 */
	int bound(int site, int chebyshev)
	{
		int node = stat.searchIndex(site);
		if (node >= 0) return Math.max(chebyshev, distance(node));
		int x = WorldPointUtil.unpackWorldX(site), y = WorldPointUtil.unpackWorldY(site);
		int plane = WorldPointUtil.unpackWorldPlane(site);
		int best = Integer.MAX_VALUE;
		for (int bit = 0; bit < 8; bit++)
		{
			int neighbour = stat.searchIndex(WorldPointUtil.packWorldPoint(x + DX[bit], y + DY[bit], plane));
			if (neighbour >= 0) best = Math.min(best, distance(neighbour));
		}
		return best == Integer.MAX_VALUE ? chebyshev : Math.max(chebyshev, 1 + best);
	}

	private int distance(int node)
	{
		int known = distances.get(node);
		return known >= 0 ? known : frontier;
	}

	private static int successor(RoutingStatic stat, int node, int bit)
	{
		int south = stat.southNode(node), north = stat.northNode(node);
		switch (bit)
		{
			case 0: return north;
			case 1: return north < 0 ? -1 : north + 1;
			case 2: return node + 1;
			case 3: return south < 0 ? -1 : south + 1;
			case 4: return south;
			case 5: return south < 0 ? -1 : south - 1;
			case 6: return node - 1;
			default: return north < 0 ? -1 : north - 1;
		}
	}

	private static boolean inComponents(int component, int[] components)
	{
		for (int value : components)
			if (value == component) return true;
		return false;
	}

	/** Open-addressing node -> distance map sized for the tile budget. */
	private static final class NodeDistances
	{
		private final int[] keys, values;
		private final int mask;

		NodeDistances(int capacity)
		{
			int size = Integer.highestOneBit(capacity * 2 - 1) << 1;
			keys = new int[size];
			values = new int[size];
			Arrays.fill(keys, -1);
			mask = size - 1;
		}

		void put(int key, int value)
		{
			int slot = mix(key) & mask;
			while (keys[slot] != -1 && keys[slot] != key) slot = (slot + 1) & mask;
			keys[slot] = key;
			values[slot] = value;
		}

		int get(int key)
		{
			int slot = mix(key) & mask;
			while (keys[slot] != -1)
			{
				if (keys[slot] == key) return values[slot];
				slot = (slot + 1) & mask;
			}
			return -1;
		}

		private static int mix(int key)
		{
			int h = key * 0x9E3779B9;
			return h ^ (h >>> 16);
		}
	}
}

package shortestpath.pathfinder.exact;

import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;

/**
 * Which global teleports the exact backend lets the player cast from a tile, by the tile's
 * wilderness band. These are legacy's global-teleport abstract nodes ({@code AbstractNodeKind}):
 *
 * <pre>
 * OVER_30  level 31+     cast level 31  GLOBAL_TELEPORTS_OVER_30
 * OVER_20  levels 21-30  cast level 30  GLOBAL_TELEPORTS_OVER_20
 * OVER_0   levels 1-20   cast level 20  GLOBAL_TELEPORTS_OVER_0
 * ALL      level 0       cast level 0   GLOBAL_TELEPORTS_NORMAL
 * </pre>
 *
 * A global is castable with a capability when {@link Transport#isUsableAtWildernessLevel} allows
 * the capability's cast level, as in legacy. Cast levels only fall from {@code OVER_30} to
 * {@code ALL}, so each capability can cast everything the one before it can.
 *
 * <p>The bands are {@code WildernessChecker}'s level-30, level-20 and wilderness areas (checked by
 * {@code TeleportCapabilityTest}), on every plane, inlined here because the forward search asks
 * for every state it pops.
 */
public enum TeleportCapability
{
	OVER_30(31), OVER_20(30), OVER_0(20), ALL(0);

	private final int castLevel;

	TeleportCapability(int castLevel)
	{
		this.castLevel = castLevel;
	}

	/** The wilderness level legacy checks a global teleport against in this band. */
	public int castLevel()
	{
		return castLevel;
	}

	/** Whether {@code transport} can be cast as a global teleport in this band. */
	public boolean canCast(Transport transport)
	{
		return transport.isUsableAtWildernessLevel(castLevel);
	}

	/** Whether a tile with this capability may cast everything {@code required} can. */
	boolean allows(TeleportCapability required)
	{
		return castLevel <= required.castLevel;
	}

	// {left, bottom, width, height}: above ground, then underground.
	static final int[][] ABOVE_LEVEL_30 = {{2944, 3760, 448, 448}, {2944, 10155, 518, 221}};
	static final int[][] ABOVE_LEVEL_20 = {{2944, 3680, 448, 448}, {2944, 10075, 518, 301}};
	static final int[][] WILDERNESS = {{2944, 3525, 448, 448}, {2944, 9918, 518, 458}};
	/** Inside the above-ground wilderness area but not wilderness: Ferox Enclave and its south edge. */
	static final int[][] NOT_WILDERNESS = {{3123, 3622, 2, 10}, {3125, 3617, 16, 23}, {3138, 3636, 18, 10},
		{3141, 3625, 14, 11}, {3141, 3619, 7, 6}, {2997, 3525, 34, 9}, {3005, 3534, 21, 10}, {3000, 3534, 5, 5},
		{3031, 3525, 2, 2}};

	public static TeleportCapability at(int tile)
	{
		return at(WorldPointUtil.unpackWorldX(tile), WorldPointUtil.unpackWorldY(tile));
	}

	static TeleportCapability at(int x, int y)
	{
		// Unrolled WILDERNESS, ABOVE_LEVEL_30 and ABOVE_LEVEL_20.
		if (x < 2944 || x >= 3462 || y < 3525) return ALL;
		if (y >= 9918)
		{
			if (y >= 10376) return ALL;
			return y >= 10155 ? OVER_30 : y >= 10075 ? OVER_20 : OVER_0;
		}
		if (x >= 3392) return ALL;
		if (y >= 3760 && y < 4208) return OVER_30;
		if (y >= 3680 && y < 4128) return OVER_20;
		if (y >= 3973 || inAny(NOT_WILDERNESS, x, y)) return ALL;
		return OVER_0;
	}

	/** The areas a tile must lie outside of all of, or inside a {@link #holes() hole}, to allow this capability. */
	int[][] excludedAreas()
	{
		switch (this)
		{
			case OVER_30:
				return new int[0][];
			case OVER_20:
				return ABOVE_LEVEL_30;
			case OVER_0:
				return EXCLUDED_FROM_OVER_0;
			case ALL:
			default:
				return EXCLUDED_FROM_ALL;
		}
	}

	/** Areas inside {@link #excludedAreas()} that still allow this capability. */
	int[][] holes()
	{
		return this == ALL ? NOT_WILDERNESS : new int[0][];
	}

	// The level-30 area reaches further north than the level-20 and wilderness ones, so all are excluded.
	private static final int[][] EXCLUDED_FROM_OVER_0 = {ABOVE_LEVEL_30[0], ABOVE_LEVEL_30[1], ABOVE_LEVEL_20[0],
		ABOVE_LEVEL_20[1]};
	private static final int[][] EXCLUDED_FROM_ALL = {ABOVE_LEVEL_30[0], ABOVE_LEVEL_30[1], ABOVE_LEVEL_20[0],
		ABOVE_LEVEL_20[1], WILDERNESS[0], WILDERNESS[1]};

	static boolean inAny(int[][] areas, int x, int y)
	{
		for (int[] area : areas)
			if (inArea(area, x, y)) return true;
		return false;
	}

	static boolean inArea(int[] area, int x, int y)
	{
		return x >= area[0] && x < area[0] + area[2] && y >= area[1] && y < area[1] + area[3];
	}
}

package shortestpath.pathfinder.exact;

import java.util.Arrays;
import shortestpath.WorldPointUtil;

/**
 * Where a walking leg may end on its plane: every tile from which the route's next action can be
 * taken with the same consequences. That is one tile for a fixed waypoint, the origins of one
 * transport action for a transport, and an area for a global teleport, which can be cast anywhere
 * the wilderness allows it.
 */
abstract class WalkGoal
{
	/** Whether the leg may end at {@code (x, y)}. */
	abstract boolean contains(int x, int y);

	/**
	 * A lexicographic lower bound on the rest of the leg from {@code (x, y)}: the fewest ticks to
	 * any goal tile in the high 32 bits and, among goal tiles that few ticks away, the least axis
	 * travel in the low 32 bits. Taking both from the same goal tile keeps the bound consistent.
	 */
	abstract long lowerBound(int x, int y);

	/**
	 * Whether the leg may end by stepping onto a goal tile that is blocked, as the exact search
	 * walks onto the blocked origin of a transport (a door or an obstacle) to take it.
	 */
	abstract boolean entersBlockedTiles();

	static long bound(int ticks, int axisTravel)
	{
		return (long) ticks << 32 | axisTravel;
	}

	static int ticks(long bound)
	{
		return (int) (bound >>> 32);
	}

	static int axisTravel(long bound)
	{
		return (int) bound;
	}

	/** One tile: a fixed waypoint, the final destination, or a transport only taken from there. */
	static WalkGoal tile(int packed)
	{
		return tiles(new int[] {packed}, WorldPointUtil.unpackWorldPlane(packed));
	}

	/** The tiles of {@code packed} on {@code plane}, all equivalent places to take the next action. */
	static WalkGoal tiles(int[] packed, int plane)
	{
		int[] xs = new int[packed.length], ys = new int[packed.length];
		int count = 0;
		for (int tile : packed)
		{
			if (WorldPointUtil.unpackWorldPlane(tile) != plane) continue;
			xs[count] = WorldPointUtil.unpackWorldX(tile);
			ys[count++] = WorldPointUtil.unpackWorldY(tile);
		}
		if (count == 0) throw new IllegalArgumentException("goal has no tile on plane " + plane);
		return new Tiles(Arrays.copyOf(xs, count), Arrays.copyOf(ys, count));
	}

	/** Every tile from which teleports needing {@code capability} can be cast. */
	static WalkGoal teleportArea(TeleportCapability capability)
	{
		return new TeleportArea(capability);
	}

	private static final class Tiles extends WalkGoal
	{
		private final int[] xs, ys;

		Tiles(int[] xs, int[] ys)
		{
			this.xs = xs;
			this.ys = ys;
		}

		@Override
		boolean contains(int x, int y)
		{
			for (int i = 0; i < xs.length; i++)
				if (xs[i] == x && ys[i] == y) return true;
			return false;
		}

		@Override
		long lowerBound(int x, int y)
		{
			long best = Long.MAX_VALUE;
			for (int i = 0; i < xs.length; i++)
			{
				int dx = Math.abs(xs[i] - x), dy = Math.abs(ys[i] - y);
				best = Math.min(best, bound(Math.max(dx, dy), dx + dy));
			}
			return best;
		}

		@Override
		boolean entersBlockedTiles()
		{
			return true;
		}

		@Override
		public String toString()
		{
			return xs.length == 1 ? "tile " + xs[0] + "," + ys[0] : xs.length + " tiles";
		}
	}

	/**
	 * The tiles outside a few rectangles, or inside a few holes in them. Leaving the rectangles takes
	 * at least as many moves as the furthest any containing rectangle's nearest edge is, and a
	 * straight walk to that edge costs as much axis travel as it does ticks; reaching a hole is
	 * bounded like reaching a tile.
	 */
	private static final class TeleportArea extends WalkGoal
	{
		private final TeleportCapability capability;
		private final int[][] excluded, holes;
		private final int left, bottom, right, top;

		TeleportArea(TeleportCapability capability)
		{
			this.capability = capability;
			this.excluded = capability.excludedAreas();
			this.holes = capability.holes();
			int l = Integer.MAX_VALUE, b = Integer.MAX_VALUE, r = Integer.MIN_VALUE, t = Integer.MIN_VALUE;
			for (int[] area : excluded)
			{
				l = Math.min(l, area[0]);
				b = Math.min(b, area[1]);
				r = Math.max(r, area[0] + area[2]);
				t = Math.max(t, area[1] + area[3]);
			}
			left = l;
			bottom = b;
			right = r;
			top = t;
		}

		@Override
		boolean contains(int x, int y)
		{
			return TeleportCapability.at(x, y).allows(capability);
		}

		@Override
		long lowerBound(int x, int y)
		{
			if (x < left || x >= right || y < bottom || y >= top) return 0;
			int distance = 0;
			for (int[] area : excluded)
			{
				if (!TeleportCapability.inArea(area, x, y)) continue;
				int left = x - area[0] + 1, right = area[0] + area[2] - x;
				int down = y - area[1] + 1, up = area[1] + area[3] - y;
				distance = Math.max(distance, Math.min(Math.min(left, right), Math.min(down, up)));
			}
			long best = bound(distance, distance);
			for (int[] hole : holes)
			{
				int dx = Math.max(0, Math.max(hole[0] - x, x - (hole[0] + hole[2] - 1)));
				int dy = Math.max(0, Math.max(hole[1] - y, y - (hole[1] + hole[3] - 1)));
				best = Math.min(best, bound(Math.max(dx, dy), dx + dy));
			}
			return best;
		}

		@Override
		boolean entersBlockedTiles()
		{
			return false;
		}

		@Override
		public String toString()
		{
			return "teleport area " + capability;
		}
	}
}

package shortestpath.transport;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import shortestpath.ItemVariations;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.PathfinderConfig;
import shortestpath.pathfinder.TransportAvailability;
import shortestpath.transport.requirement.ItemRequirement;
import shortestpath.transport.requirement.Unlock;

/**
 * Determines what items need to be picked up from the bank for a given path.
 * This handles transport-specific requirements like the Dramen staff for fairy rings.
 * Multiple transports that connect the same edge are treated as alternatives (OR):
 * if the player can satisfy any one of them, no pickup is needed; otherwise the
 * cheapest single alternative that can be filled from the bank is chosen.
 */
@SuppressWarnings("unused") // Only static methods are used, incorrectly flagged
public final class BankPickupRequirements
{

	/** Combined result of a bank pickup computation: display phrases and item IDs for highlighting. */
	public static class BankPickupResult
	{
		public final List<String> phrases;
		public final Set<Integer> bankItemIds;

		BankPickupResult(List<String> phrases, Set<Integer> bankItemIds)
		{
			this.phrases = phrases;
			this.bankItemIds = bankItemIds;
		}

		/**
		 * Computes the bank pickup requirements for a given bank step in the path.
		 * Returns both the human-readable pickup phrases (for display) and the item IDs
		 * (for bank slot highlighting) in a single pass over the remaining path.
		 *
		 * @param client           The game client
		 * @param bank             The bank ItemContainer
		 * @param pathfinderConfig The pathfinder config for bank-aware transport lookups
		 * @param bankLocations    Set of bank location coordinates
		 * @param path             The current path
		 * @param pathIndex        The current step index in the path
		 * @return BankPickupResult with phrases and item IDs, or an empty result if not at a bank step
		 */
		public static BankPickupResult compute(
			Client client,
			ItemContainer bank,
			PathfinderConfig pathfinderConfig,
			Set<Integer> bankLocations,
			List<PathStep> path,
			int pathIndex)
		{
			List<String> resultPhrases = new ArrayList<>();
			Set<Integer> resultIds = new HashSet<>();

			if (bank == null || path == null || pathIndex < 0 || pathIndex >= path.size())
			{
				return new BankPickupResult(resultPhrases, resultIds);
			}

			// Only compute for bank steps.
			int currentPoint = path.get(pathIndex).getPackedPosition();
			if (!bankLocations.contains(currentPoint))
			{
				return new BankPickupResult(resultPhrases, resultIds);
			}

			// Snapshot bank contents.
			Map<Integer, Integer> bankHas = new HashMap<>();
			OwnedItems.addContainer(bankHas, bank);

			// Runes in a rune pouch sitting in the bank, as rune id to amount.
			int bankPouchId = BankPickupRequirements.findBankPouch(bankHas);
			Map<Integer, Integer> bankPouchRunes = bankPouchId == -1
				? Map.of()
				: OwnedItems.runePouchContents(client);

			// Snapshot what the player already has (inventory + equipment + rune pouch in hand).
			Map<Integer, Integer> playerHas = BankPickupRequirements.collectPlayerItems(client);

			// Player-declared unlocks relieve requirements the same way they do during the search.
			Set<Unlock> unlocks = pathfinderConfig.getUnlocks();

			// Each entry is one edge's pickup phrase, e.g. "Air rune (3), Law rune or Varrock teleport".
			LinkedHashSet<String> phrases = new LinkedHashSet<>();
			Set<Integer> itemIds = new HashSet<>();
			boolean usesFairyRing = false;

			// Walk each edge in the remaining path in a single pass.
			for (int i = pathIndex; i < path.size() - 1; i++)
			{
				int stepPoint = path.get(i).getPackedPosition();
				int nextPoint = path.get(i + 1).getPackedPosition();
				boolean banked = path.get(i + 1).isBankVisited();

				List<Transport> edgeAlternatives = new ArrayList<>();
				// When the step carries the transport the search actually used, that single
				// transport is the edge — destination-matched alternatives (including a
				// no-requirement transport sharing the destination) must not suppress the
				// pickup phrase or bank highlight for the transport the path takes.
				Transport usedTransport = path.get(i + 1).getTransport();
				if (usedTransport != null)
				{
					edgeAlternatives.add(usedTransport);
				}
				else
				{
					TransportAvailability availability = pathfinderConfig.getTransportAvailability(banked);
					for (Transport t : availability.getTransportsAt(stepPoint))
					{
						if (t.getDestination() == nextPoint)
						{
							edgeAlternatives.add(t);
						}
					}
					for (Transport t : availability.getUsableTeleports())
					{
						if (t.getDestination() == nextPoint)
						{
							edgeAlternatives.add(t);
						}
					}
				}
				if (edgeAlternatives.isEmpty())
				{
					continue;
				}

				// Fairy rings handled once globally via the staff requirement below.
				List<Transport> nonFairy = new ArrayList<>();
				for (Transport t : edgeAlternatives)
				{
					if (TransportType.FAIRY_RING.equals(t.getType()))
					{
						usesFairyRing = true;
					}
					else
					{
						nonFairy.add(t);
					}
				}
				if (nonFairy.isEmpty())
				{
					continue;
				}

				// If at least one alternative requires no items, nothing to pick up for this edge.
				boolean anyAlternativeIsFree = false;
				for (Transport t : nonFairy)
				{
					if (t.getItemRequirements() == null || t.getItemRequirements().size() == 0)
					{
						anyAlternativeIsFree = true;
						break;
					}
				}
				if (anyAlternativeIsFree)
				{
					continue;
				}

				// If any alternative is fully satisfied by the player already, no pickup needed.
				boolean satisfied = false;
				for (Transport t : nonFairy)
				{
					if (BankPickupRequirements.transportSatisfiedBy(t, playerHas, unlocks))
					{
						satisfied = true;
						break;
					}
				}
				if (satisfied)
				{
					continue;
				}

				// Build phrases (alternatives the bank can fully supply) and collect item IDs in one pass.
				LinkedHashSet<String> altStrings = new LinkedHashSet<>();
				for (Transport t : nonFairy)
				{
					Map<Integer, Long> pickups = BankPickupRequirements.computeBankPickups(
						t, playerHas, bankHas, bankPouchId, bankPouchRunes, unlocks);
					if (pickups != null && !pickups.isEmpty())
					{
						// Bank can fully satisfy this alternative: contribute to display phrase.
						altStrings.add(BankPickupRequirements.formatPickups(client, pickups));
					}
					// Always collect actual bank item IDs for highlighting.
					// computeBankPickups uses canonical IDs (e.g. air rune) for display, but the bank
					// may only hold a variant (e.g. mist rune), so we resolve the real ID separately.
					BankPickupRequirements.collectPartialBankItemIds(
						t, playerHas, bankHas, bankPouchId, bankPouchRunes, unlocks, itemIds);
				}
				if (!altStrings.isEmpty())
				{
					phrases.add(String.join(" or ", altStrings));
				}
			}

			// Fairy ring staff (Dramen / Lunar) is a single OR requirement across the whole trip.
			// Not needed if the Lumbridge Elite diary is complete.
			if (usesFairyRing && client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) != 1)
			{
				int[] staffIds = ItemVariations.DRAMEN_STAFF.getIds();
				if (BankPickupRequirements.findCovering(staffIds, 1, Map.of(), playerHas) == -1)
				{
					// Use the canonical ID (Dramen staff) for the display phrase.
					if (BankPickupRequirements.findCovering(staffIds, 1, Map.of(), bankHas) != -1)
					{
						Map<Integer, Long> single = new LinkedHashMap<>();
						single.put(staffIds[0], 1L);
						phrases.add(BankPickupRequirements.formatPickups(client, single));
						// Highlight all staff variants present in the bank.
						BankPickupRequirements.addCovering(staffIds, 1, Map.of(), bankHas, itemIds);
					}
				}
			}

			resultPhrases.addAll(phrases);
			resultIds.addAll(itemIds);
			return new BankPickupResult(resultPhrases, resultIds);
		}
	}

	/**
	 * Collects item IDs from the bank that partially satisfy a transport's requirements.
	 * Called when the bank cannot fully satisfy the transport (so no phrase is generated),
	 * but we still want to highlight any relevant items the bank does have.
	 */
	static void collectPartialBankItemIds(Transport transport,
		Map<Integer, Integer> playerHas,
		Map<Integer, Integer> bankHas,
		int bankPouchId,
		Map<Integer, Integer> bankPouchRunes,
		Set<Integer> itemIds)
	{
		collectPartialBankItemIds(transport, playerHas, bankHas, bankPouchId, bankPouchRunes, Set.of(), itemIds);
	}

	/**
	 * As {@link #collectPartialBankItemIds(Transport, Map, Map, int, Map, Set)}, with the
	 * player-declared {@link Unlock unlocks} also counting toward requirement satisfaction.
	 */
	static void collectPartialBankItemIds(Transport transport,
		Map<Integer, Integer> playerHas,
		Map<Integer, Integer> bankHas,
		int bankPouchId,
		Map<Integer, Integer> bankPouchRunes,
		Set<Unlock> unlocks,
		Set<Integer> itemIds)
	{
		if (transport.getItemRequirements() == null)
		{
			return;
		}
		// Add the bank rune pouch if it is taken; its runes then count as carried.
		Map<Integer, Integer> carried = carriedWithBankPouch(transport, playerHas, bankHas, bankPouchRunes, unlocks);
		if (carried != playerHas)
		{
			itemIds.add(bankPouchId);
		}
		for (ItemRequirement req : transport.getItemRequirements().getRequirements())
		{
			if (playerSatisfies(req, carried, unlocks))
			{
				continue;
			}
			// Add all item variants (e.g. mist/dust/smoke rune for air rune) that cover the
			// shortfall of any OR branch, at that branch's quantity.
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				addCovering(branch.getItemIds(), pickupQuantity(branch), carried, bankHas, itemIds);
			}
			// Add all staff variants (e.g. all air battlestaff types) present in bank.
			addCovering(req.getStaffIds(), 1, Map.of(), bankHas, itemIds);
			// Add all offhand variants (e.g. tome of fire) present in bank.
			addCovering(req.getOffhandIds(), 1, Map.of(), bankHas, itemIds);
		}
	}

	/**
	 * Formats a pickup map (item id to quantity) as a comma-separated, human-readable string.
	 */
	static String formatPickups(Client client, Map<Integer, Long> pickups)
	{
		List<String> parts = new ArrayList<>(pickups.size());
		for (Map.Entry<Integer, Long> entry : pickups.entrySet())
		{
			int itemId = entry.getKey();
			long qty = entry.getValue();
			String itemName = client.getItemDefinition(itemId).getName();
			if (itemName == null || itemName.isEmpty() || "null".equals(itemName))
			{
				itemName = "Unknown item";
			}
			boolean isCurrency = PathfinderConfig.CURRENCIES.contains(itemId);
			if (isCurrency)
			{
				if (qty > 1)
				{
					itemName += " (" + String.format("%,d", qty) + ")";
				}
			}
			else
			{
				itemName = qty + " " + itemName;
			}
			parts.add(itemName);
		}
		return String.join(", ", parts);
	}

	/**
	 * Returns the quantity an OR branch asks for: the branch quantity when that is
	 * positive, otherwise 1.
	 */
	private static int pickupQuantity(ItemRequirement.Branch branch)
	{
		return branch.getQuantity() > 0 ? branch.getQuantity() : 1;
	}

	/**
	 * Returns true if the player already meets this requirement on its own, with enough of
	 * one item variant of any OR branch at that branch's quantity, or with a staff or
	 * offhand that substitutes for it. An unlock branch is met by declaring its unlock;
	 * it can never be covered by items, so it never contributes a pickup.
	 */
	private static boolean playerSatisfies(ItemRequirement req, Map<Integer, Integer> playerHas,
		Set<Unlock> unlocks)
	{
		for (ItemRequirement.Branch branch : req.getBranches())
		{
			if (branch.getUnlock() != null)
			{
				if (unlocks.contains(branch.getUnlock()))
				{
					return true;
				}
				continue;
			}
			if (findCovering(branch.getItemIds(), pickupQuantity(branch), Map.of(), playerHas) != -1)
			{
				return true;
			}
		}
		return findCovering(req.getStaffIds(), 1, Map.of(), playerHas) != -1
			|| findCovering(req.getOffhandIds(), 1, Map.of(), playerHas) != -1;
	}

	/**
	 * Returns true if {@code source} holds enough of {@code id} to make up what {@code carried}
	 * lacks of {@code requiredQty}.
	 */
	private static boolean covers(int id, int requiredQty, Map<Integer, Integer> carried, Map<Integer, Integer> source)
	{
		return source.getOrDefault(id, 0) >= requiredQty - carried.getOrDefault(id, 0);
	}

	/**
	 * Returns the first ID in {@code itemIds} that {@code source} {@link #covers covers}, or -1 if none does.
	 * Item variations list the pure item first, so it is preferred over combination variants.
	 */
	private static int findCovering(int[] itemIds, int requiredQty, Map<Integer, Integer> carried, Map<Integer, Integer> source)
	{
		if (itemIds == null)
		{
			return -1;
		}
		for (int id : itemIds)
		{
			if (covers(id, requiredQty, carried, source))
			{
				return id;
			}
		}
		return -1;
	}

	/**
	 * Returns the first ID in {@code itemIds} that the player already carries some of and that
	 * {@code source} {@link #covers covers}, or -1 if none does.
	 */
	private static int findCarriedCovering(int[] itemIds, int requiredQty, Map<Integer, Integer> carried,
		Map<Integer, Integer> source)
	{
		if (itemIds == null)
		{
			return -1;
		}
		for (int id : itemIds)
		{
			if (carried.getOrDefault(id, 0) > 0 && covers(id, requiredQty, carried, source))
			{
				return id;
			}
		}
		return -1;
	}

	/**
	 * Adds every ID in {@code itemIds} that {@code source} {@link #covers covers} to {@code out}.
	 */
	private static void addCovering(int[] itemIds, int requiredQty, Map<Integer, Integer> carried,
		Map<Integer, Integer> source, Set<Integer> out)
	{
		if (itemIds == null)
		{
			return;
		}
		for (int id : itemIds)
		{
			if (covers(id, requiredQty, carried, source))
			{
				out.add(id);
			}
		}
	}

	/**
	 * Returns true if every requirement of the transport is already met by the player's
	 * inventory/equipment/rune-pouch (taking item-id, staff and offhand variations into account).
	 */
	public static boolean transportSatisfiedBy(Transport transport, Map<Integer, Integer> playerHas)
	{
		return transportSatisfiedBy(transport, playerHas, Set.of());
	}

	/**
	 * As {@link #transportSatisfiedBy(Transport, Map)}, with the player-declared
	 * {@link Unlock unlocks} also counting toward requirement satisfaction.
	 */
	public static boolean transportSatisfiedBy(Transport transport, Map<Integer, Integer> playerHas,
		Set<Unlock> unlocks)
	{
		if (transport.getItemRequirements() == null)
		{
			return true;
		}
		return transport.getItemRequirements().isSatisfiedBy(
			playerHas, PathfinderConfig.CURRENCIES, Integer.MAX_VALUE, unlocks);
	}

	/**
	 * For an unsatisfied transport, returns the items (id to qty) that need to be picked up
	 * from the bank to satisfy it, or null if the bank can't supply them.
	 * Each counted item asks only for the shortfall: the required quantity less what the
	 * player already carries of that item ID, per OR branch at that branch's quantity.
	 * Loose items are chosen from the variants the player already carries first, across all
	 * OR branches, then from all variants in branch declaration order. The displayed item ID
	 * comes from the branch actually picked.
	 * When the bank rune pouch is taken (see {@link #carriedWithBankPouch}), the pouch itself is
	 * returned as a pickup item (qty 1), and its runes count as carried for every requirement.
	 */
	static Map<Integer, Long> computeBankPickups(Transport transport,
		Map<Integer, Integer> playerHas,
		Map<Integer, Integer> bankHas,
		int bankPouchId,
		Map<Integer, Integer> bankPouchRunes)
	{
		return computeBankPickups(transport, playerHas, bankHas, bankPouchId, bankPouchRunes, Set.of());
	}

	/**
	 * As {@link #computeBankPickups(Transport, Map, Map, int, Map)}, with the
	 * player-declared {@link Unlock unlocks} also counting toward requirement
	 * satisfaction. A pure-unlock requirement yields no pickup items, and a
	 * requirement the unlocks already meet asks for nothing.
	 */
	static Map<Integer, Long> computeBankPickups(Transport transport,
		Map<Integer, Integer> playerHas,
		Map<Integer, Integer> bankHas,
		int bankPouchId,
		Map<Integer, Integer> bankPouchRunes,
		Set<Unlock> unlocks)
	{
		Map<Integer, Long> pickups = new LinkedHashMap<>();
		if (transport.getItemRequirements() == null)
		{
			return pickups;
		}
		// Prefer bank rune pouch over individual runes. This avoids surfacing combination
		// rune variants (mist, dust, etc.) when the pouch already covers the requirement.
		Map<Integer, Integer> carried = carriedWithBankPouch(transport, playerHas, bankHas, bankPouchRunes, unlocks);
		if (carried != playerHas)
		{
			pickups.put(bankPouchId, 1L);
		}
		for (ItemRequirement req : transport.getItemRequirements().getRequirements())
		{
			if (playerSatisfies(req, carried, unlocks))
			{
				continue;
			}
			// Try to satisfy from bank directly. First top up a variant the player already carries,
			// across all OR branches, which saves a slot, then fall back to the branches in
			// declaration order (pure item variant first within each branch).
			// Use the canonical (first) item ID of the chosen branch for display so we show
			// "Air rune" rather than a combination rune variant like "Mist rune", unless the
			// player carries some of the chosen variant, which only that variant tops up.
			ItemRequirement.Branch chosen = null;
			int foundId = -1;
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				foundId = findCarriedCovering(branch.getItemIds(), pickupQuantity(branch), carried, bankHas);
				if (foundId != -1)
				{
					chosen = branch;
					break;
				}
			}
			if (chosen == null)
			{
				for (ItemRequirement.Branch branch : req.getBranches())
				{
					foundId = findCovering(branch.getItemIds(), pickupQuantity(branch), carried, bankHas);
					if (foundId != -1)
					{
						chosen = branch;
						break;
					}
				}
			}
			if (chosen != null)
			{
				int carriedQty = carried.getOrDefault(foundId, 0);
				int displayId = carriedQty > 0 ? foundId : chosen.getItemIds()[0];
				pickups.merge(displayId, (long) (pickupQuantity(chosen) - carriedQty), Long::sum);
				continue;
			}
			foundId = findCovering(req.getStaffIds(), 1, Map.of(), bankHas);
			if (foundId == -1)
			{
				foundId = findCovering(req.getOffhandIds(), 1, Map.of(), bankHas);
			}
			if (foundId == -1)
			{
				return null; // bank can't satisfy this requirement
			}
			pickups.merge(foundId, 1L, Long::sum);
		}
		return pickups;
	}

	/**
	 * Returns what the player carries plus the bank rune pouch's runes, if the pouch is taken.
	 * The pouch is taken when, for at least one requirement the player doesn't already meet,
	 * either the pouch alone covers the shortfall of any OR branch at that branch's quantity,
	 * or loose bank items alone cover the shortfall of no OR branch but the pouch and loose
	 * bank items together cover the shortfall of one of them (counted per item ID, never
	 * across variants).
	 * Otherwise the pouch is not taken and {@code playerHas} itself is returned.
	 */
	private static Map<Integer, Integer> carriedWithBankPouch(Transport transport,
		Map<Integer, Integer> playerHas,
		Map<Integer, Integer> bankHas,
		Map<Integer, Integer> bankPouchRunes,
		Set<Unlock> unlocks)
	{
		// Pouch runes plus loose bank items, per item ID.
		Map<Integer, Integer> pouchAndBank = new HashMap<>(bankHas);
		bankPouchRunes.forEach((runeId, amount) -> pouchAndBank.merge(runeId, amount, Integer::sum));
		for (ItemRequirement req : transport.getItemRequirements().getRequirements())
		{
			if (playerSatisfies(req, playerHas, unlocks))
			{
				continue;
			}
			boolean pouchAlone = false;
			boolean looseAlone = false;
			boolean combined = false;
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				int qty = pickupQuantity(branch);
				pouchAlone = pouchAlone || findCovering(branch.getItemIds(), qty, playerHas, bankPouchRunes) != -1;
				looseAlone = looseAlone || findCovering(branch.getItemIds(), qty, playerHas, bankHas) != -1;
				combined = combined || findCovering(branch.getItemIds(), qty, playerHas, pouchAndBank) != -1;
			}
			if (pouchAlone || (!looseAlone && combined))
			{
				Map<Integer, Integer> carried = new HashMap<>(playerHas);
				bankPouchRunes.forEach((runeId, amount) -> carried.merge(runeId, amount, Integer::sum));
				return carried;
			}
		}
		return playerHas;
	}

	/**
	 * Returns the ID of the first rune pouch found in the bank, or -1 if there is none.
	 */
	private static int findBankPouch(Map<Integer, Integer> bankHas)
	{
		for (int pouchId : PathfinderConfig.RUNE_POUCHES)
		{
			if (bankHas.containsKey(pouchId))
			{
				return pouchId;
			}
		}
		return -1;
	}

	/**
	 * Snapshots what the player already has on them (inventory + equipment + rune pouch
	 * contents if the pouch is in inventory or equipped).
	 */
	public static Map<Integer, Integer> collectPlayerItems(Client client)
	{
		Map<Integer, Integer> totals = new HashMap<>();
		OwnedItems.addContainer(totals, client.getItemContainer(InventoryID.INV));
		OwnedItems.addContainer(totals, client.getItemContainer(InventoryID.WORN));
		OwnedItems.addRunePouchContents(client, totals);
		return totals;
	}
}

package shortestpath.transport;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import shortestpath.transport.parser.VarRequirement;
import shortestpath.transport.requirement.TransportItems;

/**
 * Load-scoped deduplication pools for transport requirement objects and display strings (issue
 * #491). Identical requirements and labels are extremely common across the permuted transport rows,
 * so a single canonical instance is shared. The interner is local to a {@code loadAllFromResources}
 * call and discarded afterwards, so the pools themselves are never retained.
 */
final class LoadInterner
{
	private final Map<TransportItems, TransportItems> items = new HashMap<>();
	private final Map<VarRequirement, VarRequirement> vars = new HashMap<>();
	private final Map<Set<VarRequirement>, Set<VarRequirement>> varSets = new HashMap<>();
	private final Map<Set<Quest>, Set<Quest>> questSets = new HashMap<>();
	private final Map<String, String> strings = new HashMap<>();

	TransportItems intern(TransportItems value)
	{
		return value == null ? null : items.computeIfAbsent(value, v -> v);
	}

	VarRequirement intern(VarRequirement value)
	{
		return vars.computeIfAbsent(value, v -> v);
	}

	Set<VarRequirement> internVarSet(Set<VarRequirement> value)
	{
		return varSets.computeIfAbsent(value, v -> v);
	}

	Set<Quest> internQuestSet(Set<Quest> value)
	{
		return questSets.computeIfAbsent(value, v -> v);
	}

	String internString(String value)
	{
		return value == null ? null : strings.computeIfAbsent(value, v -> v);
	}
}

package shortestpath.transport;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import shortestpath.pathfinder.PathfinderConfig;

/**
 * Collects the items a player owns as item id to quantity, summing an item
 * held in several places. Pathfinding and the item hints share it so they
 * count items the same way.
 */
public final class OwnedItems
{
	private OwnedItems()
	{
	}

	public static void addContainer(Map<Integer, Integer> owned, ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				owned.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
	}

	/**
	 * Adds the runes in the rune pouch, if {@code owned} already holds a rune pouch.
	 */
	public static void addRunePouchContents(Client client, Map<Integer, Integer> owned)
	{
		if (PathfinderConfig.RUNE_POUCHES.stream().noneMatch(owned::containsKey))
		{
			return;
		}
		runePouchContents(client).forEach((runeId, amount) -> owned.merge(runeId, amount, Integer::sum));
	}

	/**
	 * Returns the runes in the rune pouch as rune id to amount. The varbits that
	 * hold the contents are current wherever the pouch is, including the bank.
	 */
	public static Map<Integer, Integer> runePouchContents(Client client)
	{
		Map<Integer, Integer> runes = new HashMap<>();
		EnumComposition runePouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runePouchEnum == null)
		{
			return runes;
		}
		for (int i = 0; i < PathfinderConfig.RUNE_POUCH_RUNE_VARBITS.length; i++)
		{
			int runeEnumId = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_RUNE_VARBITS[i]);
			int runeId = runeEnumId > 0 ? runePouchEnum.getIntValue(runeEnumId) : 0;
			int runeAmount = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_AMOUNT_VARBITS[i]);
			if (runeId > 0 && runeAmount > 0)
			{
				runes.merge(runeId, runeAmount, Integer::sum);
			}
		}
		return runes;
	}
}

package shortestpath.transport;

public enum PohMountedItem
{
	GLORY("Glory", "Amulet of Glory"),
	XERICS_TALISMAN("Xeric's Talisman", "Xeric's Talisman"),
	DIGSITE_PENDANT("Digsite Pendant", "Digsite Pendant"),
	MYTHICAL_CAPE("Mythical Cape", "Mythical cape");

	private final String label;
	private final String objectInfoFragment;

	PohMountedItem(String label, String objectInfoFragment)
	{
		this.label = label;
		this.objectInfoFragment = objectInfoFragment;
	}

	public static PohMountedItem fromObjectInfo(String objectInfo)
	{
		if (objectInfo == null)
		{
			return null;
		}
		for (PohMountedItem item : values())
		{
			if (objectInfo.contains(item.objectInfoFragment))
			{
				return item;
			}
		}
		return null;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

