package shortestpath.transport.parser;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

import lombok.extern.slf4j.Slf4j;
import shortestpath.ItemVariations;
import shortestpath.Util;
import shortestpath.transport.requirement.ItemRequirement;
import shortestpath.transport.requirement.TransportItems;
import shortestpath.transport.requirement.Unlock;

/**
 * Parses item requirements from TSV field values.
 *
 * <p>
 * Format: {@code ITEM_NAME=quantity} with AND (&amp;) and OR (|) operators
 * </p>
 * <p>
 * Example: {@code AIR_RUNE=3&FIRE_RUNE=2} (need both)
 * </p>
 * <p>
 * Example: {@code DRAMEN_STAFF=1|LUNAR_STAFF=1} (need either)
 * </p>
 * <p>
 * Each OR alternative keeps its own quantity, for example
 * {@code SHANTAY_PASS=1|COINS=5} is satisfied by one Shantay pass or by 5 coins.
 * </p>
 */
@Slf4j
public class ItemRequirementParser implements FieldParser<TransportItems>
{
	private static final String DELIM_STATE = "=";
	private static final String DELIM_AND = "&";
	private static final String DELIM_OR = "|";
	private static final String UNLOCK_PREFIX = "UNLOCK_";

	@Override
	public TransportItems parse(String value)
	{
		if (value == null || value.isEmpty())
		{
			return null;
		}

		// Normalize the input
		String normalized = value.replace(" ", "")
			.replace(DELIM_AND + DELIM_AND, DELIM_AND)
			.replace(DELIM_OR + DELIM_OR, DELIM_OR)
			.toUpperCase();

		List<ItemRequirement> requirements = new ArrayList<>();

		try
		{
			// Split by AND to get individual requirements
			String[] andParts = normalized.split(DELIM_AND);

			for (String andPart : andParts)
			{
				ItemRequirement requirement = parseRequirement(andPart);
				requirements.add(requirement);
			}

			return requirements.isEmpty() ? null : new TransportItems(requirements);
		}
		catch (NumberFormatException e)
		{
			log.error("Invalid item or quantity: {}", value);
			return null;
		}
	}

	/**
	 * Parses a single requirement which may have OR alternatives.
	 * Example: "AIR_RUNE=3|DUST_RUNE=3"
	 */
	private ItemRequirement parseRequirement(String part)
	{
		String[] orParts = part.split(Pattern.quote(DELIM_OR));
		if (orParts.length == 0)
		{
			throw new NumberFormatException("Invalid format: " + part);
		}

		List<ItemRequirement.Branch> branches = new ArrayList<>();

		for (String orPart : orParts)
		{
			String[] itemAndQuantity = orPart.split(DELIM_STATE);
			if (itemAndQuantity.length != 2)
			{
				throw new NumberFormatException("Invalid format: " + part);
			}

			String itemName = itemAndQuantity[0];
			int quantity = Integer.parseInt(itemAndQuantity[1]);

			if (itemName.startsWith(UNLOCK_PREFIX))
			{
				if (quantity < 1)
				{
					throw new IllegalArgumentException("An unlock token needs a positive quantity: " + orPart);
				}
				Unlock unlock = Unlock.fromName(itemName);
				if (unlock == null)
				{
					// A typo'd unlock name must fail loudly rather than silently
					// dropping the whole Items cell like an unknown item name.
					throw new IllegalArgumentException("Unknown unlock token: " + orPart);
				}
				branches.add(new ItemRequirement.Branch(null, null, null, quantity, unlock));
				continue;
			}

			ItemVariations variation = ItemVariations.fromName(itemName);
			if (variation != null)
			{
				branches.add(new ItemRequirement.Branch(
					copyOrNull(variation.getIds()),
					copyOrNull(ItemVariations.staves(variation)),
					copyOrNull(ItemVariations.offhands(variation)),
					quantity));
			}
			else
			{
				// Try parsing as raw item ID
				branches.add(new ItemRequirement.Branch(
					new int[]{Integer.parseInt(itemName)}, null, null, quantity));
			}
		}

		return new ItemRequirement(branches);
	}

	private static int[] copyOrNull(int[] ids)
	{
		return Util.concatenate(new int[][]{ids});
	}
}

package shortestpath.transport.parser;

import java.util.HashSet;
import java.util.Set;

import net.runelite.api.Quest;

/**
 * Parses quest requirements from TSV field values.
 *
 * <p>
 * Format: Quest names separated by semicolons
 * </p>
 * <p>
 * Example: {@code Dragon Slayer I;Recipe for Disaster}
 * </p>
 */
public class QuestParser implements FieldParser<Set<Quest>>
{
	private static final String DELIM_MULTI = ";";

	@Override
	public Set<Quest> parse(String value)
	{
		Set<Quest> quests = new HashSet<>();
		if (value == null || value.isEmpty())
		{
			return quests;
		}
		String[] questNames = value.split(DELIM_MULTI);
		for (String questName : questNames)
		{
			for (Quest quest : Quest.values())
			{
				if (quest.getName().equals(questName))
				{
					quests.add(quest);
					break;
				}
			}
		}
		return quests;
	}
}

package shortestpath.transport.parser;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/**
 * Parses skill level requirements from TSV field values.
 *
 * <p>
 * Format: {@code level skillName} (space-separated), multiple separated by
 * semicolons
 * </p>
 * <p>
 * Example: {@code 70 Agility;50 Strength}
 * </p>
 * <p>
 * Prefix a requirement with {@code Max} to use its maximum supported value.
 * </p>
 */
@Slf4j
public class SkillRequirementParser implements FieldParser<int[]>
{
	public static final int MAX_LEVEL = Integer.MAX_VALUE;
	private static final String DELIM_SPACE = " ";
	private static final String DELIM_MULTI = ";";

	@Override
	public int[] parse(String value)
	{
		int[] skillLevels = new int[Skill.values().length + 3];

		if (value == null)
		{
			return skillLevels;
		}

		String[] skillRequirements = value.split(DELIM_MULTI);

		try
		{
			for (String requirement : skillRequirements)
			{
				if (requirement.isEmpty())
				{
					continue;
				}
				String[] levelAndSkill = requirement.split(DELIM_SPACE);
				if (levelAndSkill.length != 2)
				{
					log.error("Invalid level and skill: '{}'", requirement);
					continue;
				}

				int level = "Max".equals(levelAndSkill[0])
					? MAX_LEVEL
					: Integer.parseInt(levelAndSkill[0]);
				String skillName = levelAndSkill[1] == null ? "" : levelAndSkill[1];

				Skill[] skills = Skill.values();
				int i = 0;
				for (; i < skills.length; i++)
				{
					if (skills[i].getName().equals(skillName))
					{
						skillLevels[i] = level;
					}
				}
				if (skillName.toLowerCase().startsWith("total"))
				{
					skillLevels[i] = level;
				}
				i++;
				if (skillName.toLowerCase().startsWith("combat"))
				{
					skillLevels[i] = level;
				}
				i++;
				if (skillName.toLowerCase().startsWith("quest"))
				{
					skillLevels[i] = level;
				}
			}
		}
		catch (NumberFormatException e)
		{
			log.error("Invalid level and skill: {}", value);
		}

		return skillLevels;
	}
}

package shortestpath.transport.parser;

import java.util.Map;

import lombok.Getter;

/**
 * Represents a single row from a TSV transport file.
 * Provides a clean interface to access field values by name.
 */
@Getter
public class TransportRecord
{

	/**
	 * -- GETTER --
	 * Gets the underlying field map.
	 */
	private final Map<String, String> fields;

	public TransportRecord(Map<String, String> fields)
	{
		this.fields = Map.copyOf(fields);
	}

	/**
	 * Gets a field value by name, or null if not present.
	 */
	public String get(String fieldName)
	{
		return fields.get(fieldName);
	}

	/**
	 * Checks if a field is present and non-empty.
	 */
	public boolean has(String fieldName)
	{
		String value = fields.get(fieldName);
		return value != null && !value.isEmpty();
	}

	/**
	 * Checks if a field key exists in the record (may have empty value).
	 */
	public boolean hasKey(String fieldName)
	{
		return fields.containsKey(fieldName);
	}

	/**
	 * Gets the origin field value.
	 */
	public String getOrigin()
	{
		return get(Fields.ORIGIN);
	}

	/**
	 * Gets the destination field value.
	 */
	public String getDestination()
	{
		return get(Fields.DESTINATION);
	}

	/**
	 * Gets the skills field value.
	 */
	public String getSkills()
	{
		return get(Fields.SKILLS);
	}

	/**
	 * Gets the items field value.
	 */
	public String getItems()
	{
		return get(Fields.ITEMS);
	}

	/**
	 * Gets the quests field value.
	 */
	public String getQuests()
	{
		return get(Fields.QUESTS);
	}

	/**
	 * Gets the duration field value.
	 */
	public String getDuration()
	{
		return get(Fields.DURATION);
	}

	/**
	 * Gets the display info field value.
	 */
	public String getDisplayInfo()
	{
		return get(Fields.DISPLAY_INFO);
	}

	/**
	 * Gets the consumable field value.
	 */
	public String getConsumable()
	{
		return get(Fields.CONSUMABLE);
	}

	/**
	 * Gets the wilderness level field value.
	 */
	public String getWildernessLevel()
	{
		return get(Fields.WILDERNESS_LEVEL);
	}

	/**
	 * Gets the object info field value.
	 */
	public String getObjectInfo()
	{
		return get(Fields.OBJECT_INFO);
	}

	/**
	 * Gets the varbits field value.
	 */
	public String getVarbits()
	{
		return get(Fields.VARBITS);
	}

	/**
	 * Gets the var players field value.
	 */
	public String getVarPlayers()
	{
		return get(Fields.VAR_PLAYERS);
	}

	/**
	 * Gets the league region override field value.
	 */
	public String getRegionOverride()
	{
		return get(Fields.REGION_OVERRIDE);
	}

	/**
	 * Standard field names used across TSV files
	 */
	public static final class Fields
	{
		public static final String ORIGIN = "Origin";
		public static final String DESTINATION = "Destination";
		public static final String SKILLS = "Skills";
		public static final String ITEMS = "Items";
		public static final String QUESTS = "Quests";
		public static final String DURATION = "Duration";
		public static final String DISPLAY_INFO = "Display info";
		public static final String CONSUMABLE = "Consumable";
		public static final String WILDERNESS_LEVEL = "Wilderness level";
		public static final String OBJECT_INFO = "menuOption menuTarget objectID";
		public static final String VARBITS = "Varbits";
		public static final String VAR_PLAYERS = "VarPlayers";
		public static final String REGION_OVERRIDE = "Region override";

		private Fields()
		{
		}
	}
}

package shortestpath.transport.parser;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Parses TSV file contents into TransportRecord objects.
 *
 * <p>
 * TSV files should have a header line (optionally starting with #)
 * followed by data lines. Empty lines and lines starting with # are ignored.
 * </p>
 */
public class TsvParser
{
	private static final String DELIM_COLUMN = "\t";
	private static final String PREFIX_COMMENT = "#";

	/**
	 * Parses TSV content into a list of TransportRecords.
	 * The first line must be a header line (optionally starting with #).
	 */
	public List<TransportRecord> parse(String contents)
	{
		List<TransportRecord> records = new ArrayList<>();
		Scanner scanner = new Scanner(contents);

		if (!scanner.hasNextLine())
		{
			scanner.close();
			return records;
		}

		// Parse header line
		String[] headers = parseHeaderLine(scanner.nextLine());

		// Parse data lines
		while (scanner.hasNextLine())
		{
			String line = scanner.nextLine();

			if (line.startsWith(PREFIX_COMMENT) || line.isBlank())
			{
				continue;
			}

			TransportRecord record = parseLine(line, headers);
			records.add(record);
		}

		scanner.close();
		return records;
	}

	/**
	 * Parses the header line, stripping the comment prefix if present.
	 */
	private String[] parseHeaderLine(String headerLine)
	{
		String normalized = headerLine;
		if (normalized.startsWith(PREFIX_COMMENT + " "))
		{
			normalized = normalized.substring(2);
		}
		else if (normalized.startsWith(PREFIX_COMMENT))
		{
			normalized = normalized.substring(1);
		}
		return normalized.split(DELIM_COLUMN);
	}

	/**
	 * Parses a single data line into a TransportRecord.
	 */
	private TransportRecord parseLine(String line, String[] headers)
	{
		// Use -1 limit to preserve trailing empty strings
		String[] fields = line.split(DELIM_COLUMN, -1);
		Map<String, String> fieldMap = new HashMap<>();

		for (int i = 0; i < headers.length; i++)
		{
			if (i < fields.length)
			{
				fieldMap.put(headers[i], fields[i]);
			}
		}

		return new TransportRecord(fieldMap);
	}
}

package shortestpath.transport.parser;

import lombok.Getter;

/**
 * The type of comparison to perform when checking a variable requirement.
 */
@Getter
public enum VarCheckType
{
	BIT_SET("&"),
	COOLDOWN_MINUTES("@"),
	EQUAL("="),
	GREATER(">"),
	SMALLER("<");

	private final String code;

	VarCheckType(String code)
	{
		this.code = code;
	}
}

package shortestpath.transport.parser;

import java.util.Map;

import lombok.Getter;

/**
 * Represents a variable-based requirement for a transport.
 * This can be either a varbit or a varplayer requirement.
 *
 * <p>
 * Consolidates the previously separate TransportVarbit and TransportVarPlayer
 * classes which had identical logic.
 * </p>
 */
@Getter
public class VarRequirement
{

	private final VarType varType;
	private final int id;
	private final int value;
	private final VarCheckType checkType;

	public VarRequirement(VarType varType, int id, int value, VarCheckType checkType)
	{
		this.varType = varType;
		this.id = id;
		this.value = value;
		this.checkType = checkType;
	}

	/**
	 * Creates a varbit requirement.
	 */
	public static VarRequirement varbit(int id, int value, VarCheckType checkType)
	{
		return new VarRequirement(VarType.VARBIT, id, value, checkType);
	}

	/**
	 * Creates a varplayer requirement.
	 */
	public static VarRequirement varPlayer(int id, int value, VarCheckType checkType)
	{
		return new VarRequirement(VarType.VARPLAYER, id, value, checkType);
	}

	/**
	 * Checks if this requirement is satisfied given the current variable values.
	 *
	 * @param values A map of variable IDs to their current values
	 * @param currentTimeMinutes current game time in minutes
	 * @return true if the requirement is satisfied
	 */
	public boolean check(Map<Integer, Integer> values, long currentTimeMinutes)
	{
		Integer currentValue = values.get(id);
		if (currentValue == null)
		{
			return false;
		}
		return checkValue(currentValue, currentTimeMinutes);
	}

	/**
	 * Same logic as {@link #check(Map, long)} but with the variable value already resolved (e.g. from the client).
	 *
	 * @param currentTimeMinutes current game time in minutes
	 */
	public boolean checkValue(int currentValue, long currentTimeMinutes)
	{
		switch (checkType)
		{
			case EQUAL:
				return currentValue == value;
			case GREATER:
				return currentValue > value;
			case SMALLER:
				return currentValue < value;
			case BIT_SET:
				return (currentValue & value) > 0;
			case COOLDOWN_MINUTES:
				return (currentTimeMinutes - (long) currentValue) > value;
			default:
				return false;
		}
	}

	public boolean isVarbit()
	{
		return varType == VarType.VARBIT;
	}

	public boolean isVarPlayer()
	{
		return varType == VarType.VARPLAYER;
	}

	@Override
	public int hashCode()
	{
		int result = varType.hashCode();
		result = 31 * result + id;
		result = 31 * result + value;
		result = 31 * result + checkType.hashCode();
		return result;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		VarRequirement that = (VarRequirement) o;
		return id == that.id && value == that.value && varType == that.varType && checkType == that.checkType;
	}

	@Override
	public String toString()
	{
		return varType + "[" + id + " " + checkType.getCode() + " " + value + "]";
	}

	/**
	 * The type of variable this requirement checks.
	 */
	public enum VarType
	{
		VARBIT,
		VARPLAYER
	}
}

package shortestpath.transport.parser;

import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

import lombok.extern.slf4j.Slf4j;

/**
 * Parses variable requirement strings into VarRequirement objects.
 * Supports both varbit and varplayer requirements.
 *
 * <p>
 * Format: {@code <id><check><value>} where check is one of: = > < & @
 * </p>
 * <p>
 * Multiple requirements are separated by semicolons.
 * </p>
 * <p>
 * Example: {@code 1234=1;5678>10}
 * </p>
 */
@Slf4j
public class VarRequirementParser implements FieldParser<Set<VarRequirement>>
{
	private static final String DELIM_MULTI = ";";

	private final VarRequirement.VarType varType;

	/**
	 * Creates a parser for the specified variable type.
	 */
	public VarRequirementParser(VarRequirement.VarType varType)
	{
		this.varType = varType;
	}

	/**
	 * Creates a parser for varbit requirements.
	 */
	public static VarRequirementParser forVarbits()
	{
		return new VarRequirementParser(VarRequirement.VarType.VARBIT);
	}

	/**
	 * Creates a parser for varplayer requirements.
	 */
	public static VarRequirementParser forVarPlayers()
	{
		return new VarRequirementParser(VarRequirement.VarType.VARPLAYER);
	}

	@Override
	public Set<VarRequirement> parse(String value)
	{
		Set<VarRequirement> result = new HashSet<>();
		if (value == null || value.isEmpty())
		{
			return result;
		}

		try
		{
			for (String requirement : value.split(DELIM_MULTI))
			{
				if (requirement.isEmpty())
				{
					continue;
				}

				VarRequirement parsed = parseRequirement(requirement);
				if (parsed != null)
				{
					result.add(parsed);
				}
			}
		}
		catch (NumberFormatException e)
		{
			log.error("Invalid var requirement: {}", value);
		}
		return result;
	}

	private VarRequirement parseRequirement(String requirement)
	{
		for (VarCheckType checkType : VarCheckType.values())
		{
			String[] parts = requirement.split(Pattern.quote(checkType.getCode()));
			if (parts.length == 2)
			{
				int id = Integer.parseInt(parts[0]);
				int val = Integer.parseInt(parts[1]);
				return new VarRequirement(varType, id, val, checkType);
			}
		}
		log.error("Invalid var requirement: '{}'", requirement);
		return null;
	}
}

package shortestpath.transport.parser;

import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;

/**
 * Parses world point coordinates from TSV field values.
 *
 * <p>
 * Format: {@code x y plane} (space-separated)
 * </p>
 * <p>
 * Empty values are treated as location permutations (for fairy rings, etc.)
 * </p>
 */
public class WorldPointParser implements FieldParser<Integer>
{
	private static final String DELIM_SPACE = " ";

	@Override
	public Integer parse(String value)
	{
		if (value == null || value.isEmpty())
		{
			return Transport.LOCATION_PERMUTATION;
		}
		String[] parts = value.split(DELIM_SPACE);
		return parts.length == 3 ? WorldPointUtil.packWorldPoint(
			Integer.parseInt(parts[0]),
			Integer.parseInt(parts[1]),
			Integer.parseInt(parts[2])) : Transport.LOCATION_PERMUTATION;
	}
}

package shortestpath.transport.requirement;

import java.util.Arrays;
import java.util.List;

import lombok.Getter;
import shortestpath.Util;

/**
 * Represents an item requirement with its variations and quantity.
 * For example: AIR_RUNE=3 where AIR_RUNE can be substituted by DUST_RUNE,
 * SMOKE_RUNE, etc.
 * OR alternatives are kept as separate {@link Branch branches} with their own
 * quantities, for example SHANTAY_PASS=1|COINS=5 is satisfied by one Shantay
 * pass or by 5 coins.
 */
@Getter
public class ItemRequirement
{
	/**
	 * One {@code NAME=quantity} alternative of an OR group. Its itemIds are
	 * that item's variation ids.
	 */
	@Getter
	public static final class Branch
	{
		private final int[] itemIds;
		private final int[] staffIds;
		private final int[] offhandIds;
		private final int quantity;
		/**
		 * The declared unlock this branch references, or {@code null} for a
		 * regular item branch. An unlock branch carries no item ids, so its
		 * {@link #itemIds} is always {@code null}.
		 */
		private final Unlock unlock;

		public Branch(int[] itemIds, int[] staffIds, int[] offhandIds, int quantity)
		{
			this(itemIds, staffIds, offhandIds, quantity, null);
		}

		public Branch(int[] itemIds, int[] staffIds, int[] offhandIds, int quantity, Unlock unlock)
		{
			this.itemIds = itemIds;
			this.staffIds = staffIds;
			this.offhandIds = offhandIds;
			this.quantity = quantity;
			this.unlock = unlock;
		}

		/**
		 * An unlock-only branch carries no item ids and can only be satisfied
		 * by declaring its unlock; no item can ever cover it.
		 */
		public boolean isUnlockOnly()
		{
			return itemIds == null && unlock != null;
		}

		@Override
		public int hashCode()
		{
			int result = Arrays.hashCode(itemIds);
			result = 31 * result + Arrays.hashCode(staffIds);
			result = 31 * result + Arrays.hashCode(offhandIds);
			result = 31 * result + quantity;
			result = 31 * result + (unlock == null ? 0 : unlock.hashCode());
			return result;
		}

		@Override
		public boolean equals(Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (o == null || getClass() != o.getClass())
			{
				return false;
			}
			Branch that = (Branch) o;
			return quantity == that.quantity &&
				unlock == that.unlock &&
				Arrays.equals(itemIds, that.itemIds) &&
				Arrays.equals(staffIds, that.staffIds) &&
				Arrays.equals(offhandIds, that.offhandIds);
		}
	}

	/**
	 * The OR alternatives of this requirement, in declaration order, each with
	 * its own quantity. A requirement without OR alternatives has one branch.
	 */
	private final List<Branch> branches;

	/**
	 * The item IDs that satisfy this requirement (variations of every OR branch)
	 */
	private final int[] itemIds;

	/**
	 * Staff IDs that can substitute runes for this requirement
	 */
	private final int[] staffIds;

	/**
	 * Offhand IDs that can substitute for this requirement
	 */
	private final int[] offhandIds;

	/**
	 * The largest quantity any branch requires; kept for callers that predate
	 * per-branch quantities (e.g. external report tooling). OR branches can
	 * need different quantities, so satisfaction logic must use
	 * {@link #getBranches()}.
	 */
	private final int quantity;

	public ItemRequirement(int[] itemIds, int[] staffIds, int[] offhandIds, int quantity)
	{
		this(List.of(new Branch(itemIds, staffIds, offhandIds, quantity)));
	}

	public ItemRequirement(List<Branch> branches)
	{
		if (branches == null || branches.isEmpty())
		{
			throw new IllegalArgumentException("An item requirement needs at least one branch");
		}
		this.branches = List.copyOf(branches);
		int maxQuantity = -1;
		int[][] itemIdArrays = new int[this.branches.size()][];
		int[][] staffIdArrays = new int[this.branches.size()][];
		int[][] offhandIdArrays = new int[this.branches.size()][];
		for (int i = 0; i < this.branches.size(); i++)
		{
			Branch branch = this.branches.get(i);
			itemIdArrays[i] = branch.getItemIds();
			staffIdArrays[i] = branch.getStaffIds();
			offhandIdArrays[i] = branch.getOffhandIds();
			maxQuantity = Math.max(maxQuantity, branch.getQuantity());
		}
		if (this.branches.size() == 1)
		{
			Branch only = this.branches.get(0);
			this.itemIds = only.getItemIds();
			this.staffIds = only.getStaffIds();
			this.offhandIds = only.getOffhandIds();
		}
		else
		{
			this.itemIds = Util.concatenate(itemIdArrays);
			this.staffIds = Util.concatenate(staffIdArrays);
			this.offhandIds = Util.concatenate(offhandIdArrays);
		}
		this.quantity = maxQuantity;
	}

	/**
	 * A pure-unlock requirement consists only of unlock branches: it is
	 * satisfied by declaring any one of them and can never be covered by
	 * items, staves or offhands. Item evaluation is not the only gate for
	 * such requirements, since teleportation-item modes can skip item
	 * evaluation entirely.
	 */
	public boolean isPureUnlock()
	{
		for (Branch branch : branches)
		{
			if (!branch.isUnlockOnly())
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public int hashCode()
	{
		return branches.hashCode();
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		ItemRequirement that = (ItemRequirement) o;
		return branches.equals(that.branches);
	}
}

package shortestpath.transport.requirement;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import lombok.Getter;

/**
 * Represents all item requirements for a transport.
 * All requirements must be satisfied.
 */
@Getter
public class TransportItems
{
	private final List<ItemRequirement> requirements;

	public TransportItems(List<ItemRequirement> requirements)
	{
		this.requirements = List.copyOf(requirements);
	}

	/**
	 * Creates TransportItems from legacy array format for backwards compatibility.
	 */
	public TransportItems(int[][] items, int[][] staves, int[][] offhands, int[] quantities)
	{
		List<ItemRequirement> reqs = new ArrayList<>();
		for (int i = 0; i < items.length; i++)
		{
			reqs.add(new ItemRequirement(
				items[i],
				staves != null && i < staves.length ? staves[i] : new int[0],
				offhands != null && i < offhands.length ? offhands[i] : new int[0],
				quantities[i]));
		}
		this.requirements = Collections.unmodifiableList(reqs);
	}

	/**
	 * Merges two TransportItems, combining all requirements from both.
	 * If either is null, returns the other.
	 */
	public static TransportItems merge(TransportItems first, TransportItems second)
	{
		if (first == null)
		{
			return second;
		}
		if (second == null)
		{
			return first;
		}
		List<ItemRequirement> merged = new ArrayList<>();
		merged.addAll(first.requirements);
		merged.addAll(second.requirements);
		return new TransportItems(merged);
	}

	/**
	 * Gets the number of item requirements.
	 */
	public int size()
	{
		return requirements.size();
	}

	/**
	 * Returns whether the player can satisfy every item requirement at once.
	 *
	 * <p>Runes (and other counted items) are applied first, then at most one offhand
	 * (tome), then at most one staff. Combination staves may cover multiple leftover
	 * rune types because the same item id appears in more than one staff list. Two
	 * different staves cannot be used together.
	 */
	public boolean isSatisfiedBy(Map<Integer, Integer> itemCounts, Set<Integer> currencies, int currencyThreshold)
	{
		return isSatisfiedBy(itemCounts, currencies, currencyThreshold, Set.of());
	}

	/**
	 * As {@link #isSatisfiedBy(Map, Set, int)}, with an additional set of
	 * player-declared {@link Unlock unlocks}. An unlock branch of an OR group
	 * is satisfied when its unlock is declared; it never relieves item terms
	 * of other branches and is never covered by items, staves or offhands.
	 */
	public boolean isSatisfiedBy(Map<Integer, Integer> itemCounts, Set<Integer> currencies, int currencyThreshold, Set<Unlock> unlocks)
	{
		if (requirements.isEmpty())
		{
			return true;
		}

		List<ItemRequirement> leftover = new ArrayList<>();
		boolean usedOffhand = false;
		for (ItemRequirement req : requirements)
		{
			Boolean itemsResult = satisfiedByItems(req, itemCounts, currencies, currencyThreshold, unlocks);
			if (itemsResult == null)
			{
				return false;
			}
			if (itemsResult)
			{
				continue;
			}
			if (!usedOffhand && hasOwnedOffhand(req, itemCounts))
			{
				usedOffhand = true;
				continue;
			}
			leftover.add(req);
		}

		if (leftover.isEmpty())
		{
			return true;
		}
		return existsOneStaffCovering(leftover, itemCounts);
	}

	/**
	 * {@code true} if counted items pay this requirement through any OR branch at that
	 * branch's quantity, {@code false} if not, {@code null} if the player has the items
	 * but every covering branch exceeds the currency threshold. A satisfied branch wins
	 * over a blocked one, whatever their order.
	 */
	private static Boolean satisfiedByItems(
		ItemRequirement req,
		Map<Integer, Integer> itemCounts,
		Set<Integer> currencies,
		int currencyThreshold,
		Set<Unlock> unlocks)
	{
		boolean blocked = false;
		for (ItemRequirement.Branch branch : req.getBranches())
		{
			Unlock unlock = branch.getUnlock();
			if (unlock != null)
			{
				if (unlocks.contains(unlock))
				{
					return true;
				}
				continue;
			}

			int[] itemIds = branch.getItemIds();
			if (itemIds == null)
			{
				continue;
			}
			for (int itemId : itemIds)
			{
				if (!hasQuantity(itemCounts, itemId, branch.getQuantity(), false))
				{
					continue;
				}
				if (currencies != null && currencies.contains(itemId) && branch.getQuantity() > currencyThreshold)
				{
					blocked = true;
					break;
				}
				return true;
			}
		}
		return blocked ? null : false;
	}

	/**
	 * {@code true} when any OR branch has an owned offhand id at that branch's quantity.
	 */
	private static boolean hasOwnedOffhand(ItemRequirement req, Map<Integer, Integer> itemCounts)
	{
		for (ItemRequirement.Branch branch : req.getBranches())
		{
			if (hasOwnedSubstitute(branch.getOffhandIds(), itemCounts, branch.getQuantity(), true))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean existsOneStaffCovering(List<ItemRequirement> leftover, Map<Integer, Integer> itemCounts)
	{
		Set<Integer> candidates = null;
		for (ItemRequirement req : leftover)
		{
			Set<Integer> ownedStaves = new HashSet<>();
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				ownedStaves.addAll(ownedIds(branch.getStaffIds(), itemCounts, branch.getQuantity(), true));
			}
			if (ownedStaves.isEmpty())
			{
				return false;
			}
			if (candidates == null)
			{
				candidates = ownedStaves;
			}
			else
			{
				candidates.retainAll(ownedStaves);
			}
			if (candidates.isEmpty())
			{
				return false;
			}
		}
		return true;
	}

	private static boolean hasOwnedSubstitute(int[] ids, Map<Integer, Integer> itemCounts, int requiredQuantity, boolean unlimited)
	{
		return !ownedIds(ids, itemCounts, requiredQuantity, unlimited).isEmpty();
	}

	private static Set<Integer> ownedIds(int[] ids, Map<Integer, Integer> itemCounts, int requiredQuantity, boolean unlimited)
	{
		if (ids == null || ids.length == 0)
		{
			return Set.of();
		}
		Set<Integer> owned = new HashSet<>();
		for (int itemId : ids)
		{
			if (hasQuantity(itemCounts, itemId, requiredQuantity, unlimited))
			{
				owned.add(itemId);
			}
		}
		return owned;
	}

	private static boolean hasQuantity(Map<Integer, Integer> itemCounts, int itemId, int requiredQuantity, boolean unlimited)
	{
		int quantity = itemCounts.getOrDefault(itemId, 0);
		if (unlimited)
		{
			return requiredQuantity > 0 && quantity >= 1 || requiredQuantity == 0 && quantity == 0;
		}
		return requiredQuantity > 0 && quantity >= requiredQuantity || requiredQuantity == 0 && quantity == 0;
	}

	// Legacy getters for backwards compatibility. They emit one row per OR
	// branch, in requirement order and then branch order; a requirement
	// without OR alternatives still gives one row. Use size() or
	// getRequirements() to count AND groups.
	private int branchCount()
	{
		int n = 0;
		for (ItemRequirement req : requirements)
		{
			n += req.getBranches().size();
		}
		return n;
	}

	public int[][] getItems()
	{
		int[][] items = new int[branchCount()][];
		int i = 0;
		for (ItemRequirement req : requirements)
		{
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				// Unlock-only branches carry no item ids; emit an empty array so
				// consumers iterating alternatives never dereference a null.
				int[] itemIds = branch.getItemIds();
				items[i++] = itemIds == null ? new int[0] : itemIds;
			}
		}
		return items;
	}

	public int[][] getStaves()
	{
		int[][] staves = new int[branchCount()][];
		int i = 0;
		for (ItemRequirement req : requirements)
		{
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				staves[i++] = branch.getStaffIds();
			}
		}
		return staves;
	}

	public int[][] getOffhands()
	{
		int[][] offhands = new int[branchCount()][];
		int i = 0;
		for (ItemRequirement req : requirements)
		{
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				offhands[i++] = branch.getOffhandIds();
			}
		}
		return offhands;
	}

	public int[] getQuantities()
	{
		int[] quantities = new int[branchCount()];
		int i = 0;
		for (ItemRequirement req : requirements)
		{
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				quantities[i++] = branch.getQuantity();
			}
		}
		return quantities;
	}

	private String toString(int[][] array)
	{
		StringBuilder text = new StringBuilder();
		for (int[] inner : array)
		{
			text.append((text.length() == 0) ? "" : ", ").append(Arrays.toString(inner));
		}
		return "[" + text + "]";
	}

	@Override
	public int hashCode()
	{
		return requirements.hashCode();
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		TransportItems that = (TransportItems) o;
		if (requirements.size() != that.requirements.size())
		{
			return false;
		}
		for (int i = 0; i < requirements.size(); i++)
		{
			if (!requirements.get(i).equals(that.requirements.get(i)))
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public String toString()
	{
		return "[" +
			toString(getItems()) + ", " +
			toString(getStaves()) + ", " +
			toString(getOffhands()) + ", " +
			Arrays.toString(getQuantities()) + "]";
	}
}

package shortestpath.transport.requirement;

/**
 * Player-declared unlock states that the game does not expose to the client,
 * referenced by {@code UNLOCK_<NAME>=1} tokens in transport Items cells.
 * An unlock branch satisfies a requirement by declaration alone: it never
 * contributes items and is never covered by inventory, staff or offhand ids.
 * An unlock alternative inside an OR group acts as a relief
 * ({@code AXE=1|UNLOCK_CANOE_AXE=1}), while an ANDed pure-unlock requirement
 * acts as a gate ({@code 13393=1&UNLOCK_XERICS_HONOUR=1}).
 */
public enum Unlock
{
	/**
	 * An axe stored at a canoe station, usable instead of a carried axe.
	 */
	CANOE_AXE,

	/**
	 * Dragontooth Island free passage, paying no ecto-token toll.
	 */
	DRAGONTOOTH,

	/**
	 * Xeric's Honour, unlocking the talisman teleports.
	 */
	XERICS_HONOUR,
	;

	private static final String TOKEN_PREFIX = "UNLOCK_";

	/**
	 * Resolves an {@code UNLOCK_<NAME>} token to its unlock, or {@code null}
	 * when the token does not name a known unlock. Callers that accept the
	 * token class must fail loudly on {@code null} so that a typo'd unlock
	 * name can never silently drop a requirement.
	 */
	public static Unlock fromName(String name)
	{
		if (name == null || !name.startsWith(TOKEN_PREFIX))
		{
			return null;
		}
		try
		{
			return Unlock.valueOf(name.substring(TOKEN_PREFIX.length()));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}
}

package shortestpath;

import net.runelite.client.game.AgilityShortcut;
import org.junit.Test;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportLoader;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * This test checks every AgilityShortcut enum constant against the list of all transports
 * in the resource files, to ensure that our list is complete.
 * <p>
 * This test should only fail when a new AgilityShortcut enum constant is added
 * without a corresponding entry in the TSV file.
 * <p>
 * There are some known exceptions where an AgilityShortcut cannot be matched to a TSV entry,
 * for example when the Object ID changes as the result of "unlocking" the shortcut via a quest.
 * These exceptions can be added to the {@link #createExcludedIds()} method. Use this sparingly.
 */
public class AgilityShortcutTest
{
	private static final Pattern OBJECT_ID_PATTERN = Pattern.compile("\\d+");

	/**
	 * IDs that are known exceptions and cannot be matched to TSV entries.
	 * These typically represent shortcuts that change based on quest completion or other game state.
	 */
	private static final Set<Integer> EXCLUDED_OBJECT_IDS = createExcludedIds();

	private static Set<Integer> createExcludedIds()
	{
		Set<Integer> excluded = new HashSet<>();

		// These two IDs represent the same shortcut before and after a step in the 'Making Friends with My Arm' quest
		// See: https://oldschool.runescape.wiki/w/Broken_fence_(Weiss)
		excluded.add(46815);
		excluded.add(46817);

		// somehow not found in tsv
		excluded.add(23644);

		// somehow not found in tsv
		excluded.add(11948);

		// Somehow not found in tsv
		excluded.add(23568);
		excluded.add(23569);

		// The rocks in the rock cab cave is not found because the coordinate is one off. but this is where you land
		excluded.add(31697);

		return excluded;
	}

	@Test
	public void everyEnumHasTsvEntry()
	{
		Map<Integer, Set<Transport>> allTransports = TransportLoader.loadAllFromResources();
		TransportData transportData = extractTransportData(allTransports);

		List<String> missingShortcuts = findMissingShortcuts(transportData);

		if (!missingShortcuts.isEmpty())
		{
			String errorMessage = String.join("\n", missingShortcuts);
			System.out.println("WARNING: Missing TSV entries for the following AgilityShortcut enum constants:\n" + errorMessage);
			// Non-breaking: only warn so the build does not fail when new shortcuts are added.
			// This keeps the test suite green while still surfacing the missing entries in stdout.
		}
	}

	/**
	 * Extracts coordinate and object ID data from all transports.
	 */
	private TransportData extractTransportData(Map<Integer, Set<Transport>> allTransports)
	{
		Set<String> coordinates = new HashSet<>();
		Set<Integer> objectIds = new HashSet<>();

		for (Set<Transport> transportSet : allTransports.values())
		{
			for (Transport transport : transportSet)
			{
				addCoordinatesFromTransport(transport, coordinates);
				addObjectIdsFromTransport(transport, objectIds);
			}
		}

		return new TransportData(coordinates, objectIds);
	}

	/**
	 * Adds origin and destination coordinates from a transport to the coordinate set.
	 */
	private void addCoordinatesFromTransport(Transport transport, Set<String> coordinates)
	{
		addCoordinateIfValid(transport.getOrigin(), coordinates);
		addCoordinateIfValid(transport.getDestination(), coordinates);
	}

	/**
	 * Adds a coordinate to the set if it's valid (not undefined or a permutation).
	 */
	private void addCoordinateIfValid(int packedCoordinate, Set<String> coordinates)
	{
		if (packedCoordinate != Transport.UNDEFINED_ORIGIN &&
			packedCoordinate != Transport.UNDEFINED_DESTINATION &&
			packedCoordinate != Transport.LOCATION_PERMUTATION)
		{
			String coordinate = formatCoordinate(packedCoordinate);
			coordinates.add(coordinate);
		}
	}

	/**
	 * Formats a packed coordinate as "x y plane".
	 */
	private String formatCoordinate(int packed)
	{
		int x = WorldPointUtil.unpackWorldX(packed);
		int y = WorldPointUtil.unpackWorldY(packed);
		int plane = WorldPointUtil.unpackWorldPlane(packed);
		return x + " " + y + " " + plane;
	}

	/**
	 * Extracts object IDs from the transport's object info string.
	 */
	private void addObjectIdsFromTransport(Transport transport, Set<Integer> objectIds)
	{
		String objectInfo = transport.getObjectInfo();
		if (objectInfo == null || objectInfo.isEmpty())
		{
			return;
		}

		Matcher matcher = OBJECT_ID_PATTERN.matcher(objectInfo);
		while (matcher.find())
		{
			try
			{
				objectIds.add(Integer.parseInt(matcher.group()));
			}
			catch (NumberFormatException ignored)
			{
				// Skip invalid numbers
			}
		}
	}

	/**
	 * Finds all AgilityShortcut enum constants that don't have matching TSV entries.
	 */
	private List<String> findMissingShortcuts(TransportData transportData)
	{
		List<String> missing = new ArrayList<>();

		for (AgilityShortcut shortcut : AgilityShortcut.values())
		{
			if (!isShortcutMatched(shortcut, transportData))
			{
				missing.add(shortcut.name() + " - " + shortcut.getLevel() + " - " + shortcut.getWorldLocation());
			}
		}

		return missing;
	}

	/**
	 * Checks if an AgilityShortcut matches any entry in the transport data.
	 */
	private boolean isShortcutMatched(AgilityShortcut shortcut, TransportData transportData)
	{
		// Check by world location
		if (isMatchedByLocation(shortcut, transportData.coordinates))
		{
			return true;
		}

		// Check by obstacle IDs
		return isMatchedByObstacleIds(shortcut, transportData.objectIds);
	}

	/**
	 * Checks if the shortcut's world location matches any coordinate in the transport data.
	 */
	private boolean isMatchedByLocation(AgilityShortcut shortcut, Set<String> coordinates)
	{
		if (shortcut.getWorldLocation() == null)
		{
			return false;
		}

		String coordinate = shortcut.getWorldLocation().getX() + " "
							+ shortcut.getWorldLocation().getY() + " "
							+ shortcut.getWorldLocation().getPlane();

		return coordinates.contains(coordinate);
	}

	/**
	 * Checks if any of the shortcut's obstacle IDs match object IDs in the transport data.
	 * Returns true if any non-excluded ID matches, or if all IDs are excluded.
	 */
	private boolean isMatchedByObstacleIds(AgilityShortcut shortcut, Set<Integer> objectIds)
	{
		if (shortcut.getObstacleIds() == null)
		{
			return false;
		}

		boolean hasExcludedId = false;
		for (int obstacleId : shortcut.getObstacleIds())
		{
			if (EXCLUDED_OBJECT_IDS.contains(obstacleId))
			{
				System.out.println("Skipping excluded ID " + obstacleId + " for " + shortcut.name());
				hasExcludedId = true;
				continue;
			}

			if (objectIds.contains(obstacleId))
			{
				return true;
			}
		}

		// If all IDs were excluded, consider it matched to avoid false failures
		return hasExcludedId;
	}

	/**
	 * Holds coordinate and object ID data extracted from transports.
	 */
	private static class TransportData
	{
		final Set<String> coordinates;
		final Set<Integer> objectIds;

		TransportData(Set<String> coordinates, Set<Integer> objectIds)
		{
			this.coordinates = coordinates;
			this.objectIds = objectIds;
		}
	}
}

package shortestpath;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Pattern;
import org.junit.Assert;
import org.junit.Test;

/**
 * Loader-fidelity and format lint for the four destination TSV resources
 * consumed by {@link Destination#loadAllFromResources()}.
 *
 * {@link Destination#addDestinations} degrades silently: a row whose
 * {@code Destination} cell is not a three-part {@code x y z} coordinate is
 * skipped with at most a {@code log.error}, and a dropped resource produces a
 * missing or empty category with no failure. These tests assert the loaded
 * map's category shape, that every committed row's {@code Destination} cell is
 * a concrete three-part numeric coordinate, that every such coordinate
 * actually lands in the loaded set, and that headers carry the documented
 * destination columns.
 */
public class DestinationDataLintTest
{
	/**
	 * The exact resource paths {@link Destination#loadAllFromResources()}
	 * loads, explicitly listed so a change to the consumed set is deliberate.
	 */
	private static final String[] DESTINATION_RESOURCES = {
		"/destinations/game_features/altar.tsv",
		"/destinations/game_features/bank.tsv",
		"/destinations/training/anvil.tsv",
		"/destinations/shopping/apothecary.tsv",
	};

	private static final Set<String> EXPECTED_CATEGORIES = new HashSet<>(Arrays.asList(
		"altar", "bank", "anvil", "apothecary"));

	/**
	 * Columns documented for destination TSVs: the coordinate cell plus the
	 * requirement/info columns {@link Destination} reads.
	 */
	private static final Set<String> DOCUMENTED_COLUMNS = new HashSet<>(Arrays.asList(
		"Destination", "Info", "Skills", "Quests", "Varbits", "VarPlayers"));

	private static final Pattern CONCRETE_POINT = Pattern.compile("^\\d+ \\d+ \\d+$");

	private static String readResource(String path) throws IOException
	{
		return new String(
			Util.readAllBytes(Objects.requireNonNull(ShortestPathPlugin.class.getResourceAsStream(path))),
			StandardCharsets.UTF_8);
	}

	/**
	 * The category key {@link Destination#addDestinations} derives from a
	 * resource path: the path component immediately preceding the file
	 * extension (e.g. {@code /destinations/game_features/bank.tsv -> bank}).
	 */
	private static String categoryKey(String path)
	{
		String[] parts = path.replace(".", "/").split("/");
		return parts[parts.length - 2];
	}

	private static String[] headers(String contents)
	{
		String headerLine = contents.split("\n", -1)[0];
		if (headerLine.endsWith("\r"))
		{
			headerLine = headerLine.substring(0, headerLine.length() - 1);
		}
		if (headerLine.startsWith("# "))
		{
			headerLine = headerLine.substring(2);
		}
		else if (headerLine.startsWith("#"))
		{
			headerLine = headerLine.substring(1);
		}
		return headerLine.split("\t");
	}

	private static int columnIndex(String[] headers, String name)
	{
		for (int i = 0; i < headers.length; i++)
		{
			if (name.equals(headers[i]))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Data rows of a destination file the way {@link Destination#addDestinations}
	 * sees them: lines after the header, comments and blanks skipped, split on
	 * tabs (trailing empty cells dropped, matching the loader's split).
	 */
	private static List<String[]> dataRows(String contents, List<Integer> lineNumbers)
	{
		String[] lines = contents.split("\n", -1);
		List<String[]> rows = new ArrayList<>();
		for (int i = 1; i < lines.length; i++)
		{
			String line = lines[i];
			if (line.endsWith("\r"))
			{
				line = line.substring(0, line.length() - 1);
			}
			if (line.startsWith("#") || line.isBlank())
			{
				continue;
			}
			rows.add(line.split("\t"));
			lineNumbers.add(i + 1);
		}
		return rows;
	}

	private static void report(List<String> failures, String checkName)
	{
		if (!failures.isEmpty())
		{
			StringBuilder message = new StringBuilder();
			message.append(String.format("%s found %d problem(s):\n", checkName, failures.size()));
			for (String failure : failures)
			{
				message.append("  ").append(failure).append('\n');
			}
			Assert.fail(message.toString());
		}
	}

	/**
	 * Loader fidelity: {@link Destination#loadAllFromResources()} must return
	 * exactly the four consumed categories, each non-empty, and every
	 * concrete {@code Destination} cell in every committed row must land in
	 * its category's set. A resource that fails to load or a row the loader
	 * silently skips shows up here as a missing/empty category or a missing
	 * packed point.
	 */
	@Test
	public void testLoadAllFromResourcesProducesEveryRow() throws IOException
	{
		List<String> failures = new ArrayList<>();

		Map<String, Set<Integer>> destinations = Destination.loadAllFromResources();
		Assert.assertEquals(
			"loadAllFromResources() categories differ from the consumed resource set",
			EXPECTED_CATEGORIES, destinations.keySet());

		for (String path : DESTINATION_RESOURCES)
		{
			String category = categoryKey(path);
			Set<Integer> loaded = destinations.get(category);
			if (loaded == null || loaded.isEmpty())
			{
				failures.add(String.format(
					"%s: category '%s' is missing or empty after loadAllFromResources()",
					path, category));
				continue;
			}

			String contents = readResource(path);
			String[] headers = headers(contents);
			int destinationIdx = columnIndex(headers, "Destination");
			if (destinationIdx < 0)
			{
				failures.add(path + ": header carries no Destination column");
				continue;
			}

			List<Integer> lineNumbers = new ArrayList<>();
			List<String[]> rows = dataRows(contents, lineNumbers);
			for (int i = 0; i < rows.size(); i++)
			{
				String cell = destinationIdx < rows.get(i).length ? rows.get(i)[destinationIdx] : "";
				if (!CONCRETE_POINT.matcher(cell).matches())
				{
					// Malformed cells are reported by
					// testDestinationCellsAreThreePartNumeric; skip them here.
					continue;
				}
				String[] parts = cell.split(" ");
				int packed = WorldPointUtil.packWorldPoint(
					Integer.parseInt(parts[0]),
					Integer.parseInt(parts[1]),
					Integer.parseInt(parts[2]));
				if (!loaded.contains(packed))
				{
					failures.add(String.format(
						"%s:%d: concrete destination '%s' is absent from the loaded '%s' set",
						path, lineNumbers.get(i), cell, category));
				}
			}
		}

		report(failures, "testLoadAllFromResourcesProducesEveryRow");
	}

	/**
	 * Row-shape fidelity: every non-comment row's {@code Destination} cell
	 * must be a three-part numeric {@code x y z} coordinate. The loader
	 * log-and-skips malformed cells, so a bad row is a test failure naming
	 * file+line rather than a silently dropped destination.
	 */
	@Test
	public void testDestinationCellsAreThreePartNumeric() throws IOException
	{
		List<String> failures = new ArrayList<>();

		for (String path : DESTINATION_RESOURCES)
		{
			String contents = readResource(path);
			String[] headers = headers(contents);
			int destinationIdx = columnIndex(headers, "Destination");
			if (destinationIdx < 0)
			{
				failures.add(path + ": header carries no Destination column");
				continue;
			}

			List<Integer> lineNumbers = new ArrayList<>();
			List<String[]> rows = dataRows(contents, lineNumbers);
			for (int i = 0; i < rows.size(); i++)
			{
				String cell = destinationIdx < rows.get(i).length ? rows.get(i)[destinationIdx] : "";
				if (!CONCRETE_POINT.matcher(cell).matches())
				{
					failures.add(String.format(
						"%s:%d: Destination cell '%s' is not a three-part numeric coordinate",
						path, lineNumbers.get(i), cell));
				}
			}
		}

		report(failures, "testDestinationCellsAreThreePartNumeric");
	}

	/**
	 * Header coverage: each file's header row must carry the {@code
	 * Destination} column and use only documented destination columns.
	 */
	@Test
	public void testHeadersCarryDestinationColumn() throws IOException
	{
		List<String> failures = new ArrayList<>();

		for (String path : DESTINATION_RESOURCES)
		{
			String[] headers = headers(readResource(path));
			boolean hasDestination = false;
			for (String header : headers)
			{
				if ("Destination".equals(header))
				{
					hasDestination = true;
				}
				else if (!DOCUMENTED_COLUMNS.contains(header))
				{
					failures.add(String.format(
						"%s: header cell '%s' is not a documented destination column",
						path, header));
				}
			}
			if (!hasDestination)
			{
				failures.add(path + ": header carries no Destination column");
			}
		}

		report(failures, "testHeadersCarryDestinationColumn");
	}
}

package shortestpath;

import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportLoader;
import shortestpath.transport.TransportType;
import shortestpath.transport.requirement.TransportItems;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Unit tests for the Observatory Grapple Shortcut transport.
 * Tests the transport at coordinates 2449 3155 0 to 2444 3165 0 with requirements:
 * - 23 Agility
 * - CROSSBOW=1
 * - MITH_GRAPPLE=1
 * - Observatory Quest
 */
public class ObservatoryGrappleShortcutTest
{

	private Map<Integer, Set<Transport>> transports;
	private static final String TRANSPORT_DATA =
		"# Origin\tDestination\tmenuOption menuTarget objectID\tSkills\tItems\tVarbits\tVarPlayers\tDuration\tQuests\n" +
		"2449 3155 0\t2444 3165 0\tGrapple Rocks 31850\t23 Agility\tCROSSBOW=1&MITH_GRAPPLE=1\t\t\t\tObservatory Quest\n";

	@Before
	public void setUp()
	{
		transports = new HashMap<>();
		TransportLoader.addTransportsFromContents(transports, TRANSPORT_DATA, TransportType.GRAPPLE_SHORTCUT, 0);
	}

	private Transport getTransport()
	{
		int origin = WorldPointUtil.packWorldPoint(2449, 3155, 0);
		Set<Transport> transportSet = transports.get(origin);
		Assert.assertNotNull("Transport set should exist for origin", transportSet);
		Assert.assertEquals("Should have exactly one transport", 1, transportSet.size());
		return transportSet.iterator().next();
	}

	/**
	 * Scenario 1: Verify that the transport has the correct 23 Agility requirement
	 */
	@Test
	public void testHasAgilityRequirement()
	{
		Transport transport = getTransport();

		int agilityLevel = transport.getSkillLevels()[Skill.AGILITY.ordinal()];
		Assert.assertEquals("Transport should require 23 Agility", 23, agilityLevel);
	}

	/**
	 * Scenario 2: Verify that the transport requires a crossbow item
	 */
	@Test
	public void testHasCrossbowRequirement()
	{
		Transport transport = getTransport();

		TransportItems items = transport.getItemRequirements();
		Assert.assertNotNull("Transport should have item requirements", items);

		int[][] requiredItems = items.getItems();
		int[] quantities = items.getQuantities();

		Assert.assertEquals("Should have two item requirements (CROSSBOW and MITH_GRAPPLE)", 2, requiredItems.length);

		// Find the crossbow requirement
		boolean foundCrossbow = false;
		for (int i = 0; i < requiredItems.length; i++)
		{
			int[] itemGroup = requiredItems[i];
			// Check if this group contains any crossbow variant
			// The CROSSBOW ItemVariation should expand to multiple crossbow types
			if (itemGroup.length > 1)
			{
				// Crossbows have multiple variants
				foundCrossbow = true;
				Assert.assertEquals("Crossbow quantity should be 1", 1, quantities[i]);
				break;
			}
		}

		Assert.assertTrue("Transport should require a crossbow", foundCrossbow);
	}

	/**
	 * Scenario 3: Verify that the transport requires a mithril grapple item
	 */
	@Test
	public void testHasMithrilGrappleRequirement()
	{
		Transport transport = getTransport();

		TransportItems items = transport.getItemRequirements();
		Assert.assertNotNull("Transport should have item requirements", items);

		int[][] requiredItems = items.getItems();
		int[] quantities = items.getQuantities();

		Assert.assertEquals("Should have two item requirements (CROSSBOW and MITH_GRAPPLE)", 2, requiredItems.length);

		// Find the mithril grapple requirement
		boolean foundMithGrapple = false;
		for (int i = 0; i < requiredItems.length; i++)
		{
			int[] itemGroup = requiredItems[i];
			// MITH_GRAPPLE should be a single item (ItemID.XBOWS_GRAPPLE_TIP_BOLT_MITHRIL_ROPE)
			if (itemGroup.length == 1)
			{
				foundMithGrapple = true;
				Assert.assertEquals("Mithril grapple quantity should be 1", 1, quantities[i]);
				break;
			}
		}

		Assert.assertTrue("Transport should require a mithril grapple", foundMithGrapple);
	}

	/**
	 * Scenario 4: Verify that the transport requires Observatory Quest completion
	 */
	@Test
	public void testHasObservatoryQuestRequirement()
	{
		Transport transport = getTransport();

		Set<Quest> quests = transport.getQuests();
		Assert.assertNotNull("Transport should have quest requirements", quests);
		Assert.assertEquals("Should have exactly one quest requirement", 1, quests.size());
		Assert.assertTrue("Should require Observatory Quest", quests.contains(Quest.OBSERVATORY_QUEST));
		Assert.assertTrue("Transport should be quest locked", transport.isQuestLocked());
	}

	/**
	 * Scenario 5: Verify that other skill levels are not required (should be 0)
	 */
	@Test
	public void testNoOtherSkillRequirements()
	{
		Transport transport = getTransport();

		int[] skillLevels = transport.getSkillLevels();

		// Check all skills except Agility should be 0
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.AGILITY)
			{
				int level = skillLevels[skill.ordinal()];
				Assert.assertEquals("Skill " + skill.getName() + " should not be required", 0, level);
			}
		}

		// Check total level, combat level, and quest points (last 3 indices)
		int totalLevelIndex = Skill.values().length;
		Assert.assertEquals("Total level should not be required", 0, skillLevels[totalLevelIndex]);
		Assert.assertEquals("Combat level should not be required", 0, skillLevels[totalLevelIndex + 1]);
		Assert.assertEquals("Quest points should not be required", 0, skillLevels[totalLevelIndex + 2]);
	}

	/**
	 * Scenario 6: Verify the transport has correct origin and destination coordinates
	 */
	@Test
	public void testTransportCoordinates()
	{
		Transport transport = getTransport();

		int expectedOrigin = WorldPointUtil.packWorldPoint(2449, 3155, 0);
		int expectedDestination = WorldPointUtil.packWorldPoint(2444, 3165, 0);

		Assert.assertEquals("Origin should be 2449 3155 0", expectedOrigin, transport.getOrigin());
		Assert.assertEquals("Destination should be 2444 3165 0", expectedDestination, transport.getDestination());

		// Verify unpacked coordinates
		Assert.assertEquals("Origin X should be 2449", 2449, WorldPointUtil.unpackWorldX(transport.getOrigin()));
		Assert.assertEquals("Origin Y should be 3155", 3155, WorldPointUtil.unpackWorldY(transport.getOrigin()));
		Assert.assertEquals("Origin plane should be 0", 0, WorldPointUtil.unpackWorldPlane(transport.getOrigin()));

		Assert.assertEquals("Destination X should be 2444", 2444, WorldPointUtil.unpackWorldX(transport.getDestination()));
		Assert.assertEquals("Destination Y should be 3165", 3165, WorldPointUtil.unpackWorldY(transport.getDestination()));
		Assert.assertEquals("Destination plane should be 0", 0, WorldPointUtil.unpackWorldPlane(transport.getDestination()));
	}

	/**
	 * Bonus Scenario: Verify the transport has correct object information
	 */
	@Test
	public void testObjectInformation()
	{
		Transport transport = getTransport();

		String objectInfo = transport.getObjectInfo();
		Assert.assertNotNull("Transport should have object info", objectInfo);
		Assert.assertEquals("Object info should match", "Grapple Rocks 31850", objectInfo);
	}

	/**
	 * Bonus Scenario: Verify the transport type is GRAPPLE_SHORTCUT
	 */
	@Test
	public void testTransportType()
