		// Menu covers only Etceteria; Port Sarim is unvisited in the snapshot.
		state.applyMenuSnapshot(Set.of("Etceteria"), Set.of("Etceteria"));

		assertEquals(Set.of("Port Sarim", "Etceteria"), state.getTravelableTrees());
	}

