package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import org.junit.BeforeClass;
import org.junit.Test;
import shortestpath.ShortestPathConfig;
import shortestpath.TeleportationItem;
import shortestpath.WorldPointUtil;
import shortestpath.leagues.LeagueRegion;
import shortestpath.pathfinder.exact.RoutingStatic;

/**
 * Exact honours {@code avoidWilderness} and the league's always-blocked region like legacy:
 * nothing may enter the gated area on foot, and a global teleport cast outside the wilderness
 * cannot land inside. The same exemptions apply in both backends: starting inside the gated area
 * may still leave it, and a target inside it lifts the gate entirely.
 */
public class ExactAvoidWildernessParityTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3210, 3424, 0);
	/** A safe pocket surrounded by wilderness: on foot it can only be entered through it. */
	private static final int FEROX_ENCLAVE = WorldPointUtil.packWorldPoint(3141, 3630, 0);
	private static final int CHAOS_TEMPLE = WorldPointUtil.packWorldPoint(3231, 3608, 0);
	/** Level-27 wilderness (benchmark early/quest-natural-0006's start). */
	private static final int START_WILDERNESS = WorldPointUtil.packWorldPoint(3051, 3736, 0);
	/** Asgarnia, away from the league's always-blocked Misthalin. */
	private static final int FALADOR = WorldPointUtil.packWorldPoint(2965, 3337, 0);
	/** Deep desert camp: from Falador unreachable without crossing Misthalin or a desert
	 *  transport with item requirements a bare inventory cannot meet. */
	private static final int BEDABIN = WorldPointUtil.packWorldPoint(3181, 3135, 0);
	/** Desert border town: unlocked even while Misthalin is, so transports there stay usable. */
	private static final int AL_KHARID = WorldPointUtil.packWorldPoint(3292, 3184, 0);

	private static RoutingStatic routingStatic;

	@BeforeClass
	public static void buildRoutingStatic()
	{
		routingStatic = new ExactRoutingStaticProvider(
			() -> new CollisionMap(SplitFlagMap.fromResources())).get();
	}

	@Test
	public void wildernessCannotBeEnteredOnFootWhileAvoidingIt()
	{
		// Every walking route to Ferox crosses the wilderness; with no teleports enabled both
		// backends must give up.
		PathfinderConfig config = config(true, false);
		PathfinderResult legacy = legacy(config, LUMBRIDGE, FEROX_ENCLAVE);
		ExactPathfinder exact = exact(config, LUMBRIDGE, FEROX_ENCLAVE);
		assertFalse("legacy reached Ferox without entering the wilderness", legacy.isReached());
		assertFalse("exact entered the wilderness while avoiding it", exact.getResult().isReached());

		// Without the gate the same search walks straight through, and pays the same as legacy.
		config = config(false, false);
		legacy = legacy(config, LUMBRIDGE, FEROX_ENCLAVE);
		exact = exact(config, LUMBRIDGE, FEROX_ENCLAVE);
		assertTrue(legacy.isReached());
		assertTrue(exact.getResult().isReached());
		assertEquals(legacy.getPathCost(), exact.getResult().getPathCost());

		// The route crosses the Wilderness Ditch by transport; the landing step must report
		// which transport produced it, not just the tile it landed on.
		assertTrue("the ditch hop does not report its transport",
			exact.getResult().getPathSteps().stream().anyMatch(
				s -> s.getTransport() != null && s.getTransport().getDestination() == s.getPackedPosition()));
	}

	@Test
	public void wildernessTargetLiftsTheGateLikeLegacy()
	{
		// A target inside the wilderness exempts the search: entering it is the point.
		PathfinderConfig config = config(true, true);
		PathfinderResult legacy = legacy(config, LUMBRIDGE, CHAOS_TEMPLE);
		ExactPathfinder exact = exact(config, LUMBRIDGE, CHAOS_TEMPLE);
		assertTrue(legacy.isReached());
		assertTrue(exact.getResult().isReached());
		assertEquals(legacy.getPathCost(), exact.getResult().getPathCost());
	}

	@Test
	public void startingInWildernessMayLeaveWhileAvoidingIt()
	{
		// The gate only bars entering the wilderness, not walking out of it.
		PathfinderConfig config = config(true, true);
		PathfinderResult legacy = legacy(config, START_WILDERNESS, LUMBRIDGE);
		ExactPathfinder exact = exact(config, START_WILDERNESS, LUMBRIDGE);
		assertTrue(legacy.isReached());
		assertTrue(exact.getResult().isReached());
		assertEquals(legacy.getPathCost(), exact.getResult().getPathCost());
	}

	@Test
	public void ordinaryRoutesNeverTouchTheWildernessWhileAvoidingIt()
	{
		PathfinderConfig config = config(true, true);
		PathfinderResult legacy = legacy(config, LUMBRIDGE, VARROCK);
		ExactPathfinder exact = exact(config, LUMBRIDGE, VARROCK);
		assertTrue(legacy.isReached());
		assertTrue(exact.getResult().isReached());
		for (PathStep step : exact.getPath())
		{
			assertFalse("route enters the wilderness", WildernessChecker.isInWilderness(step.getPackedPosition()));
		}
		assertEquals(legacy.getPathCost(), exact.getResult().getPathCost());
	}

	@Test
	public void leagueBlockedRegionIsGatedLikeLegacy()
	{
		// Falador to the Bedabin camp cannot be routed while Misthalin is the always-blocked
		// region: the walk crosses Misthalin and the desert transports need items this account
		// does not carry, so both backends must give up.
		PathfinderConfig config = config(false, false);
		config.getLeagueModeState().setForTest(true, EnumSet.complementOf(EnumSet.of(LeagueRegion.MISTHALIN)));
		PathfinderResult legacy = legacy(config, FALADOR, BEDABIN);
		ExactPathfinder exact = exact(config, FALADOR, BEDABIN);
		assertFalse("legacy walked into the blocked region", legacy.isReached());
		assertFalse("exact entered the blocked region", exact.getResult().isReached());

		// Transports landing in an unlocked region are unaffected: Lumbridge to Al Kharid
		// crosses the Misthalin/desert gate inside Misthalin-free destination tiles.
		legacy = legacy(config, LUMBRIDGE, AL_KHARID);
		exact = exact(config, LUMBRIDGE, AL_KHARID);
		assertTrue(legacy.isReached());
		assertTrue(exact.getResult().isReached());
		assertEquals(legacy.getPathCost(), exact.getResult().getPathCost());

		// A target inside the blocked region lifts the gate, as in legacy.
		legacy = legacy(config, FALADOR, LUMBRIDGE);
		exact = exact(config, FALADOR, LUMBRIDGE);
		assertTrue(legacy.isReached());
		assertTrue(exact.getResult().isReached());
		assertEquals(legacy.getPathCost(), exact.getResult().getPathCost());
	}

	private static PathfinderResult legacy(PathfinderConfig config, int start, int target)
	{
		Pathfinder pathfinder = new Pathfinder(config, start, Set.of(target));
		pathfinder.run();
		return pathfinder.getResult();
	}

	private static ExactPathfinder exact(PathfinderConfig config, int start, int target)
	{
		ExactPathfinder pathfinder = new ExactPathfinder(config, routingStatic, null, start,
			Set.of(target), null, 1);
		pathfinder.run();
		return pathfinder;
	}

	/** A maxed account with no items and, optionally, wilderness obelisks and minigame teleports. */
	private static PathfinderConfig config(boolean avoidWilderness, boolean teleports)
	{
		Client client = mock(Client.class);
		ShortestPathConfig settings = mock(ShortestPathConfig.class);
		ItemContainer empty = mock(ItemContainer.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doReturn(new Item[0]).when(empty).getItems();
		doReturn(empty).when(client).getItemContainer(InventoryID.INV);
		doReturn(empty).when(client).getItemContainer(InventoryID.WORN);
		when(settings.calculationCutoff()).thenReturn(500);
		when(settings.currencyThreshold()).thenReturn(10000000);
		when(settings.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(settings.avoidWilderness()).thenReturn(avoidWilderness);
		when(settings.useWildernessObelisks()).thenReturn(teleports);
		when(settings.useTeleportationMinigames()).thenReturn(teleports);

		PathfinderConfig config = new TestPathfinderConfig(client, settings, QuestState.FINISHED, true, true);
		config.refresh();
		return config;
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import org.junit.BeforeClass;
import org.junit.Test;
import shortestpath.ShortestPathConfig;
import shortestpath.TeleportationItem;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.exact.ExactRoutingSession;
import shortestpath.pathfinder.exact.PreparedRoutingAccount;
import shortestpath.pathfinder.exact.RoutingStatic;

/**
 * Exact must bank only where {@link PathfinderConfig#bankAccessible(int)} allows, like legacy.
 *
 * <p>The Farming Guild bank needs 85 Farming (bank.tsv); nothing else in the data is gated at 85
 * Farming, so 84 and 85 differ only in whether that bank is usable. The only teleport is a banked
 * camulet, so a route that banks at the guild is cheaper than one that walks to another bank.
 */
public class ExactBankAccessParityTest
{
	private static final int FARMING_GUILD_BANK = WorldPointUtil.packWorldPoint(1248, 3758, 0);
	private static final int START = WorldPointUtil.packWorldPoint(1249, 3752, 0);
	private static final int ENAKHRAS_TEMPLE = WorldPointUtil.packWorldPoint(3105, 9315, 0);
	private static final int BANK_VISIT_COST = 5;

	private static RoutingStatic routingStatic;

	@BeforeClass
	public static void buildRoutingStatic()
	{
		routingStatic = new ExactRoutingStaticProvider(
			() -> new CollisionMap(SplitFlagMap.fromResources())).get();
	}

	@Test
	public void preparedAccountsShareStaticBanksButDifferInAccess()
	{
		PreparedRoutingAccount without = config(84).prepareExactRoutingAccount(true);
		PreparedRoutingAccount with = config(85).prepareExactRoutingAccount(true);

		assertTrue("the static data knows the bank", isStaticBank(FARMING_GUILD_BANK));
		assertFalse(without.bankAccessible(FARMING_GUILD_BANK));
		assertTrue(with.bankAccessible(FARMING_GUILD_BANK));
		assertNotEquals("bank access is part of the account identity", without.fingerprint(), with.fingerprint());
	}

	@Test
	public void inaccessibleBankIsNotUsedAndMatchesLegacy()
	{
		PathfinderConfig config = config(84);
		assertFalse(config.bankAccessible(FARMING_GUILD_BANK));

		PathfinderResult legacy = legacy(config);
		ExactPathfinder exact = exact(config, null);

		assertTrue(legacy.isReached());
		assertTrue(exact.getResult().isReached());
		assertFalse("exact banked at the Farming Guild without 85 Farming", banksAt(exact.getPath(), FARMING_GUILD_BANK));
		assertEquals(legacy.getPathCost(), exact.getResult().getPathCost());
	}

	@Test
	public void accessibleBankIsUsedAndMatchesLegacy()
	{
		PathfinderConfig config = config(85);
		assertTrue(config.bankAccessible(FARMING_GUILD_BANK));

		PathfinderResult legacy = legacy(config);
		ExactPathfinder exact = exact(config, null);

		assertTrue(legacy.isReached());
		assertTrue(exact.getResult().isReached());
		assertTrue("exact should bank at the Farming Guild", banksAt(exact.getPath(), FARMING_GUILD_BANK));
		assertEquals(legacy.getPathCost(), exact.getResult().getPathCost());
		assertTrue("banking at the guild should be cheaper than walking to another bank",
			exact.getResult().getPathCost() < exact(config(84), null).getResult().getPathCost());
	}

	@Test
	public void bankVisitCostIsChargedLikeLegacy()
	{
		for (int farmingLevel : new int[] {84, 85})
		{
			PathfinderConfig free = config(farmingLevel, 0);
			PathfinderConfig costed = config(farmingLevel, BANK_VISIT_COST);
			PathfinderResult legacy = legacy(costed);
			ExactPathfinder exact = exact(costed, null);

			assertTrue(exact.getResult().isReached());
			assertEquals("Farming " + farmingLevel, legacy.getPathCost(), exact.getResult().getPathCost());
			assertTrue(exact.getPath().stream().anyMatch(PathStep::isBankVisited));
			assertEquals("the route still banks, so it pays the visit once",
				exact(free, null).getResult().getPathCost() + BANK_VISIT_COST, exact.getResult().getPathCost());
		}
	}

	@Test
	public void sessionDoesNotReuseStaleBankAccess()
	{
		ExactRoutingSession session = new ExactRoutingSession();
		int withCost = exact(config(85), session).getResult().getPathCost();

		ExactPathfinder without = exact(config(84), session);
		assertFalse("the account graph must be rebuilt when bank access changes", without.isGraphReused());
		assertFalse(banksAt(without.getPath(), FARMING_GUILD_BANK));
		assertEquals(legacy(config(84)).getPathCost(), without.getResult().getPathCost());

		ExactPathfinder with = exact(config(85), session);
		assertFalse(with.isGraphReused());
		assertEquals(withCost, with.getResult().getPathCost());
		assertTrue(exact(config(85), session).isGraphReused());

		ExactPathfinder costed = exact(config(85, BANK_VISIT_COST), session);
		assertFalse("the account graph must be rebuilt when the bank visit cost changes", costed.isGraphReused());
		assertEquals(withCost + BANK_VISIT_COST, costed.getResult().getPathCost());
	}

	private static boolean isStaticBank(int tile)
	{
		for (int i = 0; i < routingStatic.reachableBankCount(); i++)
			if (routingStatic.reachableBankTile(i) == tile) return true;
		return false;
	}

	private static boolean banksAt(List<PathStep> path, int tile)
	{
		for (int i = 1; i < path.size(); i++)
		{
			if (!path.get(i - 1).isBankVisited() && path.get(i).isBankVisited())
				return path.get(i - 1).getPackedPosition() == tile || path.get(i).getPackedPosition() == tile;
		}
		return false;
	}

	private static PathfinderResult legacy(PathfinderConfig config)
	{
		Pathfinder pathfinder = new Pathfinder(config, START, Set.of(ENAKHRAS_TEMPLE));
		pathfinder.run();
		return pathfinder.getResult();
	}

	private static ExactPathfinder exact(PathfinderConfig config, ExactRoutingSession session)
	{
		ExactPathfinder pathfinder = new ExactPathfinder(config, routingStatic, session, START,
			Set.of(ENAKHRAS_TEMPLE), null, 1);
		pathfinder.run();
		return pathfinder;
	}

	private static PathfinderConfig config(int farmingLevel)
	{
		return config(farmingLevel, 0);
	}

	/** A logged-in account with 99 in every skill except Farming and a camulet in the bank. */
	private static PathfinderConfig config(int farmingLevel, int bankVisitCost)
	{
		Client client = mock(Client.class);
		ShortestPathConfig settings = mock(ShortestPathConfig.class);
		ItemContainer empty = mock(ItemContainer.class);
		ItemContainer bank = mock(ItemContainer.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		when(client.getBoostedSkillLevel(Skill.FARMING)).thenReturn(farmingLevel);
		doReturn(new Item[0]).when(empty).getItems();
		doReturn(empty).when(client).getItemContainer(InventoryID.INV);
		doReturn(empty).when(client).getItemContainer(InventoryID.WORN);
		doReturn(new Item[] {new Item(ItemID.CAMULET, 1)}).when(bank).getItems();
		when(settings.calculationCutoff()).thenReturn(500);
		when(settings.currencyThreshold()).thenReturn(10000000);
		when(settings.useTeleportationItems()).thenReturn(TeleportationItem.INVENTORY_AND_BANK);
		when(settings.costBankVisit()).thenReturn(bankVisitCost);

		PathfinderConfig config = new TestPathfinderConfig(client, settings, QuestState.FINISHED, true, true);
		config.bank = bank;
		config.refresh();
		return config;
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import java.util.function.BooleanSupplier;
import org.junit.Test;
import shortestpath.pathfinder.exact.ExactCosts;
import shortestpath.pathfinder.exact.ExactForwardSearch;
import shortestpath.pathfinder.exact.PreparedHeuristic;
import shortestpath.pathfinder.exact.PreparedRoutingAccount;
import shortestpath.pathfinder.exact.ReverseLabels;
import shortestpath.pathfinder.exact.RoutingStatic;
import shortestpath.pathfinder.exact.RoutingStaticTestFixture;
import shortestpath.pathfinder.exact.SiteGraph;
import shortestpath.pathfinder.exact.TargetOverlay;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

public class ExactForwardSearchTest
{
	@Test
	public void walksLocallyAndKeepsTheTerminalState()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT4Walking();
		PreparedRoutingAccount account = account();
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.C, neighbours());

		ExactForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertFalse(result.cancelled());
		assertEquals(2, result.cost());
		assertTrue((result.terminalState() & 1) == 0);
		assertTrue(result.counters().walkingRelaxations() > 0);
	}

	@Test
	public void usesThePostBankLayerAndLocalTransport()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(null,
			local(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.D, 1), true);
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D,
			neighbours(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK));

		ExactForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertEquals(2, result.cost());
		assertTrue((result.terminalState() & 1) != 0);
		assertTrue(result.counters().transportRelaxations() > 0);
	}

	@Test
	public void entersABlockedLocalTransportOrigin()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(local(RoutingStaticTestFixture.BANK,
			RoutingStaticTestFixture.D, 1));
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D, neighbours(),
			RoutingStaticTestFixture.BANK);

		ExactForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertEquals(2, result.cost());
	}

	@Test
	public void staleEntriesAndUnreachableHeuristicPrunesAreSafe()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(
			local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.C, 5),
			local(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.C, 1));
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D,
			neighbours(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK,
				RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.C));

		ExactForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertFalse(result.reached());
		assertEquals(ExactCosts.INF, result.cost());
		assertTrue(result.counters().staleEntries() > 0);
	}

	@Test
	public void cancellationDoesNotPublishACompletedRoute()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account();
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D,
			neighbours(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK));
		BooleanSupplier cancelled = () -> true;

		ExactForwardSearch.Result result = ExactForwardSearch.search(target,
			PreparedHeuristic.prepare(target, ReverseLabels.compute(target)), RoutingStaticTestFixture.A, cancelled);

		assertTrue(result.cancelled());
		assertFalse(result.reached());
		assertEquals(ExactCosts.INF, result.cost());
	}

	private static ExactForwardSearch.Result search(TargetOverlay target, int start)
	{
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(target, ReverseLabels.compute(target));
		return ExactForwardSearch.search(target, heuristic, start);
	}

	private static TargetOverlay target(RoutingStatic stat, PreparedRoutingAccount account, int target,
		Map<Integer, int[]> neighbours)
	{
		return target(stat, account, target, neighbours, -1);
	}

	private static TargetOverlay target(RoutingStatic stat, PreparedRoutingAccount account, int target,
		Map<Integer, int[]> neighbours, int blocked)
	{
		SiteGraph graph = new SiteGraph(stat, account);
		return new TargetOverlay(graph, collision(neighbours, blocked), target);
	}

	private static CollisionMap collision(Map<Integer, int[]> neighbours)
	{
		return collision(neighbours, -1);
	}

	private static CollisionMap collision(Map<Integer, int[]> neighbours, int blocked)
	{
		return new CollisionMap(null)
		{
			@Override
			public int[] ordinaryWalkingNeighbors(int packedPoint)
			{
				int[] values = neighbours.get(packedPoint);
				return values == null ? new int[0] : values.clone();
			}

			@Override
			public boolean isBlocked(int x, int y, int z)
			{
				return shortestpath.WorldPointUtil.packWorldPoint(x, y, z) == blocked;
			}
		};
	}

	private static Map<Integer, int[]> neighbours(int... values)
	{
		Map<Integer, int[]> result = new HashMap<>();
		for (int i = 0; i < values.length; i += 2)
			result.put(values[i], new int[] {values[i + 1]});
		return result;
	}

	private static PreparedRoutingAccount account(Transport... carried)
	{
		return account(carried, new Transport[0], false);
	}

	private static PreparedRoutingAccount account(Transport carried, Transport banked, boolean bankPath)
	{
		return account(carried == null ? new Transport[0] : new Transport[] {carried},
			banked == null ? new Transport[0] : new Transport[] {banked}, bankPath);
	}

	private static PreparedRoutingAccount account(Transport[] carried, Transport[] banked, boolean bankPath)
	{
		return PreparedRoutingAccount.compile(availability(carried), availability(banked), bankPath,
			java.util.Set.of(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.T3_B), 0, true, ignored -> 0);
	}

	private static TransportAvailability availability(Transport[] transports)
	{
		TransportAvailability.Builder builder = new TransportAvailability.Builder(transports.length);
		for (Transport transport : transports)
			builder.add(transport);
		return builder.build();
	}

	private static Transport local(int origin, int destination, int duration)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(duration).build();
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.BeforeClass;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.Destination;
import shortestpath.ShortestPathConfig;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.exact.RoutingCuts;
import shortestpath.pathfinder.exact.RoutingStatic;
import shortestpath.pathfinder.exact.RoutingStaticBuilder;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportLoader;

/**
 * Issue #640 coverage for the exact backend: it terminates on the goal set
 * {@link TargetGoals} resolves from the requested targets, so a blocked target
 * ends the search on a walkable fallback tile on the target's side of any
 * wall instead of exhausting the map.
 */
@RunWith(MockitoJUnitRunner.class)
public class ExactPathfinderBlockedTargetTest
{
	private static RoutingStatic routingStatic;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;
	private PathfinderConfig pathfinderConfig;

	@BeforeClass
	public static void buildRoutingStatic() throws Exception
	{
		CollisionMap collision = new CollisionMap(SplitFlagMap.fromResources());
		Map<Integer, Set<Transport>> transports = TransportLoader.loadAllFromResources();
		Set<Integer> banks = Destination.loadAllFromResources().get("bank");
		routingStatic = RoutingStaticBuilder.build(collision, transports,
			banks == null ? Set.of() : banks, RoutingCuts.loadFromResources().pairs()).routingStatic;
	}

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.collisionAwareBlockedTargets()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private void setup(int unreachableDistance)
	{
		when(config.unreachableTargetDistance()).thenReturn(unreachableDistance);
		pathfinderConfig = new TestPathfinderConfig(client, config, net.runelite.api.QuestState.FINISHED, true, true);
		pathfinderConfig.refresh();
	}

	private ExactPathfinder search(int start, Set<Integer> targets)
	{
		ExactPathfinder pathfinder = new ExactPathfinder(pathfinderConfig, routingStatic,
			start, targets, null);
		pathfinder.run();
		return pathfinder;
	}

	// The same connectivity oracle PathfinderTest uses: every tile walk-connected
	// to the target within the radius, regardless of walls or footprints.
	private static Set<Integer> connectedTilesOracle(CollisionMap map, int target, int radius)
	{
		Set<Integer> connected = new HashSet<>();
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		connected.add(target);
		queue.add(target);
		while (!queue.isEmpty())
		{
			int current = queue.poll();
			for (int neighbour : map.ordinaryWalkingNeighbors(current))
			{
				if (connected.contains(neighbour)
					|| WorldPointUtil.distanceBetween(target, neighbour) > radius)
				{
					continue;
				}
				connected.add(neighbour);
				queue.add(neighbour);
			}
		}
		connected.remove(target);
		return connected;
	}

	private static int end(PathfinderResult result)
	{
		List<PathStep> steps = result.getPathSteps();
		return steps.get(steps.size() - 1).getPackedPosition();
	}

	@Test
	public void blockedTargetExpandsToWalkableNeighbours()
	{
		setup(2);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3222, 3218, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(3203, 3178, 0);
		assertTrue("test requires a blocked target tile", map.isBlocked(3203, 3178, 0));

		ExactPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue("expected a fallback tile near the blocked target", result.isReached());
		assertEquals(PathTerminationReason.TARGET_REACHED, result.getTerminationReason());
		int end = end(result);
		assertFalse("path must end on a walkable tile", map.isBlocked(
			WorldPointUtil.unpackWorldX(end), WorldPointUtil.unpackWorldY(end),
			WorldPointUtil.unpackWorldPlane(end)));
		assertTrue("path must end within the unreachable distance",
			WorldPointUtil.distanceBetween(end, blockedTarget) <= 2);
	}

	@Test
	public void fullyBlockedTargetShortCircuitsSearch()
	{
		// (2114, 5506) sits inside a fully blocked 5x5: no walkable tile within
		// the unreachable distance and no transport lands on it, so the exact
		// search must skip the map walk exactly like the legacy one.
		setup(2);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3222, 3218, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(2114, 5506, 0);
		assertTrue("test requires a blocked target tile", map.isBlocked(2114, 5506, 0));
		assertFalse("test requires that no transport lands on the target",
			pathfinderConfig.isTransportDestination(blockedTarget));

		ExactPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertFalse(result.isReached());
		assertEquals(PathTerminationReason.SEARCH_EXHAUSTED, result.getTerminationReason());
		assertEquals("a hopeless target must not explore any tile", 0, result.getNodesChecked());
	}

	@Test
	public void blockedTargetDoesNotSuppressOtherTargets()
	{
		setup(2);
		int start = WorldPointUtil.packWorldPoint(3222, 3218, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(2114, 5506, 0);
		int reachableTarget = WorldPointUtil.packWorldPoint(3213, 3428, 0);

		ExactPathfinder pathfinder = search(start, Set.of(blockedTarget, reachableTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue("the viable target should still be reached", result.isReached());
		assertEquals(PathTerminationReason.TARGET_REACHED, result.getTerminationReason());
		assertEquals(reachableTarget, end(result));
	}

	@Test
	public void blockedTargetExpansionStaysOnTargetSideOfWalls()
	{
		// Same Varrock wall fixture as the legacy test: (3258, 3351) is a blocked
		// wall segment whose expansion square covers walkable tiles on the far
		// side of the wall; the path must end on the target's connected side.
		final int radius = 6;
		setup(radius);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3258, 3341, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(3258, 3351, 0);
		assertTrue("test requires a blocked target tile", map.isBlocked(3258, 3351, 0));
		assertFalse("test requires a walkable start tile", map.isBlocked(3258, 3341, 0));
		Set<Integer> connected = connectedTilesOracle(map, blockedTarget, radius);
		assertFalse("test requires at least one connected fallback goal", connected.isEmpty());

		ExactPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue(result.isReached());
		assertEquals(PathTerminationReason.TARGET_REACHED, result.getTerminationReason());
		int end = end(result);
		assertFalse("path must end on a walkable tile", map.isBlocked(
			WorldPointUtil.unpackWorldX(end), WorldPointUtil.unpackWorldY(end),
			WorldPointUtil.unpackWorldPlane(end)));
		assertTrue("end tile must be walk-connected to the target (same side of the wall)",
			connected.contains(end));
	}

	@Test
	public void blockedTargetDoesNotTerminateOnStartTile()
	{
		// The player's own tile is excluded from the goal set: the search must
		// not terminate on the first popped state and draw an invisible path.
		final int radius = 6;
		setup(radius);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3256, 3345, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(3258, 3351, 0);
		Set<Integer> connected = connectedTilesOracle(map, blockedTarget, radius);
		assertTrue("test requires the start tile to be a connected fallback goal",
			connected.contains(start));

		ExactPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue(result.isReached());
		List<PathStep> steps = result.getPathSteps();
		assertTrue("a path of a single start tile is meaningless to draw", steps.size() > 1);
		assertNotEquals("the search must not terminate on the start tile", start, end(result));
	}

	@Test
	public void blockedTargetExpansionOffIgnoresConnectivity()
	{
		// With collisionAwareBlockedTargets off the innermost walkable ring is
		// the goal set: the Port Sarim jetty target's ring 1 holds only tiles on
		// the far side, which legacy mode accepts and aware mode rejects.
		final int radius = 6;
		when(config.collisionAwareBlockedTargets()).thenReturn(false);
		setup(radius);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3200, 3330, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(3200, 3340, 0);
		assertTrue("test requires a blocked target tile", map.isBlocked(3200, 3340, 0));
		Set<Integer> connected = connectedTilesOracle(map, blockedTarget, radius);

		ExactPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue("expected the ring scan to find a fallback goal", result.isReached());
		int end = end(result);
		assertTrue("path must end within the unreachable distance",
			WorldPointUtil.distanceBetween(end, blockedTarget) <= radius);
		assertFalse("off mode must accept a tile not connected to the target",
			connected.contains(end));
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import shortestpath.ShortestPathConfig;
import shortestpath.pathfinder.exact.ExactForwardSearch;
import shortestpath.pathfinder.exact.PreparedHeuristic;
import shortestpath.pathfinder.exact.PreparedRoutingAccount;
import shortestpath.pathfinder.exact.ReverseLabels;
import shortestpath.pathfinder.exact.RoutingStatic;
import shortestpath.pathfinder.exact.RoutingStaticTestFixture;
import shortestpath.pathfinder.exact.SiteGraph;
import shortestpath.pathfinder.exact.TargetOverlay;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

public class ExactPathfinderTest
{
	@Test
	public void sourceGlobalReconstructsAnExactTransportPath()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(global(RoutingStaticTestFixture.D, 2), new Transport[0], false);
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		ExactForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertEquals(2, result.cost());
		assertEquals(2, result.path().size());
		assertEquals(RoutingStaticTestFixture.A, result.path().get(0).getPackedPosition());
		assertEquals(RoutingStaticTestFixture.D, result.path().get(1).getPackedPosition());
		assertTrue(result.counters().heuristicEvaluations() > 0);
	}

	@Test
	public void globalsUseSearchNodesRatherThanSiteIndices()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT3();
		PreparedRoutingAccount account = account(global(RoutingStaticTestFixture.T3_B, 2),
			new Transport[0], false);
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.T3_B);

		ExactForwardSearch.Result result = search(target, RoutingStaticTestFixture.T3_A);

		assertTrue(result.reached());
		assertEquals(2, result.cost());
		assertEquals(RoutingStaticTestFixture.T3_B,
			result.path().get(result.path().size() - 1).getPackedPosition());
	}

	@Test
	public void bankTransitionKeepsThePostBankLayerAndUsesBankedGlobal()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(
			local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1),
			new Transport[] {global(RoutingStaticTestFixture.D, 3)}, true);
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		ExactForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertEquals(4, result.cost());
		assertEquals(3, result.path().size());
		assertTrue(result.path().get(2).isBankVisited());
		assertEquals(RoutingStaticTestFixture.D, result.path().get(2).getPackedPosition());
	}

	@Test
	public void inaccessibleBankIsNotEnteredEvenThoughTheStaticDataHasIt()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(
			new Transport[] {local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1)},
			new Transport[] {global(RoutingStaticTestFixture.D, 3)}, true, java.util.Set.of());
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		ExactForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertFalse("only the banked teleport reaches D, and this account cannot bank", result.reached());
		assertFalse(result.path().stream().anyMatch(PathStep::isBankVisited));
	}

	@Test
	public void bankVisitCostIsChargedAndCanMakeBankingNotWorthIt()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		Transport[] carried = {local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1),
			local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.D, 10)};
		Transport[] banked = {global(RoutingStaticTestFixture.D, 3)};

		ExactForwardSearch.Result cheapVisit = search(target(stat, account(carried, banked, true,
			java.util.Set.of(RoutingStaticTestFixture.BANK), 5), RoutingStaticTestFixture.D), RoutingStaticTestFixture.A);
		ExactForwardSearch.Result dearVisit = search(target(stat, account(carried, banked, true,
			java.util.Set.of(RoutingStaticTestFixture.BANK), 20), RoutingStaticTestFixture.D), RoutingStaticTestFixture.A);

		assertEquals("walk 1 + visit 5 + banked teleport 3", 9, cheapVisit.cost());
		assertTrue(cheapVisit.path().stream().anyMatch(PathStep::isBankVisited));
		assertEquals("the direct transport beats 1 + 20 + 3", 10, dearVisit.cost());
		assertFalse(dearVisit.path().stream().anyMatch(PathStep::isBankVisited));
	}

	@Test
	public void disabledBankPathIgnoresAnAccessibleBank()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(
			new Transport[] {local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1)},
			new Transport[] {global(RoutingStaticTestFixture.D, 3)}, false,
			java.util.Set.of(RoutingStaticTestFixture.BANK));
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		ExactForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(account.bankAccessible(RoutingStaticTestFixture.BANK));
		assertFalse(result.reached());
		assertFalse(result.path().stream().anyMatch(PathStep::isBankVisited));
	}

	@Test
	public void cancellationDoesNotPublishACompletedExactRoute()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account();
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		ExactForwardSearch.Result result = ExactForwardSearch.search(target,
			PreparedHeuristic.prepare(target, ReverseLabels.compute(target)), RoutingStaticTestFixture.A, () -> true);

		assertTrue(result.cancelled());
		assertFalse(result.reached());
		assertEquals(1, result.path().size());
		assertEquals(RoutingStaticTestFixture.A, result.path().get(0).getPackedPosition());
	}

	@Test
	public void legacyIsTheDefaultAndExactIsExplicit()
	{
		ShortestPathConfig config = mock(ShortestPathConfig.class);
		when(config.pathfinderBackend()).thenReturn(PathfinderBackend.LEGACY, PathfinderBackend.EXACT);
		assertEquals(PathfinderBackend.LEGACY, config.pathfinderBackend());
		assertEquals(PathfinderBackend.EXACT, config.pathfinderBackend());
		assertTrue(ActiveSearch.class.isAssignableFrom(ExactPathfinder.class));
	}

	@Test
	public void previousRouteIsShownUntilTheSearchCompletes()
		throws Exception
	{
		List<PathStep> previous = List.of(new PathStep(RoutingStaticTestFixture.C, false),
			new PathStep(RoutingStaticTestFixture.D, false));
		ExactPathfinder search = pathfinder(0);
		search.showUntilDone(previous);

		assertTrue(search.isShowingProvisionalPath());
		assertEquals(previous, search.getPath());
		search.run();

		assertFalse(search.isShowingProvisionalPath());
		assertTrue(search.getResult().isReached());
		assertEquals(RoutingStaticTestFixture.D, search.getPath().get(search.getPath().size() - 1).getPackedPosition());
		assertEquals(RoutingStaticTestFixture.A, search.getPath().get(0).getPackedPosition());
	}

	@Test
	public void cancelledSearchKeepsShowingThePreviousRoute()
		throws Exception
	{
		List<PathStep> previous = List.of(new PathStep(RoutingStaticTestFixture.C, false),
			new PathStep(RoutingStaticTestFixture.D, false));
		ExactPathfinder search = pathfinder(0);
		search.showUntilDone(previous);
		search.cancel();

		search.run();

		assertTrue(search.isShowingProvisionalPath());
		assertEquals(previous, search.getPath());
	}

	@Test
	public void trivialPreviousRouteIsNotShown()
		throws Exception
	{
		ExactPathfinder search = pathfinder(0);
		search.showUntilDone(List.of(new PathStep(RoutingStaticTestFixture.C, false)));

		assertFalse(search.isShowingProvisionalPath());
		assertEquals(1, search.getPath().size());
	}

	private static ExactPathfinder pathfinder(long cutoffMillis) throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PathfinderConfig config = mock(PathfinderConfig.class);
		CollisionMap collision = emptyCollision();
		when(config.getMap()).thenReturn(collision);
		when(config.prepareExactRoutingAccount(true))
			.thenReturn(account(global(RoutingStaticTestFixture.D, 2), new Transport[0], false));
		when(config.getCalculationCutoffMillis()).thenReturn(cutoffMillis);
		return new ExactPathfinder(config, stat, null, RoutingStaticTestFixture.A,
			java.util.Set.of(RoutingStaticTestFixture.D), null, 1);
	}

	private static ExactForwardSearch.Result search(TargetOverlay target, int start)
	{
		return ExactForwardSearch.search(target, PreparedHeuristic.prepare(target, ReverseLabels.compute(target)), start);
	}

	private static TargetOverlay target(RoutingStatic stat, PreparedRoutingAccount account, int target)
	{
		return new TargetOverlay(new SiteGraph(stat, account), emptyCollision(), target);
	}

	private static CollisionMap emptyCollision()
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
	{ return new int[0];
	}
			@Override public boolean isBlocked(int x, int y, int z)
	{ return false;
	}
		};
	}

	private static PreparedRoutingAccount account()
	{
		return account(new Transport[0], new Transport[0], false);
	}

	private static PreparedRoutingAccount account(Transport carried, Transport[] banked, boolean bankPath)
	{
		return account(new Transport[] {carried}, banked, bankPath);
	}

	private static PreparedRoutingAccount account(Transport[] carried, Transport[] banked, boolean bankPath)
	{
		return account(carried, banked, bankPath,
			java.util.Set.of(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.T3_B));
	}

	private static PreparedRoutingAccount account(Transport[] carried, Transport[] banked, boolean bankPath,
		java.util.Set<Integer> accessibleBanks)
	{
		return account(carried, banked, bankPath, accessibleBanks, 0);
	}

	private static PreparedRoutingAccount account(Transport[] carried, Transport[] banked, boolean bankPath,
		java.util.Set<Integer> accessibleBanks, int bankVisitCost)
	{
		return PreparedRoutingAccount.compile(availability(carried), availability(banked), bankPath,
			accessibleBanks, bankVisitCost, true, ignored -> 0);
	}

	private static TransportAvailability availability(Transport... transports)
	{
		TransportAvailability.Builder builder = new TransportAvailability.Builder(transports.length);
		for (Transport transport : transports) builder.add(transport);
		return builder.build();
	}

	private static Transport local(int origin, int destination, int duration)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(duration).build();
	}

	private static Transport global(int destination, int duration)
	{
		return new Transport.TransportBuilder().destination(destination)
			.type(TransportType.TELEPORTATION_ITEM).duration(duration).maxWildernessLevel(0).build();
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import org.junit.BeforeClass;
import org.junit.Test;
import shortestpath.ShortestPathConfig;
import shortestpath.TeleportationItem;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.exact.RoutingStatic;

/**
 * Exact casts a global teleport only where its own wilderness limit allows, like legacy.
 *
 * <p>From the level-27 obelisk (benchmark early/quest-natural-0006's start), the cheapest obelisk
 * lands at level 13 (3156,3620). The Fishing Trawler Minigame Teleport is limited to level 0, so it
 * may only be cast after leaving the wilderness, for example into Ferox Enclave a few tiles north.
 */
public class ExactWildernessTeleportParityTest
{
	private static final int START = WorldPointUtil.packWorldPoint(3051, 3736, 0);
	private static final int FISHING_TRAWLER = WorldPointUtil.packWorldPoint(2658, 3157, 0);

	private static RoutingStatic routingStatic;

	@BeforeClass
	public static void buildRoutingStatic()
	{
		routingStatic = new ExactRoutingStaticProvider(
			() -> new CollisionMap(SplitFlagMap.fromResources())).get();
	}

	@Test
	public void levelZeroTeleportIsOnlyCastOutsideTheWildernessLikeLegacy()
	{
		PathfinderConfig config = config();
		Pathfinder legacy = new Pathfinder(config, START, Set.of(FISHING_TRAWLER));
		legacy.run();
		ExactPathfinder exact = new ExactPathfinder(config, routingStatic, null, START, Set.of(FISHING_TRAWLER),
			null, 1);
		exact.run();

		assertTrue(legacy.getResult().isReached());
		assertTrue(exact.getResult().isReached());
		List<PathStep> path = exact.getPath();
		int castFrom = path.get(path.size() - 2).getPackedPosition();
		assertFalse("cast from wilderness tile " + WorldPointUtil.unpackWorldX(castFrom) + ","
			+ WorldPointUtil.unpackWorldY(castFrom), WildernessChecker.isInWilderness(castFrom));
		assertEquals(legacy.getResult().getPathCost(), exact.getResult().getPathCost());
	}

	/** Every quest and skill, no items; wilderness obelisks and minigame teleports only. */
	private static PathfinderConfig config()
	{
		Client client = mock(Client.class);
		ShortestPathConfig settings = mock(ShortestPathConfig.class);
		ItemContainer empty = mock(ItemContainer.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doReturn(new Item[0]).when(empty).getItems();
		doReturn(empty).when(client).getItemContainer(InventoryID.INV);
		doReturn(empty).when(client).getItemContainer(InventoryID.WORN);
		when(settings.calculationCutoff()).thenReturn(500);
		when(settings.currencyThreshold()).thenReturn(10000000);
		when(settings.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(settings.useWildernessObelisks()).thenReturn(true);
		when(settings.useTeleportationMinigames()).thenReturn(true);

		PathfinderConfig config = new TestPathfinderConfig(client, settings, QuestState.FINISHED, true, true);
		config.refresh();
		return config;
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;

/**
 * Pins down the cost formulas and flag bookkeeping of the structure-of-arrays node store so a
 * regression in any of the three distinct cost rules (tile walk, transport, abstract) fails fast.
 * The expected values mirror the maths of the old {@code Node}/{@code TransportNode} classes.
 */
public class NodeGraphTest
{
	@Test
	public void startNodeHasZeroCostAndNoPrevious()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));

		assertEquals(0, graph.cost(start));
		assertEquals(NodeGraph.NO_NODE, graph.previous(start));
		assertTrue(graph.isTile(start));
		assertFalse(graph.isAbstract(start));
		assertFalse(graph.isTransport(start));
		assertFalse(graph.bankVisited(start));
	}

	@Test
	public void tileFromTileAddsWalkingDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3205, 3203, 0);
		int start = graph.createStart(a);
		int tile = graph.createTile(b, start, false);

		assertEquals(WorldPointUtil.distanceBetween(a, b), graph.cost(tile));
		assertEquals(start, graph.previous(tile));
		assertTrue(graph.isTile(tile));
		assertEquals(graph.cost(tile), graph.compareCost(tile));
	}

	@Test
	public void tileFromAbstractAddsNoWalkingDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3300, 3300, 0);
		int start = graph.createStart(a);
		int tileBeforeAbstract = graph.createTile(WorldPointUtil.packWorldPoint(3201, 3200, 0), start, false);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, tileBeforeAbstract, true);
		int tileFromAbstract = graph.createTile(b, abstractNode, true);

		// Reaching a tile from an abstract node adds no travel cost: it inherits the abstract cost.
		assertEquals(graph.cost(abstractNode), graph.cost(tileFromAbstract));
		assertTrue(graph.bankVisited(tileFromAbstract));
	}

	@Test
	public void abstractInheritsPreviousCostAndCarriesKind()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		int tile = graph.createTile(WorldPointUtil.packWorldPoint(3210, 3200, 0), start, false);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_OVER_30, tile, false);

		assertEquals(graph.cost(tile), graph.cost(abstractNode));
		assertTrue(graph.isAbstract(abstractNode));
		assertFalse(graph.isTile(abstractNode));
		assertEquals(AbstractNodeKind.GLOBAL_TELEPORTS_OVER_30, graph.abstractKind(abstractNode));
		assertEquals(WorldPointUtil.UNDEFINED, graph.packedPosition(abstractNode));
	}

	@Test
	public void transportCostIsPreviousPlusTravelAndAdditionalWithNoDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int destination = WorldPointUtil.packWorldPoint(2800, 3400, 0);
		int start = graph.createStart(origin);
		int prev = graph.createTile(WorldPointUtil.packWorldPoint(3201, 3200, 0), start, false);

		int travelTime = 6;
		int additionalCost = 50;
		int differentialCost = 4;
		Transport used = new Transport.TransportBuilder()
			.origin(origin)
			.destination(destination)
			.build();
		int transport = graph.createTransport(destination, prev, travelTime, additionalCost, false, true,
			differentialCost, used);

		// No walking-distance term for transports, unlike a walked tile.
		assertEquals(graph.cost(prev) + travelTime + additionalCost, graph.cost(transport));
		assertEquals(graph.cost(transport) + differentialCost, graph.compareCost(transport));
		assertTrue(graph.isTransport(transport));
		assertTrue(graph.isDelayedVisit(transport));
		assertTrue(graph.isTile(transport)); // transports are concrete tile destinations
		assertEquals(differentialCost, graph.differentialCost(transport));
		assertSame(used, graph.transport(transport));
		assertSame(used, graph.getPathSteps(transport).get(2).getTransport());
	}

	@Test
	public void nonDelayedTransportHasNoDelayedFlagAndZeroDifferential()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		Transport used = new Transport.TransportBuilder()
			.destination(WorldPointUtil.packWorldPoint(2800, 3400, 0))
			.build();
		int transport = graph.createTransport(WorldPointUtil.packWorldPoint(2800, 3400, 0), start, 6, 0,
			true, false, 0, used);

		assertTrue(graph.isTransport(transport));
		assertFalse(graph.isDelayedVisit(transport));
		assertEquals(0, graph.differentialCost(transport));
		assertEquals(graph.cost(transport), graph.compareCost(transport));
		assertTrue(graph.bankVisited(transport));
	}

	@Test
	public void bankVisitStaysOnPositionAndCarriesConfiguredCost()
	{
		// The paid bank transition keeps the same position, is banked, and is queued like
		// a transport (cost-ordered heap, not the unit-cost FIFO tile queue).
		NodeGraph graph = new NodeGraph(16);
		int bankTile = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int start = graph.createStart(bankTile);
		int bankVisit = graph.createBankVisit(bankTile, start, 20);

		assertEquals(20, graph.cost(bankVisit));
		assertEquals(bankTile, graph.packedPosition(bankVisit));
		assertTrue(graph.isTransport(bankVisit));
		assertTrue(graph.isTile(bankVisit));
		assertFalse(graph.isAbstract(bankVisit));
		assertTrue(graph.bankVisited(bankVisit));

		// A bank visit is a state change, not a movement step: the tile the player banked
		// at is already in the path as the preceding step.
		var steps = graph.getPathSteps(bankVisit);
		assertEquals(1, steps.size());
		assertEquals(bankTile, steps.get(0).getPackedPosition());
		assertNull(steps.get(0).getTransport());
	}

	@Test
	public void pathStepsSkipAbstractNodesInOrder()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3201, 3200, 0);
		int c = WorldPointUtil.packWorldPoint(2800, 3400, 0);
		int start = graph.createStart(a);
		int tile = graph.createTile(b, start, false);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, tile, false);
		Transport teleport = new Transport.TransportBuilder()
			.destination(c)
			.build();
		int teleportDest = graph.createTransport(c, abstractNode, 6, 0, false, false, 0, teleport);

		var steps = graph.getPathSteps(teleportDest);
		assertEquals(3, steps.size()); // start, tile, teleportDest (abstract is skipped)
		assertEquals(a, steps.get(0).getPackedPosition());
		assertEquals(b, steps.get(1).getPackedPosition());
		assertEquals(c, steps.get(2).getPackedPosition());
		assertNull(steps.get(0).getTransport()); // walked steps carry no transport identity
		assertSame(teleport, steps.get(2).getTransport());

		assertEquals(c, graph.getClosestTilePosition(teleportDest));
		assertEquals(b, graph.getClosestTilePosition(abstractNode));
	}

	@Test
	public void releaseMakesChainWalksReturnEmpty()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		graph.release();

		assertTrue(graph.getPathSteps(start).isEmpty());
		assertEquals(WorldPointUtil.UNDEFINED, graph.getClosestTilePosition(start));
	}
}

package shortestpath.pathfinder;

import java.util.Arrays;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.ShortestPathConfig;
import shortestpath.TeleportationItem;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.when;

/**
 * Quantities of an item held in several places are summed when checking
 * teleport requirements. Uses Varrock Teleport (3 air, 1 fire, 1 law rune).
 */
@RunWith(MockitoJUnitRunner.class)
public class PathfinderConfigItemQuantitiesTest
{
	private static final String VARROCK_TELEPORT = "Varrock Teleport";
	private static final int POUCH_AIR = 1;

	@Mock
	private Client client;
	@Mock
	private ShortestPathConfig config;
	@Mock
	private ItemContainer inventory;
	@Mock
	private ItemContainer bank;
	@Mock
	private EnumComposition runePouchEnum;

	private PathfinderConfig pathfinderConfig;

	@Test
	public void runePouchRunesAddToLooseRunes()
	{
		// 1 loose air rune plus 2 in the pouch makes the 3 air runes Varrock Teleport needs
		setupInventory(new Item(ItemID.AIRRUNE, 1), new Item(ItemID.FIRERUNE, 1), new Item(ItemID.LAWRUNE, 1),
			new Item(ItemID.BH_RUNE_POUCH, 1));
		when(client.getEnum(EnumID.RUNEPOUCH_RUNE)).thenReturn(runePouchEnum);
		when(runePouchEnum.getIntValue(POUCH_AIR)).thenReturn(ItemID.AIRRUNE);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1)).thenReturn(POUCH_AIR);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_1)).thenReturn(2);

		refresh(false, TeleportationItem.NONE);

		assertTrue(varrockTeleportUsable(false));
	}

	@Test
	public void bankedRunesAddToCarriedRunes()
	{
		// 2 carried air runes plus 1 in the bank makes 3 on the bank path, not 1
		setupInventory(new Item(ItemID.AIRRUNE, 2), new Item(ItemID.FIRERUNE, 1), new Item(ItemID.LAWRUNE, 1));
		when(bank.getItems()).thenReturn(new Item[]{new Item(ItemID.AIRRUNE, 1)});

		refresh(true, TeleportationItem.INVENTORY_AND_BANK);

		assertFalse(varrockTeleportUsable(false));
		assertTrue(varrockTeleportUsable(true));
	}

	@Test
	public void bankedRunePouchRunesAddToLooseBankedRunes()
	{
		// A banked pouch with 2 air plus 1 loose banked air makes 3 on the bank path
		setupInventory(new Item(ItemID.FIRERUNE, 1), new Item(ItemID.LAWRUNE, 1));
		when(bank.getItems()).thenReturn(new Item[]{new Item(ItemID.BH_RUNE_POUCH, 1), new Item(ItemID.AIRRUNE, 1)});
		when(client.getEnum(EnumID.RUNEPOUCH_RUNE)).thenReturn(runePouchEnum);
		when(runePouchEnum.getIntValue(POUCH_AIR)).thenReturn(ItemID.AIRRUNE);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1)).thenReturn(POUCH_AIR);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_1)).thenReturn(2);

		refresh(true, TeleportationItem.INVENTORY_AND_BANK);

		assertFalse(varrockTeleportUsable(false));
		assertTrue(varrockTeleportUsable(true));
	}

	private void setupInventory(Item... items)
	{
		doReturn(inventory).when(client).getItemContainer(InventoryID.INV);
		when(inventory.getItems()).thenReturn(items);
	}

	private void refresh(boolean includeBankPath, TeleportationItem useTeleportationItems)
	{
		pathfinderConfig = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		when(config.calculationCutoff()).thenReturn(30);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationSpells()).thenReturn(true);
		when(config.useTeleportationItems()).thenReturn(useTeleportationItems);
		when(config.includeBankPath()).thenReturn(includeBankPath);
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		pathfinderConfig.bank = bank;
		pathfinderConfig.refresh();
	}

	private boolean varrockTeleportUsable(boolean bankVisited)
	{
		return Arrays.stream(pathfinderConfig.getUsableTeleports(bankVisited))
			.anyMatch(t -> VARROCK_TELEPORT.equals(t.getDisplayInfo()));
	}
}

package shortestpath.pathfinder;

import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import shortestpath.TestShortestPathConfig;
import shortestpath.transport.PohMountedItem;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class PathfinderConfigPohMountedItemTest
{
	private static final Map<PohMountedItem, String> OBJECTS = Map.of(
		PohMountedItem.GLORY, "Edgeville Amulet of Glory 13523",
		PohMountedItem.XERICS_TALISMAN, "Look out Xeric's Talisman 33411",
		PohMountedItem.DIGSITE_PENDANT, "Digsite Digsite Pendant 33417",
		PohMountedItem.MYTHICAL_CAPE, "Teleport Mythical cape 31986");

	@Test
	public void emptySelectionDisablesEveryMountedItem()
	{
		Set<PohMountedItem> selected = EnumSet.noneOf(PohMountedItem.class);
		for (String objectInfo : OBJECTS.values())
		{
			assertFalse(PathfinderConfig.isPohMountedItemEnabled(selected, objectInfo));
		}
	}

	@Test
	public void singletonSelectionsAreIndependent()
	{
		assertSelection(PohMountedItem.XERICS_TALISMAN);
		assertSelection(PohMountedItem.GLORY);
	}

	@Test
	public void allMountedItemsReproduceTheEnabledBehaviour()
	{
		Set<PohMountedItem> selected = EnumSet.allOf(PohMountedItem.class);
		for (String objectInfo : OBJECTS.values())
		{
			assertTrue(PathfinderConfig.isPohMountedItemEnabled(selected, objectInfo));
		}
	}

	@Test
	public void legacyBooleanSuppliesTheInitialMultiSelection()
	{
		assertTrue(new TestShortestPathConfig().pohMountedItems().containsAll(
			EnumSet.allOf(PohMountedItem.class)));
		TestShortestPathConfig legacyDisabled = new TestShortestPathConfig()
		{
			@Override
			public boolean usePohMountedItems()
			{
				return false;
			}
		};
		assertTrue(legacyDisabled.pohMountedItems().isEmpty());
	}

	@Test
	public void carriedXericsTalismanIsNotAMountedObject()
	{
		String carriedDisplayInfo = "Xeric's talisman: 1. Xeric's Lookout";
		assertNull(PohMountedItem.fromObjectInfo(carriedDisplayInfo));
		assertTrue(PathfinderConfig.isPohMountedItemEnabled(
			EnumSet.noneOf(PohMountedItem.class), carriedDisplayInfo));
	}

	private static void assertSelection(PohMountedItem selectedItem)
	{
		Set<PohMountedItem> selected = EnumSet.of(selectedItem);
		for (Map.Entry<PohMountedItem, String> entry : OBJECTS.entrySet())
		{
			assertSame(entry.getKey(), PohMountedItem.fromObjectInfo(entry.getValue()));
			if (entry.getKey().equals(selectedItem))
			{
				assertTrue(PathfinderConfig.isPohMountedItemEnabled(selected, entry.getValue()));
			}
			else
			{
				assertFalse(PathfinderConfig.isPohMountedItemEnabled(selected, entry.getValue()));
			}
		}
	}
}

package shortestpath.pathfinder;

import java.util.EnumSet;
