		TargetOverlay otherTarget =
			new TargetOverlay(new SiteGraph(RoutingStaticTestFixture.createT3(), emptyAccount()),
				collision(RoutingStaticTestFixture.T3_TARGET), RoutingStaticTestFixture.T3_TARGET);
