		assertEquals(ExactCosts.INF - 1, ExactCosts.add(ExactCosts.INF - 1, 0));
	}

	@Test
	public void infinitySaturates()
	{
		assertEquals(ExactCosts.INF, ExactCosts.add(ExactCosts.INF, 1));
		assertEquals(ExactCosts.INF, ExactCosts.add(1, ExactCosts.INF));
		assertEquals(ExactCosts.INF, ExactCosts.add(ExactCosts.INF - 1, 1));
	}

	@Test
	public void rejectsNegativeCosts()
	{
		try
		{
			ExactCosts.add(-1, 0);
			fail("negative costs must be rejected");
		}
		catch (IllegalArgumentException expected)
		{
		}
	}

	@Test
	public void weightsSearchPrioritySafely()
	{
		assertEquals(13, ExactForwardSearch.priority(3, 5, 2));
		assertEquals(ExactCosts.INF - 1,
			ExactForwardSearch.priority(3, ExactCosts.INF - 1, Double.MAX_VALUE));
		try
		{
			ExactForwardSearch.validateHeuristicWeight(0);
			fail("zero heuristic weight must be rejected");
		}
		catch (IllegalArgumentException expected)
		{
		}
	}
}

package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

public class ExactForwardSearchHotPathTest
{
	private static final int OUTSIDE = WorldPointUtil.packWorldPoint(3200, 3520, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(3202, 3520, 0);
	private static final int DEEP_WILDERNESS = WorldPointUtil.packWorldPoint(3200, 3760, 0);

	@Test
	public void nodeStatesAndReachableBankIndexesMatchTileData() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT4Walking();
		TargetOverlay target = target(stat, account(), RoutingStaticTestFixture.C);
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(target, ReverseLabels.compute(target));
		for (int node = 0; node < stat.searchTileCount(); node++)
		{
			assertEquals(stat.searchIndex(stat.searchTile(node)) * 2,
				ExactForwardSearch.stateForNode(node, false));
			assertEquals(stat.searchIndex(stat.searchTile(node)) * 2 + 1,
				ExactForwardSearch.stateForNode(node, true));
			assertEquals(isBankTile(stat, stat.searchTile(node)), stat.isBankNode(node));
			for (boolean banked : new boolean[] {false, true})
				assertEquals(heuristic.estimate(stat.searchTile(node), banked,
					new int[] {stat.routingComponent(node)}), heuristic.estimateBaseNode(stat.searchTile(node),
					banked, stat.routingComponent(node)));
		}
		for (int site = 0; site < stat.siteCount(); site++)
			assertEquals(isBankTile(stat, stat.siteTile(site)), stat.isBankSite(site));
	}

	@Test
	public void walkingAndLocalTransportKeepExactStatesCostsAndRoute() throws Exception
	{
		RoutingStatic walking = RoutingStaticTestFixture.createT4Walking();
		ExactForwardSearch.Result walked = search(walking, account(), RoutingStaticTestFixture.A,
			RoutingStaticTestFixture.C);
		assertEquals(2, walked.cost());
		assertEquals(List.of(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK,
			RoutingStaticTestFixture.C), tiles(walked.path()));
		assertTrue(walked.counters().walkingPqPushes() > 0);

		RoutingStatic transported = RoutingStaticTestFixture.create();
		ExactForwardSearch.Result moved = search(transported,
			account(local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.D, 7)),
			RoutingStaticTestFixture.A, RoutingStaticTestFixture.D);
		assertEquals(7, moved.cost());
		assertEquals(List.of(RoutingStaticTestFixture.A, RoutingStaticTestFixture.D), tiles(moved.path()));
		assertEquals(1, moved.counters().localTransportPqPushes());
	}

	@Test
	public void cancelledSearchKeepsTheRouteToTheClosestPoppedTile() throws Exception
	{
		TargetOverlay target = target(RoutingStaticTestFixture.createT4Walking(), account(), RoutingStaticTestFixture.C);
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(target, ReverseLabels.compute(target));
		int[] checks = {0};

		ExactForwardSearch.Result result = ExactForwardSearch.search(target, heuristic, RoutingStaticTestFixture.A,
			() -> ++checks[0] >= 4);

		assertTrue(result.cancelled());
		assertEquals(List.of(RoutingStaticTestFixture.A), tiles(result.path()));
		assertEquals(List.of(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK), tiles(result.closestPath()));
		assertEquals(1, result.closestCost());
	}

	@Test
	public void unreachableTargetKeepsTheRouteToTheClosestReachableTile() throws Exception
	{
		ExactForwardSearch.Result result = search(RoutingStaticTestFixture.createT4Walking(), account(),
			RoutingStaticTestFixture.A, RoutingStaticTestFixture.D);

		assertFalse(result.reached());
		assertEquals(List.of(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.C),
			tiles(result.closestPath()));
		assertEquals(2, result.closestCost());
	}

	@Test
	public void restrictedStartUsesCapThenNormalHeuristicAfterGlobalActivation() throws Exception
	{
		RoutingStatic stat = wildernessStatic();
		PreparedRoutingAccount account = account(local(DEEP_WILDERNESS, OUTSIDE, 5), global(TARGET, 1));
		TargetOverlay target = target(stat, account, TARGET);
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(target, ReverseLabels.compute(target));

		ExactForwardSearch.Result oracle = ExactForwardSearch.search(target, heuristic, DEEP_WILDERNESS, false);
		ExactForwardSearch.Result result = ExactForwardSearch.search(target, heuristic, DEEP_WILDERNESS, true);

		assertEquals(oracle.cost(), result.cost());
		assertEquals(6, result.cost());
		assertEquals(List.of(DEEP_WILDERNESS, OUTSIDE, TARGET), tiles(result.path()));
		assertEquals("OVER_30", result.counters().initialCapability());
		assertFalse(result.counters().normalHeuristicEnabledAtStart());
		assertTrue(result.counters().restrictedHeuristicStates() > 0);
		assertTrue(result.counters().normalHeuristicStates() > 0);
	}

	@Test
	public void wildernessPositionDoesNotDisableHeuristicWhenAccountHasNoGlobals() throws Exception
	{
		RoutingStatic stat = wildernessStatic();
		ExactForwardSearch.Result result = search(stat, account(local(DEEP_WILDERNESS, TARGET, 4)),
			DEEP_WILDERNESS, TARGET);

		assertEquals(4, result.cost());
		assertTrue(result.counters().normalHeuristicEnabledAtStart());
		assertEquals(0, result.counters().restrictedHeuristicStates());
		assertTrue(result.counters().normalHeuristicStates() > 0);
	}

	private static boolean isBankTile(RoutingStatic stat, int tile)
	{
		for (int i = 0; i < stat.reachableBankCount(); i++)
			if (stat.reachableBankTile(i) == tile) return true;
		return false;
	}

	private static List<Integer> tiles(List<PathStep> path)
	{
		return path.stream().map(PathStep::getPackedPosition).collect(java.util.stream.Collectors.toList());
	}

	private static ExactForwardSearch.Result search(RoutingStatic stat, PreparedRoutingAccount account,
		int start, int destination)
	{
		TargetOverlay target = target(stat, account, destination);
		return ExactForwardSearch.search(target, PreparedHeuristic.prepare(target, ReverseLabels.compute(target)), start);
	}

	private static TargetOverlay target(RoutingStatic stat, PreparedRoutingAccount account, int destination)
	{
		return new TargetOverlay(new SiteGraph(stat, account), emptyCollision(), destination);
	}

	private static PreparedRoutingAccount account(Transport... transports)
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(transports),
			TransportAvailabilityFixture.of(), false, java.util.Set.of(), 0, true, ignored -> 0);
	}

	private static Transport local(int origin, int destination, int cost)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(cost).build();
	}

	private static Transport global(int destination, int cost)
	{
		return new Transport.TransportBuilder().destination(destination)
			.type(TransportType.TELEPORTATION_ITEM).duration(cost).maxWildernessLevel(0).build();
	}

	private static RoutingStatic wildernessStatic() throws Exception
	{
		return RoutingStatic.create(new int[0], new int[0], new byte[0], new int[0], new int[0],
			new int[] {OUTSIDE, TARGET, DEEP_WILDERNESS}, new int[] {0, 1, 2, 3}, new int[] {0, 0, 0},
			1, new int[] {0, 3}, new int[] {0, 1, 2}, new int[0], new int[0], new int[0], new int[0],
			3, 3, 0, 0, 0, new int[] {0, 0, 0, 0}, new int[0], new int[0]);
	}

	private static CollisionMap emptyCollision()
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
			{ return new int[0];
			}
			@Override public boolean isBlocked(int x, int y, int z)
			{ return false;
			}
		};
	}
}

package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertFalse;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.stream.Stream;
import org.junit.Test;

public class ExactPackageDependencyTest
{
	@Test
	public void exactSourcesDoNotImportClientOrLegacySearch() throws IOException
	{
		Path sourceRoot = Paths.get("src/main/java/shortestpath/pathfinder/exact");
		try (Stream<Path> files = Files.walk(sourceRoot))
		{
			files.filter(path -> path.toString().endsWith(".java")).forEach(this::assertAllowedImports);
		}
	}

	private void assertAllowedImports(Path source)
	{
		try
		{
			String text = Files.readString(source);
			assertFalse(source + " imports RuneLite Client", text.contains("net.runelite.api.Client"));
			assertFalse(source + " imports legacy search", text.contains("shortestpath.pathfinder.Pathfinder"));
			assertFalse(source + " imports legacy graph", text.contains("NodeGraph"));
			assertFalse(source + " imports legacy visited state", text.contains("VisitedTiles"));
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}
}

package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.TransportAvailability;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

public class ExactRoutingSessionTest
{
	private static final int A = RoutingStaticTestFixture.A;
	private static final int BANK = RoutingStaticTestFixture.BANK;
	private static final int C = RoutingStaticTestFixture.C;
	private static final int D = RoutingStaticTestFixture.D;

	@Test
	public void graphIsReusedForAnEqualFingerprintFromAFreshCompile() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		ExactRoutingSession session = new ExactRoutingSession();

		ExactRoutingSession.Lookup<SiteGraph> first = session.graph(stat, account(global(D, 2)));
		ExactRoutingSession.Lookup<SiteGraph> second = session.graph(stat, account(global(D, 2)));

		assertFalse(first.reused());
		assertTrue(second.reused());
		assertSame(first.value(), second.value());
	}

	@Test
	public void changedAccountRebuildsTheGraphAndDropsPreparedTargets() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		CollisionMap collision = emptyCollision();
		ExactRoutingSession session = new ExactRoutingSession();
		SiteGraph before = session.graph(stat, account(global(D, 2))).value();
		session.target(before, collision, D);

		ExactRoutingSession.Lookup<SiteGraph> after = session.graph(stat, account(global(D, 3)));

		assertFalse(after.reused());
		assertNotSame(before, after.value());
		assertEquals(0, session.cachedTargetCount());
		assertFalse(session.target(after.value(), collision, D).reused());
	}

	@Test
	public void changedBankAccessRebuildsTheGraphInBothDirections() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		CollisionMap collision = emptyCollision();
		ExactRoutingSession session = new ExactRoutingSession();

		SiteGraph inaccessible = session.graph(stat, bankingAccount(java.util.Set.of())).value();
		ExactRoutingSession.Lookup<SiteGraph> accessible = session.graph(stat, bankingAccount(java.util.Set.of(BANK)));
		assertFalse(accessible.reused());
		assertTrue(search(accessible.value(), collision).reached());

		ExactRoutingSession.Lookup<SiteGraph> again = session.graph(stat, bankingAccount(java.util.Set.of()));
		assertFalse("a graph that may bank must not be reused for an account that may not", again.reused());
		assertNotSame(inaccessible, again.value());
		ExactForwardSearch.Result result = search(again.value(), collision);
		assertFalse(result.reached());
		assertFalse(result.path().stream().anyMatch(PathStep::isBankVisited));
	}

	@Test
	public void differentStaticDataRebuildsTheGraph() throws Exception
	{
		ExactRoutingSession session = new ExactRoutingSession();
		session.graph(RoutingStaticTestFixture.create(), account(global(D, 2)));

		assertFalse(session.graph(RoutingStaticTestFixture.create(), account(global(D, 2))).reused());
	}

	@Test
	public void preparedTargetIsReusedForNewStartsWithIdenticalResults() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		CollisionMap collision = emptyCollision();
		PreparedRoutingAccount account = account(global(D, 2));
		ExactRoutingSession session = new ExactRoutingSession();
		SiteGraph graph = session.graph(stat, account).value();

		ExactRoutingSession.Lookup<PreparedTarget> first = session.target(graph, collision, D);
		ExactRoutingSession.Lookup<PreparedTarget> second = session.target(graph, collision, D);

		assertFalse(first.reused());
		assertTrue(second.reused());
		assertSame(first.value(), second.value());
		for (int start : new int[] {A, BANK, C})
		{
			TargetOverlay fresh = new TargetOverlay(new SiteGraph(stat, account), collision, D);
			ExactForwardSearch.Result expected = ExactForwardSearch.search(fresh,
				PreparedHeuristic.prepare(fresh, ReverseLabels.compute(fresh)), start);
			ExactForwardSearch.Result actual = second.value().search(start, () -> false, 1);
			assertEquals(expected.reached(), actual.reached());
			assertEquals(expected.cost(), actual.cost());
			assertEquals(positions(expected), positions(actual));
		}
	}

	@Test
	public void leastRecentlyUsedTargetIsEvicted() throws Exception
	{
		CollisionMap collision = emptyCollision();
		ExactRoutingSession session = new ExactRoutingSession(2);
		SiteGraph graph = session.graph(RoutingStaticTestFixture.create(), account(global(D, 2))).value();
		session.target(graph, collision, A);
		session.target(graph, collision, C);
		assertTrue(session.target(graph, collision, A).reused());

		session.target(graph, collision, D);

		assertEquals(2, session.cachedTargetCount());
		assertTrue(session.target(graph, collision, A).reused());
		assertFalse(session.target(graph, collision, C).reused());
	}

	@Test
	public void clearingTargetsKeepsTheGraph() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		CollisionMap collision = emptyCollision();
		ExactRoutingSession session = new ExactRoutingSession();
		SiteGraph graph = session.graph(stat, account(global(D, 2))).value();
		session.target(graph, collision, D);

		session.clearTargets();

		assertTrue(session.graph(stat, account(global(D, 2))).reused());
		assertFalse(session.target(graph, collision, D).reused());
	}

	@Test
	public void targetsAreNotSharedAcrossCollisionMaps() throws Exception
	{
		ExactRoutingSession session = new ExactRoutingSession();
		SiteGraph graph = session.graph(RoutingStaticTestFixture.create(), account(global(D, 2))).value();
		session.target(graph, emptyCollision(), D);

		assertFalse(session.target(graph, emptyCollision(), D).reused());
	}

	@Test
	public void graphsFromOutsideTheSessionAreNotCached() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		CollisionMap collision = emptyCollision();
		ExactRoutingSession session = new ExactRoutingSession();
		SiteGraph outside = new SiteGraph(stat, account(global(D, 2)));

		session.target(outside, collision, D);

		assertFalse(session.target(outside, collision, D).reused());
		assertEquals(0, session.cachedTargetCount());
	}

	private static List<Integer> positions(ExactForwardSearch.Result result)
	{
		return result.path().stream().map(PathStep::getPackedPosition).collect(Collectors.toList());
	}

	private static PreparedRoutingAccount account(Transport global)
	{
		TransportAvailability availability = TransportAvailabilityFixture.of(global);
		return PreparedRoutingAccount.compile(availability, availability, false, java.util.Set.of(), 0, true,
			ignored -> 0);
	}

	/** Banks at BANK (reached by a local transport from A) to take the only teleport to D. */
	private static PreparedRoutingAccount bankingAccount(java.util.Set<Integer> accessibleBanks)
	{
		Transport toBank = new Transport.TransportBuilder().origin(A).destination(BANK)
			.type(TransportType.TRANSPORT).duration(1).build();
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(toBank),
			TransportAvailabilityFixture.of(global(D, 3)), true, accessibleBanks, 0, true, ignored -> 0);
	}

	private static ExactForwardSearch.Result search(SiteGraph graph, CollisionMap collision)
	{
		TargetOverlay target = new TargetOverlay(graph, collision, D);
		return ExactForwardSearch.search(target, PreparedHeuristic.prepare(target, ReverseLabels.compute(target)), A);
	}

	private static Transport global(int destination, int duration)
	{
		return new Transport.TransportBuilder().destination(destination)
			.type(TransportType.TELEPORTATION_ITEM).duration(duration).maxWildernessLevel(0).build();
	}

	private static CollisionMap emptyCollision()
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
	{ return new int[0];
	}
			@Override public boolean isBlocked(int x, int y, int z)
	{ return false;
	}
		};
	}
}

package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.function.IntPredicate;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

public class ExactWalkCanonicalizerTest
{
	// Away from the wilderness, so every global teleport is castable.
	private static final int BASE_X = 3200, BASE_Y = 3200;
	private static final PreparedRoutingAccount NO_TRANSPORTS = PreparedRoutingAccount.compile(null, null, false,
		java.util.Set.of(), 0, false, ignored -> 0);

	@Test
	public void straightWalkStaysStraight()
	{
		Shape shape = walk(new Grid(), 0, 0, 40, WalkGoal.tile(pack(0, 40)));

		assertEquals(40, shape.ticks);
		assertEquals(40, shape.axis);
		assertEquals(0, shape.turns);
	}

	@Test
	public void diagonalWalkStaysDiagonal()
	{
		Shape shape = walk(new Grid(), 0, 0, 40, WalkGoal.tile(pack(40, 40)));

		assertEquals(40, shape.ticks);
		assertEquals(80, shape.axis);
		assertEquals(0, shape.turns);
		assertEquals("NE40", shape.runs);
	}

	@Test
	public void unequalDeltasTakeOneDiagonalAndNoAlternation()
	{
		Shape shape = walk(new Grid(), 0, 0, 40, WalkGoal.tile(pack(1, 40)));

		assertEquals(40, shape.ticks);
		assertEquals(41, shape.axis);
		assertEquals(1, shape.turns);
		assertEquals(1, shape.diagonals);
	}

	@Test
	public void sidewaysDetoursThatCancelAreRemoved()
	{
		Grid grid = new Grid();
		// Same ticks, but west then back east: 2 more axis travel than walking straight north.
		List<PathStep> route = steps(0, 0, -1, 1, -1, 2, 0, 3, 0, 4);
		assertEquals(6, shape(route, 0, 4).axis);

		ExactWalkCanonicalizer.Result result = canonicalize(grid, NO_TRANSPORTS, route);

		assertEquals(List.of(), result.diagnostics());
		assertEquals(describe(steps(0, 0, 0, 1, 0, 2, 0, 3, 0, 4)), describe(result.path()));
	}

	@Test
	public void fewerTurnsWinAmongEquallyDirectWalks()
	{
		Grid grid = new Grid();
		// N NE N NE N N: as few ticks and as little axis travel as possible, but four turns.
		List<PathStep> route = steps(0, 0, 0, 1, 1, 2, 1, 3, 2, 4, 2, 5, 2, 6);
		Shape before = shape(route, 0, 6);
		assertEquals(8, before.axis);
		assertEquals(4, before.turns);

		ExactWalkCanonicalizer.Result result = canonicalize(grid, NO_TRANSPORTS, route);

		Shape after = shape(result.path(), 0, 6);
		assertEquals(6, after.ticks);
		assertEquals(8, after.axis);
		assertEquals(1, after.turns);
		assertEquals(last(route), last(result.path()));
	}

	@Test
	public void wallsAreWalkedAroundWithTheReferenceOrdering()
	{
		Set<Integer> blocked = new HashSet<>();
		for (int x = -3; x <= 4; x++) blocked.add(pack(x, 5));
		for (int y = 5; y <= 9; y++) blocked.add(pack(4, y));
		Grid grid = new Grid(blocked);
		WalkGoal goal = WalkGoal.tile(pack(1, 12));
		int[] reference = Reference.best(grid, pack(0, 0), goal, 30);
		assertNotNull(reference);

		Shape shape = walk(grid, 0, 0, reference[0], goal);

		assertArrayEquals(reference, new int[] {shape.ticks, shape.axis, shape.turns});
		assertLegal(grid, shape.tiles);
	}

	@Test
	public void randomGridsMatchTheReferenceOrdering()
	{
		Random random = new Random(20261002);
		int checked = 0;
		for (int trial = 0; trial < 300; trial++)
		{
			Set<Integer> blocked = new HashSet<>();
			for (int x = -1; x <= 13; x++)
				for (int y = -1; y <= 13; y++)
					if (x < 0 || y < 0 || x > 12 || y > 12 || random.nextInt(100) < 22) blocked.add(pack(x, y));
			int start = pack(random.nextInt(13), random.nextInt(13));
			blocked.remove(start);
			int goalCount = 1 + random.nextInt(3);
			int[] goals = new int[goalCount];
			for (int i = 0; i < goalCount; i++)
			{
				goals[i] = pack(random.nextInt(13), random.nextInt(13));
				blocked.remove(goals[i]);
			}
			Grid grid = new Grid(blocked);
			WalkGoal goal = WalkGoal.tiles(goals, 0);
			int[] reference = Reference.best(grid, start, goal, 60);
			ExactWalkCanonicalizer canonicalizer = new ExactWalkCanonicalizer(grid, NO_TRANSPORTS);
			if (reference == null || reference[0] == 0) continue;
			ExactWalkCanonicalizer.Walk walk = canonicalizer.walk(start, reference[0], goal);
			assertEquals("trial " + trial, ExactWalkCanonicalizer.Outcome.CANONICAL, walk.outcome);
			Shape shape = Shape.of(start, walk.tiles);
			assertArrayEquals("trial " + trial, reference, new int[] {shape.ticks, shape.axis, shape.turns});
			assertTrue(goal.contains(x(walk.tiles[walk.tiles.length - 1]), y(walk.tiles[walk.tiles.length - 1])));
			assertLegal(grid, shape.tiles);
			// Asked for a longer leg than the shortest, it reports the route as too long.
			assertEquals(ExactWalkCanonicalizer.Outcome.SHORTER_ROUTE,
				canonicalizer.walk(start, reference[0] + 1, goal).outcome);
			checked++;
		}
		assertTrue("too few reachable trials: " + checked, checked > 150);
	}

	@Test
	public void teleportAreaIsLeftStraightAhead()
	{
		// Level 30 wilderness above-ground ends below y = 3760; level 20 below y = 3680.
		Shape wilderness = walk(new Grid(), 3000 - BASE_X, 3800 - BASE_Y, 41,
			WalkGoal.teleportArea(TeleportCapability.OVER_20));
		assertEquals("S41", wilderness.runs);
		assertEquals(41, wilderness.axis);

