package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Set;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.pathfinder.WildernessChecker;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/**
 * {@link SearchRestrictions} mirrors the positional gates legacy checks per edge: neither walking
 * nor a local transport may land inside the wilderness or the league's always-blocked region from
 * outside it, while moving inside the gated area or out of it stays allowed. Global teleports are
 * barred from landing in the wilderness only when cast from outside it, matching the source-tile
 * check legacy runs on its abstract nodes.
 */
public class SearchRestrictionsTest
{
	// Fixture tiles: a short non-wilderness line leading to wilderness tiles. Masks join them in
	// array order, so geometry is irrelevant to the search but the coordinates are real, so the
	// wilderness and region predicates report genuine answers.
	private static final int SAFE2 = WorldPointUtil.packWorldPoint(2998, 3523, 0);
	private static final int SAFE = WorldPointUtil.packWorldPoint(2998, 3524, 0);
	private static final int WILD = WorldPointUtil.packWorldPoint(2995, 3540, 0);
	private static final int WILDT = WorldPointUtil.packWorldPoint(2995, 3541, 0);
	/** Level-25 wilderness: its teleport capability band is OVER_20. */
	private static final int WILD25 = WorldPointUtil.packWorldPoint(3200, 3712, 0);

	private static final SearchRestrictions AVOID_WILDERNESS = SearchRestrictions.of(true, null);
	private static final SearchRestrictions BLOCKED_WILD =
		SearchRestrictions.of(false, tile -> tile == WILD || tile == WILDT);

	@Test
	public void fixtureTilesHaveExpectedStatus()
	{
		assertFalse(WildernessChecker.isInWilderness(SAFE2));
		assertFalse(WildernessChecker.isInWilderness(SAFE));
		assertTrue(WildernessChecker.isInWilderness(WILD));
		assertTrue(WildernessChecker.isInWilderness(WILDT));
		assertEquals(TeleportCapability.OVER_20, TeleportCapability.at(WILD25));
	}

	@Test
	public void walkingIntoWildernessIsGated()
	{
		assertFalse(search(SAFE, WILD, AVOID_WILDERNESS).reached());
		assertTrue(search(SAFE, WILD, SearchRestrictions.none()).reached());
	}

	@Test
	public void leavingWildernessOnFootIsAllowed()
	{
		// The gate bars entering the wilderness, never walking out of it.
		assertTrue(search(WILD, SAFE, AVOID_WILDERNESS).reached());
		assertEquals(1, search(WILD, SAFE, AVOID_WILDERNESS).cost());
	}

	@Test
	public void localTransportIntoWildernessIsGated()
	{
		// Legacy flags transport destination nodes as tiles, so the same positional gate applies
		// to the jump's landing tile; a ditch-style crossing must not bypass it.
		PreparedRoutingAccount account = account(local(SAFE2, WILDT, 3));
		assertFalse(search(SAFE2, WILDT, AVOID_WILDERNESS, account).reached());
		assertTrue(search(SAFE2, WILDT, SearchRestrictions.none(), account).reached());
	}

	@Test
	public void localTransportOutOfWildernessIsAllowed()
	{
		PreparedRoutingAccount account = account(local(WILDT, SAFE2, 3));
		ExactForwardSearch.Result result = search(WILDT, SAFE2, AVOID_WILDERNESS, account);
		assertTrue(result.reached());
		assertEquals(3, result.cost());
	}

	@Test
	public void blockedRegionGatesWalkingAndTransports()
	{
		PreparedRoutingAccount account = account(local(SAFE2, WILDT, 3));
		assertFalse("walked into the blocked region", search(SAFE, WILD, BLOCKED_WILD, account).reached());
		assertFalse("transported into the blocked region",
			search(SAFE2, WILDT, BLOCKED_WILD, account).reached());
		assertTrue(search(SAFE, WILD, SearchRestrictions.none(), account).reached());
		assertTrue(search(SAFE2, WILDT, SearchRestrictions.none(), account).reached());
	}

	@Test
	public void leavingBlockedRegionByTransportIsAllowed()
	{
		PreparedRoutingAccount account = account(local(WILDT, SAFE2, 3));
		assertTrue(search(WILDT, SAFE2, BLOCKED_WILD, account).reached());
	}

	@Test
	public void globalTeleportIntoWildernessIsBarredFromOutside()
	{
		PreparedRoutingAccount account = account(teleport(WILDT, 0));
		assertFalse(search(SAFE2, WILDT, AVOID_WILDERNESS, account).reached());
		assertTrue(search(SAFE2, WILDT, SearchRestrictions.none(), account).reached());
	}

	@Test
	public void globalTeleportIntoWildernessIsAllowedFromInside()
	{
		// Legacy exempts wilderness landings when the cast tile is itself in the wilderness; the
		// capability band carries the same information. A limit-30 teleport is castable in level 25.
		PreparedRoutingAccount account = account(teleport(WILDT, 30));
		assertTrue(search(WILD25, WILDT, AVOID_WILDERNESS, account).reached());
	}

	private static ExactForwardSearch.Result search(int start, int target, SearchRestrictions restrictions)
	{
		return search(start, target, restrictions, account());
	}

	private static ExactForwardSearch.Result search(int start, int target, SearchRestrictions restrictions,
		PreparedRoutingAccount account)
	{
		TargetOverlay overlay = new TargetOverlay(new SiteGraph(routingStatic(), account), emptyCollision(), target);
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(overlay, ReverseLabels.compute(overlay));
		ExactForwardSearch.Result result = ExactForwardSearch.search(overlay, heuristic, start,
			() -> false, true, 1, restrictions);
		ExactForwardSearch.Result oracle = ExactForwardSearch.search(overlay, heuristic, start,
			() -> false, false, 1, restrictions);
		assertEquals("optimised search agrees with the unoptimised one", oracle.reached(), result.reached());
		assertEquals("optimised search agrees with the unoptimised one", oracle.cost(), result.cost());
		return result;
	}

	private static PreparedRoutingAccount account(Transport... transports)
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(transports),
			TransportAvailabilityFixture.of(), false, Set.of(), 0, true, ignored -> 0);
	}

	private static Transport local(int origin, int destination, int cost)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(cost).build();
	}

	private static Transport teleport(int destination, int maxWildernessLevel)
	{
		return new Transport.TransportBuilder().destination(destination).type(TransportType.TELEPORTATION_MINIGAME)
			.duration(2).maxWildernessLevel(maxWildernessLevel).build();
	}

	/**
	 * {@code SAFE2 - SAFE - WILD} walk each way, {@code WILDT} and {@code WILD25} reachable only by
	 * transport. Mask bit 2 steps to the next array element and bit 6 to the previous one, so the
	 * tiles need no real-world adjacency.
	 */
	private static RoutingStatic routingStatic()
	{
		int[] tiles = {SAFE2, SAFE, WILD, WILDT, WILD25};
		int n = tiles.length;
		int[] siteOffsets = new int[n + 1], componentMembers = new int[n], sparseOffsets = new int[n + 1];
		for (int i = 0; i < n; i++)
		{
			siteOffsets[i] = i;
			componentMembers[i] = i;
		}
		siteOffsets[n] = n;
		try
		{
			return RoutingStatic.create(tiles, new int[n], new byte[] {4, 68, 64, 0, 0},
				new int[] {-1, -1, -1, -1, -1}, new int[] {-1, -1, -1, -1, -1}, tiles, siteOffsets,
				new int[n], 1, new int[] {0, n}, componentMembers, new int[0], new int[0], new int[0],
				new int[0], n, n, 0, 0, 0, sparseOffsets, new int[0], new int[0]);
		}
		catch (java.io.IOException e)
		{
			throw new AssertionError(e);
		}
	}

	private static CollisionMap emptyCollision()
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
			{
				return new int[0];
			}

			@Override public boolean isBlocked(int x, int y, int z)
			{
				return false;
			}
		};
	}
}

package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.TransportAvailabilityFixture;

public class SparseManhattanTest
{
	private static final int A = WorldPointUtil.packWorldPoint(1000, 1000, 0);
	private static final int B = WorldPointUtil.packWorldPoint(1003, 1000, 0);
	private static final int C = WorldPointUtil.packWorldPoint(1003, 1004, 0);
	private static final int OTHER_PLANE = WorldPointUtil.packWorldPoint(1000, 1000, 1);
	private static final int TARGET = WorldPointUtil.packWorldPoint(1001, 1001, 0);

	@Test
	public void sparseSteinerLabelsMatchCliqueForSyntheticTarget() throws Exception
	{
		RoutingStatic stat = syntheticSparse();
		TargetOverlay target = new TargetOverlay(new SiteGraph(stat, emptyAccount()),
			attachments(A, OTHER_PLANE), TARGET);
		ReverseLabels sparse = ReverseLabels.computeSparse(target);
		ReverseLabels clique = ReverseLabels.computeClique(target);
		assertArrayEquals(clique.labels(), sparse.labels());
		assertTrue(sparse.sparse());
		assertTrue(sparse.sparseRelaxationCount() > 0);
		assertTrue(sparse.attachmentRelaxationCount() > 0);
		assertEquals(0, sparse.targetLabel(false));
	}

	@Test
	public void reducedGeneratorsMatchRawSeedsAndRetainOracle() throws Exception
	{
		RoutingStatic stat = syntheticSparse();
		TargetOverlay target = new TargetOverlay(new SiteGraph(stat, emptyAccount()),
			attachments(A, OTHER_PLANE), TARGET);
		ReverseLabels reverse = ReverseLabels.compute(target);
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(target, reverse);
		for (int packed : new int[] {A, B, C, TARGET, OTHER_PLANE,
			WorldPointUtil.packWorldPoint(1002, 1002, 0)})
		{
			assertEquals(heuristic.estimateRaw(packed, false, new int[] {0}),
				heuristic.estimate(packed, false, new int[] {0}));
			assertEquals(heuristic.estimateRaw(packed, true, new int[] {0}),
				heuristic.estimate(packed, true, new int[] {0}));
		}
		assertEquals(heuristic.rawSeedCount(), heuristic.seedCount(0, false) + heuristic.seedCount(0, true)
			+ heuristic.seedCount(1, false) + heuristic.seedCount(1, true));
		assertEquals(10, heuristic.rawSeedCount());
		assertEquals(4, heuristic.generatorCount());
		assertEquals(0.4, heuristic.generatorRatio(), 0.0);
		assertTrue(heuristic.generatorCount() <= heuristic.rawSeedCount());
		assertTrue(heuristic.generatorCount() > 0);
		assertTrue(heuristic.preparationNanos() >= 0);
	}

	private static RoutingStatic syntheticSparse() throws Exception
	{
		return RoutingStatic.create(new int[] {A, OTHER_PLANE}, new int[] {0, 1}, new byte[] {0, 0},
			new int[] {-1, -1}, new int[] {-1, -1}, new int[] {A, B, C, OTHER_PLANE},
			new int[] {0, 1, 2, 3, 4}, new int[] {0, 0, 0, 1}, 2, new int[] {0, 3, 4},
			new int[] {0, 1, 2, 3}, new int[0], new int[0], new int[0], new int[0], 4, 5, 1, 3, 6,
			new int[] {0, 1, 2, 3, 3, 6}, new int[] {4, 4, 4, 0, 1, 2}, new int[] {6, 0, 8, 6, 0, 8});
	}

	private static CollisionMap attachments(int... sites)
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
			{
				return sites.clone();
			}

			@Override public boolean isBlocked(int x, int y, int z)
			{
				return false;
			}
		};
	}

	private static PreparedRoutingAccount emptyAccount()
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(), TransportAvailabilityFixture.of(),
			false, java.util.Set.of(), 0, true, ignored -> 0);
	}
}

package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import org.junit.Test;
import shortestpath.WorldPointUtil;

/** Synthetic correctness tests for {@link SparseWalkingNetworkBuilder}. */
public class SparseWalkingNetworkBuilderTest
{
	private static final int INF = Integer.MAX_VALUE;

	@Test
	public void emptyInputProducesEmptyNetwork()
	{
		SparseWalkingNetworkBuilder.Result result =
			SparseWalkingNetworkBuilder.build(new int[0], new int[] {0}, new int[0]);
		assertEquals(0, result.originalCount);
		assertEquals(0, result.vertexCount);
		assertEquals(0, result.steinerCount);
		assertEquals(0, result.undirectedEdgeCount);
		assertArrayEquals(new int[] {0}, result.offsets);
		assertArrayEquals(new int[0], result.destinations);
		assertArrayEquals(new int[0], result.weights);
	}

	@Test
	public void singleSiteProducesSingleIsolatedVertex()
	{
		int tile = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		SparseWalkingNetworkBuilder.Result result =
			SparseWalkingNetworkBuilder.build(new int[] {tile}, new int[] {0, 1}, new int[] {0});
		assertEquals(1, result.originalCount);
		assertEquals(1, result.vertexCount);
		assertEquals(0, result.steinerCount);
		assertEquals(0, result.undirectedEdgeCount);
		assertArrayEquals(new int[] {0, 0}, result.offsets);
	}

	@Test
	public void siteWithNoComponentAttachmentIsIsolated()
	{
		int a = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		int b = WorldPointUtil.packWorldPoint(1010, 1000, 0);
		// Site 0 has no component attachments (empty range); site 1 attaches to component 0 alone.
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(
			new int[] {a, b}, new int[] {0, 0, 1}, new int[] {0});
		assertEquals(2, result.originalCount);
		assertEquals(2, result.vertexCount);
		assertEquals(0, result.steinerCount);
		assertEquals(0, result.undirectedEdgeCount);
	}

	@Test
	public void distancesEqualDoubledChebyshevWithinOneComponent()
	{
		int[] xs = {1000, 1003, 1003, 998, 1050, 1000, 1200};
		int[] ys = {1000, 1000, 1004, 990, 1050, 1200, 900};
		int[] tiles = new int[xs.length];
		for (int i = 0; i < xs.length; i++)
		{
			tiles[i] = WorldPointUtil.packWorldPoint(xs[i], ys[i], 0);
		}
		int[] offsets = new int[tiles.length + 1];
		int[] ids = new int[tiles.length];
		for (int i = 0; i < tiles.length; i++)
		{
			offsets[i + 1] = i + 1;
			ids[i] = 0;
		}
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(tiles.length, result.originalCount);
		assertTrue(result.vertexCount >= result.originalCount);
		assertEquals(result.vertexCount - result.originalCount, result.steinerCount);
		assertEquals(result.undirectedEdgeCount * 2, result.destinations.length);

		for (int i = 0; i < tiles.length; i++)
		{
			for (int j = 0; j < tiles.length; j++)
			{
				if (i == j)
				{
					continue;
				}
				int expected = 2 * WorldPointUtil.distanceBetween(tiles[i], tiles[j]);
				int actual = dijkstra(result, i, j);
				assertEquals("distance " + i + "->" + j, expected, actual);
			}
		}
	}

	@Test
	public void coincidentSitesAreConnectedByZeroWeightEdges()
	{
		int tile = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		int[] tiles = {tile, tile, tile};
		int[] offsets = {0, 1, 2, 3};
		int[] ids = {0, 0, 0};
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(3, result.originalCount);
		assertEquals(3, result.vertexCount);
		assertEquals(0, result.steinerCount);
		assertEquals(2, result.undirectedEdgeCount);
		for (int i = 0; i < 3; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				if (i != j)
				{
					assertEquals(0, dijkstra(result, i, j));
				}
			}
		}
	}

	@Test
	public void differentComponentsDoNotConnect()
	{
		int a = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		int b = WorldPointUtil.packWorldPoint(1005, 1000, 0);
		int c = WorldPointUtil.packWorldPoint(1000, 1000, 1);
		int d = WorldPointUtil.packWorldPoint(1005, 1000, 1);
		// Sites 0,1 -> component 0 (plane 0). Sites 2,3 -> component 1 (plane 1, same x/y).
		int[] tiles = {a, b, c, d};
		int[] offsets = {0, 1, 2, 3, 4};
		int[] ids = {0, 0, 1, 1};
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(4, result.originalCount);
		assertEquals(INF, dijkstra(result, 0, 2));
		assertEquals(INF, dijkstra(result, 0, 3));
		assertEquals(INF, dijkstra(result, 1, 2));
		assertEquals(INF, dijkstra(result, 1, 3));
		assertEquals(2 * WorldPointUtil.distanceBetween(a, b), dijkstra(result, 0, 1));
		assertEquals(2 * WorldPointUtil.distanceBetween(c, d), dijkstra(result, 2, 3));
	}

	@Test
	public void multiComponentSiteBridgesBothTrees()
	{
		int a = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		int bridge = WorldPointUtil.packWorldPoint(1010, 1000, 0);
		int c = WorldPointUtil.packWorldPoint(1020, 1000, 0);
		int[] tiles = {a, bridge, c};
		// site 1 (bridge) attaches to both component 0 and component 1; sites 0 and 2 attach to
		// only one of them each, mirroring a site straddling two routing components.
		int[] offsets = {0, 1, 3, 4};
		int[] ids = {0, 0, 1, 1};
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(3, result.originalCount);
		assertEquals(2 * WorldPointUtil.distanceBetween(a, bridge), dijkstra(result, 0, 1));
		assertEquals(2 * WorldPointUtil.distanceBetween(bridge, c), dijkstra(result, 1, 2));
		// 0 and 2 are never members of the same component's tree, but the bridge site is a
		// vertex shared by both trees, so a path can still transit through it.
		assertEquals(2 * WorldPointUtil.distanceBetween(a, c), dijkstra(result, 0, 2));
	}

	@Test
	public void buildIsDeterministic()
	{
		int[] xs = {1000, 1003, 1003, 998, 1050, 1000, 1200, 1007, 995, 1300};
		int[] ys = {1000, 1000, 1004, 990, 1050, 1200, 900, 1002, 1500, 700};
		int[] tiles = new int[xs.length];
		for (int i = 0; i < xs.length; i++)
		{
			tiles[i] = WorldPointUtil.packWorldPoint(xs[i], ys[i], 0);
		}
		int[] offsets = new int[tiles.length + 1];
		int[] ids = new int[tiles.length];
		for (int i = 0; i < tiles.length; i++)
		{
			offsets[i + 1] = i + 1;
			ids[i] = 0;
		}
		SparseWalkingNetworkBuilder.Result first = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		SparseWalkingNetworkBuilder.Result second = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(first.originalCount, second.originalCount);
		assertEquals(first.vertexCount, second.vertexCount);
		assertEquals(first.steinerCount, second.steinerCount);
		assertEquals(first.undirectedEdgeCount, second.undirectedEdgeCount);
		assertArrayEquals(first.offsets, second.offsets);
		assertArrayEquals(first.destinations, second.destinations);
		assertArrayEquals(first.weights, second.weights);
	}

	private static void assertArrayEquals(int[] expected, int[] actual)
	{
		assertTrue("expected " + Arrays.toString(expected) + " but was " + Arrays.toString(actual),
			Arrays.equals(expected, actual));
	}

	/** Plain O(V^2) Dijkstra over the built CSR graph, for small test graphs only. */
	private static int dijkstra(SparseWalkingNetworkBuilder.Result net, int source, int target)
	{
		int[] dist = new int[net.vertexCount];
		Arrays.fill(dist, INF);
		dist[source] = 0;
		boolean[] settled = new boolean[net.vertexCount];
		for (int iteration = 0; iteration < net.vertexCount; iteration++)
		{
			int best = -1;
			int bestDist = INF;
			for (int v = 0; v < net.vertexCount; v++)
			{
				if (!settled[v] && dist[v] < bestDist)
				{
					bestDist = dist[v];
					best = v;
				}
			}
			if (best < 0)
			{
				break;
			}
			settled[best] = true;
			for (int edge = net.offsets[best]; edge < net.offsets[best + 1]; edge++)
			{
				int next = net.destinations[edge];
				int candidate = dist[best] + net.weights[edge];
				if (candidate < dist[next])
				{
					dist[next] = candidate;
				}
			}
		}
		return dist[target];
	}
}

package shortestpath.pathfinder.exact;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.SplitFlagMap;

/**
 * A small, entirely in-memory {@link CollisionMap} for {@link RoutingStaticBuilder} unit tests.
 * Every world-scanning entry point {@link RoutingStaticBuilder} uses is overridable on
 * {@link CollisionMap} for exactly this reason: {@link #regionExtent()},
 * {@link #getRegionPlaneCounts(int)}, {@link #isBlocked(int, int, int)},
 * {@link #ordinaryWalkingMask(int)} and {@link #ordinaryWalkingNeighbors(int)}. This class
 * therefore never touches a real {@link SplitFlagMap} or its shared static region-extent state.
 *
 * <p>Test worlds declare walkable tiles and an explicit, small adjacency list per tile (the test
 * author is responsible for keeping it symmetric, exactly like real collision data: if {@code b}
 * is a declared neighbour of {@code a}, {@code a} must also be a declared neighbour of {@code b}).
 * Only ordinary 8-directional adjacency is modelled; no transport-blocked-origin behaviour is
 * needed since {@link RoutingStaticBuilder} never uses that path.
 */
final class SyntheticCollisionMap extends CollisionMap
{
	// Matches CollisionMap.ordinaryWalkingNeighbors's own bit layout exactly (0-N..7-NW).
	private static final int[] DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private final Set<Integer> walkable;
	private final Map<Integer, int[]> neighbors;
	private final SplitFlagMap.RegionExtent extent;
	private final int planeCount;

	SyntheticCollisionMap(Set<Integer> walkableTiles, Map<Integer, int[]> neighborOverrides, int planeCount)
	{
		super(null);
		this.walkable = walkableTiles;
		this.neighbors = new HashMap<>(neighborOverrides);
		this.extent = new SplitFlagMap.RegionExtent(0, 0, 0, 0);
		this.planeCount = planeCount;
	}

	@Override
	public SplitFlagMap.RegionExtent regionExtent()
	{
		return extent;
	}

	@Override
	public byte getRegionPlaneCounts(int regionIndex)
	{
		return regionIndex == 0 ? (byte) planeCount : 0;
	}

	@Override
	public boolean isBlocked(int x, int y, int z)
	{
		return !walkable.contains(WorldPointUtil.packWorldPoint(x, y, z));
	}

	@Override
	public byte ordinaryWalkingMask(int packedPoint)
	{
		if (!walkable.contains(packedPoint))
		{
			return 0;
		}
		int x = WorldPointUtil.unpackWorldX(packedPoint);
		int y = WorldPointUtil.unpackWorldY(packedPoint);
		int z = WorldPointUtil.unpackWorldPlane(packedPoint);
		int[] declared = neighbors.getOrDefault(packedPoint, new int[0]);
		int mask = 0;
		for (int bit = 0; bit < 8; bit++)
		{
			int candidate = WorldPointUtil.packWorldPoint(x + DX[bit], y + DY[bit], z);
			if (contains(declared, candidate))
			{
				mask |= 1 << bit;
			}
		}
		return (byte) mask;
	}

	@Override
	public int[] ordinaryWalkingNeighbors(int packedPoint)
	{
		return neighbors.getOrDefault(packedPoint, new int[0]).clone();
	}

	private static boolean contains(int[] values, int target)
	{
		for (int value : values)
		{
			if (value == target)
			{
				return true;
			}
		}
		return false;
	}

	/** Builds symmetric adjacency from an explicit list of open, undirected tile-pair edges. */
	static Map<Integer, int[]> symmetricAdjacency(int[][] edges)
	{
		Map<Integer, java.util.List<Integer>> adjacency = new HashMap<>();
		for (int[] edge : edges)
		{
			adjacency.computeIfAbsent(edge[0], k -> new java.util.ArrayList<>()).add(edge[1]);
			adjacency.computeIfAbsent(edge[1], k -> new java.util.ArrayList<>()).add(edge[0]);
		}
		Map<Integer, int[]> result = new HashMap<>();
		for (Map.Entry<Integer, java.util.List<Integer>> entry : adjacency.entrySet())
		{
			result.put(entry.getKey(), entry.getValue().stream().mapToInt(Integer::intValue).toArray());
		}
		return result;
	}
}

package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.TransportAvailabilityFixture;

/**
 * Covers {@link TargetWalkDistances}: the reverse-BFS walking bound a synthetic target's
 * attachment edges use instead of a bare Chebyshev distance. Earlier fixtures never ran it —
 * their synthetic targets were not search tiles ({@code search()} returned null) or their targets
 * were static sites — so these tests use a U-shaped corridor whose dead end is far closer in a
 * straight line than on foot:
 *
 * <pre>
 *   y=12:  T --+--+--+--+
 *   y=11:              |
 *   y=10:  B +--+--+--+
 * </pre>
 */
public class TargetWalkDistancesTest
{
	private static final int TARGET = tile(10, 12);
	private static final int BANK = tile(10, 10);
	/** A blocked nook east of the corridor, a stand-in for a site on a non-search tile. */
	private static final int POCKET_BANK = tile(15, 10);
	/** A blocked tile inside the bend, a stand-in for a non-search-tile target. */
	private static final int BLOCKED_TARGET = tile(11, 11);
	/** The corridor in walking-distance order from TARGET, so CORRIDOR[i] is i steps away. */
	private static final int[] CORRIDOR =
	{
		tile(10, 12), tile(11, 12), tile(12, 12), tile(13, 12), tile(14, 12),
		tile(14, 11),
		tile(14, 10), tile(13, 10), tile(12, 10), tile(11, 10), tile(10, 10)
	};

	private static int tile(int x, int y)
	{
		return WorldPointUtil.packWorldPoint(x, y, 0);
	}

	private static SyntheticCollisionMap corridorCollision()
	{
		int[][] edges = new int[CORRIDOR.length - 1][];
		for (int i = 1; i < CORRIDOR.length; i++)
		{
			edges[i - 1] = new int[] {CORRIDOR[i - 1], CORRIDOR[i]};
		}
		Map<Integer, int[]> adjacency = SyntheticCollisionMap.symmetricAdjacency(edges);
		// One-way declarations for the blocked tiles: attachment lookups see the corridor as their
		// neighbour, without corridor tiles gaining an edge into a blocked tile.
		adjacency.put(POCKET_BANK, new int[] {tile(14, 10)});
		adjacency.put(BLOCKED_TARGET, new int[] {tile(11, 12), tile(12, 12)});
		return new SyntheticCollisionMap(new HashSet<>(Arrays.asList(
			Arrays.stream(CORRIDOR).boxed().toArray(Integer[]::new))), adjacency, 1);
	}

	private static RoutingStatic corridorStatic(boolean withCut) throws Exception
	{
		int[] cuts = withCut ? new int[] {tile(14, 10), tile(14, 11)} : new int[0];
		return RoutingStaticBuilder.build(corridorCollision(), Map.of(), Set.of(BANK, POCKET_BANK), cuts, BANK)
			.routingStatic;
	}

	private static int[] targetComponents(RoutingStatic stat)
	{
		return new int[] {stat.routingComponent(stat.searchIndex(TARGET))};
	}

	private static TargetOverlay overlay(RoutingStatic stat, int target)
	{
		return new TargetOverlay(new SiteGraph(stat, account()), corridorCollision(), target);
	}

	private static PreparedRoutingAccount account()
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(),
			TransportAvailabilityFixture.of(), false, Set.of(), 0, true, ignored -> 0);
	}

	@Test
	public void searchRunsOnlyForSearchTileTargets() throws Exception
	{
		RoutingStatic stat = corridorStatic(false);

		assertNotNull(TargetWalkDistances.search(stat, TARGET, targetComponents(stat)));
		assertNull(TargetWalkDistances.search(stat, BLOCKED_TARGET, targetComponents(stat)));
	}

	@Test
	public void windingCorridorSitesGetWalkDistanceNotChebyshev() throws Exception
	{
		RoutingStatic stat = corridorStatic(false);
		TargetWalkDistances walk = TargetWalkDistances.search(stat, TARGET, targetComponents(stat));

		assertNotNull(walk);
		for (int i = 0; i < CORRIDOR.length; i++)
		{
			int chebyshev = WorldPointUtil.distanceBetween(TARGET, CORRIDOR[i]);
			assertEquals(Math.max(chebyshev, i), walk.bound(CORRIDOR[i], chebyshev));
		}
		// The far end of the corridor: straight-line distance 2, walking distance 10.
		assertEquals(10, walk.bound(BANK, 2));
		// A site on a blocked tile steps to its nearest reached search-tile neighbour first:
		// (14,11) at distance 5 bounds it at 6, above the Chebyshev 5.
		assertEquals(6, walk.bound(POCKET_BANK, WorldPointUtil.distanceBetween(TARGET, POCKET_BANK)));
	}

	@Test
	public void overlayAttachmentsUseTheWalkingBound() throws Exception
	{
		RoutingStatic stat = corridorStatic(false);
		TargetOverlay overlay = overlay(stat, TARGET);

		assertTrue(overlay.synthetic());
		assertEquals(2, overlay.attachmentCount());
		for (int i = 0; i < overlay.attachmentCount(); i++)
		{
			int site = stat.siteTile(overlay.attachmentSite(i));
			if (site == BANK)
			{
				assertEquals(10, overlay.attachmentCost(i));
			}
			else if (site == POCKET_BANK)
			{
				assertEquals(6, overlay.attachmentCost(i));
			}
			else
			{
				fail("unexpected attachment site " + site);
			}
		}
	}

	@Test
	public void blockedTargetKeepsChebyshevAttachments() throws Exception
	{
		RoutingStatic stat = corridorStatic(false);
		TargetOverlay overlay = overlay(stat, BLOCKED_TARGET);

		assertTrue(overlay.synthetic());
		assertEquals(2, overlay.attachmentCount());
		for (int i = 0; i < overlay.attachmentCount(); i++)
		{
			assertEquals(WorldPointUtil.distanceBetween(BLOCKED_TARGET, stat.siteTile(overlay.attachmentSite(i))),
				overlay.attachmentCost(i));
		}
	}

	@Test
	public void walkBoundStaysInsideTheTargetRoutingComponent() throws Exception
	{
		RoutingStatic stat = corridorStatic(true);
		TargetOverlay overlay = overlay(stat, TARGET);

		// The cut makes the bottom row a second routing component: only the (14,11) crossing
		// endpoint attaches to the target's component, at its real walking distance 5.
		assertEquals(1, overlay.attachmentCount());
		assertEquals(tile(14, 11), stat.siteTile(overlay.attachmentSite(0)));
		assertEquals(5, overlay.attachmentCost(0));

		// Tiles beyond the cut are never reached: their bound is the exhausted frontier's
		// distance (last reached distance 5, plus one).
		TargetWalkDistances walk = TargetWalkDistances.search(stat, TARGET, targetComponents(stat));
		assertEquals(6, walk.bound(BANK, WorldPointUtil.distanceBetween(TARGET, BANK)));
		assertEquals(6, walk.bound(POCKET_BANK, WorldPointUtil.distanceBetween(TARGET, POCKET_BANK)));
	}

	@Test
	public void raisedBoundsKeepTheSearchExact() throws Exception
	{
		List<Integer> corridor = Arrays.stream(CORRIDOR).boxed().collect(Collectors.toList());
		java.util.Collections.reverse(corridor);
		for (boolean cut : new boolean[] {false, true})
		{
			RoutingStatic stat = corridorStatic(cut);
			TargetOverlay overlay = overlay(stat, TARGET);

			ExactForwardSearch.Result result = ExactForwardSearch.search(overlay,
				PreparedHeuristic.prepare(overlay, ReverseLabels.compute(overlay)), BANK);

			assertTrue(result.reached());
			assertEquals(10, result.cost());
			assertEquals(corridor, result.path().stream()
				.map(PathStep::getPackedPosition).collect(Collectors.toList()));
			assertTrue(result.counters().heuristicCacheHits() > 0);
		}
	}
}

package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.AbstractNodeKind;
import shortestpath.pathfinder.WildernessChecker;

public class TeleportCapabilityTest
{
	/** Legacy's global-teleport band for a tile, as {@code Pathfinder.updateWildernessLevel} narrows it. */
	private static AbstractNodeKind legacyKind(int tile)
	{
		return WildernessChecker.isInLevel30Wilderness(tile) ? AbstractNodeKind.GLOBAL_TELEPORTS_OVER_30
			: WildernessChecker.isInLevel20Wilderness(tile) ? AbstractNodeKind.GLOBAL_TELEPORTS_OVER_20
			: WildernessChecker.isInWilderness(tile) ? AbstractNodeKind.GLOBAL_TELEPORTS_OVER_0
			: AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL;
	}

	@Test
	public void capabilityIsLegacysGlobalTeleportBand()
	{
		for (int plane = 0; plane < 4; plane += 3)
			for (int x = 2900; x < 3500; x++)
				for (int[] ys : new int[][] {{3500, 4250}, {9890, 10420}})
					for (int y = ys[0]; y < ys[1]; y++)
					{
						int tile = WorldPointUtil.packWorldPoint(x, y, plane);
						AbstractNodeKind legacy = legacyKind(tile);
						TeleportCapability capability = TeleportCapability.at(tile);
						assertEquals(x + "," + y + "," + plane, legacy.maxWildernessLevel(), capability.castLevel());
					}
	}

	@Test
	public void bandBoundaries()
	{
		// Wilderness level is (y - 3520) / 8 + 1 above ground, from y = 3525.
		assertEquals(TeleportCapability.ALL, at(3200, 3400));
		assertEquals(TeleportCapability.ALL, at(3200, 3524));
		assertEquals("level 1", TeleportCapability.OVER_0, at(3200, 3525));
		assertEquals("level 13, the obelisk landing", TeleportCapability.OVER_0, at(3156, 3620));
		assertEquals("level 20", TeleportCapability.OVER_0, at(3200, 3679));
		assertEquals("level 21", TeleportCapability.OVER_20, at(3200, 3680));
		assertEquals("level 25", TeleportCapability.OVER_20, at(3200, 3712));
		assertEquals("level 30", TeleportCapability.OVER_20, at(3200, 3759));
		assertEquals("level 31", TeleportCapability.OVER_30, at(3200, 3760));
		assertEquals("Ferox Enclave is not wilderness", TeleportCapability.ALL, at(3130, 3630));
		assertEquals("underground level 1-20", TeleportCapability.OVER_0, at(3000, 10000));
	}

	@Test
	public void eachCapabilityCastsWhatTheOneBeforeItCan()
	{
		TeleportCapability[] order = {TeleportCapability.OVER_30, TeleportCapability.OVER_20,
			TeleportCapability.OVER_0, TeleportCapability.ALL};
		assertEquals(order.length, TeleportCapability.values().length);
		for (int i = 0; i < order.length; i++)
			for (int j = 0; j < order.length; j++)
				assertEquals(order[i] + " allows " + order[j], i >= j, order[i].allows(order[j]));
	}

	@Test
	public void teleportAreasAreWhereTheCapabilityAllowsCasting()
	{
		for (TeleportCapability capability : TeleportCapability.values())
		{
			WalkGoal area = WalkGoal.teleportArea(capability);
			for (int x = 2900; x < 3500; x += 7)
				for (int y = 3500; y < 4250; y += 3)
				{
					assertEquals(capability + " " + x + "," + y, TeleportCapability.at(x, y).allows(capability),
						area.contains(x, y));
					assertEquals(area.contains(x, y), WalkGoal.ticks(area.lowerBound(x, y)) == 0);
				}
		}
		WalkGoal over20 = WalkGoal.teleportArea(TeleportCapability.OVER_20);
		WalkGoal over0 = WalkGoal.teleportArea(TeleportCapability.OVER_0);
		WalkGoal all = WalkGoal.teleportArea(TeleportCapability.ALL);
		// Straight south out of level 30 wilderness; out of level 20 wilderness, west is nearer.
		assertEquals(41, WalkGoal.ticks(over20.lowerBound(3000, 3800)));
		assertEquals(3000 - 2943, WalkGoal.ticks(over0.lowerBound(3000, 3800)));
		assertEquals(3700 - 3679, WalkGoal.ticks(over0.lowerBound(3100, 3700)));
		// The level-30 area runs further north than the level-20 one.
		assertEquals(4208 - 4150, WalkGoal.ticks(over0.lowerBound(3200, 4150)));
		// From the level-13 obelisk landing, Ferox Enclave is five tiles north.
		assertEquals(5, WalkGoal.ticks(all.lowerBound(3156, 3620)));
	}

	@Test
	public void teleportAreaBoundNeverOverestimatesAroundFeroxEnclave()
	{
		WalkGoal all = WalkGoal.teleportArea(TeleportCapability.ALL);
		for (int x = 3100; x < 3180; x += 3)
			for (int y = 3590; y < 3670; y += 3)
			{
				int nearest = Integer.MAX_VALUE;
				for (int gx = x - 100; gx <= x + 100; gx++)
					for (int gy = y - 100; gy <= y + 100; gy++)
						if (all.contains(gx, gy))
							nearest = Math.min(nearest, Math.max(Math.abs(gx - x), Math.abs(gy - y)));
				assertTrue(x + "," + y, WalkGoal.ticks(all.lowerBound(x, y)) <= nearest);
			}
	}

	private static TeleportCapability at(int x, int y)
	{
		return TeleportCapability.at(WorldPointUtil.packWorldPoint(x, y, 0));
	}
}

package shortestpath.pathfinder.exact;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/** Global teleports are castable only where their own wilderness limit allows, as in legacy. */
public class WildernessGlobalTeleportTest
{
	private static final int OUTSIDE = WorldPointUtil.packWorldPoint(3200, 3400, 0);
	private static final int LEVEL_13 = WorldPointUtil.packWorldPoint(3156, 3620, 0);
	private static final int LEVEL_25 = WorldPointUtil.packWorldPoint(3200, 3712, 0);
	private static final int LEVEL_31 = WorldPointUtil.packWorldPoint(3200, 3760, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(2658, 3157, 0);
	private static final int WALK = 50;
	private static final int TELEPORT = 2;

	@Test
	public void preparedGlobalsFollowEachTeleportsLimit()
	{
		Transport limit0 = teleport(WorldPointUtil.packWorldPoint(1000, 1000, 0), 0);
		Transport limit20 = teleport(WorldPointUtil.packWorldPoint(1001, 1000, 0), 20);
		Transport limit30 = teleport(WorldPointUtil.packWorldPoint(1002, 1000, 0), 30);
		Transport seasonal = new Transport.TransportBuilder().destination(WorldPointUtil.packWorldPoint(1003, 1000, 0))
			.type(TransportType.SEASONAL_TRANSPORTS).duration(TELEPORT).maxWildernessLevel(60).build();
		PreparedRoutingAccount account = account(limit0, limit20, limit30, seasonal);

		// location -> {limit 0, limit 20, limit 30, seasonal (not a teleport type)}
		assertCastable(account, OUTSIDE, true, true, true, true);
		assertCastable(account, LEVEL_13, false, true, true, true);
		assertCastable(account, LEVEL_25, false, false, true, true);
		assertCastable(account, LEVEL_31, false, false, false, true);
	}

	@Test
	public void levelZeroTeleportIsNotCastAfterAnObeliskToLevel13()
	{
		// Deep wilderness start, obelisk to the level-13 landing: Fishing Trawler (level 0) is not castable there.
		Transport obelisk = local(LEVEL_31, LEVEL_13, 1);
		ExactForwardSearch.Result result = search(LEVEL_31, obelisk, local(LEVEL_13, TARGET, WALK), teleport(TARGET, 0));

		assertEquals(1 + WALK, result.cost());
		assertEquals(List.of(LEVEL_31, LEVEL_13, TARGET), tiles(result));
	}

	@Test
	public void level20TeleportIsCastAfterAnObeliskToLevel13()
	{
		ExactForwardSearch.Result result = search(LEVEL_31, local(LEVEL_31, LEVEL_13, 1), local(LEVEL_13, TARGET, WALK),
			teleport(TARGET, 20));

		assertEquals(1 + TELEPORT, result.cost());
	}

	@Test
	public void startingAtLevel13CastsOnlyTeleportsUsableThere()
	{
		assertEquals(WALK, search(LEVEL_13, local(LEVEL_13, TARGET, WALK), teleport(TARGET, 0)).cost());
		assertEquals(TELEPORT, search(LEVEL_13, local(LEVEL_13, TARGET, WALK), teleport(TARGET, 20)).cost());
		assertEquals(TELEPORT, search(LEVEL_13, local(LEVEL_13, TARGET, WALK), teleport(TARGET, 30)).cost());
	}

	@Test
	public void level25CastsOnlyLevel30Teleports()
	{
		assertEquals(WALK, search(LEVEL_25, local(LEVEL_25, TARGET, WALK), teleport(TARGET, 0)).cost());
		assertEquals(WALK, search(LEVEL_25, local(LEVEL_25, TARGET, WALK), teleport(TARGET, 20)).cost());
		assertEquals(TELEPORT, search(LEVEL_25, local(LEVEL_25, TARGET, WALK), teleport(TARGET, 30)).cost());
		// Reached rather than started at.
		assertEquals(1 + WALK, search(LEVEL_31, local(LEVEL_31, LEVEL_25, 1), local(LEVEL_25, TARGET, WALK),
			teleport(TARGET, 20)).cost());
		assertEquals(1 + TELEPORT, search(LEVEL_31, local(LEVEL_31, LEVEL_25, 1), local(LEVEL_25, TARGET, WALK),
			teleport(TARGET, 30)).cost());
	}

	@Test
	public void aboveLevel30NoTeleportIsCast()
	{
		for (int limit : new int[] {0, 20, 30})
			assertEquals("limit " + limit, WALK,
				search(LEVEL_31, local(LEVEL_31, TARGET, WALK), teleport(TARGET, limit)).cost());
	}

	@Test
	public void outsideTheWildernessEveryTeleportIsCast()
	{
		for (int limit : new int[] {0, 20, 30})
			assertEquals("limit " + limit, TELEPORT,
				search(OUTSIDE, local(OUTSIDE, TARGET, WALK), teleport(TARGET, limit)).cost());
	}

	private static void assertCastable(PreparedRoutingAccount account, int location, boolean... expected)
	{
		TeleportCapability capability = TeleportCapability.at(location);
		Set<Integer> castable = new HashSet<>();
		for (int i = 0; i < account.globalCount(capability, false); i++)
			castable.add(account.globalDestination(capability, false, i));
		for (int i = 0; i < expected.length; i++)
			assertEquals(capability + " destination " + i, expected[i],
				castable.contains(WorldPointUtil.packWorldPoint(1000 + i, 1000, 0)));
	}

	private static ExactForwardSearch.Result search(int start, Transport... transports)
	{
		PreparedRoutingAccount account = account(transports);
		TargetOverlay target = new TargetOverlay(new SiteGraph(routingStatic(), account), emptyCollision(), TARGET);
		ExactForwardSearch.Result result = ExactForwardSearch.search(target,
			PreparedHeuristic.prepare(target, ReverseLabels.compute(target)), start);
		assertTrue(result.reached());
		ExactForwardSearch.Result oracle = ExactForwardSearch.search(target,
			PreparedHeuristic.prepare(target, ReverseLabels.compute(target)), start, false);
		assertEquals("optimised search agrees with the unoptimised one", oracle.cost(), result.cost());
		return result;
	}

	private static List<Integer> tiles(ExactForwardSearch.Result result)
	{
		return result.path().stream().map(PathStep::getPackedPosition).collect(java.util.stream.Collectors.toList());
	}

	private static PreparedRoutingAccount account(Transport... transports)
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(transports),
			TransportAvailabilityFixture.of(), false, Set.of(), 0, true, ignored -> 0);
	}

	private static Transport local(int origin, int destination, int cost)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(cost).build();
	}

	private static Transport teleport(int destination, int maxWildernessLevel)
	{
		return new Transport.TransportBuilder().destination(destination).type(TransportType.TELEPORTATION_MINIGAME)
			.duration(TELEPORT).maxWildernessLevel(maxWildernessLevel).build();
	}

	/** One site per tile, no walking: every move is a transport. */
	private static RoutingStatic routingStatic()
	{
		int[] sites = {OUTSIDE, LEVEL_13, LEVEL_25, LEVEL_31, TARGET};
		sites = Arrays.stream(sites).map(t -> t ^ Integer.MIN_VALUE).sorted().map(t -> t ^ Integer.MIN_VALUE).toArray();
		int n = sites.length;
		int[] offsets = new int[n + 1], ids = new int[n], members = new int[n];
		for (int i = 0; i <= n; i++) offsets[i] = i;
		for (int i = 0; i < n; i++) members[i] = i;
		try
		{
			return RoutingStatic.create(new int[0], new int[0], new byte[0], new int[0], new int[0], sites, offsets,
				ids, 1, new int[] {0, n}, members, new int[0], new int[0], new int[0], new int[0], n, n, 0, 0, 0,
				new int[n + 1], new int[0], new int[0]);
		}
		catch (java.io.IOException e)
		{
			throw new AssertionError(e);
		}
	}

	private static CollisionMap emptyCollision()
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
			{ return new int[0];
			}
			@Override public boolean isBlocked(int x, int y, int z)
			{ return false;
			}
		};
	}
}

package shortestpath.transport;

import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.ItemVariations;
import shortestpath.transport.requirement.ItemRequirement;
import shortestpath.transport.requirement.TransportItems;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class BankPickupRequirementsTest
{
	private static final int POUCH_AIR = 1;
	private static final int NO_POUCH = -1;
	private static final int[] NO_SUBSTITUTES = new int[0];
	// Falador Teleport: 1 law, 3 air, 1 water
	private static final Transport FALADOR_TELEPORT = teleport(
		rune(ItemVariations.LAW_RUNE, 1), rune(ItemVariations.AIR_RUNE, 3), rune(ItemVariations.WATER_RUNE, 1));
	private static final Transport THREE_AIR = teleport(rune(ItemVariations.AIR_RUNE, 3));
	private static final Transport SHANTAY_GATE = teleport(new ItemRequirement(List.of(
		new ItemRequirement.Branch(ItemVariations.SHANTAY_PASS.getIds(), null, null, 1),
		new ItemRequirement.Branch(ItemVariations.COINS.getIds(), null, null, 5))));

	@Mock
	private Client client;
	@Mock
	private ItemContainer inventory;
	@Mock
	private ItemContainer equipment;
	@Mock
	private EnumComposition runePouchEnum;
	@Mock
	private ItemComposition airRune;
	@Mock
	private ItemComposition waterRune;

	private final Map<Integer, Integer> playerHas = new HashMap<>();
	private final Map<Integer, Integer> bankHas = new HashMap<>();
	private final Map<Integer, Integer> bankPouchRunes = new HashMap<>();

	@Test
	public void collectPlayerItemsCountsInventoryEquipmentAndRunePouch()
	{
		setupPlayerItems();
		when(client.getEnum(EnumID.RUNEPOUCH_RUNE)).thenReturn(runePouchEnum);
		when(runePouchEnum.getIntValue(POUCH_AIR)).thenReturn(ItemID.AIRRUNE);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1)).thenReturn(POUCH_AIR);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_1)).thenReturn(5);

		Map<Integer, Integer> collected = BankPickupRequirements.collectPlayerItems(client);

		assertEquals(Integer.valueOf(15), collected.get(ItemID.AIRRUNE));
		assertEquals(Integer.valueOf(1), collected.get(ItemID.STAFF_OF_FIRE));
		assertEquals(Integer.valueOf(1), collected.get(ItemID.BH_RUNE_POUCH));
	}

	@Test
	public void pickupAsksOnlyForTheShortfall()
	{
		when(client.getItemDefinition(ItemID.AIRRUNE)).thenReturn(airRune);
		when(client.getItemDefinition(ItemID.WATERRUNE)).thenReturn(waterRune);
		when(airRune.getName()).thenReturn("Air rune");
		when(waterRune.getName()).thenReturn("Water rune");
		playerHas.put(ItemID.LAWRUNE, 1);
		playerHas.put(ItemID.AIRRUNE, 2);
		bankHas.put(ItemID.AIRRUNE, 1000);
		bankHas.put(ItemID.WATERRUNE, 1000);

		Map<Integer, Long> pickups = pickups(FALADOR_TELEPORT, NO_POUCH);

		assertEquals("1 Air rune, 1 Water rune", BankPickupRequirements.formatPickups(client, pickups));
	}

	@Test
	public void bankHoldingOnlyTheShortfallCanSupplyIt()
	{
		// The pathfinder routes via the bank for 2 carried + 1 banked air, so the hint must too
		playerHas.put(ItemID.LAWRUNE, 1);
		playerHas.put(ItemID.AIRRUNE, 2);
		bankHas.put(ItemID.AIRRUNE, 1);
		bankHas.put(ItemID.WATERRUNE, 1);

		assertEquals(Map.of(ItemID.AIRRUNE, 1L, ItemID.WATERRUNE, 1L), pickups(FALADOR_TELEPORT, NO_POUCH));
	}

	@Test
	public void pureRuneIsPreferredAmongCarriedVariants()
	{
		// Both carried variants can be topped up; air comes first in the variations
		playerHas.put(ItemID.AIRRUNE, 1);
		playerHas.put(ItemID.DUSTRUNE, 1);
		bankHas.put(ItemID.AIRRUNE, 1000);
		bankHas.put(ItemID.DUSTRUNE, 1000);

		assertEquals(Map.of(ItemID.AIRRUNE, 2L), pickups(THREE_AIR, NO_POUCH));
	}

	@Test
	public void carriedCombinationRuneIsToppedUpBeforePureRune()
	{
		// Topping up the 2 carried dust saves a slot over bringing 3 air
		playerHas.put(ItemID.DUSTRUNE, 2);
		bankHas.put(ItemID.AIRRUNE, 1000);
		bankHas.put(ItemID.DUSTRUNE, 1000);

		assertEquals(Map.of(ItemID.DUSTRUNE, 1L), pickups(THREE_AIR, NO_POUCH));
	}

	@Test
	public void pureRuneIsUsedWhenCarriedVariantCannotBeToppedUp()
	{
		playerHas.put(ItemID.DUSTRUNE, 2);
		bankHas.put(ItemID.AIRRUNE, 1000);

		assertEquals(Map.of(ItemID.AIRRUNE, 3L), pickups(THREE_AIR, NO_POUCH));
	}

	@Test
	public void combinationRuneIsUsedWhenNoPureRuneCovers()
	{
		// The player carries 2 dust, so only dust tops them up: show dust, not air
		playerHas.put(ItemID.DUSTRUNE, 2);
		bankHas.put(ItemID.DUSTRUNE, 1);

		assertEquals(Map.of(ItemID.DUSTRUNE, 1L), pickups(THREE_AIR, NO_POUCH));
	}

	@Test
	public void combinationRuneNotCarriedIsShownAsThePureRune()
	{
		bankHas.put(ItemID.DUSTRUNE, 3);

		assertEquals(Map.of(ItemID.AIRRUNE, 3L), pickups(THREE_AIR, NO_POUCH));
	}

	@Test
	public void bankHoldingLessThanTheShortfallCannotSupplyIt()
	{
		playerHas.put(ItemID.AIRRUNE, 1);
		bankHas.put(ItemID.AIRRUNE, 1);

		assertNull(pickups(THREE_AIR, NO_POUCH));
	}

	@Test
	public void bankPouchShortOfTheShortfallFallsBackToLooseRunes()
	{
		bankHas.put(ItemID.BH_RUNE_POUCH, 1);
		bankHas.put(ItemID.AIRRUNE, 3);
		bankPouchRunes.put(ItemID.AIRRUNE, 2);

		assertEquals(Map.of(ItemID.AIRRUNE, 3L), pickups(THREE_AIR, ItemID.BH_RUNE_POUCH));
		assertEquals(Set.of(ItemID.AIRRUNE), highlighted(THREE_AIR, ItemID.BH_RUNE_POUCH));
	}

	@Test
	public void bankPouchAndLooseRunesCombineForOneShortfall()
	{
		// Neither the pouch's 2 air nor the 1 loose air covers 3 alone, but together they do,
		// as the pathfinder's bank path already counts them
		bankHas.put(ItemID.BH_RUNE_POUCH, 1);
		bankHas.put(ItemID.AIRRUNE, 1);
		bankPouchRunes.put(ItemID.AIRRUNE, 2);

		assertEquals(Map.of(ItemID.BH_RUNE_POUCH, 1L, ItemID.AIRRUNE, 1L), pickups(THREE_AIR, ItemID.BH_RUNE_POUCH));
		assertEquals(Set.of(ItemID.BH_RUNE_POUCH, ItemID.AIRRUNE), highlighted(THREE_AIR, ItemID.BH_RUNE_POUCH));
	}

	@Test
	public void bankPouchAndLooseRunesStillShortGiveNoPickup()
	{
		bankHas.put(ItemID.BH_RUNE_POUCH, 1);
		bankHas.put(ItemID.AIRRUNE, 1);
		bankPouchRunes.put(ItemID.AIRRUNE, 1);

		assertNull(pickups(THREE_AIR, ItemID.BH_RUNE_POUCH));
	}

	@Test
	public void bankPouchCoveringTheShortfallIsPreferredOnce()
	{
		playerHas.put(ItemID.LAWRUNE, 1);
		playerHas.put(ItemID.AIRRUNE, 2);
		bankHas.put(ItemID.BH_RUNE_POUCH, 1);
		bankHas.put(ItemID.AIRRUNE, 5);
		bankHas.put(ItemID.WATERRUNE, 5);
		bankPouchRunes.put(ItemID.AIRRUNE, 1);
		bankPouchRunes.put(ItemID.WATERRUNE, 1);

		// One pouch covers both air and water
		assertEquals(Map.of(ItemID.BH_RUNE_POUCH, 1L), pickups(FALADOR_TELEPORT, ItemID.BH_RUNE_POUCH));
	}

	@Test
	public void bankPouchRunesCountTowardOtherShortfallsOnceTaken()
	{
		// The pouch is taken for law and water, so its 2 air leave a shortfall of 1 air
		bankHas.put(ItemID.BH_RUNE_POUCH, 1);
		bankHas.put(ItemID.AIRRUNE, 1000);
		bankPouchRunes.put(ItemID.LAWRUNE, 1);
		bankPouchRunes.put(ItemID.AIRRUNE, 2);
		bankPouchRunes.put(ItemID.WATERRUNE, 1);

		assertEquals(Map.of(ItemID.BH_RUNE_POUCH, 1L, ItemID.AIRRUNE, 1L),
			pickups(FALADOR_TELEPORT, ItemID.BH_RUNE_POUCH));
		assertEquals(Set.of(ItemID.BH_RUNE_POUCH, ItemID.AIRRUNE),
			highlighted(FALADOR_TELEPORT, ItemID.BH_RUNE_POUCH));
	}

	@Test
	public void highlightingUsesTheShortfall()
	{
		// 1 banked air covers the shortfall; 2 banked dust do not (none carried, so 3 needed).
		// No water in the bank, so the bank can't supply the teleport, but the air is still highlighted.
		playerHas.put(ItemID.LAWRUNE, 1);
		playerHas.put(ItemID.AIRRUNE, 2);
		bankHas.put(ItemID.AIRRUNE, 1);
		bankHas.put(ItemID.DUSTRUNE, 2);

		assertNull(pickups(FALADOR_TELEPORT, NO_POUCH));
		assertEquals(Set.of(ItemID.AIRRUNE), highlighted(FALADOR_TELEPORT, NO_POUCH));
	}

	@Test
	public void carriedShantayPassNeedsNoBankPickup()
	{
		playerHas.put(ItemID.SHANTAY_PASS, 1);
		bankHas.put(ItemID.COINS, 100);

		assertEquals(Map.of(), pickups(SHANTAY_GATE, NO_POUCH));
		assertEquals(Set.of(), highlighted(SHANTAY_GATE, NO_POUCH));
		assertTrue(BankPickupRequirements.transportSatisfiedBy(SHANTAY_GATE, playerHas));
	}

	@Test
	public void bankCoinsAloneArePickedUpAsFiveCoins()
	{
		bankHas.put(ItemID.COINS, 100);

		assertEquals(Map.of(ItemID.COINS, 5L), pickups(SHANTAY_GATE, NO_POUCH));
	}

	@Test
	public void bankShantayPassPreferredOverCoins()
	{
		bankHas.put(ItemID.SHANTAY_PASS, 1);
		bankHas.put(ItemID.COINS, 100);

		assertEquals(Map.of(ItemID.SHANTAY_PASS, 1L), pickups(SHANTAY_GATE, NO_POUCH));
	}

	@Test
	public void carriedCoinsAreToppedUpBeforeTakingAPass()
	{
		playerHas.put(ItemID.COINS, 4);
		bankHas.put(ItemID.SHANTAY_PASS, 1);
		bankHas.put(ItemID.COINS, 100);

		assertEquals(Map.of(ItemID.COINS, 1L), pickups(SHANTAY_GATE, NO_POUCH));
	}

	@Test
	public void highlightingUsesEachBranchQuantity()
	{
		bankHas.put(ItemID.SHANTAY_PASS, 1);
		bankHas.put(ItemID.COINS, 3);

		assertEquals(Set.of(ItemID.SHANTAY_PASS), highlighted(SHANTAY_GATE, NO_POUCH));
		assertEquals(Map.of(ItemID.SHANTAY_PASS, 1L), pickups(SHANTAY_GATE, NO_POUCH));
	}

	private Map<Integer, Long> pickups(Transport transport, int bankPouchId)
	{
		return BankPickupRequirements.computeBankPickups(transport, playerHas, bankHas, bankPouchId, bankPouchRunes);
	}

	private Set<Integer> highlighted(Transport transport, int bankPouchId)
	{
		Set<Integer> itemIds = new HashSet<>();
		BankPickupRequirements.collectPartialBankItemIds(
			transport, playerHas, bankHas, bankPouchId, bankPouchRunes, itemIds);
		return itemIds;
	}

	private static ItemRequirement rune(ItemVariations rune, int quantity)
	{
		return new ItemRequirement(rune.getIds(), NO_SUBSTITUTES, NO_SUBSTITUTES, quantity);
	}

	private static Transport teleport(ItemRequirement... requirements)
	{
		return new Transport.TransportBuilder()
			.type(TransportType.TELEPORTATION_SPELL)
			.itemRequirements(new TransportItems(List.of(requirements)))
			.build();
	}

	private void setupPlayerItems()
	{
		doReturn(inventory).when(client).getItemContainer(InventoryID.INV);
		doReturn(equipment).when(client).getItemContainer(InventoryID.WORN);
		when(inventory.getItems()).thenReturn(new Item[]{
			new Item(ItemID.AIRRUNE, 10), new Item(ItemID.BH_RUNE_POUCH, 1)});
		when(equipment.getItems()).thenReturn(new Item[]{new Item(ItemID.STAFF_OF_FIRE, 1)});
	}
}

package shortestpath.transport;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class OwnedItemsTest
{
	private static final int POUCH_AIR = 1;
	private static final int POUCH_LAW = 2;

	@Mock
	private Client client;
	@Mock
	private ItemContainer inventory;
	@Mock
	private ItemContainer equipment;
	@Mock
	private EnumComposition runePouchEnum;

	private final Map<Integer, Integer> owned = new HashMap<>();

	@Test
	public void quantitiesAreSummedAcrossContainers()
	{
		when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.COINS, 100)});
		when(equipment.getItems()).thenReturn(new Item[]{new Item(ItemID.COINS, 5)});

		OwnedItems.addContainer(owned, inventory);
		OwnedItems.addContainer(owned, equipment);

		assertEquals(Integer.valueOf(105), owned.get(ItemID.COINS));
	}

	@Test
	public void emptySlotsAndMissingContainersAreIgnored()
	{
		when(inventory.getItems()).thenReturn(new Item[]{new Item(-1, 0), new Item(ItemID.COINS, 0)});

		OwnedItems.addContainer(owned, inventory);
		OwnedItems.addContainer(owned, null);

		assertTrue(owned.isEmpty());
	}

	@Test
	public void runePouchRunesAddToLooseRunes()
	{
		// 1000 loose air runes plus 2 in the pouch is 1002, not 2
		when(inventory.getItems()).thenReturn(new Item[]{
			new Item(ItemID.AIRRUNE, 1000), new Item(ItemID.BH_RUNE_POUCH, 1)});
		setupRunePouch(2, 5);

		OwnedItems.addContainer(owned, inventory);
		OwnedItems.addRunePouchContents(client, owned);

		assertEquals(Integer.valueOf(1002), owned.get(ItemID.AIRRUNE));
		assertEquals(Integer.valueOf(5), owned.get(ItemID.LAWRUNE));
	}

	@Test
	public void runePouchIsOnlyReadWhenOwned()
	{
		OwnedItems.addRunePouchContents(client, owned);

		assertTrue(owned.isEmpty());
		verifyNoInteractions(client);
	}

	@Test
	public void runePouchContentsAreDecodedAsRuneIdToAmount()
	{
		setupRunePouch(2, 5);

		assertEquals(Map.of(ItemID.AIRRUNE, 2, ItemID.LAWRUNE, 5), OwnedItems.runePouchContents(client));
	}

	private void setupRunePouch(int airRunes, int lawRunes)
	{
		when(client.getEnum(EnumID.RUNEPOUCH_RUNE)).thenReturn(runePouchEnum);
		when(runePouchEnum.getIntValue(POUCH_AIR)).thenReturn(ItemID.AIRRUNE);
		when(runePouchEnum.getIntValue(POUCH_LAW)).thenReturn(ItemID.LAWRUNE);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1)).thenReturn(POUCH_AIR);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_1)).thenReturn(airRunes);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_2)).thenReturn(POUCH_LAW);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_2)).thenReturn(lawRunes);
	}
}

package shortestpath.transport;

import java.util.EnumSet;
import org.junit.Test;
import shortestpath.TestShortestPathConfig;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class PohNexusPortalTest
{
	@Test
	public void testSimpleMappings()
	{
		assertSame(PohNexusPortal.APE_ATOLL_DUNGEON, PohNexusPortal.fromDisplayInfo("Ape Atoll Dungeon Portal"));
		assertSame(PohNexusPortal.ANNAKARL, PohNexusPortal.fromDisplayInfo("Annakarl Portal"));
		assertSame(PohNexusPortal.ARCEUUS_LIBRARY, PohNexusPortal.fromDisplayInfo("Arceuus Library Portal"));
	}

	@Test
	public void testGroupedMappings()
	{
		assertSame(PohNexusPortal.CAMELOT, PohNexusPortal.fromDisplayInfo("Camelot Portal"));
		assertSame(PohNexusPortal.CAMELOT, PohNexusPortal.fromDisplayInfo("Seers' Village Portal"));
		assertSame(PohNexusPortal.VARROCK, PohNexusPortal.fromDisplayInfo("Varrock Portal"));
		assertSame(PohNexusPortal.VARROCK, PohNexusPortal.fromDisplayInfo("Grand Exchange Portal"));
		assertSame(PohNexusPortal.WATCHTOWER, PohNexusPortal.fromDisplayInfo("Watchtower Portal"));
		assertSame(PohNexusPortal.WATCHTOWER, PohNexusPortal.fromDisplayInfo("Yanille Portal"));
